window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["四季"]=[{"uid":"50fa86ae-4358-4dac-bc7d-26a60929034f","title":"杂曲歌辞 昔昔盐 蘼芜叶复齐","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["提筐红叶下，度日采蘼芜。","掬翠香盈袖，看花忆故夫。","叶齐谁复见，风暖恨偏孤。","一被春光累，容颜与昔殊。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["花","春"],"cats":{"抒情":["思念","孤独","闺怨"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.9},{"uid":"e283ac05-0ee6-4342-b972-af263c1e2405","title":"尊师是桃源黄先生传法弟子常见尊师称先师灵迹今重赋此诗兼寄题黄先生旧馆","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["后学方成市，吾师又上宾。","洞天应不夜，源树秪如春。","棋客留童子，山精避直神。","无因握石髓，及与养生人。"],"theme":"佛道禅颂","theme2":["送别","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","夜","山"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.85},{"uid":"cp9d526676093b5f","title":"绿意・疏影","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["碧圆自洁。","向浅洲远渚，亭亭清绝。","犹有遗簪，不展秋心，能卷几多炎热。","鸳鸯密语同倾盖，且莫与、浣纱人说。","恐怨歌、忽断花风，碎却翠云千叠。","回首当年汉舞，怕飞去、谩皱留仙裙折。","恋恋青衫，犹染枯香，还叹鬓丝飘雪。","盘心清露如铅水，又一夜、西风吹折。","喜静看、匹练秋光，倒泻半湖明月。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"愁怨","mood2":["欢愉","恬淡"],"scene":["江","秋","月"],"cats":{"抒情":["爱情"],"四季":["秋天"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"a0bee52e-3b61-475b-9f5b-120e056e24da","title":"中秋与空上人同宿华严寺","author":"冷朝阳","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["埽榻相逢宿，论诗旧梵宫。","磬声迎鼓尽，月色过山穷。","庭簇安禅草，窗飞带火虫。","一宵何惜别，回首隔秋风。"],"theme":"山水田园","theme2":["节令风俗"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"b54ccce5-156f-4067-8408-a1d8a0d4c180","title":"奉赠萧二十使君","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["惜在严公幕，俱为蜀使臣。","艰危参大府，前后间清尘。","起草鸣先路，乘槎动要津。","王凫聊暂出，萧雉只相驯。","终始任安义，荒芜孟母邻。","联翩匍匐礼，意气死生亲。","张老存家事，嵇康有故人。","食恩慙卤莽，镂骨抱酸辛。","巢许山林志，夔龙廊庙珍。","鹏图乃矫翼，熊轼且移轮。","磊落衣冠地，苍茫土木身。","埙篪鸣自合，金石莹逾新。","重忆罗江外，同游锦水滨。","结欢随过隙，怀旧益沾巾。","旷绝含香舍，稽留伏枕辰。","停骖双阙早，回雁五湖春。","不达长卿病，从来原宪贫。","监河受贷粟，一起辙中鳞。"],"theme":"寄赠酬答","theme2":[],"style":"雄浑","style2":["绮丽","旷达"],"mood":"慷慨","mood2":["欢愉"],"scene":["江","春"],"cats":{"抒情":["友情"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.86},{"uid":"ed0a8f5b-76c8-4fc8-aa9d-4b45fe3a18eb","title":"送萧颖士赴东府得草字","author":"姚发","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天生良史笔，浪迹擅文藻。","中夏授参谋，东夷愿闻道。","行轩玩春日，饯席藉芳草。","幸得师季良，欣留箧笥宝。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","春"],"cats":{"四季":["春天","夏天"]},"theme_conf":1.0},{"uid":"824423a3-e7e6-41f5-bf24-d0d755bd5ed7","title":"过孔北海墓二十韵","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["抚事如神遇，临风独涕零。","墓平春草绿，碑折古苔青。","珪玉埋英气，山河孕炳灵。","发言惊辨囿，㧑翰动文星。","蕴策期干世，持权欲反经。","激扬思壮志，流落叹颓龄。","恶木人皆息，贪泉我独醒。","轮辕无匠石，刀几有庖丁。","碌碌迷藏器，规规守挈瓶。","愤容凌鼎镬，公议动朝廷。","故国将辞宠，危邦竟缓刑。","钝工磨白璧，凡石砺青萍。","揭日昭东夏，抟风滞北溟。","后尘遵轨辙，前席咏仪型。","木秀当忧悴，弦伤不底宁。","矜夸遭斥鷃，光彩困飞萤。","白羽留谈柄，清风袭德馨。","鸾凰婴雪刃，狼虎犯云屏。","兰蕙荒遗址，榛芜蔽旧坰。","轘辕近沂水，何事恋明庭。"],"theme":"咏史怀古","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["夏","雪","春"],"cats":{"抒情":["孤独","怀古"],"四季":["春天","夏天"],"人生":["励志","梦想"]},"theme_conf":0.96},{"uid":"f3cb8917-c2b2-4619-9fa4-0f548a512bae","title":"相和歌辞 子夜冬歌","author":"崔国辅","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寂寥抱冬心，裁罗又褧褧。","夜久频挑灯，霜寒剪刀冷。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","夜"],"cats":{"四季":["冬天"]},"theme_conf":0.65},{"uid":"b4ab0057-6846-46fc-afce-1d641980509f","title":"吊江南老家人春梅","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["念尔筋力尽，违我衣食恩。","奈何粗犷儿，生鞭见死痕。","旧使常以礼，新怨将谁吞。","胡为乎泥中，消歇教义源。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆","惆怅"],"scene":["江南","春","江"],"cats":{"抒情":["怀古"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.606},{"uid":"b2d89260-e3b7-4077-aaaa-0a67db01d5b6","title":"酬窦拾遗秋日见呈","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["孤城永巷时相见，衰柳闲门日半斜。","欲送近臣朝魏阙，犹怜残菊在陶家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["太阳"]},"theme_conf":0.93},{"uid":"aa155708-e969-4a7f-9a96-800ecc8818b8","title":"奉寄辰州房使君郎中","author":"窦常","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["汉代文明今盛明，犹将贾傅暂专城。","何妨密旨先符竹，莫是除书误姓名。","蜗舍喜时春梦去，隼旟行处瘴江清。","新年只可三十二，却笑潘郎白发生。"],"theme":"寄赠酬答","theme2":[],"style":"旷达","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.95},{"uid":"c1f1cc1d-4eff-438e-8aea-60cb69174965","title":"同卫八题陆少府书斋","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["知君薄州县，好静无冬春。","散帙至栖鸟，明灯留故人。","深房腊酒熟，高院梅花新。","若是周旋地，当令风义亲。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","春","酒"],"cats":{"抒情":["友情"],"四季":["春天","冬天"]},"theme_conf":0.618},{"uid":"40a92675-3a77-4ce1-9242-17eb287a246a","title":"渡江秋怨二首 二","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渡秋江兮渺然，望秋月兮婵娟。","色如练，万里徧，我有所思兮不得见。","不得见兮露寒水深，耿遥夜兮伤心。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"f990af2e-d929-48da-a9b3-fdbc706ca4a3","title":"子夜吴歌 冬歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"],"theme":"闺情宫怨","theme2":["羁旅思乡","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"]},"theme_conf":0.347},{"uid":"c8b006af-ed1c-4206-8647-24e8623ca5b2","title":"相和歌辞 上留田","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["行至上留田，孤坟何峥嵘。","积此万古恨，春草不复生。","悲风四边来，肠断白杨声。","借问谁家地，埋没蒿里茔。","古老向余言，言是上留田。","蓬科马鬣今已平，昔之弟死兄不葬。","他人于此举铭旌，一鸟死，百鸟鸣，一兽死，百兽惊。","桓山之禽别离苦，欲去回翔不能征。","田氏仓卒骨肉分，青天白日摧紫荆。","交柯之木本同形，东枝顦顇西枝荣。","无心之物尚如此，参商胡乃寻天兵。","孤竹延陵，让国扬名。","高风缅邈，颓波激清。","尺布之谣，塞耳不能听。"],"theme":"咏史怀古","theme2":["悼亡挽歌","送别","讽喻刺世"],"style":"沉郁","style2":["雄浑"],"mood":"愁怨","mood2":["悲怆"],"scene":["塞外","春"],"cats":{"抒情":["离别","伤感","悼亡","怀古"],"四季":["春天"]},"theme_conf":0.95},{"uid":"f93545e7-747e-4d12-a6c8-e484c46b2860","title":"相和歌辞 玉阶怨","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["玉阶生白露，夜久侵罗袜。","却下水精帘，玲珑望秋月。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋","夜","月"],"cats":{"抒情":["闺怨"],"四季":["秋天"]},"theme_conf":0.836},{"uid":"6d843e05-dc54-4fd9-beb9-44f188b596b3","title":"奉和王侍郎春日喜李侍郎崔给谏张舍人韦谏议见访因命觞观乐之什","author":"窦庠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["华馆迟嘉宾，逢迎淑景新。","锦筵开绛帐，玉佩下朱轮。","曲里三仙会，风前百啭春。","欲知忘味处，共仰在齐人。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"人物":["老师"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"b67cee37-9190-4581-89ec-473df5ef0c6f","title":"到村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧涧虽多雨，秋沙先少泥。","蛟龙引子过，荷芰逐花低。","老去参戎幕，归来散马蹄。","稻粱须就列，榛草即相迷。","蓄积思江汉，疎顽惑町畦。","稍酬知己分，还入故林栖。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","雨","江"],"cats":{"抒情":["友情"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.707},{"uid":"15a37290-0aef-4c6b-92c9-97cff61aafa6","title":"曲池荷","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["浮香绕曲岸，圆影覆华池。","常恐秋风早，飘零君不知。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["园林","夏"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.56},{"uid":"d6d2ba3a-f3a7-479e-b4d7-705ef40659fc","title":"颍州从事西湖亭䜩饯","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西湖清宴不知回，一曲离歌酒一杯。","城带夕阳闻鼓角，寺临秋水见楼台。","兰堂客散蝉犹噪，桂檝人稀鸟自来。","独想征车过巩洛，此中霜菊遶潭开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["江南","楼","秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["西湖"]},"theme_conf":0.688},{"uid":"0fb0189c-8ff3-4106-af94-f6d26d528a1d","title":"琵琶引","author":"白居易","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["浔阳江头夜送客，枫叶荻花秋索索。","主人下马客在船，举酒欲饮无管弦。","醉不成欢惨将别，别时茫茫江浸月。","忽闻水上琵琶声，主人忘归客不发。","寻声暗问弹者谁，琵琶声停欲语迟。","移船相近邀相见，添酒回灯重开宴。","千呼万唤始出来，犹抱琵琶半遮面。","转轴拨弦三两声，未成曲调先有情。","弦弦掩抑声声思，似诉平生不得意。","低眉信手续续弹，说尽心中无限事。","轻拢慢撚抹复挑，初为霓裳后六幺。","大弦嘈嘈如急雨，小弦切切如私语。","嘈嘈切切错杂弹，大珠小珠落玉盘。","间关莺语花底滑，幽咽泉流水下滩。","水泉冷涩弦疑绝，疑绝不通声暂歇。","别有幽愁暗恨生，此时无声胜有声。","银缾乍破水浆迸，铁骑突出刀枪鸣。","曲终收拨当心画，四弦一声如裂帛。","东舟西舫悄无言，唯见江心秋月白。","沈吟放拨插弦中，整顿衣裳起敛容。","自言本是京城女，家在虾蟇陵下住。","十三学得琵琶成，名蜀教坊第一部。","曲罢曾教善才伏，妆成每被秋娘妬。","五陵年少争缠头，一曲红绡不知数。","钿头云箆击节碎，血色罗帬飜酒污。","今年欢笑复明年，秋月春风等闲度。","弟走从军阿姨死，暮去朝来颜色故。","门前冷落鞍马稀，老大嫁作商人妇。","商人重利轻别离，前月浮梁买茶去。","去来江口守空船，绕船月明江水寒。","夜深忽梦少年事，梦啼妆泪红阑干。","我闻琵琶已叹息，又闻此语重唧唧。","同是天涯沦落人，相逢何必曾相识。","我从去年辞帝京，谪居卧病浔阳城。","浔阳小处无音乐，终岁不闻丝竹声。","住近湓江地低湿，黄芦苦竹绕宅生。","其间旦暮闻何物，杜鹃啼血猨哀鸣。","春江花朝秋月夜，往往取酒还独倾。","岂无山歌与村笛，呕哑嘲哳难为听。","今夜闻君琵琶语，如听仙乐耳暂明。","莫辞更坐弹一曲，为君飜作琵琶行。","感我此言良久立，却坐促弦弦转急。","凄凄不似向前声，满座重闻皆掩泣。","座中泣下谁最多，江州司马青衫湿。"],"theme":"题画咏艺","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["欢愉","悲怆"],"scene":["夜","舟","酒","秋","春","鸟"],"cats":{"抒情":["离别","伤感"],"四季":["春天","秋天"]},"theme_conf":0.328},{"uid":"ba10246a-c026-41e7-87a9-2e6ce2a27559","title":"建都十二韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["苍生未苏息，胡马半乾坤。","议在云台上，谁扶黄屋尊。","建都分魏阙，下韶辟荆门。","恐失东人望，其如西极存。","时危当雪耻，计大岂轻论。","虽倚三阶正，终愁万国飜。","牵裾恨不死，漏网荷殊恩。","永负汉庭哭，遥怜湘水魂。","穷冬客江劒，随事有田园。","风断青蒲节，霜埋翠竹根。","衣冠空穰穰，关辅久昏昏。","愿枉长安日，光辉照北原。"],"theme":"边塞征战","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["冬","园林","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"],"生活":["田野"]},"theme_conf":0.531},{"uid":"e56e4c5d-9552-4ec9-a4c5-a86e08e1ef6f","title":"相和歌辞 春江花月夜二首 一","author":"张子容","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["林花发岸口，气色动江新。","此夜江中月，流光花上春。","分明石潭里，宜照浣纱人。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","夜","月","江","花"],"cats":{"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.91},{"uid":"7e808dee-54f9-428c-a303-71ea2ee91df5","title":"听崔莒侍御叶家歌","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宛罗重縠起歌筵，活凤生花动碧烟。","一声唱断无人和，触破秋云直上天。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.65},{"uid":"de28c365-7d67-4513-a2d5-5dec1ff3c795","title":"寄高云","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南徐风日好，怅望毘陵道。","毘陵有故人，一见恨无因。","独恋青山久，唯令白发新。","每嫌持手板，时见著头巾。","烟景临寒食，农桑接仲春。","家贫仍嗜酒，生事今何有。","芳草遍江南，劳心忆携手。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["清明","江南","春","酒"],"cats":{"抒情":["友情","思念","孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.96},{"uid":"f8e07cab-06f6-4ea0-a6b6-815bd8c22506","title":"归燕","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不独避霜雪，其如俦侣稀。","四时无失序，八月自知归。","春色岂相访，众雏还识机。","故巢傥未毁，会傍主人飞。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","雪","春","月"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.519},{"uid":"292c14cd-151f-4321-a94c-46fc86693eb3","title":"秋日赴阙题潼关驿楼","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红叶晚萧萧，长亭酒一瓢。","残云归太华，疎雨过中条。","树色随山迥，河声入海遥。","帝乡明日到，犹自梦渔樵。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["楼","秋"],"cats":{"抒情":["离别","思乡"],"四季":["秋天"],"天气":["太阳"]},"theme_conf":0.78},{"uid":"7136e8b6-cec9-423f-89e9-a260eeb32481","title":"春日登陕州城楼俯眺原野回丹碧缀烟霞密翠斑红芳菲花柳即目川岫聊以命篇","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧原开雾隰，绮岭峻霞城。","烟峰高下翠，日浪浅深明。","斑红粧橤树，圆青压溜荆。","迹岩劳傅想，窥野访莘情。","巨川何以济，舟楫伫时英。"],"theme":"山水田园","theme2":["咏史怀古","山水田园"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","花"],"cats":{"抒情":["怀古"],"四季":["春天"],"天气":["太阳"],"植物":["柳树"]},"theme_conf":0.82},{"uid":"5eb68e82-7216-4179-9b85-6f04894890b0","title":"九日五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧与苏司业，兼随郑广文。","采花香泛泛，坐客醉纷纷。","野树歌还倚，秋砧醒却闻。","欢娱两冥漠，西北有孤云。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["重阳","秋","花","塞外"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.78},{"uid":"284295e3-3fc4-4afb-a38b-d5ae9bccc0b1","title":"奉和谏议酬先辈霜菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["紫茎芳艳照西风，秖怕霜华掠断丛。","争奈病夫难强饮，应须速自召车公。"],"theme":"寄赠酬答","theme2":["送别"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.7},{"uid":"a56eb8bb-1b57-4106-a3a6-34be16282ea3","title":"夏夜饯裴行军赴朝命","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["三年同看锦城花，银烛连宵照绮霞。","报国从来先意气，临岐不用重咨嗟。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["夜","夏"],"cats":{"抒情":["离别","爱国"],"四季":["夏天"]},"theme_conf":0.639},{"uid":"6d1ee060-5750-4c9b-8c75-6080912cbe17","title":"野菊","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晚艳出荒篱，冷香著秋水。","忆向山中见，伴蛩石壁里。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["重阳","秋","山"],"cats":{"抒情":["思念"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.579},{"uid":"cp1acc2f34cdbd10","title":"东风第一枝","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["巧沁兰心，偷黏草甲，东风欲障新暖。","谩凝碧瓦难留，信知暮寒轻浅。","行天入镜，做弄出、轻松纤软。","料故园、不卷重帘，误了乍来双燕。","青未了、柳回白眼。","红欲断、杏开素面。","旧游忆著山阴，厚盟遂妨上苑。","寒炉重暖，便放慢春衫针线。","恐凤靴、挑菜归来，万一灞桥相见。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"344b8022-5073-4b18-a099-ee3e1f12412b","title":"相和歌辞 短歌行","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人若不死，吾亦何所悲。","萧萧烟雨九原上，白杨青松葬者谁。","贵贱同一尘，死生同一指。","人生在世共如此，何异浮云与流水。","短歌行，短歌无穷日已倾。","邺宫梁苑徒有名，春草秋风伤我情。","何为不学金仙侣？一悟空王无死生。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","秋","雨"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"人生":["哲理"]},"theme_conf":0.531},{"uid":"a4c287ae-d6f5-414a-a05b-f69d7baff4a0","title":"水阁朝霁奉简严云安","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城抱春岑，江阁邻石面。","崔嵬晨云白，朝旭射芳甸。","雨槛卧花丛，风床展书卷。","钩帘宿鹭起，丸药流莺啭。","呼婢取酒壶，绩儿诵文选。","晚交严明府，矧此数相见。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","酒"],"cats":{"四季":["春天"],"天气":["写云"],"人生":["读书"]},"theme_conf":0.9},{"uid":"15520925-c4b7-4f94-a3dd-e79e48420c45","title":"同中书刘舍人题青龙上房","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西掖归来后，东林静者期。","远峰春雪里，寒竹暮天时。","笑说金人偈，闲听宝月诗。","更怜茶兴在，好出下方迟。"],"theme":"佛道禅颂","theme2":["咏物","山水田园","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["雪","春","月","山"],"cats":{"四季":["春天"],"山水":["庐山"]},"theme_conf":0.72},{"uid":"4d79a7f2-2e3c-496a-b9bd-9f778aee26ee","title":"秋日旅舍别司空文明","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风飒穷巷，秋思满高云。","吏隐俱不就，此心仍别君。","素怀宗淡泊，羁旅念功勋。","转忆西林寺，江声月下闻。"],"theme":"羁旅思乡","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["离别","思念","思乡"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.477},{"uid":"809cc96a-74a8-4569-a88d-c218523e0d3c","title":"相和歌辞 秋胡行","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["妾本邯郸未嫁时，容华倚翠人未知。","一朝结发从君子，将妾迢迢东路陲。","时逢大道无难阻，君方游宦从陈汝。","蕙楼独卧频度春，彩落辞君几徂暑。","三月垂杨蚕未眠，携笼结侣南陌边。","道逢行子不相识，赠妾黄金买少年。","妾家夫壻轻离久，寸心誓与长相守。","愿言行路莫多情，送妾贞心在人口。","日暮蚕饥相命归，携笼端饰来庭闱。","劳心苦力终无恨，所冀君恩那可依。","闻说行人已归止，乃是向来赠金子。","相看颜色不复言，相顾怀慙有何已。","从来自隐无疑背，直为君情也相会。","如何咫尺仍有情，况复迢迢千里外。","此时顾恩不顾身，念君此日赴河津。","莫道向来不得意，故欲留规诫后人。"],"theme":"闺情宫怨","theme2":["民生疾苦"],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["慷慨"],"scene":["秋","夏"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"]},"theme_conf":0.84},{"uid":"d3e37fe7-24cf-41a3-aab4-66398019be30","title":"送柳宜城葬","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鸣笳已逐春风咽，匹马犹依旧路嘶。","遥望柳家门外树，恐闻黄鸟向人啼。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"a456cc8d-2cd1-41c9-9cc8-52163216510d","title":"西江上送渔父","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["却逐严光向若耶，钓轮菱櫂寄年华。","三秋梅雨愁枫叶，一夜篷舟宿苇花。","不见水云应有梦，偶随鸥鹭便成家。","白苹风起楼船暮，江燕双双五两斜。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","舟","秋"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"山水":["江河"],"人物":["父亲"]},"theme_conf":0.443},{"uid":"629687ee-7e6f-4b7a-8c3d-2034d5e752da","title":"远游联句","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别肠车轮转，一日一万周。","离思春冰泮，澜漫不可收。","驰光忽以迫，飞辔谁能留。","取之讵灼灼，此去信悠悠。","楚客宿江上，夜魂栖浪头。","晓日生远岸，水芳缀孤舟。","村饮泊好木，野蔬拾新柔。","独含凄凄别，中结郁郁愁。","人忆旧行乐，鸟吟新得俦。","灵瑟时窅窅，霠猨夜啾啾。","愤涛气尚盛，恨竹泪空幽。","长怀绝无已，多感良自尤。","即路涉献岁，归期眇凉秋。","两欢日牢落，孤悲坐绸缪。","观怪忽荡漾，叩奇独冥搜。","海鲸吞明月，浪岛没大沤。","我有一寸钩，欲钓千丈流。","良知忽然远，壮志郁无抽。","魍魅暂出没，蛟螭互蟠蟉。","昌言拜舜禹，举颿凌斗牛。","怀糈餽贤屈，乘桴追圣丘。","飘然天外步，岂肯区中囚。","楚些待谁吊，贾辞缄恨投。","翳明弗可晓，秘魂安所求。","气毒放逐域，蓼杂芳菲畴。","当春忽凄凉，不枯亦飕飗。","貉谣众猥款，巴语相咿嚘。","默誓去外俗，嘉愿还中州。","江生行既乐，躬辇自相勠。","饮醇趣明代，味腥谢荒陬。","驰深鼓利檝，趋险惊蜚𬨎。","系石沈靳尚，开弓射𫛝吺。","路暗执屏翳，波惊戮阳侯。","广泛信缥缈，高行恣浮游。","外患萧萧去，中悒稍稍瘳。","振衣造云阙，跪坐陈清猷。","德风变谗巧，仁气销戈矛。","名声照西海，淑问无时休。","归哉孟夫子，归去无夷犹。"],"theme":"送别","theme2":["边塞征战","羁旅思乡","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"愁怨","mood2":[],"scene":["春","月"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.83},{"uid":"aa3363f3-d276-4f9a-985e-37f2db392800","title":"寄淮上柳十三","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["苇萧中辟户，相映绿淮流。","莫讶春潮阔，鸥边可泊舟。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","舟","江"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.9},{"uid":"bcf88d70-488c-40a7-b7bf-febc7ab7c797","title":"同王员外雨后登开元寺南楼因寄西岩警上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["过雨开楼看晚虹，白云相逐水相通。","寒蝉噪暮野无日，古树伤秋天有风。","数穗远烟凝垅上，一枝繁果忆山中。","何言暂别东林友，惆怅人间事不同。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["相思"],"scene":["雨","楼","山","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.87},{"uid":"2c036362-9f1d-434c-854f-b97a2a4bb19b","title":"天末忆李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风起天末，君子意如何。","鸿雁几时到，江湖秋水多。","文章憎命达，魑魅喜人过。","应共冤魂语，投诗赠汩罗。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江","秋"],"cats":{"抒情":["思念"],"四季":["秋天"]},"theme_conf":0.668},{"uid":"7277c420-9f3f-4093-a5b2-6331494721e8","title":"春思","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["燕草如碧丝，秦桑低绿枝。","当君怀归日，是妾断肠时。","春风不相识，何事入罗帏。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"7dccdf60-ec93-4a4d-be1c-4d725b92cb8e","title":"秋雨叹三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["雨中百草秋烂死，阶下决明颜色鲜。","著叶满枝翠羽盖，开花无树黄金钱。","凉风萧萧吹汝急，恐汝后时难独立。","堂上书生空白头，临风三齅馨香泣。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["秋","雨"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.8},{"uid":"ffed3e70-8753-466c-ac59-0fdb5894adfd","title":"奉和皇甫大夫夏日游花严寺","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["初第华严会，王家少长行。","到宫龙节驻，礼塔雁行成。","莲界千峰静，梅天一雨清。","禅庭未可恋，圣主寄苍生。"],"theme":"应制干谒","theme2":["哲理悟道"],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.93},{"uid":"527b27aa-af81-41ed-b7f4-31c4eb7bb57f","title":"守岁","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今宵冬律尽，来朝丽景新。","花余凝地雪，条含煖吹分。","绶吐芽犹嫩，冰□已镂津。","薄红梅色冷，浅绿柳轻春。","送迎交两节，暄寒变一辰。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["冬","除夕"],"cats":{"四季":["冬天"],"节日":["春节"]},"theme_conf":0.96},{"uid":"41d7e65e-5a99-4597-a1cc-d716c5380584","title":"石柜阁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["季冬日已长，山晚半天赤。","蜀道多早花，江间饶奇石。","石柜曾波上，临虚荡高壁。","清晖回群鸥，暝色带远客。","羁栖负幽意，感叹向绝迹。","信甘孱懦婴，不独冻馁迫。","优游谢康乐，放浪陶彭泽。","吾衰未自安，谢尔性所适。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":["孤寂","欢愉"],"scene":["楼","冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"]},"theme_conf":0.667},{"uid":"5ec67bba-ece4-49ff-81b0-455d662a0be2","title":"荣华乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["鸢肩公子二十余，齿编贝，唇激朱。","气如虹霓，饮如建瓴。","走马夜归呌严更，径穿复道游椒房。","龙裘金玦杂花光，玉堂调笑金楼子。","台下戏学邯郸倡，口吟舌话称女郎。","锦祛绣面汉帝旁，得明珠十斛。","白璧一双，新诏垂金曳紫光煌煌。","马如飞，人如水。","九卿六官皆望履，将回日月先反掌。","欲作江河唯画地，峨峨虎冠上切云。","竦劒晨趋凌紫氛，绣段千寻贻皂隶。","黄金百镒贶家臣，十二门前张大宅。","晴春烟起连天碧，金铺缀日杂红光。","铜龙啮环似争力，瑶姬凝醉卧芳席。","海素笼窗空下隔，丹穴取凤充行庖。","貜貜如拳那足食，金蟾呀呀兰烛香。","军装武妓声琅珰，谁知花雨夜来过。","但见池台春草长，嘈嘈弦吹匝天开。","洪厓箫声遶天来，天长一矢贯双虎。","云弝绝骋聒旱雷，乱袖交竿管儿舞。","吴音绿鸟学言语，能教刻石平紫金。","解送刻毛寄新兔，三皇皇后七贵人。","五十校尉二将军，当时飞去逐彩云，化作今日京华春。"],"theme":"讽喻刺世","theme2":["送别","边塞征战"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","月","楼","夜","春"],"cats":{"四季":["春天"],"天气":["写云","彩虹"]},"theme_conf":0.86},{"uid":"9f033648-d76a-4de4-ba1d-8c0298fa5c3d","title":"送薛居士和州读书","author":"严维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤云独鹤共悠悠，万卷经书一叶舟。","楚地巢城民舍少，烟村社树鹭湖秋。","蒿莱织妾晨炊黍，隅落耕童夕放牛。","年少不应辞苦节，诸生若遇亦封侯。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.49},{"uid":"80159919-0b66-4956-a563-ef9bcf6a05c0","title":"金谷园","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["繁华事散逐香尘，流水无情草自春。","日暮东风怨啼鸟，落花犹似堕楼人。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["春","园林","花"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.586},{"uid":"8324db66-b75a-40ff-9469-cba276d2f88f","title":"书边事","author":"张乔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["调角断清秋，征人倚戍楼。","春风对青冢，白日落梁州。","大汉无兵阻，穷边有客游。","蕃情似此水，长愿向南流。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","春","楼"],"cats":{"四季":["春天","秋天"]},"theme_conf":1.0},{"uid":"3f049d66-1513-407f-bb4e-cf25a7b5069a","title":"自夏口至鹦鹉洲夕望岳阳寄源中丞","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["[汀]洲无浪复无烟，楚客相思益渺然。","汉口夕阳斜渡鸟，洞庭秋水远连天。","孤城背岭寒吹角，独戍临江夜泊船。","贾谊上书忧汉室，长沙谪去古今怜。"],"theme":"寄赠酬答","theme2":["应制干谒","山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["江"],"cats":{"抒情":["思念","孤独"],"四季":["夏天"]},"theme_conf":0.9},{"uid":"0e651edd-1bc8-49c9-bd85-b49df84c9743","title":"横吹曲辞 折杨柳","author":"韦承庆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里边城地，三春杨柳节。","叶似镜中眉，花如关外雪。","征人远乡思，倡妇高楼别。","不忍掷年华，含情寄攀折。"],"theme":"送别","theme2":["边塞征战","羁旅思乡"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春","楼"],"cats":{"抒情":["思乡"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.463},{"uid":"d0fa1454-f337-4343-ab4a-2a42dfdf4e8f","title":"春宫曲","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨夜风开露井桃，未央前殿月轮高。","平阳歌舞新承宠，帘外春寒赐锦袍。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"b64c656c-1346-4fce-9667-57d2472ab4f2","title":"岁日作","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["不觉老将春共至，更悲携手几人全。","还丹寂寞羞明镜，手把屠苏让少年。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.78},{"uid":"e7c246f6-8c50-43a0-b4ad-6a42a6cf6d7e","title":"云梦故城秋望","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故国遗墟在，登临想旧游。","一朝人事变，千载水空流。","梦渚鸿声晚，荆门树色秋。","片云凝不散，遥挂望乡愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.479},{"uid":"60cc0c7d-7a16-4474-9e97-710f3f5ba362","title":"秋灯","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["向壁暖悠悠，罗帏寒寂寂。","斜照碧山图，松间一片石。"],"theme":"闺情宫怨","theme2":[],"style":"幽峭","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","元宵","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"cpe95478f7a37a64","title":"薄幸","author":"吕渭老","dynasty":"宋","section":"宋词","form":"词","paragraphs":["青楼春晚。","昼寂寂、梳匀又懒。","乍听得、鸦啼莺弄，惹起新愁无限。","记年时、偷掷春心，花间隔雾遥相见。","便角枕题诗，宝钗贳酒，共醉青苔深院。","怎忘得、回廊下，携手处、花明月满。","如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。","却谁拘管。","尽无言、闲品秦筝，泪满参差雁。","腰支渐小，心与杨花共远。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","春","月","酒","园林"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.62},{"uid":"91019fe2-b58e-4320-a986-6a323847e944","title":"相和歌辞 春江花月夜","author":"张若虚","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["春江潮水连海平，海上明月共潮生。","滟滟随波千万里，何处春江无月明？","江流宛转遶芳甸，月照花林皆似霰。","空里流霜不觉飞，汀上白沙看不见。","江天一色无纤尘，皎皎空中孤月轮。","江畔何人初见月？江月何年初照人？","人生代代无穷已，江月年年望相似。","不知江月待何人，但见长江送流水。","白云一片去悠悠，青枫浦上不胜愁。","谁家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，应照离人妆镜台。","玉户帘中卷不去，捣衣砧上拂还来。","此时相望不相闻，愿逐月华流照君。","鸿雁长飞光不度，鱼龙潜跃水成文。","昨夜闲潭梦落花，可怜春半不还家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海雾，碣石潇湘无限路。","不知乘月几人归，落月摇情满江树。"],"theme":"爱情相思","theme2":["送别","羁旅思乡"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["江","月","春"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"山水":["江河","长江"],"天气":["月亮"]},"theme_conf":0.75},{"uid":"a8d2011c-dc24-4e9a-a795-92e7473c7ad1","title":"春夜过长孙绎别业","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳期难再得，清夜此云林。","带竹新泉冷，穿花片月深。","含毫凝逸思，酌水话幽心。","不觉星河转，山枝惊曙禽。"],"theme":"山水田园","theme2":["送别","闲适隐逸","咏史怀古"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","春"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"天气":["星星"]},"theme_conf":0.74},{"uid":"4b6c721e-3383-47a7-ab92-d04732ab8d61","title":"九曲词三首 三","author":"高适","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["铁骑横行铁岭头，西看逻逤取封侯。","青海只今将饮马，黄河不用更防秋。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江","秋"],"cats":{"四季":["秋天"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"c74950d3-3194-4abe-a37c-03a623d03636","title":"送李明府赴滑州","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["渭城寒食罢，送客归远道。","乌帽背斜晖，青骊踏春草。","酒醒孤烛夜，衣冷千山早。","去事沈尚书，应怜词赋好。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","春","酒","夜"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.633},{"uid":"dfe41fd5-0f8c-4a52-9ce5-8622202264ff","title":"琴曲歌辞 湘妃怨","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南巡竟不返，帝子怨逾积。","万里丧蛾眉，潇湘水空碧。","冥冥荒山下，古庙收贞魄。","乔木深青春，清光满瑶席。","搴芳徒有荐，灵意殊脉脉。","玉佩不可亲，裴回烟波夕。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.593},{"uid":"bbe30e55-8238-495c-bcf9-8144fe363439","title":"自淇涉黄河途中作十三首 六","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日登滑台，台高秋已暮。","独行既未惬，怀土怅无趣。","晋宋何萧条，羌胡散驰骛。","当时无战略，此地即边戍。","兵革徒自勤，山河孰云固。","乘闲喜临眺，感物伤游寓。","惆怅落日前，飘飖远帆处。","北风吹万里，南雁不知数。","归意方浩然，云沙更廻互。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":["孤寂","欢愉"],"scene":["江","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河","黄河"],"人生":["战争"]},"theme_conf":1.0},{"uid":"5a76b6ea-07ee-44b6-ac20-a87d18203810","title":"答侯少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常日好读书，晚年学垂纶。","漆园多乔木，睢水清粼粼。","诏书下柴门，天命敢逡巡。","赫赫三伏时，十日到咸秦。","褐衣不得见，黄绶翻在身。","吏道顿羁束，生涯难重陈。","北使经大寒，关山饶苦辛。","边兵若刍狗，战骨成埃尘。","行矣勿复言，归欤伤我神。","如何燕赵陲，忽遇平生亲。","开馆纳征骑，弹弦娱远宾。","飘飖天地间，一别方兹晨。","东道有佳作，南朝无此人。","性灵出万象，风骨超常伦。","吾党谢王粲，群贤推郄诜。","明时取秀才，落日过蒲津。","节苦名已富，禄微家转贫。","相逢愧薄游，抚己荷陶钧。","心事正堪尽，离居宁太频。","两河归路遥，二月芳草新。","柳接滹沱暗，莺连渤海春。","谁谓行路难，猥当希代珍。","提握每终日，相思犹比邻。","江海有扁舟，丘园有角巾。","君意定何适，我怀知所遵。","浮沈各异宜，老大贵全真。","莫作云霄计，遑遑随缙绅。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"清新","style2":["旷达"],"mood":"相思","mood2":[],"scene":["舟","春","鸟"],"cats":{"抒情":["离别","思念","思乡"],"四季":["春天"],"天气":["太阳"],"人生":["读书","战争"]},"theme_conf":0.96},{"uid":"a5546090-d778-47ce-abde-d3184e225f64","title":"江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清江一曲抱村流，长夏江村事事幽。","自去自来堂上燕，相亲相近水中鸥。","老妻画纸为碁局，稚子敲针作钓钩。","多病所须唯药物，微躯此外更何求。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"山水":["江河"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.832},{"uid":"1d70922b-4e1b-4eb5-ae5b-79df44859f57","title":"新竹","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["笋添南堦竹，日日成清閟。","缥节已储霜，黄苞犹揜翠。","出栏抽五六，当户罗三四。","高标陵秋严，贞色夺春媚。","稀生巧补林，并出疑争地。","纵横乍依行，烂熳忽无次。","风枝未飘吹，露粉先涵泪。","何人可携玩，清景空瞪视。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋","春"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["竹子"]},"theme_conf":0.609},{"uid":"002d65d7-a386-46f1-8c8f-007095ec68bd","title":"岁暮怀崔峒耿𣲗","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["腊月江天见春色，白花青柳疑寒食。","洛阳旧社各东西，楚国游人不相识。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["清明","春","月"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.87},{"uid":"20dea002-e0ee-453b-89a0-f54b746aa435","title":"天星送杨凝郎中贺正","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天星牢落鸡喔咿，仆夫起餐车载脂。","正当穷冬寒未已，借问君子行安之。","会朝元正无不至，受命上宰须及期。","侍从近臣有虚位，公今此去归何时。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["星星"]},"theme_conf":0.745},{"uid":"04e6eb11-0b8c-4b26-ae73-2c7dc13845dc","title":"衞明府寄枇杷叶以诗荅","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["倾筐呈绿叶，重叠色何鲜。","讵是秋风里，犹如晓露前。","仙方当见重，消疾本应便。","全胜甘蕉赠，空投谢氏篇。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"cpfccab6cdeebb35","title":"石州引・石州慢","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["薄雨初寒，斜照弄晴，春意空阔。","长亭柳色缠黄，远客一枝先折。","烟横水际，映带几点归鸦，东风销尽龙沙雪。","还记初关来，恰而今时节。","将发。","画楼芳酒，红泪清歌，顿成清别。","已是经年，杳杳音尘多绝。","欲知方寸，共有几许清愁，芭蕉不展丁香结。","枉望断天涯，两厌厌风月。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":[],"scene":["春","楼","花","雪","酒"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["春天"]},"theme_conf":0.509},{"uid":"76d1a527-f7ad-4732-98a1-248d9b64c781","title":"萧八明府隄处觅桃栽","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["奉乞桃栽一百根，春前为送浣花村。","河阳县里虽无数，濯锦江边未满园。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江","园林"],"cats":{"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"7f2e77fa-3093-46bd-837e-08dc3934ada6","title":"徐州送丘侍御之越","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["时鸟催春色，离人惜岁华。","远山随拥传，芳草引还家。","北固潮当阔，西陵路稍斜。","纵令寒食过，犹有镜中花。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","江南","花","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.752},{"uid":"0d6eed96-a408-4c95-9d9a-fc1ba93675fc","title":"渔父","author":"张志和","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["八月九月芦花飞，南谿老人垂钓归。","秋山入帘翠滴滴，野艇倚槛云依依。","却把渔竿寻小径，闲梳鹤发对斜晖。","翻嫌四皓曾多事，出为储皇定是非。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["月","秋","山"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.556},{"uid":"93d82a12-5e4d-45c2-b837-d0c54447fba3","title":"与高适薛据慈恩寺浮图","author":"岑参","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塔势如涌出，孤高耸天宫。","登临出世界，磴道盘虚空。","突兀压神州，峥嵘如鬼工。","四角碍白日，七层摩苍穹。","下窥指高鸟，俯听闻惊风。","连山若波涛，奔凑似朝东。","青槐夹驰道，宫馆何玲珑。","秋色从西来，苍然满关中。","五陵北原上，万古青蒙蒙。","净理了可悟，胜因夙所宗。","誓将挂冠去，觉道资无穷。"],"theme":"题画咏艺","theme2":["哲理悟道"],"style":"雄浑","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.615},{"uid":"cp55185352520840","title":"洞仙歌","author":"李元膺","dynasty":"宋","section":"宋词","form":"词","paragraphs":["雪云散尽，放晓晴池院。","杨柳于人便青眼。","更风流多处，一点梅心、相映远。","约略轻笑浅。","一年春好处，不在浓芳，小艳疏香最娇软。","到清明时候，百紫千红花正乱。","已失春风一半。","蚤占取韶光，共追游，但莫管春寒，醉红自暖。"],"theme":"咏怀抒感","theme2":["游仙梦幻"],"style":"清新","style2":["婉约","旷达"],"mood":"欢愉","mood2":[],"scene":["花","清明","园林","春"],"cats":{"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.74},{"uid":"cpa67f4336a27ef4","title":"剑器近","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["夜来雨。","赖倩得、东风吹住。","海棠正妖饶处。","且留取。","悄庭户。","试细听、莺啼燕语。","分明共人愁绪。","怕春去。","佳树。","翠阴初转午。","重帘未卷，乍睡起、寂寞看风絮。","偷弹清泪寄烟波，见江头故人，为言憔悴如许。","彩笺无数。","去却寒暄，到了浑无定据。","断肠落日千山暮。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","鸟"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["春天"]},"theme_conf":0.637},{"uid":"98fc0ac5-1c75-4c64-8e09-6813c8d1b9fc","title":"峡口二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["峡口大江间，西南控百蛮。","城欹连粉堞，岸断更青山。","开辟多天险，防隅一水关。","乱离闻鼓角，秋气动衰颜。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","江","山"],"cats":{"四季":["秋天"],"山水":["长江"]},"theme_conf":0.6},{"uid":"b411ce1e-ac09-4427-ab32-f8dc7a57e566","title":"同题仙游观","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["仙台下见五城楼，风物凄凄宿雨收。","山色遥连秦树晚，砧声近报汉宫秋。","疎松影落空坛静，细草香闲小洞幽。","何用别寻方外去，人间亦自有丹丘。"],"theme":"山水田园","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":["婉约"],"mood":"恬淡","mood2":["愁怨"],"scene":["秋","楼","雨"],"cats":{"四季":["秋天"]},"theme_conf":0.85},{"uid":"15fac24c-4cf1-424d-8758-511f755aa8fc","title":"除夜","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁阴穷暮纪，献节启新芳。","冬尽今宵促，年开明日长。","冰消出镜水，梅散入风香。","对此欢终宴，倾壶待曙光。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["夜","冬"],"cats":{"四季":["冬天"]},"theme_conf":0.98},{"uid":"3e046bc6-cc22-4226-90f8-5d8793fb343e","title":"和薛秀才寻梅花同饮见赠","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忽惊林下发寒梅，便试花前饮冷杯。","白马走迎诗客去，红筵铺待舞人来。","歌声怨处微微落，酒气熏时旋旋开。","若到岁寒无雨雪，犹应醉得两三回。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["冬","酒","花"],"cats":{"四季":["冬天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"f699ef22-319a-481b-8575-103300613ab9","title":"仆射来示有三春向晚四者难幷之说诚哉是言辄引起题重为联句疲兵再战勍敌难降下笔之时冁然自哂走呈仆射兼简尚书","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三春今向晚，四者昔难幷。","借问低眉坐，何如携手行。","旧游多过隙，新宴且寻盟。","鹦鹉林须乐，麒麟阁未成。","分阴当爱惜，迟景好逢迎。","林野熏风起，楼台谷雨晴。","墙低山半出，池广水初平。","桥转长虹曲，舟回小鹢轻。","残花犹布绣，密竹自闻笙。","欲过芳菲节，难忘宴慰情。","月轮行似箭，时物始如倾。","见雁随兄去，听莺求友声。","蕙长书带展，菰嫩剪刀生。","坐密衣裳暖，堂虚丝管清。","峰峦侵碧落，草木近朱明。","与点非沂水，陪膺是洛城。","拨醅争绿醑，卧酪待朱樱。","几处能留客，何人唤解酲。","旧仪尊右揆，新命宠春卿。","有喜鹊频语，无机鸥不惊。","青林思小隐，白雪仰芳名。","访旧殊千里，登高赖九城。","酂侯司管钥，疏傅傲簪缨。","纶綍曾同掌，烟霄即上征。","册庭尝接武，书殿忝连衡。","兰室春弥馥，松心晚更贞。","琴招翠羽下，钩掣紫鳞呈。","只愿回乌景，谁能避兕觥。","方知醉兀兀，应是走营营。","凤阁鸾台路，从他年少争。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"21bf8b8a-d5c1-4146-b572-31d2372a6474","title":"杂曲歌辞 少年行三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["五陵年少金市东，银鞍白马度春风。","落花踏尽游何处？笑入胡姬酒肆中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"人生":["青春"]},"theme_conf":1.0},{"uid":"a335f6c4-e9df-47d5-879d-9ebd3c1baf5c","title":"北征","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["皇帝二载秋，闰八月初吉。","杜子将北征，苍茫问家室。","维时遭艰虞，朝野少暇日。","顾慙恩私被，诏许归蓬荜。","拜辞诣阙下，怵惕久未出。","虽乏谏诤姿，恐君有遗失。","君诚中兴主，经纬固密勿。","东胡反未已，臣甫愤所切。","挥涕恋行在，道途犹恍惚。","乾坤含疮痍，忧虞何时毕。","靡靡逾阡陌，人烟眇萧瑟。","所遇多被伤，呻吟更流血。","回首凤翔县，旌旗晚明灭。","前登寒山重，屡得饮马窟。","邠郊入地底，泾水中荡潏。","猛虎立我前，苍崖吼时裂。","菊垂今秋花，石戴古车辙。","青云动高兴，幽事亦可悦。","山果多琐细，罗生杂橡栗。","或红如丹砂，或黑如点漆。","雨露之所濡，甘苦齐结实。","缅思桃源内，益叹身世拙。","坡陀望鄜畤，岩谷互出没。","我行已水滨，我仆犹木末。","鸱鸟鸣黄桑，野鼠拱乱穴。","夜深经战场，寒月照白骨。","潼关百万师，往者散何卒。","遂令半秦民，残害为异物。","况我堕胡尘，及归尽华发。","经年至茅屋，妻子衣百结。","恸哭松声回，悲泉共幽咽。","平生所娇儿，颜色白胜雪。","见耶背面啼，垢腻脚不韤。","床前两小女，补绽才过膝。","海图坼波涛，旧绣移曲折。","天吴及紫凤，颠倒在裋褐。","老夫情怀恶，呕泄卧数日。","那无囊中帛，救汝寒凛栗。","粉黛亦解苞，衾裯稍罗列。","瘦妻面复光，痴女头自栉。","学母无不为，晓妆随手抹。","移时施朱铅，狼藉画眉阔。","生还对童穉，似欲忘饥渴。","问事竞挽须，谁能即嗔喝。","飜思在贼愁，甘受杂乱聒。","新归且慰意，生理焉能说。","至尊尚蒙尘，几日休练卒。","仰观天色改，坐觉祅气豁。","阴风西北来，惨澹随回鹘。","其王愿助顺，其俗善驰突。","送兵五千人，驱马一万匹。","此辈少为贵，四方服勇决。","所用皆鹰腾，破敌过箭疾。","圣心颇虚伫，时议气欲夺。","伊洛指掌收，西京不足拔。","官军请深入，蓄锐何俱发。","此举开青徐，旋瞻略恒碣。","昊天积霜露，正气有肃杀。","祸转亡胡岁，势成擒胡月。","胡命其能久，皇纲未宜绝。","忆昨狼狈初，事与古先别。","奸臣竟葅醢，同恶随荡析。","不闻夏殷衰，中自诛褒妲。","周汉获再兴，宣光果明哲。","桓桓陈将军，仗钺奋忠烈。","微尔人尽非，于今国犹活。","凄凉大同殿，寂寞白兽闼。","都人望翠华，佳气向金阙。","园陵固有神，埽洒数不缺。","煌煌太宗业，树立甚宏达。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":["绮丽","悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["秋","山","夜","夏","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天","秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"cp2a47b894761820","title":"青玉案","author":"无名氏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一年春事都来几。","早过了、三之二。","绿暗红嫣浑可事。","绿杨庭院，暖风帘幕，有个人憔悴。","买花载酒长安市。","又争似家山见桃李。","不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"婉约","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["春","园林"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"]},"theme_conf":0.571},{"uid":"f7cbf2e2-135e-4220-931b-aa406aff8545","title":"感古四首 二","author":"卢仝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["人生何所贵，所贵有终始。","昨日盈尺璧，今朝尽瑕弃。","苍蝇点垂棘，巧舌成锦绮。","箕子为之奴，比干谏而死。","仲尼鲁司寇，出走为群婢。","假如屈原醒，其奈一国醉。","一国醉号呶，一人行清高。","便欲激颓波，此事真徒劳。","上山逢猛虎，入海逢巨鼇。","王者苟不死，腰下鱼鳞刀。","东海波连天，三度成桑田。","高岸高于屋，斯须变溪谷。","天地犹尚然，人情难久全。","夜半白刃讐，旦来金石坚。","萧绶既解坼，陈印亦弃捐。","竭节遇刀割，输忠遭祸缠。","不予衾之眠，信予衾之穿。","镜明不自照，膏润徒自煎。","抱剑长太息，泪堕秋风前。"],"theme":"山水田园","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"悲怆","mood2":[],"scene":["端午","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.487},{"uid":"6326d175-7980-4cbc-9237-62120d12a482","title":"献荥阳公诗五十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑驿骑翩翩，丘门子弟贤。","文翁开学日，正礼骋途年。","骏骨黄金买，英髦绛帐延。","趋风皆蹀足，侍坐各差肩。","解榻招徐穉，登楼引仲宣。","凤攒题字扇，鱼落讲经筵。","盛气河包济，贞姿岳柱天。","臯夔当五百，邹鲁重三千。","科斗翻腾取，关雎教授先。","篆垂朝露滴，诗缀夜珠联。","逸礼多心匠，焚书旧口传。","陈遵修尺牍，阮瑀让飞牋。","中的颜初启，抽毫踵未旋。","森罗万木合，属对百花全。","词海跳波涌，文星拂坐悬。","戴冯遥避席，祖逖后施鞭。","西蜀凌云赋，东阳咏月篇。","劲芟鼇足断，精贯虱心穿。","浩汗神弥王，鹞飏兴欲仙。","冰壶通皓雪，绮树眇晴烟。","驱驾雷霆走，铺陈锦绣鲜。","情机登穾奥，流韵溢山川。","墨客膺潜服，谈宾膝误前。","张鳞定摧败，折角反矜怜。","句句推琼玉，声声播管弦。","纤新撩造化，澒洞斡陶甄。","卫磬琤鍧极，齐竽僭滥偏。","空虚慙炙輠，点窜许怀铅。","惫色秋来草，哀吟雨后蝉。","自伤魂惨沮，何暇思幽玄。","喜到樽罍侧，愁亲几案边。","菁华知竭矣，胏腑尚求旃。","抵滞浑成醉，徘徊转慕膻。","老叹才渐少，闲苦病相煎。","瓦砾难追琢，刍荛分弃捐。","漫劳成恳恳，那得美娟娟。","拙劣仍非速，迂愚且异专。","移时停笔砚，挥景乏戈鋋。","仪舌忻犹在，舒帷誓不褰。","会将连献楚，深耻谬游燕。","蒲有临书叶，韦充读易编。","沙须披见宝，经拟带耕田。","入雾长期闰，持朱本望研。","轮辕呈曲直，凿枘取方圆。","呼吸宁徒尔，沾濡岂浪然。","过箫资响亮，随水涨沦涟。","惜日看圭短，偷光恨壁坚。","勤勤雕朽木，细细导蒙泉。","传癖今应甚，头风昨已痊。","丹青公旧物，一为变蚩妍。"],"theme":"应制干谒","theme2":["山水田园","应制干谒","羁旅思乡"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["慷慨"],"scene":["酒","雪","冬","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.98},{"uid":"0174cbbc-31fa-4daf-b1cf-7f91c6a646a9","title":"赋得古原草送别","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["离离原上草，一岁一枯荣。","野火烧不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孙去，萋萋满别情。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":0.662},{"uid":"89799bab-6157-4af8-a292-46807a9ed427","title":"春日即事二首 一","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["诗书成志业，嬾慢致蹉跎。","圣代丹霄远，明时白发多。","浅谋堪自笑，穷巷忆谁过。","寂寞前山暮，归人樵采歌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["春"],"cats":{"抒情":["思念","孤独"],"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"cpa5a53502587e8e","title":"御街行","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["街南绿树春饶絮。","雪满游春路。","树头花艳杂娇云，树底人家朱户。","北楼闲上，疏帘高卷，直见街南树。","阑干倚尽犹慵去。","几度黄昏雨。","晚春盘马踏青苔，曾傍绿阴深驻。","落花犹在，香屏空掩，人面知何处。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","花","清明","雪","雨"],"cats":{"四季":["春天"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"519750da-fa09-4e97-a520-42a78269efaf","title":"山春洞","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["引烛踏仙泥，时时乱乳燕。","不知何道士，手把灵书卷。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"afa11a8c-8bce-408c-a688-2af0cc6632b5","title":"琴曲歌辞 胡笳十八拍 第八拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昔私家恣娇小，远取珍禽学驯扰。","如今沦弃念故乡，悔不当初放林表。","朔风萧萧寒日暮，星河寥落胡天晓。","旦夕思归不得归，愁心想似笼中鸟。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":["愁怨"],"scene":["冬"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["冬天"],"天气":["写风","星星"]},"theme_conf":0.446},{"uid":"ef96daf2-7596-4663-8431-901daf08fafa","title":"美人尝茶行","author":"崔珏","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["云鬟枕落困春泥，玉郎为碾瑟瑟尘。","闲教鹦鹉啄窗响，和娇扶起浓睡人。","银瓶贮泉水一掬，松雨声来乳花熟。","朱唇啜破绿云时，咽入香喉爽红玉。","明眸渐开横秋水，手拨丝簧醉心起。","台时却坐推金筝，不语思量梦中事。"],"theme":"爱情相思","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["花","春","秋","雨"],"cats":{"四季":["春天","秋天"],"人物":["女子"],"食物":["写茶"]},"theme_conf":0.62},{"uid":"a3c6b2bf-35cf-40dc-bbcf-cfb5efa9f82e","title":"送褚大落第东归","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["离琴弹苦调，美人惨向隅。","顷来荷策干明主，还复扁舟归五湖。","汉家侧席明扬久，岂意遗贤在林薮。","玉堂金马隔青云，墨客儒生皆白首。","昨梦芳洲采白苹，归期且喜故园春。","稚子只思陶令至，文君不厌马卿贫。","剡中风月久相忆，池上旧游应再得。","酒熟宁孤芳杜春，诗成不枉青山色。","念此那能不羡归，长杨谏猎事皆违。","他日东流一乘兴，知君为我扫荆扉。"],"theme":"送别","theme2":["羁旅思乡"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":["欢愉","孤寂"],"scene":["舟","园林","江","春"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["春天"],"人物":["女子","儿童"],"人生":["梦想"]},"theme_conf":0.361},{"uid":"77a60918-aade-46c7-92f5-744c1f6d025c","title":"送人赴举","author":"郑巢","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["篇章动玉京，坠叶满前程。","旧国与僧别，秋江罢钓行。","马过隋代寺，樯出楚山城。","应近嵩阳宿，潜闻瀑布声。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","江","山"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.613},{"uid":"7bafe460-9265-428c-ab3e-1d2844809efa","title":"吴姬十首 三","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["滴滴春霖透荔枝，笔题牋动手中垂。","天阴不得君王召，嚬著青蛾作小诗。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","春","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.97},{"uid":"8b73dd1d-d744-4620-965f-163b4b45127d","title":"南中春意","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入仕无知言，游方随世道。","平生愿开济，遇物干怀抱。","已阻青云期，甘同散樗老。","客游南海曲，坐见韶阳蚤。","旧国别佳人，他乡思芳草。","惜无鸿鹄翅，安得凌苍昊。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["女子"],"人生":["梦想"]},"theme_conf":0.618},{"uid":"cp8d50fc0d263aa9","title":"蝶恋花","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["醉别西楼醒不记。","春梦秋云，聚散真容易。","斜月半窗还少睡。","画屏闲展吴山翠。","衣上酒痕诗里字。","点点行行，总是凄凉意。","红烛自怜无好计。","夜寒空替人垂泪。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":["绮丽","豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["酒","花","春","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"]},"theme_conf":0.84},{"uid":"9e10394a-b2cf-4f84-a07c-2b1103966824","title":"秋野五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["身许麒膦画，年衰鸳鹭群。","大江秋易盛，空峡夜多闻。","径隐千重石，帆留一片云。","儿童解蛮语，不必作参军。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["长江"],"人物":["儿童"]},"theme_conf":0.72},{"uid":"64ce1225-6e8b-46b5-b1df-50a4cba1f0f3","title":"晚发江宁道中呈严维","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["惆怅遥江路，萧条落日过。","蝉鸣独树急，鸦向古城多。","转曲随青嶂，因高见白波。","潘生秋径草，严子意如何。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["江","秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["江河"]},"theme_conf":0.86},{"uid":"d1c29cbc-5e59-4332-8a20-033c7524e3d0","title":"杂曲歌辞 少年行三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见淮南少年游侠客，白日毬猎夜拥掷。","呼卢百万终不惜，报讐千里如咫尺。","少年游侠好经过，浑身装束皆绮罗。","兰蕙相随喧妓女，风光去处满笙歌。","骄矜自言不可有，侠士堂中养来久。","好鞍好马乞与人，十千五千旋沽酒。","赤心用尽为知己，黄金不惜栽桃李。","桃李栽来几度春，一回花落一回新。","府县尽为门下客，王侯皆是平交人。","男儿百年且乐命，何须徇书受贫病。","男儿百年且荣身，何须徇节甘风尘。","衣冠半是征战士，穷儒浪作林泉民。","遮莫枝根长百丈，不如当代多还往。","遮莫姻亲连帝城，不如当身自簪缨。","看取富贵眼前者，何用悠悠身后名。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["旷达"],"mood":"慷慨","mood2":[],"scene":["春","酒"],"cats":{"抒情":["友情","思乡"],"四季":["春天"],"人生":["青春","战争"]},"theme_conf":0.441},{"uid":"b700208d-d859-4e36-96bf-883c81d4df0f","title":"谷口书斋寄杨补阙","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["泉壑带茅茨，云霞生薜帷。","竹怜新雨后，山爱夕阳时。","闲鹭栖常早，秋花落更迟。","家童扫萝迳，昨与故人期。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["山","秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.9},{"uid":"3ab356ea-69fc-43ff-b74c-4ece4a0b8277","title":"杂曲歌辞 长安少年行十首 一","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["金紫少年郎，绕街鞍马光。","身从左中尉，官属右春坊。","刬戴扬州帽，重熏异国香。","垂鞭踏青草，来去杏园芳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["清明","花","春","园林"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"3f3870ea-0cc1-4829-971c-b9f5fc7283a9","title":"相和歌辞 挽歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丹旐何飞扬，素骖亦悲鸣。","晨光照闾巷，輀车俨欲行。","萧条九月天，哀挽出重城。","借问送者谁，妻子与弟兄。","苍苍上古原，峨峨开新茔。","含酸一恸哭，异口同哀声。","旧垄转芜绝，新坟日罗列。","春风草绿北邙山，此地年年生死别。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["清新"],"mood":"悲怆","mood2":[],"scene":["春","月"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"]},"theme_conf":0.99},{"uid":"0b722208-9e02-4dac-9ec5-979859eea818","title":"正月三日归溪上有作简院内诸公","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野外堂依竹，篱边水向城。","蚁浮仍腊味，鸥泛已春声。","药许隣人㔉，书从稚子擎。","白头趋幕府，深觉负平生。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","园林","春"],"cats":{"四季":["春天"],"天气":["月亮"],"人物":["儿童"]},"theme_conf":0.772},{"uid":"70580fb2-022f-4fea-9944-776f5637d835","title":"和韦开州盛山十二首 桃坞","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["春坞桃花发，多将野客游。","日西殊未散，看望酒缸头。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","酒"],"cats":{"四季":["春天"],"植物":["桃花"]},"theme_conf":0.515},{"uid":"2cd54f56-4ee1-4e91-827b-d6874acd09b2","title":"题花叶诗","author":"德宗宫人","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["一入深宫里，无由得见春。","题诗花叶上，寄与接流人。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"植物":["叶子"]},"theme_conf":0.653},{"uid":"bb4a1d16-2a2e-4a68-9732-77e2bfafde5e","title":"奉酬北海李太守丈人夏日平阴亭","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["天子股肱守，丈人山岳灵。","出身侍丹墀，举翮凌青冥。","当昔皇运否，人神俱未宁。","谏官莫敢议，酷吏方专刑。","谷永独言事，匡衡多引经。","两朝纳深衷，万乘无不听。","盛烈播南史，雄词豁东溟。","谁谓整隼旟，翻然忆柴扃。","寄书汶阳客，廻首平阴亭。","开封见千里，结念存百龄。","隐轸江山丽，氛氲兰茝馨。","自怜遇时休，漂泊随流萍。","春野变木德，夏天临火星。","一生徒羡鱼，四十犹聚萤。","从此日闲放，焉能怀拾青。"],"theme":"寄赠酬答","theme2":[],"style":"旷达","style2":["豪放"],"mood":"相思","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["思念","孤独"],"四季":["夏天"],"天气":["太阳"]},"theme_conf":0.76},{"uid":"9b51ca3b-92b6-4a73-b382-201a23ac190f","title":"柏学士茅屋","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["碧山学士焚银鱼，白马却走身岩居。","古人已用三冬足，年少今开万卷余。","晴云满户团倾盖，秋水浮阶溜决渠。","富贵必从勤苦得，男儿须读五车书。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","冬","秋"],"cats":{"四季":["秋天","冬天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"869a90a2-6d0b-4c59-90c4-f6c2ec8ab6b6","title":"暮春游长沙东湖赠辛兖州巢父二首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["回环路不尽，历览意弥新。","古木畬田火，澄江荡桨人。","缓歌寻极浦，一醉送残春。","莫恨长沙远，他年忆此辰。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春","江"],"cats":{"抒情":["思念"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.78},{"uid":"a44b9d2a-65fb-40d6-ba19-6cea71b89b53","title":"种莴苣","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阴阳一错乱，骄蹇不复理。","枯旱于其中，炎方惨如毁。","植物半蹉跎，嘉生将已矣。","云雷歘奔命，师伯集所使。","指麾赤白日，澒洞青光起。","雨声先已风，散足尽西靡。","山泉落沧江，霹雳犹在耳。","终朝纡飒沓，信宿罢潇洒。","堂下可以畦，呼童对经始。","苣兮蔬之常，随事蓺其子。","破块数席间，荷锄功易止。","两旬不甲坼，空惜埋泥滓。","野苋迷汝来，宗生实于此。","此辈岂无秋，亦蒙寒露委。","飜然出地速，滋蔓户庭毁。","因知邪干正，掩抑至没齿。","贤良虽得禄，守道不封己。","拥寒败芝兰，众多盛荆杞。","中园陷萧艾，老圃永为耻。","登于白玉盘，借以如霞绮。","苋也无所施，胡颜入筐篚。"],"theme":"山水田园","theme2":["节令风俗"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":["孤寂"],"scene":["园林","夏","秋"],"cats":{"四季":["夏天","秋天"],"生活":["田野"]},"theme_conf":0.6},{"uid":"e4a87504-f9a3-4599-b770-aba4afd3cb04","title":"杂曲歌辞 渭城曲","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谓城朝雨浥轻尘，客舍青青柳色春。","劝君更尽一杯酒，西出阳关无故人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","春"],"cats":{"抒情":["友情"],"四季":["春天"]},"theme_conf":0.589},{"uid":"c6b86ec1-0218-4426-96a9-ee66e88cd449","title":"别崔少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["知君少得意，汶上掩柴扉。","寒食仍留火，春风未授衣。","皆言黄绶屈，早向青云飞。","借问他乡事，今年归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","春"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.538},{"uid":"05d03b46-d786-4acf-995e-a20721f16583","title":"秋莺","author":"后主煜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["残莺何事不知秋，横过幽林尚独游。","老舌百般倾耳听，深黄一点入烟流。","栖迟背世同悲鲁，浏亮如笙碎在缑。","莫更留连好归去，露华凄冷蓼花愁。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","春","鸟"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"c5082a98-967f-45dd-aa62-6a0217f71d65","title":"见上林春鴈翔青云寄杨起居李员外","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上林春更好，宾鴈不知归。","顾影怜青籞，传声入紫微。","夜陪池鹭宿，朝出苑花飞。","宁忆寒乡侣，鸾凰一见稀。"],"theme":"咏物","theme2":["山水田园","羁旅思乡"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.78},{"uid":"35319d7e-9cf6-43b0-bfa3-991cf82a49f9","title":"相和歌辞 子夜四时歌四首 冬歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"],"theme":"闺情宫怨","theme2":["羁旅思乡","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"]},"theme_conf":0.347},{"uid":"eb1817f2-140c-47c4-b6f3-0f374d7eaded","title":"谒禹庙","author":"徐浩","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["亩浍敷四海，川源涤九州。","既膺九命锡，乃建洪范畴。","鼎革固天启，运兴匪人谋。","肇开宅土业，永庇昏垫忧。","山足灵庙在，门前清镜流。","象筵陈玉帛，容卫俨戈矛。","探穴图书朽，卑宫堂殿修。","梅梁今不坏，松祏古仍留。","负责故乡近，朅来申俎羞。","为鱼知造化，叹凤仰徽猷。","不复闻夏乐，唯余奏楚幽。","婆娑非舞羽，镗鞳异鸣球。","盛德吾无间，高功谁与俦。","灾淫破凶慝，祚圣拥神休。","出谷莺初语，空山猨独愁。","春晖生草树，柳色暖汀洲。","恩贷题舆重，荣殊衣锦游。","宦情同械击，生理任桴浮。","地极临沧海，天遥过斗牛。","精诚如可谅，他日寄冥搜。"],"theme":"山水田园","theme2":["边塞征战","咏史怀古"],"style":"豪放","style2":["清新","绮丽"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["江","春"],"cats":{"抒情":["思乡","伤感","孤独","怀古","感恩"],"四季":["春天"]},"theme_conf":0.4},{"uid":"a8133806-1aeb-44d9-8b5e-6309fe6bd8cb","title":"同吕员外酬田著作幕门军西宿盘山秋夜作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碛路天早秋，边城夜应永。","遥传戎旅作，已报关山冷。","上将顿盘阪，诸军徧泉井。","绸缪阃外书，慷慨幕中请。","能使勋业高，动令氛雾屏。","远途能自致，短步终难骋。","羽翮时一看，穷愁始三省。","人生感然诺，何啻若形影。","白发知苦心，阳春见佳境。","星河连塞络，刁斗兼山静。","忆君霜露时，使我空引领。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","夜","山","塞外"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.428},{"uid":"1274d774-d716-4705-8497-c3cdd510a7c0","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 早梅桥","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["早梅花，满枝发。","东风报春春未彻，紫萼迎风玉珠裂。","杨柳未黄莺结舌，委素飘香照新月。","桥边一树伤离别，游荡行人莫攀折。","不竞江南艳阳节，任落东风伴春雪。"],"theme":"送别","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","冬","花","雪"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.576},{"uid":"96314951-671b-423f-a172-4f10ec08a6f2","title":"初秋夜坐赠吴武陵","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["稍稍雨侵竹，翻翻鹊惊丛。","美人隔湘浦，一夕生秋风。","积雾杳难极，沧波浩无穷。","相思岂云远，即席莫与同。","若人抱奇音，朱弦緪枯桐。","清商激西颢，泛滟凌长空。","自得本无作，天成谅非功。","希声閟大朴，聋俗何由聪。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":0.95},{"uid":"2d66a9e4-7b4d-4be4-91fd-6a4b2cd8817b","title":"听安万善吹觱篥歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["南山截竹为觱篥，此乐本自龟兹出。","流传汉地曲转奇，凉州胡人为我吹。","傍邻闻者多叹息，远客思乡皆泪垂。","世人解听不解赏，长飙风中自来往。","枯桑老柏寒飕飗，九雏鸣凤乱啾啾。","龙吟虎啸一时发，万籁百泉相与秋。","忽然更作渔阳掺，黄云萧条白日暗。","变调如闻杨柳春，上林繁花照眼新。","岁夜高堂列明烛，美酒一杯声一曲。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"欢愉","mood2":["恬淡"],"scene":["酒","夜","秋","春"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"]},"theme_conf":0.547},{"uid":"d06f921a-9125-4a21-aad1-f98a429e4727","title":"扬旗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江雨飒长夏，府中有余清。","我公会宾客，肃肃有异声。","初筵阅军装，罗列照广庭。","庭空六马入，𫘟騀扬旗旌。","回回偃飞盖，熠熠迸流星。","来缠风飙急，去擘山岳倾。","材归俯身尽，妙取略地平。","虹霓就掌握，舒卷随人轻。","三州陷犬戎，但见西岭青。","公来练猛士，欲夺天边城。","此堂不易升，庸蜀日已宁。","吾徒且加餐，休适蛮与荆。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":[],"mood":"相思","mood2":[],"scene":["山","夏","园林"],"cats":{"抒情":["思乡"],"四季":["夏天"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"bad7958c-eafc-4acb-8c6a-663f745cb133","title":"奉和鄜州刘大夫麦秋出师遮虏有怀中朝亲故","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["天子爱全才，故人雄外台。","绿油登上将，青绶亚中台。","亭障鸣笳入，风云转斾来。","兰坊分杳杳，麦垅望莓莓。","月向雕弓满，莲依宝劒开。","行师齐鹤列，锡马尽龙媒。","壮志征梁甫，嘉招萃楚材。","千寻推直干，百炼去纤埃。","间阔劳相望，欢言幸早陪。","每联花下骑，几泛竹间杯。","芳讯双鱼远，流年两鬓催。","何时介圭觐，携手咏康哉。"],"theme":"边塞征战","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["秋","楼","花"],"cats":{"四季":["秋天"],"人生":["励志","时光","梦想"]},"theme_conf":0.82},{"uid":"d12edd29-d467-4b19-b3f5-533fa5c8d56a","title":"秋夕","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红烛秋光冷画屏，轻罗小扇扑流萤。","天阶夜色凉如水，坐看牵牛织女星。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"27246964-80bd-4b60-ae59-0921b0832948","title":"赠别沈四逸人","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["沈侯未可测，其况信浮沈。","十载常独坐，几人知此心。","乘舟蹈沧海，买劒投黄金。","世务不足烦，有田西山岑。","我来遇知己，遂得开清襟。","何意阃阈间，沛然江海深。","疾风扫秋树，濮上多鸣砧。","耿耿尊酒前，联雁飞愁音。","平生重离别，感激对孤琴。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["江","秋","舟","酒"],"cats":{"抒情":["友情","离别","孤独"],"四季":["秋天"]},"theme_conf":0.711},{"uid":"7bdd44ad-6a7e-4c17-802a-c88127770ca2","title":"秋日台中寄怀简诸僚","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["宪府日多事，秋光照碧林。","干云岩翠合，布石地苔深。","忧悔耿遐抱，尘埃缁素襟。","物情牵跼促，友道旷招寻。","颓节风霜变，流年芳景侵。","池荷足幽气，烟竹又繁阴。","簪组赤墀恋，池鱼沧海心。","涤烦滞幽赏，永度瑶华音。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.9},{"uid":"fc1ccfae-5091-4e0a-9b84-2e2cdecd6f78","title":"虹藏不见","author":"徐敞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迎冬小雪至，应节晚虹藏。","玉气徒成象，星精不散光。","美人初比色，飞鸟罢呈祥。","石涧收晴影，天津失彩梁。","霏霏空暮雨，杳杳暎残阳。","舒卷应时令，因知圣历长。"],"theme":"节令风俗","theme2":["山水田园"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["雨","冬","雪"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.96},{"uid":"7201ac2c-75bd-495d-a203-339fb042959a","title":"相和歌辞 子夜四时歌六首 冬歌二首 二","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["帷横双翡翠，被卷两鸳鸯。","婉态不自得，宛转君王床。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["爱情"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"56ca5b29-4bb9-4f12-9200-6bc7c72e4e47","title":"秋登兰山寄张五","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北山白云里，隐者自怡悦。","相望试登高，心飞逐鸟灭。","愁因薄暮起，兴是清秋发。","时见归村人，沙行渡头歇。","天边树若荠，江畔舟如月。","何当载酒来，共醉重阳节。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["豪放"],"mood":"相思","mood2":["愁怨"],"scene":["秋","重阳","山"],"cats":{"抒情":["伤感"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"a64899a4-3471-40d4-a63a-336d1b9145c0","title":"自蜀奉册命往朔方途中呈韦左相文部房尚书门下崔侍郎","author":"贾至","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡羯乱中夏，銮舆忽南巡。","衣冠陷戎寇，狼狈随风尘。","豳公秉大节，临难不顾身。","激昂白刃前，溅血下沾巾。","尚书抱忠义，历险披荆榛。","扈从出剑门，登翼岷江滨。","时望挹侍郎，公才标缙绅。","亭亭昆山玉，皎皎无缁磷。","顾惟乏经济，扞牧陪从臣。","永愿雪会稽，仗剑清咸秦。","太皇时内禅，神器付嗣君。","新命集旧邦，至德被远人。","捧册自南服，奉诏趋北军。","觐谒心载驰，违离难重陈。","策马出蜀山，畏途上缘云。","饮啄丛箐间，栖息虎豹群。","崎岖凌危栈，惴栗惊心神。","峭壁上嵚岑，大江下沄沄。","皇风扇八极，异类怀深仁。","元凶诱黠虏，肘腋生妖氛。","明主信英武，威声赫四邻。","誓师自朔方，旗帜何缤纷。","铁骑照白日，旄头拂秋旻。","将来荡沧溟，宁止蹴昆仑。","古来有屯难，否泰长相因。","夏康缵禹绩，代祖复汉勋。","于役各勤王，驱驰拱紫宸。","岂惟太公望，往昔逢周文。","谁谓三杰才，功业独殊伦。","感此慰行迈，无为歌苦辛。"],"theme":"应制干谒","theme2":["边塞征战"],"style":"幽峭","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["夏","雪"],"cats":{"四季":["夏天"],"山水":["长江"]},"theme_conf":0.76},{"uid":"00a2e26b-5799-453b-bdc1-16b870e092be","title":"清明二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["此身飘泊苦西东，右臂偏枯半耳聋。","寂寂系舟双下泪，悠悠伏枕左书空。","十年蹴鞠将雏远，万里秋千习俗同。","旅雁上云归紫塞，家人钻火用青枫。","秦城楼阁烟花里，汉主山河锦绣中。","风水春来洞庭阔，白苹愁杀白头翁。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"沉郁","style2":["冲淡","绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["清明","楼","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"节日":["清明节"]},"theme_conf":0.8},{"uid":"5aa3def9-8feb-467b-9f28-84df62f0c714","title":"喜钱左丞再除华州以诗伸贺","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["左辖辍中台，门东委上才。","彤襜经宿到，绛帐及春开。","民望恳难夺，天心慈易回。","那知不隔岁，重借寇恂来。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["老师"]},"theme_conf":0.96},{"uid":"26f085ee-d6b5-4461-9197-8ada7ead97fe","title":"与孟郊洛北野泉上煎茶","author":"刘言史","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["粉细越笋芽，野煎寒溪滨。","恐乖灵草性，触事皆手亲。","敲石取鲜火，撇泉避腥鳞。","荧荧爨风铛，拾得坠巢薪。","洁色既爽别，浮氲亦慇懃。","以兹委曲静，求得正味真。","宛如摘山时，自歠指下春。","湘瓷泛轻花，涤尽昏渴神。","此游惬醒趣，可以话高人。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"婉约","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"食物":["写茶"]},"theme_conf":0.477},{"uid":"cp841ff9b4d78bde","title":"湘春夜月","author":"黄孝迈","dynasty":"宋","section":"宋词","form":"词","paragraphs":["近清明。","翠禽枝上消魂。","可惜一片清歌，都付与黄昏。","欲共柳花低诉，怕柳花轻薄，不解伤春。","念楚乡旅宿，柔情别绪，谁与温存。","空樽夜泣，青山不语，残月当门。","翠玉楼前，惟是有、一波湘水，摇荡湘云。","天长梦短，问甚时、重见桃根。","这次第，算人间没个并刀，翦断心上愁痕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["悲怆","相思"],"scene":["夜","春","月"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.477},{"uid":"cp49f286ee613c2d","title":"秋霁","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["江水苍苍，望倦柳愁荷，共感秋色。","废阁先凉，古帘空暮，雁程最嫌风力。","故园信息。","爱渠入眼南山碧。","念上国。","谁是、脍鲈江汉未归客。","还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。","露蛩悲、清灯冷屋，翻书愁上鬓毛白。","年少俊游浑断得。","但可怜处，无奈苒苒魂惊，采香南浦，翦梅烟驿。"],"theme":"羁旅思乡","theme2":["送别"],"style":"清新","style2":["幽峭","沉郁"],"mood":"愁怨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["秋天"]},"theme_conf":0.643},{"uid":"565d931a-ff49-4f37-b633-524b48c2f4f0","title":"寻陆鸿渐不遇","author":"皎然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["移家虽带郭，野径入桑麻。","近种篱边菊，秋来未著花。","扣门无犬吠，欲去问西家。","报道山中去，归时每日斜。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","山"],"cats":{"四季":["秋天"],"生活":["乡村","田野"],"动物":["写鸟"]},"theme_conf":0.439},{"uid":"e57b65b7-0644-43db-9cb7-24c1f048abd1","title":"送上官侍御","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["执简朝方下，乘轺去不赊。","感恩轻远道，入幕比还家。","碣石春云色，邯郸古树花。","飞书报明主，烽火静天涯。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"]},"theme_conf":0.558},{"uid":"80e7683d-5fdb-4cb6-96a0-c6fe3caac9fd","title":"和武相公中秋锦楼玩月 二","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["四时皆有月，一夜独当秋。","照耀初含露，裴回正满楼。","遥连雪山净，逈入锦江流。","愿以清光末，年年许从游。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"fdc07d9f-95b8-45f7-b1b3-9d272b3416a4","title":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"],"theme":"咏史怀古","theme2":["哲理悟道","边塞征战","羁旅思乡"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["秋","江"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.242},{"uid":"bb68efa3-9758-4ac2-927c-a0985c84acad","title":"答白刑部闻新蝉","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蝉声未发前，已自感流年。","一入凄凉耳，如闻断续弦。","晴清依露叶，晚急畏霞天。","何事秋卿咏，逢时亦悄然。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.86},{"uid":"496955eb-549a-4176-84d3-ab6460eaa70f","title":"桃花","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["桃花浅深处，似匀深浅妆。","春风助肠断，吹落白衣裳。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.516},{"uid":"92c10ce9-23b4-4e64-9b20-fc62a84e288c","title":"枯椶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蜀门多椶榈，高者十八九。","其皮割剥甚，虽众亦易朽。","徒布如云叶，青黄岁寒后。","交横集斧斤，凋丧先蒲柳。","伤时苦军乏，一物官尽取。","嗟尔江汉人，生成复何有。","有同枯椶木，使我沈叹久。","死者即已休，生者何自守。","啾啾黄雀啅，侧见寒蓬走。","念尔形影干，摧残没藜莠。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":0.65},{"uid":"3ce2a6ae-98e8-46bd-b9c1-05f545f7ea1d","title":"太和初靖恭里感事","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清湘吊屈原，垂泪撷苹蘩。","谤起乘轩鹤，机沈在槛猨。","乾坤三事贵，华夏一夫冤。","宁有唐虞世，心知不为言。"],"theme":"讽喻刺世","theme2":[],"style":"清新","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["夏","端午"],"cats":{"抒情":["伤感"],"四季":["夏天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"a2d1860f-cd55-488c-9c4b-3d19d5b8d3ef","title":"病后遇王倚饮赠歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["麟角凤觜世莫识，煎胶续弦奇自见。","尚看王生抱此怀，在于甫也何由羡。","且遇王生慰畴昔，素知贱子甘贫贱。","酷见冻馁不足耻，多病沈年苦无健。","王生怪我颜色恶，荅云伏枕艰难徧。","疟疠三秋孰可忍，寒热百日相交战。","头白眼暗坐有胝，肉黄皮皱命如线。","惟生哀我未平复，为我力致美殽膳。","遣人向市赊香稉，唤妇出房亲自馔。","长安冬葅酸且绿，金城土酥静如练。","兼求富豪且割鲜，密沽斗酒谐终宴。","故人情义晚谁似，令我手脚轻欲漩。","老马为驹信不虚，当时得意况深眷。","但使残年饱吃饭，只愿无事常相见。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"恬淡","mood2":["悲怆"],"scene":["冬","秋","酒"],"cats":{"抒情":["友情"],"四季":["秋天","冬天"]},"theme_conf":0.9},{"uid":"8e7a1341-509d-4548-b45e-2d223e034977","title":"送故人归蜀","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一骑西南远，翩翩入剑门。","客衣筒布润，山舍荔枝繁。","古庙祠金马，春江带白鼋。","自应成旅逸，爱客有王孙。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山","江"],"cats":{"抒情":["友情","思乡"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.623},{"uid":"f800050a-d7a0-4f12-a614-17fe23df8f41","title":"送杨氏女","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["永日方戚戚，出门复悠悠。","女子今有行，大江溯轻舟。","尔辈况无恃，抚念益慈柔。","幼为长所育，两别泣不休。","对此结中肠，义往难复留。","自小阙内训，事姑贻我忧。","赖兹托令门，仁恤庶无尤。","贫俭诚所尚，资从岂待周。","孝恭遵妇道，容止顺其猷。","别离在今晨，见尔当何秋。","居闲始自遣，临感忽难收。","归来视幼女，零泪缘缨流。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","秋"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"35c4618c-3896-45f8-9b24-51764c90383f","title":"横吹曲辞 折杨柳","author":"刘宪","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沙塞三河道，金闺二月春。","碧烟杨柳色，红粉绮罗人。","露叶怜啼脸，风花思舞巾。","攀持君不见，为听曲中新。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["塞外","春","花","月"],"cats":{"抒情":["思念","闺怨"],"四季":["春天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.5},{"uid":"333b66bc-2738-4424-aaf9-c8834be7fabe","title":"琴曲歌辞 风入松歌","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西岭松声落日秋，千枝万叶风飕飗。","美人援琴弄成曲，写得松间声断续。","声断续，清我魂，流波坏陵安足论。","美人夜坐月明里，含少商兮照清征。","风何凄兮飘飉，搅寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["夜","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.565},{"uid":"cp64b47d95c7e13e","title":"青玉案","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["三年枕上吴中路。","遣黄耳、随君去。","若到松江呼小渡。","莫惊鸥鹭，四桥尽是，老子经行处。","辋川图上看春暮。","常记高人右丞句。","作个归期天已许。","春衫犹是，小蛮针线，曾湿西湖雨。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["江南","江","春"],"cats":{"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"757a180d-55eb-4931-9f10-c71649f6a06d","title":"秋日过鸿举法师寺院便送归江陵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["看画长廊遍，寻僧一径幽。","小池兼鹤净，古木带蝉秋。","客至茶烟起，禽归讲席收。","浮杯明日去，相望水悠悠。"],"theme":"送别","theme2":["咏史怀古","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"动物":["写鸟"]},"theme_conf":0.28},{"uid":"8e2f586b-9ef4-4672-af24-723a5ec87773","title":"和令狐舍人酬峰上人题山栏孤竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["满院冰姿粉箨残，一茎青翠近帘端。","离丛自欲亲香火，抱节何妨共岁寒。","能让繁声任真籁，解将孤影对芳兰。","范云许访西林寺，枝叶须和彩凤看。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山"],"植物":["竹子"]},"theme_conf":0.381},{"uid":"f8c0f02f-21d3-4bce-acb9-eff80ce4f0c0","title":"新楼诗二十首","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿波春水湖光满，丹槛连楹碧嶂遥。","兰鹢对飞渔棹急，彩虹翻影海旗摇。","鬬疑斑虎归三岛，散作游龙上九霄。","鼍鼓若雷争胜负，柳堤花岸万人招。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春"],"cats":{"四季":["春天"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"e80bca1f-12ef-4187-b623-b614aa6bee78","title":"寄李十二白二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔年有狂客，号尔谪仙人。","笔落惊风雨，诗成泣鬼神。","声名从此大，汩没一朝伸。","文彩承殊渥，流传必绝伦。","龙舟移櫂晚，兽锦夺袍新。","白日来深殿，青云满后尘。","乞归优诏许，遇我宿心亲。","未负幽栖志，兼全宠辱身。","剧谈怜野逸，嗜酒见天真。","醉舞梁园夜，行歌泗水春。","才高心不展，道屈善无邻。","处士祢衡俊，诸生原宪贫。","稻粱求未足，薏苡谤何频。","五岭炎蒸地，三危放逐臣。","几年遭𫛳鸟，独泣向麒麟。","苏武先还汉，黄公岂事秦。","楚筵辞醴日，梁狱上书辰。","已用当时法，谁将此义陈。","老吟秋月下，病起暮江滨。","莫怪恩波隔，乘槎与问津。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒","雨","端午","舟","春","秋"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人生":["梦想"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"b86dfe06-639c-446e-ac96-298a1403d16e","title":"同群公秋登琴台","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古迹使人感，琴台空寂寥。","静然顾遗尘，千载如昨朝。","临眺自兹始，群贤久相邀。","德与形神高，孰知天地遥。","四时何倏忽，六月鸣秋蜩。","万象归白帝，平川横赤霄。","犹是对夏伏，几时有凉飙。","燕雀满簷楹，鸿鹄抟扶摇。","物性各自得，我心在渔樵。","兀然还复醉，尚握尊中瓢。"],"theme":"咏史怀古","theme2":["闲适隐逸","山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["怀古"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.408},{"uid":"eeafa160-a9d9-484d-9cbe-01a796260aa2","title":"相和歌辞 门有车马客行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["财雄重交结，戚里擅豪华。","曲台临上路，高门抵狭斜。","赭汗千金马，绣毂五香车。","白鹤随飞盖，朱鹭入鸣笳。","夏莲开劒水，春桃发露花。","轻裙染回雪，浮蚁泛流霞。","高谈辨飞兔，摛藻握灵蛇。","逢恩借羽翼，失路委泥沙。","暧暧风烟晚，路长归骑远。","日斜青琐第，尘飞金谷苑。","危弦促柱奏巴渝，遗簪堕珥解罗襦。","如何守直道，飜使谷名愚。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"相思","mood2":[],"scene":["夏","花","雪","春"],"cats":{"抒情":["思乡"],"四季":["春天","夏天"],"动物":["写马"]},"theme_conf":0.661},{"uid":"18a2193c-1bd7-4426-b17f-d02a8a4aec1b","title":"莺莺歌","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伯劳飞迟燕飞疾，垂杨绽金花笑日。","绿窗娇女字莺莺，金雀娅鬟年十七。","黄姑上天阿母在，寂莫霜姿素莲质。","门掩重关萧寺中，芳草花时不曾出。"],"theme":"哲理悟道","theme2":[],"style":"清新","style2":["冲淡"],"mood":"孤寂","mood2":["欢愉"],"scene":["鸟","春"],"cats":{"四季":["春天"],"人物":["母亲"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"9c725632-fe02-4fc7-b443-9410da36c7e5","title":"秋雨叹三首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长安布衣谁比数，反鏁衡门守环堵。","老夫不出长蓬蒿，穉子无忧走（一作「奏」）风雨。","雨声飕飕催早寒，胡雁翅湿高飞难。","秋来未曾（一作「省」）见白日，埿污后（一作「厚」）土何时干？"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","秋"],"cats":{"四季":["秋天"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"6c18667b-708f-4a2a-9c20-d4a104e36904","title":"春雪题兴善寺广宣上人竹院","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["皎洁青莲客，焚香对雪朝。","竹风催淅沥，花雨让飘飖。","触石和云积，萦池拂水消。","只应将日月，颜色不相饶。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","园林","春"],"cats":{"四季":["春天"],"天气":["写雪"],"植物":["竹子"]},"theme_conf":0.535},{"uid":"a7994f02-d08b-4d5b-9ffa-1aab1ca621a1","title":"冬夜饶州使堂饯相公五叔赴歙州","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丞相过邦牧，清弦送羽觞。","高情同客醉，子夜为人长。","斜汉这过斗，寒云正护霜。","新安江自绿，明主待惟良。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","冬","酒"],"cats":{"四季":["冬天"]},"theme_conf":0.738},{"uid":"8fd9bf41-ae6c-4def-aa3e-e6c92abc811f","title":"杂曲歌辞 出门行","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兄弟同出门，同行不同志。","凄凄分岐路，各各营所为。","兄上荆山巅，翻石辨虹气。","弟沈沧海底，偷珠待龙睡。","出门不数年，同归亦同遂。","俱用私所珍，升沈自兹异。","献珠龙王宫，值龙觅珠次。","但喜复得珠，不求珠所自。","酬客双龙女，授客六龙辔。","遣充行雨神，雨泽随客意。","雩夏钟鼓繁，禜秋玉帛积。","彩色画廊庙，奴僮被珠翠。","骥𫘧千万双，鸳鸯七十二。","言者禾稼枯，无人敢轻议。","其兄因献璞，再刖不履地。","门户亲戚疎，匡床妻妾弃。","铭心有所待，视足无所愧。","持璞自枕头，泪痕双血渍。","一朝龙醒寤，本问偷珠事。","因知行雨偏，妻子五刑备。","仁兄捧尸哭，势友掉头讳。","丧车黔首葬，吊客青蝇至。","楚有望气人，王前忽长跪。","贺王得贵宝，不远王所莅。","求之果如言，剖则浮云腻。","白珩无颜色，垂棘有瑕累。","在楚列地封，入赵连城贵。","秦遣李斯书，书为传国瑞。","秦亡汉魏传，传者得神器。","卞和名永永，与宝不相坠。","劝尔出门行，行难莫行易。","易得还易失，难同亦难离。","善贾识贪廉，良田无稙穉。","磨劒莫磨锥，磨锥成小利。"],"theme":"哲理悟道","theme2":["送别","悼亡挽歌"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["悲怆"],"scene":["夏","雨"],"cats":{"抒情":["伤感","悼亡"],"四季":["夏天"]},"theme_conf":0.8},{"uid":"cb55e33f-ee4d-4b88-a23f-280fd0cfd271","title":"杂曲歌辞 春日行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["深宫高楼入紫清，金作蛟龙盘绣楹。","佳人当窗弄白日，弦将手语弹鸣筝。","春风吹落君王耳，此曲乃是升天行。","因出天池泛蓬瀛，楼船蹙沓波浪惊。","三千双蛾献歌笑，挝钟考鼓宫殿倾。","万姓聚舞歌太平，我无为，人自宁。","三十六帝欲相迎，仙人飘翩下云𫐌。","帝不去，留镐京。","安能为轩辕，独往入窅冥。","小臣拜献南山寿，陛下万古垂鸿名。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["太阳"],"人物":["女子"]},"theme_conf":0.65},{"uid":"56f535d2-27cb-485a-9fc4-1c4f04e2131d","title":"霜菊","author":"席夔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["时令忽已变，行看被霜菊。","可怜后时秀，当此凛风肃。","淅沥翠枝翻，凄清金蘂馥。","凝姿节堪重，澄艳景非淑。","宁祛青女威，愿盈君子掬。","持来泛罇酒，永以照幽独。"],"theme":"咏物","theme2":["咏物"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["秋","重阳"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"f45104c8-145d-4f09-ac5d-1b9ac85dad65","title":"人日两篇 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["元日到人日，未有不阴时。","冰雪莺难至，春寒花较迟。","云随白水落，风振紫山悲。","蓬鬓稀疎久，无劳比素丝。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","雪","冬"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.58},{"uid":"b41e25f5-5a57-497f-a3a2-84bdfb9331f5","title":"春怨","author":"金昌绪","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["打起黄莺儿，莫教枝上啼。","啼时惊妾梦，不得到辽西。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.769},{"uid":"8b5741ba-0a9b-4a04-9ea8-fed55e797055","title":"和令狐相公九日对黄白二菊花见怀","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["素萼迎寒秀，金英带露香。","繁华照旄钺，荣盛对银黄。","琮璧交辉映，衣裳杂彩章。","晴云遥盖覆，秋蝶近悠扬。","空想逢九日，何由陪一觞。","满丛佳色在，未肯委严霜。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":[],"scene":["重阳","花"],"cats":{"四季":["秋天"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"04adc73f-5d2d-4a17-9254-28a80a52069f","title":"相和歌辞 采莲曲","author":"贺知章","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["稽山罢雾郁嵯峨，镜水无风也自波。","莫言春度芳菲尽，别有中流采芰荷。"],"theme":"爱情相思","theme2":["送别","山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":0.393},{"uid":"2b8a54fd-f08a-4f0d-a6ab-96774ef6b15b","title":"杂曲歌辞 夜坐吟","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["冬夜夜寒觉夜长，沈吟久坐坐北堂。","冰合井泉月入闺，青缸凝明照悲嗁。","青缸灭，嗁转多，掩妾泪，听君歌。","歌有声，妾有情，情声合，两无违。","一语不入意，从君万曲梁尘飞。"],"theme":"闺情宫怨","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["夜","冬"],"cats":{"抒情":["伤感","闺怨"],"四季":["冬天"]},"theme_conf":0.676},{"uid":"ef4d4ca2-59ea-4c84-b360-b63252700998","title":"同吉中孚梦桃源 一","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["春雨夜不散，梦中山亦阴。","云中碧潭水，路暗红花林。","花水自深浅，无人知古今。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["花","春","雨","夜","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人生":["梦想"],"植物":["桃花"]},"theme_conf":0.784},{"uid":"6382d668-2787-4a30-b0f2-c58a3b3b9f25","title":"相和歌辞 从军行","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["向夕临大荒，朔风轸归虑。","平沙万里余，飞鸟宿何处？","虏骑猎长原，翩翩傍河去。","边声摇白草，海气生黄雾。","百战苦风尘，十年履霜露。","虽投定远笔，未坐将军树。","早知行路难，悔不理章句。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["写风"],"人生":["战争"]},"theme_conf":0.854},{"uid":"b298777c-4db6-424c-b441-e4051bf7ecc9","title":"春日叶秀才曲江","author":"罗隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江花江草暖相隈，也向江边把酒杯。","春色恼人遮不得，别愁如疟避还来。","安排贱迹无良策，裨补明时望重才。","一曲吴歌齐拍手，十年尘眼未曾开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["江河"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"18b46e80-2f5a-46a6-90c7-04489f737d04","title":"句","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["水田飞白鹭，夏木啭黄鹂。","白马撼金珂，纷纷侍从多。","身居骠骑幕，家住滹沱河。","溪北映初星。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":1.0},{"uid":"f4227169-1e61-4208-aaeb-ebea6439eec0","title":"秋日送僧志幽归山寺","author":"秦系","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禅室绳床在翠微，松间荷笠一僧归。","磬声寂历宜秋夜，手冷灯前自衲衣。"],"theme":"送别","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.97},{"uid":"5d5532a1-5286-4ccb-abdc-6118ad48504d","title":"横吹曲辞 折杨柳","author":"乔知之","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["可怜濯濯春杨柳，攀折将来就纤手。","妾容与此同盛衰，何必君恩独能久。"],"theme":"闺情宫怨","theme2":[],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"2446f3e6-9a1f-465f-9cba-e481a62e956d","title":"暮春游长沙东湖赠辛兖州巢父二首 一","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["湘流分曲浦，缭绕古城东。","岸转千家合，林开一镜空。","人生无事少，心赏几回同。","且复忘羁束，悠悠落照中。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"人物":["父亲"]},"theme_conf":0.88},{"uid":"46013ebf-55a5-421e-a8fb-c1d55a3c67b3","title":"壮游","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往昔十四五，出游翰墨场。","斯文崔魏徒，以我似班扬。","七龄思即壮，开口咏凤皇。","九龄书大字，有作成一囊。","性豪业嗜酒，嫉恶怀刚肠。","脱略小时辈，结交皆老苍。","饮酣视八极，俗物都茫茫。","东下姑苏台，已具浮海航。","到今有遗恨，不得穷扶桑。","王谢风流远，阖庐丘墓荒。","劒池石壁仄，长洲荷芰香。","嵯峨阊门北，清庙映回塘。","每趋吴太伯，抚事泪浪浪。","枕戈忆句践，渡浙想秦皇。","蒸鱼闻匕首，除道哂要章。","越女天下白，鉴湖五月凉。","剡溪蕴秀异，欲罢不能忘。","归帆拂天姥，中岁贡旧乡。","气劘屈贾垒，目短曹刘墙。","忤下考功第，独辞京尹堂。","放荡齐赵间，裘马颇清狂。","春歌丛台上，冬猎青丘旁。","呼鹰皂枥林，逐兽云雪冈。","射飞曾纵鞚，引臂落鹙鸧。","苏侯据鞍喜，忽如携葛强。","快意八九年，西归到咸阳。","许与必词伯，赏游实贤王。","曳裾置醴地，奏赋入明光。","天子废食召，群公会轩裳。","脱身无所爱，痛饮信行藏。","黑貂不免敝，斑鬓兀称觞。","杜曲晚耆旧，四郊多白杨。","坐深乡党敬，日觉死生忙。","朱门任倾夺，赤族迭罹殃。","国马竭粟豆，官鸡输稻粱。","举隅见烦费，引古惜兴亡。","河朔风尘起，岷山行幸长。","两宫各警跸，万里遥相望。","崆峒杀气黑，少海旌旗黄。","禹功亦命子，涿鹿亲戎行。","翠华拥英岳，螭虎噉豺狼。","爪牙一不中，胡兵更陆梁。","大军载草草，凋瘵满膏肓。","备员窃补衮，忧愤心飞扬。","上感九庙焚，下悯万民疮。","斯时伏青蒲，延争守御床。","君辱敢爱死，赫怒幸无伤。","圣哲体仁恕，宇县复小康。","哭庙灰烬中，鼻酸朝未央。","小臣议论绝，老病客殊方。","郁郁苦不展，羽翮困低昂。","秋风动哀壑，碧蕙捐微芳。","之推避赏从，渔父濯沧浪。","荣华敌勋业，岁暮有严霜。","吾观鸱夷子，才格出寻常。","群凶逆未定，侧伫英俊翔。"],"theme":"咏怀抒感","theme2":["咏史怀古","边塞征战","悼亡挽歌"],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["悲怆","慷慨"],"scene":["冬","江南","酒","山","秋"],"cats":{"抒情":["伤感","悼亡","怀古"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.85},{"uid":"2e0dfd8f-821c-40ce-b802-251e56eb1ed3","title":"隄上柳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["垂柳万条丝，春来织别离。","行人攀折处，闺妾断肠时。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.403},{"uid":"8522b687-c845-4d15-9e44-b60c3df77707","title":"元日喜闻大礼寄上翰林四学士中书六舍人二十韵","author":"窦牟","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有事郊坛毕，无私日月临。","岁华春更早，天瑞雪犹深。","玉辇回时令，金门降德音。","翰飞鸳别侣，藂植桂为林。","粉泽资鸿笔，薰和本素琴。","礼成戎器下，恩彻鬼方沈。","麟爵来称纪，官师退绝箴。","道风黄阁静，祥景紫垣阴。","寿酒朝时献，农书夜直寻。","国香煴翠幄，庭燎赩红衾。","汉魏文章盛，尧汤雨露霃。","密辞投水石，精义出沙金。","宸扆亲唯敬，钧衡近匪侵。","疾驱千里骏，清唳九霄禽。","庆赐迎新服，斋庄弃旧簪。","忽思班女怨，遥听越人吟。","末路甘贫病，流年苦滞淫。","梦中青琐闼，归处碧山岑。","窃抃闻韶濩，观光想韎任。","大哉环海晏，不笇子牟心。"],"theme":"应制干谒","theme2":["送别","山水田园"],"style":"绮丽","style2":["豪放","幽峭"],"mood":"愁怨","mood2":["欢愉","相思"],"scene":["雪","月","夜","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.86},{"uid":"26cd7866-5191-4331-9520-3c807474298f","title":"棠梨花和李太尉","author":"薛涛","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴均蕙圃移嘉木，正及东溪春雨时。","日晚莺啼何所为，浅深红腻压繁枝。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"0a9b2767-706e-40b9-a423-2097e5f97d10","title":"避暑摩诃池上作","author":"后蜀嗣主孟昶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["冰肌玉骨清无汗，水殿风来暗香暖。","帘开明月独窥人，敧枕钗横云鬓乱。","起来琼户寂无声，时见疎星渡河汉。","屈指西风几时来，只恐流年暗中换。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月","园林"],"cats":{"抒情":["孤独","闺怨"],"四季":["夏天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":1.0},{"uid":"5ceea715-909e-454c-ad89-5cda63cc119d","title":"送汤中丞和蕃","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["继好中司出，天心外国知。","已传尧雨露，更说汉威仪。","陇上应回首，河源复载驰。","孤峰问徒御，空碛见旌麾。","春草乡愁起，边城旅梦移。","莫嗟行远地，此去荅恩私。"],"theme":"送别","theme2":["羁旅思乡"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["春","雨","山"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["黄河"]},"theme_conf":0.448},{"uid":"f6b75eb2-255e-4071-bf01-a5db4d409051","title":"孤雁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孤雁不饮啄，飞鸣声念群。","谁怜一片影，相失万重云。","望尽似犹见，哀多如更闻。","野鵶无意绪，鸣噪自纷纷。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.526},{"uid":"8e4f53da-0190-413d-9c18-f8043d90e2be","title":"送幽州陈参军赴任寄呈乡曲父老","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蓟北三千里，关西二十年。","冯唐犹在汉，乐毅不归燕。","人同黄鹤远，乡共白云连。","郭隗池台处，昭王尊酒前。","故人当已老，旧壑几成田。","红颜如昨日，衰鬓似秋天。","西蜀桥应毁，东周石尚全。","灞池水犹绿，榆关月早圆。","塞云初上雁，庭树欲销蝉。","送君之旧国，挥泪独澘然。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["鸟","园林","秋"],"cats":{"抒情":["友情","离别","伤感","孤独"],"四季":["秋天"],"人物":["父亲"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"ad472842-1792-451c-826d-311acb8d8b21","title":"和宋中丞夏日游福贤观天长寺寺即陈左相宅所施之作","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["已相殷王国，空余尚父谿。","钓矶开月殿，筑道出云梯。","积水浮香象，深山鸣白鸡。","虚空陈伎乐，衣服制虹霓。","墨点三千界，丹飞六一泥。","桃源勿遽返，再访恐君迷。"],"theme":"山水田园","theme2":["哲理悟道","应制干谒"],"style":"冲淡","style2":[],"mood":"惆怅","mood2":["欢愉"],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["彩虹"]},"theme_conf":0.447},{"uid":"098ed74c-c5fa-4944-9078-b76bd958fbba","title":"春日忆家","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["自觉劳乡梦，无人见客心。","空余庭草色，日日伴愁襟。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["春"],"cats":{"抒情":["思念","思乡","伤感","孤独"],"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"545f574e-4691-4405-bc8d-5c9adda64210","title":"萧员外寄新蜀茶","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["蜀茶寄到但惊新，渭水煎来始觉珍。","满瓯似乳堪持玩，况是春深酒渴人。"],"theme":"咏物","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"食物":["写茶"]},"theme_conf":0.8},{"uid":"22df0b35-cf47-4dd2-844b-1984891d5db0","title":"杂曲歌辞 春江曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["摇漾越江春，相将看白苹。","归时不觉夜，出浦月随人。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"山水":["江河"]},"theme_conf":0.9},{"uid":"14e71d5c-ff47-4b86-b37f-f79cbfbc4796","title":"季秋江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乔木村墟古，疎篱野蔓悬。","清琴将暇日，白首望霜天。","登俎黄甘重，支床锦石圆。","远游虽寂寞，难见此山川。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.75},{"uid":"cp501aea08a51a86","title":"齐天乐","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["庾郎先自吟愁赋。","凄凄更闻私语。","露湿铜铺，苔侵石井，都是曾听伊处。","哀音似诉。","正思妇无眠，起寻机杼。","曲曲屏山，夜凉独自甚情绪。","西窗又吹暗雨。","为谁频断续，相和砧杵。","候馆迎秋，离宫吊月，别有伤心无数。","豳诗漫与。","笑篱落呼灯，世间儿女。","写入琴丝，一声声更苦。"],"theme":"送别","theme2":["民生疾苦","山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["夜","秋"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"]},"theme_conf":0.404},{"uid":"cp5f02926940644e","title":"夜合花","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳锁莺魂，花翻蝶梦，自知愁染潘郎。","轻衫未揽，犹将泪点偷藏。","念前事，怯流光。","早春窥、酥雨池塘。","向销凝里，梅开半面，情满徐妆。","风丝一寸柔肠。","曾在歌边惹恨，烛底萦香。","芳机瑞锦，如何未织鸳鸯。","人扶醉，月依墙。","是当初、谁敢疏狂。","把闲言语，花房夜久，各自思量。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","夜","春"],"cats":{"抒情":["爱情","伤感"],"四季":["春天"]},"theme_conf":0.8},{"uid":"a65e5646-14b1-4f75-924b-bbf262b242d7","title":"玉阶怨","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["玉阶生白露，夜久侵罗袜。","却下水晶帘，玲珑望秋月。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋","夜","月"],"cats":{"抒情":["闺怨"],"四季":["秋天"]},"theme_conf":0.836},{"uid":"a05bf553-aa6e-49b8-8988-a104d0207473","title":"杂歌谣辞 古歌","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["落叶流风向玉台，夜寒秋思洞房开。","水精帘外金波下，云母窗前银汉回。","玉阶阴阴苔藓色，君王履綦难再得。","璇闺窈窕秋夜长，绣户徘徊秋月光。","燕姬彩帐芙蓉色，秦子金炉兰麝香。","北斗七星横夜半，清歌一曲断君肠。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","月","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"cp23f78a4e960805","title":"兰陵王","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳阴直。","烟里丝丝弄碧。","隋堤上、曾见几番，拂水飘绵送行色。","登临望故国。","谁识。","京华倦客。","长亭路，年去岁来，应折柔条过千尺。","闲寻旧踪迹。","又酒趁哀弦，灯照离席。","梨花榆火催寒食。","愁一箭风快，半篙波暖，回头迢递便数驿。","望人在天北。","凄恻。","恨堆积。","渐别浦萦回，津堠岑寂。","斜阳冉冉春无极。","念月榭携手，露桥闻笛。","沈思前事，似梦里，泪暗滴。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["清明","酒","春"],"cats":{"抒情":["离别","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.427},{"uid":"ed9ff702-9ada-422f-885d-8e4fafb39c87","title":"采莲子二首 二","author":"皇甫松","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["船动湖光滟滟秋，贪看年少信船流。","无端隔水抛莲子，遥被人知半日羞。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.764},{"uid":"5197293d-6d7e-48f7-9387-f992e9c3a2ee","title":"七月十五日题章敬寺","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["招提迩皇邑，复道连重城。","法筵会早秋，驾言访禅扃。","尝闻大仙教，清净宗无生。","七物匪吾宝，万行先求成。","名相既双寂，繁华奚所荣。","金风扇微凉，远烟凝翠晶。","松院静苔色，竹房深磬声。","境幽真虑恬，道胜外物轻。","意适本非说，含毫空复情。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡"],"scene":["月","秋"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"a2b4e8ca-92e3-4101-8a54-739b8f1d8184","title":"辋川闲居赠裴秀才迪","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒山转苍翠，秋水日潺湲。","倚杖柴门外，临风听暮蝉。","渡头余落日，墟里上孤烟。","复值接舆醉，狂歌五柳前。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":["沉郁"],"mood":"恬淡","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"]},"theme_conf":0.82},{"uid":"00f12a19-bb96-4980-a4f5-11a1b9d604dd","title":"山居秋暝","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["空山新雨后，天气晚来秋。","明月松间照，清泉石上流。","竹喧归浣女，莲动下渔舟。","随意春芳歇，王孙自可留。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"1b0eb975-d6fd-4b70-b6e6-a8ee5bbd6563","title":"同群公题郑少府田家","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑侯应凄惶，五十头尽白。","昔为南昌尉，今作东郡客。","与语多远情，论心知所益。","秋林既清旷，穷巷空淅沥。","蝶舞园更闲，鸡鸣日云夕。","男儿未称意，其道固无适。","劝君且杜门，勿叹人事隔。"],"theme":"寄赠酬答","theme2":["民生疾苦","羁旅思乡","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"生活":["田野"]},"theme_conf":0.85},{"uid":"72f577cd-8974-4e77-810b-731a0c7d5e2c","title":"隋堤柳","author":"李山甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曾傍龙舟拂翠华，至今凝恨倚天涯。","但经春色还秋色，不觉杨家是李家。","背日古阴从北朽，逐波疎影向南斜。","年年只有晴风便，遥为雷塘送雪花。"],"theme":"羁旅思乡","theme2":["送别","咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","雪","舟","春","秋"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.374},{"uid":"f8afed4e-e8cd-467f-afae-51dc149921f7","title":"夏日南亭怀辛大","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山光忽西落，池月渐东上。","散发乘夕凉，开轩卧闲敞。","荷风送香气，竹露滴清响。","欲取鸣琴弹，恨无知音赏。","感此怀故人，中宵劳梦想。"],"theme":"送别","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["夏"],"cats":{"抒情":["友情"],"四季":["夏天"]},"theme_conf":0.467},{"uid":"afb30a8c-345b-471d-bf80-9f1828f8e097","title":"横吹曲辞 折杨柳","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红粉青楼曙，垂杨仲月春。","怀君重攀折，非妾妒腰身。","舞带萦丝断，娇娥向叶嚬。","横吹凡几曲，独自最愁人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["春","楼","月"],"cats":{"抒情":["伤感","孤独","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"3bb3897a-7460-40d1-9ec3-b4738e3f20b4","title":"忆春日太液池亭候对","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宫莺报晓瑞烟开，三岛灵禽拂水回。","桥转彩虹当绮殿，舰浮花鹢近蓬莱。","草承香辇王孙长，桃艳仙颜阿母栽。","簪笔此时方侍从，却思金马笑邹枚。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["彩虹"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"e38b8c76-9f0b-484c-8791-34340abf20b1","title":"郊庙歌辞 享龙池乐章 第六章","author":"崔日用","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["龙兴白水汉兴符，圣主时乘运斗枢。","岸上丰茸五花树，波中的皪千金珠。","操环昔闻迎夏启，发匣先来瑞有虞。","风色云光随隐见，赤云神化象江湖。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江","园林","夏"],"cats":{"四季":["夏天"]},"theme_conf":0.86},{"uid":"cp8c488ffc868c19","title":"奉梨诗","author":"庾信","dynasty":"魏晋南北朝","section":"魏晋南北朝","form":"五言绝句","paragraphs":["接枝秋转脆，含情落更香。","擎置仙人掌，应添瑞露浆。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["梨花"]},"theme_conf":0.65},{"uid":"16986240-98d2-47da-a4a9-cf487c2c2f0e","title":"鸥","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江浦寒鸥戏，无他亦自饶。","却思飜玉羽，随意点春苗。","雪暗还须浴，风生一任飘。","几群沧海上，清影日萧萧。"],"theme":"山水田园","theme2":[],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["江","雪","春"],"cats":{"四季":["春天"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"888e21ea-f3bc-4453-83b8-2048410e3b91","title":"杂曲歌辞 蓟门行","author":"李希仲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旄头有精芒，胡骑猎秋草。","羽檄南渡河，边庭用兵早。","汉家爱征战，宿将今已老。","辛苦羽林儿，从戎榆关道。","一身救边速，烽火连蓟门。","前军鸟飞断，格鬬尘沙昏。","寒日鼓声急，单于夜火奔。","当须徇忠义，身死报国恩。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂","悲怆"],"scene":["秋","夜"],"cats":{"抒情":["爱国"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.864},{"uid":"8f179f71-6bfa-4329-9340-2aa81745b2c6","title":"月晦","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晦魄移中律，凝暄起丽城。","罩云朝盖上，穿露晓珠呈。","笑树花分色，啼枝鸟合声。","披襟欢眺望，极目畅春情。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["月","春"],"cats":{"四季":["春天"],"天气":["月亮"]},"theme_conf":0.72},{"uid":"883fcd05-a7b4-40f8-8cbe-5d93d4fad76c","title":"冬日洛城北谒玄元皇帝庙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["配极玄都閟，凭虚禁御长。","守祧严具礼，掌节镇非常。","碧瓦初寒外，金茎一气旁。","山河扶绣户，日月近雕梁。","仙李盘根大，猗兰奕叶光。","世家遗旧史，道德付今王。","画手看前辈，吴生远擅场。","森罗移地轴，妙绝动宫墙。","五圣联龙衮，千官列雁行。","冕旒俱秀发，旌斾尽飞扬。","翠柏深留景，红棃迥得霜。","风筝吹玉柱，露井冻银床。","身退卑周室，经传拱汉皇。","谷神如不死，养拙更何乡。"],"theme":"佛道禅颂","theme2":["咏史怀古","民生疾苦","应制干谒"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["怀古"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":0.9},{"uid":"6e27c564-356b-4c7b-8594-861f03d55cfc","title":"武陵书怀五十韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西汉开支郡，南朝号戚藩。","四封当列宿，百雉俯清沅。","高岸朝霞合，惊湍激箭奔。","积阴春暗度，将霁雾先昏。","俗尚东皇祀，谣传义帝冤。","桃花迷隐迹，楝叶慰忠魂。","户算资渔猎，乡豪恃子孙。","照山畬火动，踏月俚歌喧。","拥檝舟为市，连甍竹覆轩。","披沙金粟见，拾羽翠翘翻。","茗折苍溪秀，苹生枉渚暄。","禽惊格磔起，鱼戏𪡋喁繁。","沈约台榭故，李衡墟落存。","湘灵悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星悬橘柚村。","虎咆空野震，鼍作满川浑。","邻里皆迁客，儿童习左言。","炎天无冽井，霜月见芳荪。","清白家传远，诗书志所敦。","列科叨甲乙，从宦出丘樊。","结友心多契，驰声气尚吞。","士安曾重赋，元礼许登门。","草檄嫖姚幕，巡兵戊己屯。","筑台先自隗，送客独留髠。","遂结王畿绶，来观衢室罇。","鸢飞入鹰隼，鱼目俪玙璠。","晓烛罗驰道，朝阳辟帝阍。","王正会夷夏，月朔盛旗旛。","独立当瑶阙，传呵步紫垣。","按章清犴狱，视祭洁苹蘩。","御历昌期远，传家宝祚蕃。","繇文光夏启，神教畏轩辕。","内禅因天性，雄图授化元。","继明悬日月，出震统乾坤。","大孝三朝备，洪恩九族惇。","百川宗渤澥，五岳辅昆仑。","何幸逢休运，微班识至尊。","校𦈏资筦榷，复土奉山园。","一失贵人意，徒闻太学论。","直庐辞锦帐，远守愧朱幡。","巢幕方犹燕，抢榆尚笑鲲。","邅回过荆楚，流落感凉温。","旅望花无色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥数，看方理病源。","带赊衣改制，尘涩劒成痕。","三秀悲中散，二毛伤虎贲。","来忧御魑魅，归愿牧鸡豚。","就日秦京远，临风楚奏烦。","南登无灞岸，旦夕上高原。"],"theme":"羁旅思乡","theme2":["山水田园","送别"],"style":"绮丽","style2":["清新","雄浑"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["夏","江","楼","花"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["夏天"],"天气":["太阳"],"人物":["儿童"],"人生":["读书"],"植物":["桃花"]},"theme_conf":0.239},{"uid":"cp63eba452c87667","title":"风入松","author":"俞国宝","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一春长费买花钱。","日日醉花边。","玉骢惯识西湖路，骄嘶过、沽酒垆前。","红杏香中箫鼓，绿杨影里秋千。","暖风十里丽人天。","花压髻云偏。","画船载取春归去，馀情寄、湖水湖烟。","明日重扶残醉，来寻陌上花钿。"],"theme":"山水田园","theme2":["送别","闲适隐逸"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["酒","花","春","江南"],"cats":{"四季":["春天"],"山水":["西湖"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.393},{"uid":"0bec6ec5-bac0-4fc3-9c26-c1ef63cd1d0a","title":"题苗员外竹间亭","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高甃绝行尘，开帘似有春。","风倾竹上雪，山对酒边人。","步暖先逢日，书空远见邻。","还同内斋暇，登赏及诸姻。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","雪","春","酒","山"],"cats":{"四季":["春天"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"dd4808c5-cefb-4840-8782-a1636acc9856","title":"琴曲歌辞 走马引","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我有辞乡劒，玉锋堪截云。","襄阳走马客，意气自生春。","朝嫌劒光静，暮嫌劒花冷。","能持劒向人，不解持照身。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.612},{"uid":"2b87015d-2a4a-4fa7-af5e-fe7cebc4a99f","title":"杂曲歌辞 长相思","author":"张继","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["辽阳望河县，白首无由见。","海上珊瑚枝，年年寄春燕。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["爱情","思念"],"四季":["春天"]},"theme_conf":0.704},{"uid":"22923091-18da-429d-9ef1-6b367fd74b1a","title":"杂曲歌辞 游子吟","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"人物":["母亲"]},"theme_conf":0.845},{"uid":"32021394-9342-4eb9-b5c0-f98c6e3beece","title":"钱唐湖春行","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤山寺北贾亭西，水面初平云脚低。","几处早莺争暖树，谁家新燕啄春泥。","乱花渐欲迷人眼，浅草才能没马蹄。","最爱湖东行不足，绿杨阴里白沙堤。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["西湖"]},"theme_conf":0.585},{"uid":"bbcf126a-4653-4297-8d15-52e894fcaaf4","title":"琴曲歌辞  秋思二首 二","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宫连太液见苍波，暑气微清秋意多。","一夜轻风苹末起，露珠翻尽满池荷。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["秋","夏"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"]},"theme_conf":0.6},{"uid":"98cf143d-0917-47aa-8a24-ce3db79ce765","title":"赋得春雪映早梅","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞舞先春雪，因依上番梅。","一枝方渐秀，六出已同开。","积素光逾密，真花节暗催。","抟风飘不散，见𬀪忽偏摧。","郢曲琴空奏，羌音笛自哀。","今朝两成咏，翻挟昔人才。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["雪","冬","春"],"cats":{"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.796},{"uid":"cpffa9ae8e43982f","title":"法曲献仙音","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["层绿峨峨，纤琼皎皎，倒压波痕清浅。","过眼年华，动人幽意，相逢几番春换。","记唤酒寻芳处，盈盈褪妆晚。","已销黯。","况凄凉、近来离思，应忘却、明月夜深归辇。","荏苒一枝春，恨东风、人似天远。","纵有残花，洒征衣、铅泪都满。","但殷勤折取，自遣一襟幽怨。"],"theme":"咏物","theme2":["游仙梦幻"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["春","月","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.8},{"uid":"4b20b87c-18e6-4769-b07e-72665771fd11","title":"相和歌辞 饮马长城窟行","author":"袁朗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动秋草，清跸长安道。","长城连不穷，所以隔华戎。","规模惟圣作，荷负晓成功。","鸟庭已向内，龙荒更凿空。","玉关尘卷静，金微路已通。","汤征随北怨，舜咏起南风。","画野功初立，绥边事云集。","朝服践狼居，凯歌旋马邑。","山响传凤吹，霜华藻琼钑。","属国拥节归，单于款关入。","日落寒云起，惊沙被原隰。","零落叶已寒，河流清且急。","四时徭役尽，千载干戈戢。","太平今若斯，汗马竟无施。","惟当事笔研，归去草封禅。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.522},{"uid":"e7b46a9e-9dd8-444c-baa2-645422ee243a","title":"早春钱塘湖晚眺","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日下林坂，抚襟睇前踪。","轻澌流回浦，残雪明高峰。","仰视天宇旷，俯登云树重。","聊当问真界，昨夜西峦钟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","江南","江","雪"],"cats":{"四季":["春天"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"918eefe5-fd66-441d-ac06-01ad799fb485","title":"绛州过夏留献郑尚书","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["朝朝沈醉引金船，不觉西风满树蝉。","光景暗消银烛下，梦魂长寄玉轮边。","因循每被时流诮，奋发须由国士怜。","明月客肠何处断，绿槐风里独扬鞭。"],"theme":"应制干谒","theme2":["应制干谒","送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月"],"cats":{"抒情":["思乡","孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["励志"]},"theme_conf":0.95},{"uid":"8e6ba3fd-d983-4950-9fec-8e55331d0c09","title":"海上诗送薛文学归海东","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处归且远，送君东悠悠。","沧溟千万里，日夜一孤舟。","旷望绝国所，微茫天际愁。","有时近仙境，不定若梦游。","或见青色古，孤山百里秋。","前心方杳眇，后路劳夷犹。","离别惜吾道，风波敬皇休。","春浮花气远，思逐海水流。","日暮骊歌后，永怀空沧洲。"],"theme":"送别","theme2":[],"style":"豪放","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["舟","秋","春","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["春天","秋天"],"山水":["西湖"]},"theme_conf":0.66},{"uid":"18575058-f526-4248-a273-164a84618218","title":"杂曲歌辞 昔昔盐 水溢芙蓉沼","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["渌沼春光后，青青草色浓。","绮罗惊翡翠，暗粉妒芙蓉。","云遍窗前见，荷翻镜里逢。","将心托流水，终日渺无从。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"d9a38c34-7eb7-46d6-af26-da6f6f68bdf2","title":"送刘四赴夏县","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["九霄特立红鸾姿，万仞孤生玉树枝。","刘侯致身能若此，天骨自然多叹美。","声名播扬二十年，足下长途几千里。","举世皆亲丞相阁，我心独爱伊川水。","脱略势利犹埃尘，啸傲时人而已矣。","新诗数岁即文雄，上书昔召蓬莱宫。","明主拜官麒麟阁，光车骏马看玉童。","高人往来庐山远，隐士往来张长公。","扶南甘蔗甜如蜜，杂以荔枝龙州橘。","赤县繁词满剧曹，白云孤峰晖永日。","朝持手板望飞鸟，暮诵楞伽对空室。","一朝出宰汾河间，明府下车人吏闲。","端坐讼庭更无事，开门咫尺巫咸山。","男耕女织蒙惠化，麦熟雉鸣长秋稼。","明年九府议功时，五辟三征当在兹。","闻道桐乡有遗老，邑中还欲置生祠。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":[],"scene":["山","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["庐山"],"食物":["荔枝"]},"theme_conf":0.307},{"uid":"26812d7f-e7f0-4936-be69-3dc2cf0bc0c8","title":"和武相公中秋锦楼玩月 一","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清景同千里，寒光尽一年。","竟天多鴈过，通夕少人眠。","照别江楼上，添愁野帐前。","隋侯恩未报，犹有夜珠圆。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["中秋","楼","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"a7a08144-c10f-44ef-8558-7064cc123c68","title":"孟夫子生生亭赋","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["玉川子沿孟冬之寒流兮，辍櫂上登生生亭。","夫子何之兮，面逐云没兮南行。","百川注海而心不写兮，落日千里凝寒精。","予日衰期人生之世斯已矣，爰为今日犹犹岐路之心生。","悲夫！南国风涛，鱼龙畜伏。","予小子戆朴，必不能济夫子欲。","嗟自慙承夫子而不失予兮，传古道甚分明。","予且广孤目遐賷于天壤兮，庶得外尽万物变化之幽情。","然后慙愧而来归兮，大息吾躬于夫子之亭。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["悲怆","惆怅"],"scene":["楼","冬"],"cats":{"抒情":["伤感","孤独"],"四季":["冬天"],"人物":["老师"]},"theme_conf":0.72},{"uid":"5901d95d-baf0-46dd-9a29-fd3c020c0a70","title":"相和歌辞 雁门太守行","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["城头月没霜如水，趚趚蹋沙人似鬼。","灯前拭泪试香裘，长引一声残漏子。","驼囊泻酒酒一杯，前头啑血心不回。","寄语年少妻莫哀，鱼金虎竹天上来，雁门山边骨成灰。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":["婉约"],"mood":"悲怆","mood2":["愁怨"],"scene":["鸟","酒"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.638},{"uid":"00ede8d1-4ba1-4b59-9021-bddf471b00e4","title":"早春思归有唱竹枝歌者坐中下泪","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["渺渺春生楚水波，楚人齐唱竹枝歌。","与君皆是思归客，拭泪看花奈老何。"],"theme":"羁旅思乡","theme2":["题画咏艺"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.402},{"uid":"d5a61d84-8246-462a-beae-fea8dbc3c0df","title":"送孙德谕罢官往黔州","author":"苗发","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["中岁分符典石城，两朝趋陛谒承明。","阙下昨承归老疏，天南今切去乡情。","亲知握手三秋别，几杖扶身万里行。","伯道暮年无嗣子，欲将家事托门生。"],"theme":"送别","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["老师"]},"theme_conf":0.715},{"uid":"a4d718ee-c020-42b4-97df-499cd0076f7b","title":"登高","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["风急天高猨啸哀，渚清沙白鸟飞回。","无边落木萧萧下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艰难苦恨繁霜鬓，潦倒新停浊酒桮。"],"theme":"民生疾苦","theme2":["咏史怀古"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["江","秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"],"节日":["重阳节"]},"theme_conf":0.52},{"uid":"b423f06b-4c05-4892-a409-7933ccf2edf8","title":"横吹曲辞 陇头吟","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陇水潺湲陇树黄，征人陇上尽思乡。","马嘶斜日朔风急，雁过寒云边思长。","残月出林明劒戟，平沙隔水见牛羊。","横行俱足封侯者，谁斩楼兰献未央。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","楼","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["冬天"],"天气":["写风"],"生活":["边塞"]},"theme_conf":0.645},{"uid":"cp4fe328e8e81bc3","title":"浪涛沙・浪淘沙","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["昼阴重，霜凋岸草，雾隐城堞。","南陌脂车待发。","东门帐饮乍阕。","正拂面垂杨堪缆结。","掩红泪、玉手亲折。","念汉浦离鸿去何许，经时信音绝。","情切。","望中地远天阔。","向露冷风清，无人处、耿耿寒漏咽。","嗟万事难忘，唯是轻别。","翠尊未竭。","凭断云留取，西楼残月。","罗带光销纹衾叠。","连环解、旧香顿歇。","怨歌永、琼壶敲尽缺。","恨春去、不与人期，弄夜色，空馀满地梨花雪。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["雪","花","夜","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天"]},"theme_conf":0.59},{"uid":"57259261-28ad-4dde-a63f-e3bb6a9dd1a7","title":"元日早朝","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["九陌朝臣满，三朝候鼓赊。","远珂时接韵，攒炬偶成花。","紫贝为高阙，黄龙建大牙。","参差万戟合，左右八貂斜。","羽扇纷朱槛，金𬬻隔翠华。","微风传曙漏，晓日上春霞。","环珮声重叠，蛮夷服等差。","乐和天易感，山固寿无涯。","渥泽千年圣，车书四海家。","盛明多在位，谁得守蓬麻。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["春节"]},"theme_conf":0.96},{"uid":"04c61f91-42b2-4604-9209-f779f63af881","title":"留题","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["茶兴复诗心，一瓯还一吟。","压春甘蔗冷，喧雨荔枝深。","骤去无遗恨，幽栖已徧寻。","峨眉不可到，高处望千岑。"],"theme":"咏物","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","雨"],"cats":{"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.508},{"uid":"297dd100-6aab-4685-a52d-983fb0999c7a","title":"和乐天春词","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["新妆面面下朱楼，深锁春光一院愁。","行到中庭数花朵，蜻蜓飞上玉搔头。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"acbe1729-cefd-4678-9719-09c5c9c27db0","title":"咏怀古迹五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["摇落深知宋玉悲，风流儒雅亦吾师。","怅望千秋一洒泪，萧条异代不同时。","江山故宅空文藻，云雨荒台岂梦思。","最是楚宫俱泯灭，舟人指点到今疑。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":["婉约","沉郁"],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["秋","舟","雨","江","山"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"]},"theme_conf":0.805},{"uid":"6fac0cea-b4ee-419b-9802-786d508141f9","title":"冬行三首 一","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虫豸腊月皆在蛰，吾独何乃劳其形。","小大无由知天命，但怪守道不得宁。","老母妻子一挥手，涕下便作千里行。","自顾不及遭霜叶，旦夕保得同飘零。","达生何足云，偶然苦乐经其身。","古来尧孔与桀跖，善恶何补如今人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["欢愉"],"scene":["冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"73f35093-8a40-44ba-ba98-6b4457303408","title":"送徐州张建封还镇","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["牧守寄所重，才贤生为时。","宣风自淮甸，授钺膺藩维。","入觐展遐恋，临轩慰来思。","忠诚在方寸，感激陈情词。","报国尔所向，恤人予是资。","欢宴不尽怀，车马当还期。","谷雨将应候，行春犹未迟。","勿以千里遥，而云无己知。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["春","雨"],"cats":{"抒情":["爱国"],"四季":["春天"]},"theme_conf":0.771},{"uid":"cp4d7a1643bbbda8","title":"喜迁莺","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["月波疑滴。","望玉壶天近，了无尘隔。","翠眼圈花，冰丝织练，黄道宝光相直。","自怜诗酒瘦，难应接、许多春色。","最无赖，是随香趁烛，曾伴狂客。","踪迹。","谩记忆。","老了杜郎，忍听东风笛。","柳院灯疏，梅厅雪在，谁与细倾春碧。","旧情拘未定，犹自学、当年游历。","怕万一，误玉人、夜寒帘隙。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["豪放","绮丽"],"mood":"欢愉","mood2":["相思"],"scene":["春","冬"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.65},{"uid":"0a5dd0d4-f619-4303-b2ed-7e40061c58aa","title":"没了期歌 二","author":"吴越王钱镠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["没了期，没了期，春衣才了又冬衣。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["冬","春"],"cats":{"四季":["春天","冬天"]},"theme_conf":0.84},{"uid":"dbda2c85-f609-450a-8e93-a6c8f2723372","title":"柏崖老人号无名先生男削发女黄冠自以云泉独乐命予赋诗","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古也忧婚嫁，君能乐性肠。","长男栖月宇，少女炫霓裳。","问尔餐霞处，春山芝桂旁。","鹤前飞九转，壶里驻三光。","与我开龙峤，披云静药堂。","胡麻兼藻绿，石髓隔花香。","帝力言何有，椿年喜渐长。","窅然高象外，宁不傲羲皇。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["月","花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.779},{"uid":"9a42f0ea-06a9-4bb4-a71a-f4ba0485cb5f","title":"首夏花萼楼观群臣宴宁王山亭回楼下又申之以赏乐赋诗","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今年通闰月，入夏展春辉。","楼下风光晚，城隅宴赏归。","九歌扬政要，六舞散朝衣。","天喜时相合，人和事不违。","礼中推意厚，乐处感心微。","别赏阳台乐，前旬暮雨飞。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["楼","夏","花"],"cats":{"四季":["夏天"]},"theme_conf":0.507},{"uid":"397d3ca6-87eb-49f5-ac12-65687c07ce8c","title":"相和歌辞 来日大难","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["来日一身，携粮负薪。","道长食尽，苦口焦唇。","今日醉饱，乐过千春。","仙人相存，诱我远学。","海陵三山，陆憩五岳。","乘龙上三天，飞目瞻两角。","授以神药，金丹满握。","蟪蛄蒙恩，深媿短促。","思填东海，彊衔一木。","道重天地，轩师广成。","蝉翼九五，以求长生。","下士大笑，如苍蝇声。"],"theme":"游仙梦幻","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"72da81b5-8de5-4b5f-bc46-820925a90d64","title":"寄宋申锡评事时从李少师移军回归","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["君逐元侯静虏归，虎旗龙节驻春晖。","欲求岱岳燔柴礼，已锡鲁人缝掖衣。","长劒一时天外倚，五云多遶日边飞。","心期共贺太平世，去去故乡亲食薇。"],"theme":"寄赠酬答","theme2":["边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","感恩"],"四季":["春天"],"山水":["泰山"]},"theme_conf":0.9},{"uid":"2b9b6071-6dc8-4b04-949c-5350f23e4f9d","title":"和微之春日投简阳明洞天五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青阳行已半，白日坐将徂。","越国强仍大，稽城高且孤。","利饶盐煮海，名胜水澄湖。","牛斗天垂象，台明地展图。","瓌奇填市井，佳丽溢𬮱阇。","句践遗风霸，西施旧俗姝。","船头龙夭矫，桥脚兽睢盱。","乡味珍蟛蚏，时鲜贵鹧鸪。","语言诸夏异，衣服一方殊。","捣练蛾眉婢，鸣榔蛙角奴。","江清敌伊洛，山翠胜荆巫。","华表双栖鹤，联樯几点乌。","烟波分渡口，云树接城隅。","涧远松如画，洲平水似铺。","绿科秧早稻，紫笋折新芦。","暖蹋泥中藕，香寻石上蒲。","雨来萌尽达，雷后蛰全苏。","柳眼黄丝颣，花房绛蜡珠。","林风新竹折，野烧老桑枯。","带亸长枝蕙，钱穿短贯榆。","暄和生野菜，卑湿长街芜。","女浣纱相伴，儿烹鲤一呼。","山魈啼稚子，林狖挂山都。","产业论蚕蚁，孳生计鸭雏。","泉岩雪飘洒，苔壁锦漫糊。","堰限舟航路，堤通车马途。","耶溪岸回合，禹庙径盘纡。","洞穴何因凿，星槎谁与刳。","石凹仙药臼，峰峭佛香炉。","去为投金简，来因挈玉壶。","贵仍招客宿，健未要人扶。","闻望贤丞相，仪形美丈夫。","前驱驻旌斾，偏坐列笙竽。","刺史旟翻隼，尚书履曳凫。","学禅超后有，观妙造虚无。","髻里传僧宝，环中得道枢。","登楼诗八咏，置砚赋三都。","捧拥罗将绮，趋跄紫与朱。","庙谟藏稷卨，兵略贮孙吴。","令下三军整，风高四海趋。","千家得慈母，六郡事严姑。","重士过三哺，轻财抵一铢。","送觥歌宛转，嘲妓笑卢胡。","佐饮时炮鼈，蠲酲数鲙鲈。","醉乡虽咫尺，乐事亦须臾。","若不中贤圣，何由外智愚。","伊予一生志，我尔百年躯。","江上三千里，城中十二衢。","出多无伴侣，归只对妻孥。","白首青山约，抽身去得无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"欢愉","mood2":["孤寂"],"scene":["江","山","江南","舟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"天气":["太阳"],"人物":["母亲","儿童"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"a1255e7f-9db9-45a3-85cf-ad00559a3e58","title":"沣水送郑鄠县读书","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["麦秋中夏凉风起，送君西郊及沣水。","孤烟远树动离心，隔岸江流若千里。","早年江海谢浮名，此路云山惬尔情。","上古全经皆在口，秦人如见济南生。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","秋","江","山"],"cats":{"抒情":["离别","孤独"],"四季":["夏天","秋天"],"山水":["江河"],"人生":["读书"]},"theme_conf":0.766},{"uid":"c611bf84-57f9-44ee-ac22-d7a270a21190","title":"送马将军奏事毕归滑州使幕","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["吴门别后蹈沧州，帝里相逢俱白头。","自叹马卿常带病，还嗟李广未封侯。","棠梨宫里瞻龙衮，细柳营前著豹裘。","想到滑台桑叶落，黄河东注荻花秋。"],"theme":"边塞征战","theme2":["送别"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["江","秋","江南"],"cats":{"四季":["秋天"],"山水":["黄河"],"动物":["写马"]},"theme_conf":0.574},{"uid":"3e6f3ca9-f771-438d-8f5f-75ba5b802739","title":"酬李端校书见赠","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿槐垂穗乳乌飞，忽忆山中独未归。","青镜流年看发变，白云芳草与心违。","乍逢酒客春游惯，久别林僧夜坐稀。","昨日闻君到城阙，莫将簪弁胜荷衣。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["酒","春","夜","山"],"cats":{"抒情":["思念","孤独"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.97},{"uid":"cp60a401fbbbc431","title":"莺啼序","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"相思","mood2":["愁怨"],"scene":["江南","鸟","春"],"cats":{"抒情":["离别","思念","伤感","悼亡"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"],"节日":["清明节"],"动物":["写鸟"]},"theme_conf":0.93},{"uid":"3e2a6b80-7713-4eb1-af64-67bfd3f1d705","title":"谢李六郎中寄新蜀茶","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故情周匝向交亲，新茗分张及病身。","红纸一封书后信，绿芽十片火前春。","汤添勺水煎鱼眼，末下刀圭搅曲尘。","不寄他人先寄我，应缘我是别茶人。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.95},{"uid":"25be9870-8794-4702-bdb9-8ed2a7df8051","title":"湘夫人二首 二","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南有涔阳路，渺渺多新愁。","桂酒神降时，回风江上秋。","彩云忽无处，碧水空安流。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","秋","江"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.68},{"uid":"0d04cc1d-1ad6-472c-9de3-75695aae467c","title":"送唐中丞开淘西湖夏日游泛因书示郡人","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["萍岸新淘见碧霄，中流相去忽成遥。","空余孤屿来诗景，无复横槎碍柳条。","红斾路幽山翠湿，锦帆风起浪花飘。","共知浸润同雷泽，何虑川源有旱苗。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["夏","江南","江"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["西湖"]},"theme_conf":0.67},{"uid":"7ef7bc94-3b3f-4224-ba4c-889a39870e38","title":"朝日勅赐百官樱桃","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["仙果人间都未有，今朝忽见下天门。","捧盘小吏初宣勅，当殿群臣共拜恩。","日色遥分门下坐，露香才出禁中园。","每年重此先偏待，愿得千春奉至尊。"],"theme":"游仙梦幻","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"天气":["太阳"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"cp7857964ab0bf7a","title":"曲游春","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚苑东风外，暖丝情絮，春思如织。","燕约莺期，恼芳情偏在，翠深红隙。","漠漠香尘隔。","沸十里、乱弦丛笛。","看画船，尽入西泠，闲却半湖春色。","柳陌。","新烟凝碧。","映帘底宫眉，堤上游勒。","轻暝笼寒，怕梨云梦冷，杏香愁幂。","歌管酬寒食。","奈蝶怨、良宵岑寂。","正满湖、碎月摇花，怎生去得。"],"theme":"节令风俗","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.86},{"uid":"169ff044-695d-4889-b2d0-3c1bd70dfc6c","title":"唐大飨拜洛乐章 禋和","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["百礼崇容，千官肃事。","灵降舞兆，神凝有粹。","奠享咸周，威仪毕备。","奏夏登列，歌雍撤肆。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.97},{"uid":"49d2767d-7281-4df2-ba8f-36276d5928e4","title":"伤春五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鸎入新年语，花开满故枝。","天青风卷幔，草碧水通池。","牢落官军速，萧条万事危。","鬓毛元自白，泪点向来垂。","不是无兄弟，其如有别离。","巴山春色静，北望转逶迤。"],"theme":"送别","theme2":["悼亡挽歌"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":["恬淡"],"scene":["春"],"cats":{"抒情":["离别","伤感","悼亡"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.4},{"uid":"c5f9b99b-fe97-4eef-8fea-30b45125aa97","title":"送韦侍御奉使江岭诸道催青苗钱","author":"包何","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近远从王事，南行处处经。","手持霜简白，心在夏苗青。","回鴈书应报，愁猨夜屡听。","因君使绝域，方物尽来庭。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江","山","夏","夜"],"cats":{"抒情":["伤感"],"四季":["夏天"]},"theme_conf":0.681},{"uid":"da5adcc3-327e-4fc0-aa4c-5da11168391e","title":"游坊口悬泉偶题石上","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["济源山水好，老尹知之久。","常日听人言，今秋入吾手。","孔山刀劒立，沁水龙蛇走。","危磴上悬泉，澄湾转坊口。","虚明见深底，净绿无纤垢。","仙櫂浪悠扬，尘缨风斗薮。","岩寒松柏短，石古莓苔厚。","锦坐缨高低，翠屏张左右。","虽无安石妓，不乏文举酒。","谈笑逐身来，管弦随事有。","时逢杖锡客，或值垂纶叟。","相与澹忘归，自辰将及酉。","公门欲返驾，溪路犹回首。","早晚重来游，心期罢官后。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["绮丽","清新"],"mood":"恬淡","mood2":[],"scene":["山","秋","酒"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.845},{"uid":"923eceba-072c-4fe4-b193-6fd190839a14","title":"和李相公勉晦日蓬池游宴","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高会吹台中，新年月桂空。","貂蝉临野水，旌斾引春风。","细草萦斜岸，纤条出故丛。","微文复看猎，宁与解神同。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["月","园林","春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.86},{"uid":"16f2a421-f439-45f3-9fe5-b9948368568e","title":"送柳道时余北还","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["征役各异路，烟波同旅愁。","轻桡上桂水，大艑下扬州。","何处成后会，今朝分旧游。","离心比杨柳，萧飒不胜秋。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感"],"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.802},{"uid":"d4e3c78d-a404-4910-8e0d-aca1f0a29f2b","title":"相和歌辞 采桑","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杨柳送行人，青青西入秦。","秦家采桑女，楼上不胜春。","盈盈灞水曲，步步春芳绿。","红脸耀明珠，绛唇含白玉。","回首渭桥东，遥怜树色同。","青丝娇落日，缃绮弄春风。","携笼长叹息，逶迤恋春色。","看花若有情，倚树疑无力。","薄暮思悠悠，使君南陌头。","相逢不相识，归去梦青楼。"],"theme":"山水田园","theme2":["送别"],"style":"绮丽","style2":["婉约"],"mood":"相思","mood2":[],"scene":["花","春","楼"],"cats":{"四季":["春天"],"生活":["写桥"]},"theme_conf":0.488},{"uid":"ea4f954e-f947-4ea6-a7ce-24425dcf7fea","title":"相和歌辞  相逢行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾年初二八，家住洛桥头。","玉户临驰道，朱门近御沟。","使君何假问，夫壻大长秋。","女弟新承宠，诸兄近拜侯。","春生百子殿，花发五城楼。","出入千门里，年年乐未休。"],"theme":"讽喻刺世","theme2":["羁旅思乡","闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","春","楼"],"cats":{"抒情":["思乡","闺怨"],"四季":["春天","秋天"],"生活":["写桥"]},"theme_conf":0.372},{"uid":"cp0f289616020e5f","title":"念奴娇","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["野棠花落，又匆匆、过了青明时节。","地东风欺客梦，一夜云屏寒怯。","曲岸持觞，垂杨系马，此地曾轻别。","楼空人去，旧游飞燕能说。","闻道绮陌东头，行人长见，帘底纤纤月。","旧恨春江流未断，新恨云山千叠。","料得明朝，尊前重见，镜里花难折。","也应惊问，近来多少华发。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":["清新","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.531},{"uid":"9d974ae6-2223-4fa3-bb66-15a079adec68","title":"送孔巢父赴河南军","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江城相送阻烟波，况复新秋一雁过。","闻道全师征北虏，更言诸将会南河。","边心杳杳乡人绝，塞草青青战马多。","共许陈琳工奏记，知君名宦未蹉跎。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","塞外","秋"],"cats":{"四季":["秋天"],"山水":["江河"],"人物":["父亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"0a0f9231-d88c-4f81-b941-83b67a736194","title":"长恨歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["夜","楼","山","春","秋","园林"],"cats":{"抒情":["爱情","伤感","孤独","闺怨","感恩"],"四季":["春天","秋天"],"天气":["写雨","星星"],"人物":["老师"],"人生":["梦想"]},"theme_conf":0.85},{"uid":"0f980b6f-473d-4f04-8090-0e04da5e2655","title":"奉同郭给事汤东灵湫作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东山气鸿蒙，宫殿居上头。","君来必十月，树羽临九州。","阴火煮玉泉，喷薄涨岩幽。","有时浴赤日，光抱空中搂。","阆风入辙迹，旷原延冥搜。","沸天万乘动，观水百丈湫。","幽灵斯可佳，王命宫属休。","初闻龙用壮，擘石摧林丘。","中夜窟宅改，移因风雨秋。","倒悬瑶池影，屈注苍江流。","味如甘露浆，挥弄滑且柔。","翠旗澹偃蹇，云车纷少留。","箫鼓荡四溟，异香泱漭浮。","鲛人献微绡，曾祝沈豪牛。","百祥奔盛明，古先莫能俦。","坡陀金虾蟆，出见盖有由。","至尊顾之笑，王母不肯收。","复归虚无底，化作长黄虬。","飘飘青琐郎，文采珊瑚钩。","浩歌渌水曲，清绝听者愁。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["婉约","冲淡"],"mood":"慷慨","mood2":["愁怨","恬淡"],"scene":["山","雨","秋"],"cats":{"抒情":["伤感","爱国"],"四季":["秋天"],"山水":["江河"]},"theme_conf":1.0},{"uid":"72cbfe88-6a41-4893-b31a-7c10562da7cb","title":"莲叶","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["根是泥中玉，心承露下珠。","在君塘下种，埋没任春蒲。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["荷花","叶子"]},"theme_conf":0.96},{"uid":"621d6001-ea93-4bce-adb6-7e085437f15f","title":"秋夜宴王郎中宅赋得露中菊","author":"朱湾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["众芳春竞发，寒菊露偏滋。","受气何曾异，开花独自迟。","晚成犹待赏，欲采未过时。","忍弃东篱下，看随秋草衰。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["秋","重阳","夜"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.682},{"uid":"cpcd87e66c3b994c","title":"石州慢","author":"张元干","dynasty":"宋","section":"宋词","form":"词","paragraphs":["寒水依痕，春意渐回，沙际烟阔。","溪梅晴照生香，冷芯数枝争发。","天涯旧恨，试看几许消魂，长亭门外山重叠。","不尽眼中青，是愁来时节。","情切。","画楼深闭，想见东风，暗销肌雪。","辜负枕前云雨，尊前花月。","心期切处，更有多少凄凉，殷勤留与归时说。","到得却相逢，恰经年离别。"],"theme":"送别","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春","楼","冬","花","雪"],"cats":{"抒情":["离别","伤感"],"四季":["春天"]},"theme_conf":0.529},{"uid":"81144889-f17a-4590-bbeb-5a9fdb7fcf4d","title":"春日江村五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["群盗哀王粲，中年召贾生。","登楼初有作，前席竟为荣。","宅入先贤传，才高处士名。","异时怀二子，春日复含情。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"070d66a9-c9a0-44a3-be22-af612fac4861","title":"自澧浦东游江表途出巴丘投员外从公虞","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["短翮后飞者，前攀鸾鹤翔。","力微应万里，矫首空苍苍。","谁昔探花源，考槃西岳阳。","高风动商洛，绮皓无馨香。","一朝下蒲轮，清辉照岩廊。","孤醒立众醉，古道何由昌。","经术震浮荡，国风扫齐梁。","文襟即玄圃，笔下成琳琅。","霞水散吟啸，松筠奉琴觞。","冰壶避皎洁，武库羞锋铓。","小子书代耕，束发颇自强。","艰哉水投石，壮志空摧藏。","十年侣龟鱼，垂头在沅湘。","巴歌揜白雪，鲍肆埋兰芳。","骚雅道未丧，何忧名不彰。","饥寒束困厄，默塞飞星霜。","百志不成一，东波掷年光。","尘生脱粟甑，万里违高堂。","中夜恨火来，焚烧九回肠。","平明梁山泪，缘枕沾匡床。","依泊洞庭波，木叶忽已黄。","哀碪捣秋色，晓月啼寒螀。","复此櫂孤舟，云涛浩茫茫。","朱门待媒势，短褐谁揄扬。","仰羡野陂凫，无心忧稻粱。","不如天边雁，南北皆成行。","男儿白日间，变化未可量。","所希困辱地，剪拂成腾骧。","咋笔话肝肺，咏兹枯鱼章。","何由首西路，目断白云乡。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":["婉约","豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","酒","月","花","秋","山"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.367},{"uid":"73727332-47c2-459f-b186-fef59872a906","title":"相和歌辞 櫂歌行","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["写月图黄罢，凌波拾翠通。","镜花摇芰日，衣麝入荷风。","叶密舟难荡，莲疎浦易空。","凤媒羞自托，鸳翼恨难穷。","秋帐灯花翠，倡楼粉色红。","相思无别曲，幷在櫂歌中。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["花","舟","秋","月","楼"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"]},"theme_conf":0.536},{"uid":"cp6c37ef5b5bb72d","title":"兰陵王","author":"张元干","dynasty":"宋","section":"宋词","form":"词","paragraphs":["卷朱箔。","朝雨轻阴乍阁。","阑干外，烟柳弄晴，芳草侵阶映红药。","东风妒花恶。","吹落。","梢头嫩萼。","屏山掩，沈水倦熏，中酒心情怕杯勺。","寻思旧京洛。","正年少疏狂，歌笑迷著。","障泥油壁催梳掠。","曾驰道同载，上林携手，灯夜初过早共约。","又争信漂泊。","寂寞。","念行乐。","甚粉淡衣襟，音断弦索。","琼枝璧月春如昨。","怅别后华表，那回双鹤。","相思除是，向醉里、暂忘却。"],"theme":"爱情相思","theme2":["送别","羁旅思乡","咏史怀古"],"style":"冲淡","style2":["豪放","清新"],"mood":"相思","mood2":["欢愉"],"scene":["酒","花","春","楼","夜"],"cats":{"抒情":["爱情","思念","思乡","孤独","怀古"],"四季":["春天"]},"theme_conf":0.317},{"uid":"46dacd68-1e8b-41fa-b15f-f5a9ced5652e","title":"题郡中荔枝诗十八韵兼寄万州杨八使君","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["奇果标南土，芳林对北堂。","素华春漠漠，丹实夏煌煌。","叶捧低垂户，枝擎重压墙。","始因风弄色，渐与日争光。","夕讶条悬火，朝惊树点妆。","深于红踯躅，大校白槟榔。","星缀连心朵，珠排耀眼房。","紫罗裁衬壳，白玉裹填瓤。","早岁曾闻说，今朝始摘尝。","嚼疑天上味，嗅异世间香。","润胜莲生水，鲜逾橘得霜。","燕支掌中颗，甘露舌头浆。","物少尤珍重，天高苦渺茫。","已教生暑月，又使阻遐方。","粹液灵难驻，妍姿嫩易伤。","近南光景热，向北道途长。","不得充王赋，无由寄帝乡。","唯君堪掷赠，面白似潘郎。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","花","塞外"],"cats":{"四季":["夏天"],"食物":["荔枝"]},"theme_conf":0.78},{"uid":"e10bd711-4a4e-40e6-85a7-bcec617b61c0","title":"批叶翘谏书纸尾","author":"闽王王继鹏","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["春色曾看紫陌头，乱红飞尽不禁愁。","人情自厌芳华歇，一叶随风落御沟。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春"],"植物":["叶子"]},"theme_conf":0.67},{"uid":"a891f80d-fe12-429e-a820-3890a3c6af9e","title":"秋风函谷应诏","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋风起函谷，劲气动河山。","偃松千岭上，杂雨二陵间。","低云愁广隰，落日惨重关。","此时飘紫气，应验真人还。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.97},{"uid":"6393b72d-7d61-4201-9072-e5589b1637ab","title":"杂曲歌辞 行路难","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见长安城北渭桥边，枯木横槎卧古田。","昔日含红复含紫，常时留雾亦留烟。","春景春风花似雪，香车玉轝恒阗咽。","若个游人不竞攀，若个倡家不来折。","倡家宝袜蛟龙帔，公子银鞍千万骑。","黄莺一向花娇春，两两三三将子戏。","千尺长条百尺枝，丹桂青榆相蔽亏。","珊瑚叶上鸳鸯鸟，凤凰巢里雏鹓儿。","巢倾枝折凤归去，条枯叶落狂风吹。","一朝零落无人问，万古摧残君讵知。","人生贵贱无终始，倏忽须臾难久恃。","谁家能驻西山日，谁家能堰东流水。","汉家陵树满秦川，行来行去尽哀怜。","自昔公卿二千石，咸拟荣华一万年。","不见朱唇将白貌，惟闻素棘与黄泉。","金貂有时须换酒，玉麈但摇莫计钱。","寄言坐客神仙署，一生一死交情处。","苍龙阙下君不来，白鹤山前我应去。","云间海上邈难期，赤心会合在何时？","但愿尧年一百万，长作巢由也不辞。"],"theme":"羁旅思乡","theme2":["哲理悟道","送别","山水田园"],"style":"绮丽","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","春","花","雪"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":0.35},{"uid":"7ee919e0-cdff-4594-bc72-3d5d88503cee","title":"杂曲歌辞 行路难三首 二","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见担雪塞井徒用力，炊砂作饭岂堪吃。","一生肝胆向人尽，相识不如不相识。","冬青树上挂凌宵，岁[晏]花凋树不凋。","凡物各自有根本，种禾终不生豆苗。","行路难，行路难，何处是平道？","中心无事当富贵，今日觉君颜色好。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["冬","塞外","雪"],"cats":{"四季":["冬天"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"e7686a0a-7362-4c2f-94d2-e18d8640534a","title":"同柳侍郎题侯钊侍郎新昌里","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清源君子居，左右尽图书。","三迳春自足，一飘欢有余。","庭莎成野席，阑药是家蔬。","幽显岂殊迹，昔贤徒病诸。"],"theme":"寄赠酬答","theme2":["咏物","闲适隐逸"],"style":"清新","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"41e2e819-270c-4ae0-acab-8ede9188a7d0","title":"西陵道士茶歌","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["乳窦溅溅通石脉，绿尘愁草春江色。","涧花入井水味香，山月当人松影直。","仙翁白扇霜鸟翎，拂坛夜读黄庭经。","疎香皓齿有余味，更觉鹤心通杳冥。"],"theme":"山水田园","theme2":["闲适隐逸","咏史怀古"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","夜","花","春","月","江"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.388},{"uid":"ff2b3cb0-be10-47e9-986f-3fa62c69e727","title":"秋日二首 一","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["菊散金风起，荷疎玉露圆。","将秋数行雁，离夏几林蝉。","云凝愁半岭，霞碎缬高天。","还似成都望，直见峨眉前。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["夏天","秋天"]},"theme_conf":0.667},{"uid":"3701a25a-98c8-4ff3-bfa5-1118d77f8800","title":"答窦援遗卧病见寄","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["今春扶病移沧海，几度承恩对白花。","送客屡闻帘外鹊，销愁已辨酒中虵。","瓶开枸杞悬泉水，鼎炼芙蓉伏火砂。","误入尘埃牵吏役，羞将簿领到君家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","酒","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["瀑布"]},"theme_conf":0.95},{"uid":"d7890db1-28cc-4cc4-b81a-90b6f9d68568","title":"酬乐天早春闲游西湖颇多野趣恨不得与微之同赏因思在越官重事殷镜湖之游或恐未暇因成十八韵见寄乐天前篇到时适会予亦宴镜湖南亭因述目前所睹以成酬荅末章亦示暇诚则势使之然亦欲粗为恬养之赠耳","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雁思欲回宾，风声乍变新。","各携红粉伎，俱伴紫垣人。","水面波疑縠，山腰虹似巾。","柳条黄大带，茭葑绿文茵。","雪尽才通屐，汀寒未有苹。","向阳偏晒羽，依岸小游鳞。","浦屿崎岖到，林园次第巡。","墨池怜嗜学，丹井羡登真。","雅叹游方盛，聊非意所亲。","白头辞北阙，沧海是东邻。","问俗烦江界，搜畋想渭津。","故交音讯少，归梦往来频。","独喜同门旧，皆为列郡臣。","三刀连地轴，一苇碍车轮。","尚阻青天雾，空瞻白玉尘。","龙因雕字识，犬为送书驯。","胜事无穷境，流年有限身。","嬾将闲气力，争鬬野塘春。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["恬淡"],"scene":["江","江南","春"],"cats":{"四季":["春天"],"山水":["西湖"],"人生":["时光"]},"theme_conf":0.9},{"uid":"47fc9ebc-0070-4a86-bf6c-63fe970ae534","title":"杂曲歌辞 春游曲三首 三","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["行乐三春节，林花百和香。","当年重意气，先占鬬鸡场。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":1.0},{"uid":"afb30a0c-422f-4656-b0bb-90174c0d3d1f","title":"长安叙怀寄崔十五","author":"武元衡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["延首直城西，花飞绿草齐。","迢遥隔山水，怅望思游子。","百啭黄鹂细雨中，千条翠柳衡门里。","门对长安九衢路，愁心不惜芳菲度。","风尘冉冉秋复春，钟鼓喧喧朝复暮。","汉家宫阙在中天，紫陌朝臣车马连。","萧萧霓旌合仙杖，悠悠剑佩入炉烟。","李广少时思报国，终军未遇敢论边。","无媒守儒行，荣悴纷相映。","家甚长卿贫，身多公干病。","不知身病竟如何，嬾向青山眠薜萝。","鸡黍空多元伯惠，琴书不见子猷过。","超名累岁与君同，自叹还随鹢退风。","闻说唐生子孙在，何当一为问穷通。"],"theme":"寄赠酬答","theme2":["边塞征战","山水田园"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["相思","恬淡"],"scene":["雨","春","花"],"cats":{"抒情":["思念","爱国"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.9},{"uid":"e09998e4-ec09-4118-ac1b-92f7b53b2f7c","title":"寄武陵李少府","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["小县春山口，公孙吏隐时。","楚歌催晚醉，蛮语入新诗。","桂水遥相忆，花源暗有期。","郢门千里外，莫怪尺书迟。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["春","山","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.96},{"uid":"0457d34c-f28a-47a0-aa77-ab3b3a3b14e7","title":"杂曲歌辞 古别离","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["太湖三山口，吴王在时道。","寂寞千载心，无人见春草。","谁堪缄怨者，持此伤怀抱。","孤舟畏狂风，一点宿烟岛。","望所思兮若何，月荡漾兮空波。","云离离兮北断，鴈眇眇兮南多。","身去兮天畔，心折兮湖岸。","春山胡为兮塞路，使我归梦兮撩乱。"],"theme":"送别","theme2":[],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["春","塞外","舟","山","月"],"cats":{"抒情":["离别","孤独"],"四季":["春天"],"天气":["写风"]},"theme_conf":0.619},{"uid":"92fa6241-0397-448c-8a97-27f659ef9dd9","title":"秋雨叹三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["阑风长雨（一作「东风细雨」）秋纷纷，四海（一作「万里」）八荒同一云。","去马来牛不复辨，浊泾清渭何当分。","禾（一作「木」）头生耳黍穗黑，农夫田妇（一作「父」）无消息。","城中斗米换（一作「抱」）衾裯，相许宁论两相直。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","秋"],"cats":{"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.673},{"uid":"1352fbf1-2c3d-459c-b4ac-061e0c6befb8","title":"杂曲歌辞 长干行二首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾发初覆额，折花门前剧。","郎骑竹马来，遶床弄青梅。","同居长干里，两小无嫌猜。","十四为君妇，羞颜尚不开。","低头向暗壁，千唤不一回。","十五始展眉，愿同尘与灰。","常存抱柱信，岂上望夫台。","十六君远行，瞿塘滟预堆。","五月不可触，猨鸣天上哀。","门前迟行迹，一一生绿苔。","苔深不能扫，落叶秋风早。","八月蝴蝶来，双飞西园草。","感此伤妾心，坐愁红颜老。","早晚下三巴，预将书报家。","相迎不道远，直至长风沙。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":["豪放","清新"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","月","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.557},{"uid":"6a35a5c8-851b-4f2d-aa73-a0fd3b2fd2b6","title":"郑驸马宅宴洞中","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["主家阴洞细烟雾，留客夏簟清琅玕。","春酒杯浓琥珀薄，冰浆椀碧玛瑙寒。","误疑茅堂过江麓，已入风磴霾云端。","自是秦楼压郑谷，时闻杂佩声珊珊。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","夏","春"],"cats":{"抒情":["思乡"],"四季":["春天","夏天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"9973b5a9-2259-428d-8d11-9bf2368a32e9","title":"和杨郎中贺杨仆射致仕后杨侍郎门生合宴席上作","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["业重关西继大名，恩深阙下遂高情。","祥鳣降伴趋庭鲤，贺燕飞和出谷莺。","范蠡舟中无子弟，疏家席上欠门生。","可怜玉树连桃李，从古无如此会荣。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["鸟","春","舟","园林"],"cats":{"四季":["春天"],"人物":["老师"]},"theme_conf":0.89},{"uid":"cp4696cb09a62715","title":"采桑子·蝤蛴领上诃梨子","author":"和凝","dynasty":"五代","section":"五代","form":"词","paragraphs":["蝤蛴领上诃梨子，绣带双垂，椒户闲时，竞学樗蒲赌荔枝。","丛头鞋子红编细，裙窣金丝。","无事颦眉，春思翻教阿母疑。"],"theme":"山水田园","theme2":["闺情宫怨","闲适隐逸"],"style":"绮丽","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["母亲"],"植物":["梨花"],"食物":["荔枝"]},"theme_conf":0.416},{"uid":"58ba4d44-398a-4af4-9ae5-764f809b0de1","title":"绝句漫兴九首 七","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["糁径杨花铺白毡，点溪荷叶叠青钱。","笋根稚子无人见，沙上凫雏傍母眠。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"人物":["儿童"]},"theme_conf":0.593},{"uid":"abb3e465-f10e-43dd-b564-a5de08010478","title":"子夜吴歌 夏歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["镜湖三百里，菡萏发荷花。","五月西施采，人看隘若耶。","回舟不待月，归去越王家。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.504},{"uid":"9fa92cdf-24cf-4a6a-af33-db5809652091","title":"杂曲歌辞 秋夜曲二首 一","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天清漏长霜泊泊，兰绿收荣桂膏涸。","高楼云鬟弄婵娟，古瑟暗断秋风弦。","玉关遥隔万里道，金刀不翦双泪泉。","香囊火死香气少，向帷合眼何时晓？","城乌作营嗁野月，秦川少妇生离别。"],"theme":"送别","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","夜"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.511},{"uid":"12c990df-c417-480a-aa17-39836764b4ef","title":"湘岸移木芙蓉植龙兴精舍","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["有美不自蔽，安能守孤根。","盈盈湘西岸，秋至风露繁。","丽影别寒水，秾芳委前轩。","芰荷谅难杂，反此生高原。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["婉约"],"mood":"孤寂","mood2":["欢愉"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.621},{"uid":"6db52079-cf43-4b08-ba0d-edbc69eebe29","title":"相和歌辞 团扇郎","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["团扇复团扇，奉君清暑殿。","秋风入庭树，从此不相见。","上有乘鸾女，苍苍虫网遍。","明年入怀袖，别是机中练。"],"theme":"闺情宫怨","theme2":[],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","秋","园林"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"]},"theme_conf":0.505},{"uid":"56164c0c-6a83-4c3b-8f92-4c26a6e8e34e","title":"送从弟谒员外叔父回归义兴","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["异乡兄弟少，见尔自依然。","来酌林中酒，去耕湖上田。","何朝逢暑雨，几夜泊鱼烟。","余力当勤学，成名贵少年。"],"theme":"送别","theme2":["羁旅思乡","亲情"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","夏"],"cats":{"抒情":["思乡"],"四季":["夏天"],"人物":["父亲"]},"theme_conf":0.296},{"uid":"b244fa50-b7bf-4901-b030-464f18c1c455","title":"送杨将军","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一身良将后，万里讨乌孙。","落日边陲静，秋风鼓角喧。","远山当碛路，茂草向营门。","生死酬恩宠，功名岂敢论。"],"theme":"边塞征战","theme2":["送别"],"style":"冲淡","style2":["豪放"],"mood":"恬淡","mood2":["悲怆","慷慨"],"scene":["秋","山"],"cats":{"四季":["秋天"],"人物":["老师"]},"theme_conf":0.528},{"uid":"2bfd3472-5aea-48b4-ae78-6c030ef4e64f","title":"春池柳","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["年柳变池台，隋堤曲直回。","逐浪丝阴去，迎风带影来。","疎黄一鸟弄，半翠几眉开。","萦雪临春岸，参差间早梅。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"24629e4a-bb7a-49cc-b65d-74e1c4302908","title":"白菊三首 三","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["为报繁霜且莫催，穷秋须到自低垂。","横拖长袖招人别，只待春风却舞来。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳","春"],"cats":{"四季":["春天","秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"e3553a22-2323-4926-a694-752c3481e2a5","title":"阆州东楼筵奉送十一舅往青城县得昏字","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["曾城有高楼，制古丹雘存。","迢迢百余尺，豁达开四门。","虽有车马客，而无人世喧。","游目俯大江，列筵慰别魂。","是时秋冬交，节往颜色昏。","天寒鸟兽休，霜露在草根。","今我送舅氏，万感集清尊。","岂伊山川间，回首盗贼繁。","高贤意不暇，王命久崩奔。","临风欲恸哭，声出已复吞。"],"theme":"送别","theme2":[],"style":"旷达","style2":["清新","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["楼","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"06203cef-1dc5-4d60-9ef7-a4bf4306c730","title":"送裴补阙入河南幕","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["皎然青琐客，何事动行轩。","苦节酬知己，清吟去掖垣。","秋城临海树，寒月上营门。","邹鲁诗书国，应无鼙鼓喧。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","月"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"3ec9cb88-517c-4922-a82e-e6cc561ace29","title":"往在","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["往在西京日，胡来满彤宫。","中宵焚九庙，云汉为之红。","解瓦飞十里，𰬸帷纷曾空。","疚心惜木主，一一灰悲风。","合昏排铁骑，清旭散锦𩦺贼臣表逆节，相贺以成功。","是时妃嫔戮，连为粪土丛。","当宁陷玉座，白间剥画虫。","不知二圣处，私泣百岁翁。","车驾既云还，楹桷歘穹崇。","故老复涕泗，祠官树椅桐。","宏壮不如初，已见帝力雄。","前春礼郊庙，祀事亲圣躬。","微躯忝近臣，景从陪群公。","登阶捧玉册，峨冕耿金钟。","侍祠恧先露，掖垣迩濯龙。","天子惟孝孙，五云起九重。","镜匳换粉黛，翠羽犹葱胧。","前者厌羯胡，后来遭犬戎。","俎豆腐膻肉，罘罳行角弓。","安得自西极，申命空山东。","尽躯诣阙下，士庶塞关中。","主将晓逆顺，元元归始终。","一朝自罪己，万里车书通。","锋镝供锄犂，征戍听所从。","冗官各复业，土著还力农。","君臣节俭足，朝野欢呼同。","中兴似国初，继体如太宗。","端拱纳谏诤，和风日冲融。","赤墀樱桃枝，隐映银丝笼。","千春荐陵寝，永永垂无穷。","京都不再火，泾渭开愁容。","归号故松柏，老去苦飘蓬。"],"theme":"边塞征战","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["春","塞外"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["田野","边塞"]},"theme_conf":0.516},{"uid":"8eeb3273-d271-4674-900b-2057c3f59957","title":"杂曲歌辞 结客少年场行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["韩魏多奇节，倜傥遗名利。","共矜然诺心，各负纵横志。","结友一言重，相思千里至。","绿沈明月弦，金络浮云辔。","吹箫入吴市，击筑游燕肆。","寻源博望侯，结客远相求。","少年重一顾，长驱背陇头。","燄燄霜戈动，耿耿劒虹浮。","天山冬夏雪，交河南北流。","云起龙沙暗，木落鴈行秋。","轻生徇知己，非是为身谋。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"清新","style2":["豪放"],"mood":"相思","mood2":[],"scene":["月","冬","秋","夏","雪"],"cats":{"抒情":["友情","思念","思乡"],"四季":["夏天","秋天","冬天"],"天气":["月亮"],"人生":["青春"]},"theme_conf":0.495},{"uid":"06273196-6d2a-4c70-9680-257cea297824","title":"郊庙歌辞 享太庙乐章 太和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["时文圣后，清庙肃邕。","致诚勤荐，在貌思恭。","玉节肆夏，金锵五钟。","绳绳云步，穆穆天容。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.97},{"uid":"8399a509-3f09-4027-a389-f5c4ba9e5dfe","title":"送李翺习之","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["习之势翩翩，东南去遥遥。","赠君双履足，一为上臯桥。","臯桥路逶迤，碧水清风飘。","新秋折藕花，应对吴语娇。","千巷分渌波，四门生早潮。","湖榜轻褭褭，酒旗高寥寥。","小时屐齿痕，有处应未销。","旧忆如雾星，怳见于梦消。","言之烧人心，事去不可招。","独孤宅前曲，箜篌醉中谣。","壮年俱悠悠，逮兹各焦焦。","执手复执手，唯道无枯凋。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["酒","江","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["老师"],"生活":["写桥"]},"theme_conf":0.8},{"uid":"8eaf97fd-82bb-4651-9dde-9a5a6f78182c","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"a36d2096-432b-4a13-8527-0110a781f74f","title":"送李明府赴连州","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里向南湘，孤舟入桂阳。","诸侯迎上客，小吏拜官郎。","春服橦花细，初筵木槿芳。","看承雨露速，不待荔枝香。"],"theme":"送别","theme2":[],"style":"婉约","style2":["豪放","清新"],"mood":"孤寂","mood2":[],"scene":["花","舟","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.538},{"uid":"71d9f2b6-dfd3-4ee9-8e0e-cbd31c2829e0","title":"黄菊湾","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["时菊凝晓露，露华滴秋湾。","仙人酿酒熟，醉里飞空山。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["酒","重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.562},{"uid":"cpfeda664cad7f2d","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿树听鹈。","更那堪、鹧鸪声住，杜鹃声切。","啼到春归无寻处，苦恨芳菲都歇。","算未抵、人间离别。","马上琵琶关塞黑，更长门、翠辇辞金阙。","看燕燕，送归妾。","将军百战身名裂。","向河梁、回头万里，故人长绝。","易水萧萧西风冷，满座衣冠似雪。","正壮士、悲歌未彻。","啼鸟还知如许恨，料不啼清泪长啼血。","谁共我，醉明月。"],"theme":"送别","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["悲慨","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","春","月"],"cats":{"抒情":["友情","离别","伤感","闺怨"],"四季":["春天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.357},{"uid":"a2833e0a-d45e-4103-9604-e22a620a016b","title":"池上竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丛婵娟色，四面清冷波。","气润晚烟重，光闲秋露多。","翠筠入疎柳，清影拂圆荷。","岁晏琅玕实，心期有凤过。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","中秋","秋"],"cats":{"四季":["秋天"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.408},{"uid":"1f6ef42b-eb0a-49f8-971b-d59a58ec6239","title":"百丈谿新理茅茨读书","author":"阎防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浪迹弃人世，远山自幽独。","始傍巢由踪，吾其获心曲。","荒庭何所有，老树半空腹。","秋蜩鸣北林，暮鸟穿我屋。","栖迟乐遵渚，恬旷寡所欲。","开卦推盈虚，散帙攻节目。","养闲度人事，达命知止足。","不学东周儒，俟时劳伐辐。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.9},{"uid":"77ac62ee-6396-4ac0-a3ab-cb84ba2e5cd0","title":"寒食","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["春城无处不飞花，寒食东风御柳斜。","日暮汉宫传蜡烛，轻烟散入五侯家。"],"theme":"讽喻刺世","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"2d6eff0e-d937-4d1f-9e3b-91241dd3db27","title":"冬夜赠别友人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["愁听千家流水声，相思独向月中行。","侵堦暗草秋霜重，遍郭寒山夜月明。","连年客舍唯多病，数亩田园又废耕。","更送乘轺归上国，应怜贡禹未成名。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["夜","冬"],"cats":{"抒情":["友情","离别","思念","伤感","孤独"],"四季":["秋天","冬天"],"生活":["田野"]},"theme_conf":0.601},{"uid":"ae31da45-73ca-411d-ada1-d564ed9c765a","title":"自悼","author":"薛令之","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朝日上团团，照见先生盘。","盘中何所有，苜蓿长阑干。","饭澁匙难绾，羹稀筯易宽。","只可谋朝夕，何由保岁寒。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"]},"theme_conf":0.86},{"uid":"2b7e4088-5605-41dc-8565-bcce73c7dfad","title":"相和歌辞 楚妃怨","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["梧桐叶下黄金井，横架辘轳牵素绠。","美人初起天未明，手拂银缾秋水冷。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"fb087f9d-b19c-4c65-a310-c605f73a1fde","title":"夏日叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夏日出东北，陵天经中街。","朱光彻厚地，郁蒸何由开。","上苍久无雷，无乃号令乖。","雨降不濡物，良田起黄埃。","飞鸟苦热死，池鱼涸其泥。","万人尚流冗，举目唯蒿莱。","至今大河北，化作虎与豺。","浩荡想幽蓟，王师安在哉？","对食不能餐，我心殊未谐。","眇然贞观初，难与数子偕。"],"theme":"民生疾苦","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"山水":["江河"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"e0eb3016-9288-4dc0-9257-3de36e5ad73c","title":"锦瑟","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["锦瑟无端五十弦，一弦一柱思华年。","庄生晓梦迷蝴蝶，望帝春心托杜鹃。","沧海月明珠有泪，蓝田日暖玉生烟。","此情可待成追忆，只是当时已惘然。"],"theme":"爱情相思","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"相思","mood2":["惆怅"],"scene":["春","月","江","鸟"],"cats":{"抒情":["思念"],"四季":["春天"]},"theme_conf":0.633},{"uid":"6d303931-f900-4f29-a8b9-caea611a521f","title":"寄韩谏议","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今我不乐思岳阳，身欲奋飞病在床。","美人娟娟隔秋水，濯足洞庭望八荒。","鸿飞冥冥日月白，青枫叶赤天雨霜。","玉京群帝集北斗，或骑骐𬴊翳凤皇。","芙蓉旌旗烟雾乐，影动倒景摇潇湘。","星宫之君醉琼浆，羽人稀少不在旁。","似闻昨者赤松子，恐是汉代韩张良。","昔随刘氏定长安，帷幄未改神惨伤。","国家成败吾岂敢，色难腥腐餐风香。","周南留滞古所惜，南极老人应寿昌。","美人胡为隔秋水，焉得置之贡玉堂。"],"theme":"游仙梦幻","theme2":["送别","边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["星星"],"人物":["女子"]},"theme_conf":0.385},{"uid":"34d3b009-d2b6-456e-969f-8b4a0283356b","title":"东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["南去经三楚，东来过五湖。","山头看候馆，水面问征途。","地远穷江界，天低极海隅。","飘零同落叶，浩荡似乘桴。","渐觉乡原异，深知土产殊。","夷音语嘲异常，蛮态笑睢盱。","水市通阛阓，烟村混舳舻。","吏征渔户税，人纳火田租。","亥日饶𫚥蟹，寅年足虎䝙。","成人男作丱，事鬼女为巫。","楼暗攒倡妇，隄长簇贩夫。","夜船论铺赁，春酒断缾酤。","见果皆卢橘，闻禽悉鹧鸪。","山歌猨独叫，野哭鸟相呼。","岭徼云成栈，江郊水当郛。","月移翘柱鹤，风泛飐樯乌。","鼇碍潮无信，蛟惊浪不虞。","鼍鸣江擂鼓，蜃气海浮图。","树裂山魈穴，沙含水弩枢。","喘牛犂紫芋，羸马放青菰。","绣面谁家婢，鵶头几岁奴。","泥中采菱芡，烧后拾樵苏。","鼎腻愁烹鼈，盘腥厌脍鲈。","钟仪徒恋楚，张翰浪思吴。","气序凉还热，光阴旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园废，江西岁月徂。","忆归恒惨澹，怀旧忽踟蹰。","自念咸秦客，尝为邹鲁儒。","蕴藏经国术，轻弃度关𦈡。","赋力凌鹦鹉，词锋敌辘轳。","战文重掉鞅，射策一弯弧。","崔杜鞭齐下，元韦辔并驱。","名声逼扬马，交分过萧朱。","世务轻摩揣，周行窃觊觎。","风云皆会合，雨露各沾濡。","共遇升平代，偏慙固陋躯。","承明连夜直，建礼拂晨趋。","美服颁王府，珍羞降御厨。","议高通白虎，谏切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗张鸟兽，天籁动笙芋。","戈劒星芒耀，鱼龙电策驱。","定场排越伎，促坐进吴歈。","缥缈疑仙乐，婵娟胜画图。","歌鬟低翠羽，舞汗堕红珠。","别选闲游伴，潜招小饮徒。","一杯愁已破，三醆气弥麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正当垆。","论笑杓胡律，谈怜巩嗫嚅。","李酣犹短窦，庾醉更蔫迂。","鞍马呼教住，骰盘喝遣输。","长驱波卷白，连掷采成卢。","筹幷频逃席，觥严列置盂。","满巵那可灌，颓玉不胜扶。","入视中枢草，归乘内廐驹。","醉曾冲宰相，骄不揖金吾。","日近恩虽重，云高势却孤。","飜身落霄汉，失脚倒泥涂。","博望移门籍，浔阳佐郡符。","时情变寒暑，世利算锱铢。","即日辞双阙，明朝别九衢。","播迁分郡国，次第出京都。","秦岭驰三驿，商山上二邘。","岘阳亭寂莫，夏口路崎岖。","大道全生棘，中丁尽执殳。","江关未撤警，淮寇尚稽诛。","林对东西寺，山分大小姑。","庐峰莲刻削，湓浦带萦纡。","九派吞青草，孤城覆绿芜。","黄昏钟寂寂，清晓角呜呜。","春色辞门柳，秋声到井梧。","残芳悲𫛸鴂，暮节感茱萸。","蘂坼金英菊，花飘雪片芦。","波红日斜没，沙白月平铺。","几见林抽笋，频惊燕引雏。","岁华何倏忽，年少不须臾。","眇默思千古，苍茫想八区。","孔穷缘底事，颜夭有何辜。","龙智犹经醢，龟灵未免刳。","穷通应已定，圣哲不能逾。","况我身谋拙，逢他厄运拘。","漂流随大海，锤锻任洪𬬻。","险阻尝之矣，栖迟命也夫。","沈冥消意气，穷饿耗肌肤。","防瘴和残药，迎寒补旧襦。","书床鸣蟋蟀，琴匣网蜘蛛。","贫室如悬磐，端忧剧守株。","时遭人指点，数被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女惊朝不起，妻怪夜长吁。","万里抛朋侣，三年隔友于。","自然悲聚散，不是恨荣枯。","去夏微之疟，今春席八殂。","天涯书达否，泉下哭知无。","谩写诗盈卷，空盛酒满壶。","只添新怅望，岂复旧欢娱。","壮志因愁减，衰容与病俱。","相逢应不识，满颔白髭须。"],"theme":"寄赠酬答","theme2":["羁旅思乡","民生疾苦","送别"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["酒","山","江","夏","夜","鸟"],"cats":{"抒情":["思乡","伤感","孤独","悼亡"],"四季":["夏天"],"天气":["月亮"],"人生":["励志","时光","梦想"],"生活":["田野"],"节日":["中秋节","重阳节"]},"theme_conf":0.85},{"uid":"bd57a0b0-28a1-4d53-bc09-51899d2dac38","title":"兵车行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["车辚辚，马萧萧，行人弓箭各在腰。","耶娘妻子走相送，尘埃不见咸阳桥。","牵衣顿足阑道哭，哭声直上干云霄。","道傍过者问行人，行人但云点行频。","或从十五北防河，便至四十西营田。","去时里正与裹头，归来头白还戍边。","边亭流血成海水，武皇开边意未已。","君不闻汉家山东二百州，千村万落生荆杞。","纵有健妇把锄犂，禾生陇亩无东西。","况复秦兵耐苦战，被驱不异犬与鸡。","长者虽有问，役夫敢申恨。","且如今年冬，未休关西卒。","县官急索租，租税从何出？信知生男恶，反是生女好。","生女犹是嫁比邻，生男埋没随百草。","君不见青海头，古来白骨无人收。","新鬼烦冤旧鬼哭，天阴雨湿声啾啾。"],"theme":"边塞征战","theme2":["民生疾苦"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["冬"],"cats":{"四季":["冬天"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"7e1be9c9-fa2f-44c2-a6bc-3edcece745fe","title":"夜泊牛渚怀古","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["牛渚西江夜，青天无片云。","登舟望秋月，空忆谢将军。","余亦能高咏，斯人不可闻。","明朝挂帆席，枫叶落纷纷。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["江","月","夜","舟","秋"],"cats":{"抒情":["思念","怀古"],"四季":["秋天"]},"theme_conf":0.796},{"uid":"402c5cc0-8255-4a01-8e5e-2641417bf8a2","title":"杂曲歌辞 白马篇","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙马花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬鸡事万乘，轩盖一何高。","弓摧宜山虎，手接泰山猱。","酒后竞风彩，三杯弄宝刀。","杀人如翦草，剧孟同游遨。","发愤去函谷，从军向临洮。","叱咤万战场，匈奴尽波涛。","归来使酒气，未肯拜萧曹。","羞入原宪室，荒径隐蓬蒿。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":[],"scene":["山","酒","秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.79},{"uid":"d949bec5-34ee-44c3-a70c-ecfa7cb36b0c","title":"玉真张观主下小女冠阿容","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绰约小天仙，生来十六年。","姑山半峰雪，瑶水一枝莲。","晚院花留立，春窗月伴眠。","回眸虽欲语，阿母在傍边。"],"theme":"爱情相思","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","雪","春","月"],"cats":{"四季":["春天"],"人物":["母亲"]},"theme_conf":0.6},{"uid":"c89fcc8b-70df-4b67-84c8-6c855555eb41","title":"杂曲歌辞 夜坐吟","author":"李白","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["踏踏马头谁见过，眼看北斗直天河。","西风罗幕生翠波，铅华笑妾颦青蛾。","为君起唱长相思，帘外严霜皆倒飞。","明星烂烂东方陲，红霞稍出东南涯，陆郎去矣乘斑骓。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念","闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.5},{"uid":"71077c12-3f1e-40bc-b453-2fa73f3be4aa","title":"又题洛苑梧叶上","author":"天宝宫人","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一叶题诗出禁城，谁人酬和独含情。","自嗟不及波中叶，荡漾乘春取次行。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.617},{"uid":"3530235e-e711-41d8-b30a-4a238a3d9ed4","title":"宋中十首 五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["登高临旧国，怀古对穷秋。","落日鸿雁度，寒城砧杵愁。","昔贤不复有，行矣莫淹留。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":1.0},{"uid":"33f3bc50-8a7f-4445-995e-1d1af406ae26","title":"送汴州监军俱文珍","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["奉使羌池静，临戎汴水安。","冲天鹏翅阔，报国劒铓寒。","晓日驱征骑，春风咏采兰。","谁言臣子道，忠孝两全难。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["爱国"],"四季":["春天"]},"theme_conf":0.507},{"uid":"dcb153ef-db2d-4222-b72e-f762b9f6ef6d","title":"拟古三首 三","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["颓光无淹晷，逝水有迅流。","绿苔纷易歇，红颜不再求。","歌笑当及春，无令壮志秋。","弱年仕关辅，簃门豁御沟。","敷愉东城际，婉娈南陌头。","荷花娇绿水，杨叶暖青楼。","中有绮罗人，可怜名莫愁。","画屏绕金膝，珠帘悬玉钩。","纤指调宝琴，泠泠哀且柔。","赠君鸳鸯带，因以鹔鹴裘。","窗晓吟日坐，闺夕秉烛游。","无作北门客，咄咄怀百忧。"],"theme":"咏怀抒感","theme2":["悼亡挽歌","送别","山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","秋"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天","秋天"],"人生":["励志","梦想"]},"theme_conf":0.7},{"uid":"7241e2c5-7d41-4cbd-86d7-9be3e63208f7","title":"送客之上谷","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北客悲秋色，田园忆去来。","披衣朝易水，匹马夕燕台。","风翦荷花碎，霜迎栗罅开。","赏心知不浅，累月故人杯。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":["悲慨"],"mood":"悲怆","mood2":["相思"],"scene":["秋"],"cats":{"抒情":["友情","思念","思乡","伤感"],"四季":["秋天"],"生活":["田野"]},"theme_conf":0.465},{"uid":"ca8dc6f9-911f-4ae1-8f6a-0e6b374a5ede","title":"奉先刘少府新画山水障歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["堂上不合生枫树，怪底江山起烟雾。","闻君埽却赤县图，乘兴谴画沧洲趣。","画师亦无数，好手不可遇。","对此融心神，知君重毫素。","岂但祁岳与郑虔，笔迹远过杨契丹。","得非悬圃裂，无乃潇湘飜。","悄然坐我天姥下，耳边已似闻清猨。","反思前夜风雨急，乃是蒲城鬼神人。","元气淋漓障犹湿，真宰上诉天应泣。","野亭春还杂花远，渔翁暝蹋孤舟立。","沧浪水深青溟阔，攲岸侧岛秋毫末。","不见湘妃鼓瑟时，至今斑竹临江活。","刘侯天机精，爱画入骨髓。","自有两儿郎，挥洒亦莫比。","大儿聪明到，能添老树巅崖里。","小儿心孔开，貌得山僧及童子。","若耶溪，云门寺。","吾独胡为在泥滓，青鞵布韤从此始。"],"theme":"山水田园","theme2":["题画咏艺"],"style":"幽峭","style2":["清新","沉郁"],"mood":"孤寂","mood2":["相思","悲怆"],"scene":["山","秋","江","雨"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.468},{"uid":"b4f9c5b3-0108-4127-bf3e-73fd207176f3","title":"杂曲歌辞 行路难三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机才多岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道？君不见吴中张翰称达士，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"theme":"民生疾苦","theme2":["哲理悟道"],"style":"旷达","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["酒","端午","秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.601},{"uid":"5180277d-a3b2-4644-9f1f-2d5a4af7c604","title":"杂曲歌辞 春日行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["春日融融池上暖，竹牙出土兰心短。","草堂晨起酒半醒，家僮报我园花满。","头上皮冠未曾整，直入花间不寻径。","树树殷勤尽遶行，举枝未徧春日暝。","不用积金著青天，不用服药求神仙。","但愿园里花长好，一生饮酒花前老。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"c353940d-4bbc-4420-83bf-07cb4606d35f","title":"赋得早雁出云鸣","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["初秋玉露清，早雁出空鸣。","隔云时乱影，因风乍含声。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"四季":["秋天"],"天气":["写云"],"动物":["写鸟"]},"theme_conf":0.697},{"uid":"33f9ccb9-1b90-41cf-9ce3-e9394b68c4a3","title":"落叶","author":"孔绍安","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["早秋惊落叶，飘零似客心。","翻飞未肯下，犹言惜故林。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.791},{"uid":"cbdd1bd4-58ea-4bd4-a64c-40654f818387","title":"咏庭梅寄人","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蚤花常犯寒，繁实常苦酸。","何事上春日，坐令芳意阑。","夭桃定相笑，游妓肯回看。","君问调金鼎，方知正味难。"],"theme":"咏物","theme2":["咏物"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["园林","花","春","冬"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"24a70c7d-e01e-46b4-9764-647153bf10d0","title":"诣顺公问道","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["此身知是妄，远远诣支公。","何法住持后，能逃生死中。","秋苔经古径，萚叶满疎丛。","方便如开诱，南宗与北宗。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","秋"],"cats":{"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"7569d663-805a-47fc-97ed-72d88c179880","title":"送右司薛员外赴处州","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["怀中天子书，腰下使君鱼。","瀑布和云落，仙都与世疎。","远程兼水陆，半岁在舟车。","相送难相别，南风入夏初。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","舟"],"cats":{"四季":["夏天"],"山水":["瀑布"]},"theme_conf":1.0},{"uid":"f8ec87e7-3074-40dd-8d87-a260dad83ae7","title":"相和歌辞 短歌行二首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曈曈太阳如火色，上行千里下一刻。","出为白昼入为夜，圜转如珠住不得。","住不得，可奈何？为君举酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风才往春风回。","人无根蔕时不驻，朱颜白日相隳颓。","劝君且强笑一面，劝君复强饮一杯。","人生不得长欢乐，年少须臾老到来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","秋","春"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"天气":["写风"],"人生":["青春"]},"theme_conf":0.65},{"uid":"8cefa67f-2b9a-4e13-8158-4d38cbfb331b","title":"长沙过贾谊宅","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["三年谪宦此栖迟，万古惟留楚客悲。","秋草独寻人去后，寒林空见日斜时。","汉文有道恩犹薄，湘水无情吊岂知。","寂寂江山摇落处，怜君何事到天涯。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"雄浑","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","江","山"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"]},"theme_conf":0.519},{"uid":"b18e52d9-a647-499b-a759-bca7c250393f","title":"与沈杨二舍人合老同食勅赐樱桃玩物感恩因成十四韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["清晓趋丹禁，红缨降紫宸。","驱禽养得熟，和叶摘来新。","圆转盘倾玉，鲜明笼透银。","内园题两字，西掖赐三臣。","荧惑晶华赤，醍醐气味真。","如珠未穿孔，似火不烧人。","杏俗难为对，桃顽讵可伦。","肉嫌卢橘厚，皮笑荔枝皴。","琼液酸甜足，金丸大小匀。","偷须防曼倩，惜莫掷安仁。","手擘才离核，匙抄半是津。","甘为舌上露，暖作腹中春。","已惧长尸禄，仍惊数食珍。","最慙恩未报，饱𫗪不才身。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"植物":["桃花"],"食物":["荔枝"]},"theme_conf":0.87},{"uid":"8e427cef-2f58-4725-a290-2e3e6f4db072","title":"听蜀道士琴歌","author":"李宣古","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["至道不可见，正声难得闻。","忽逢羽客抱绿绮，西别峨嵋峰顶云。","初排□面蹑轻响，似掷细珠鸣玉上。","忽挥素爪画七弦，苍崖劈裂迸碎泉。","愤声高，怨声咽，屈原呌天两妃绝。","朝雉飞，双鹤离，属玉夜啼独鹜悲。","吹我神飞碧霄里，牵我心灵入秋水。","有如驱逐太古来，邪淫辟荡贞心开。","孝为子，忠为臣，不独语言能教人。","前弄啸，后弄嚬，一舒一惨非冬春。","从朝至暮听不足，相将直说瀛洲宿。","更深弹罢背孤灯，窗雪萧萧打寒竹。","人间岂合值仙踪，此别多应不再逢。","抱琴却上瀛洲去，一片白云千万峰。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["夜","冬","雪","端午"],"cats":{"抒情":["离别","孤独"],"四季":["冬天"],"节日":["端午节"]},"theme_conf":0.437},{"uid":"49577c84-9adc-4983-96ef-81d474492aa9","title":"又雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南雪不到地，青崖沾未消。","微微向日薄，脉脉去人遥。","冬热鸳鸯病，峡深豺虎骄。","愁边有江水，焉得北之朝。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["爱情","伤感"],"四季":["冬天"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"3f692193-2a80-41b5-b4bf-47176d040535","title":"赋得长亭柳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["濯濯长亭柳，阴连灞水流。","雨搓金缕细，烟褭翠丝柔。","送客添新恨，听莺忆旧游。","赠行多折取，那得到深秋。"],"theme":"送别","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":["相思"],"scene":["楼","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.786},{"uid":"f250e306-a578-4bb0-bdef-066a2be420fb","title":"晚发咸阳寄同院遗补","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["征战初休草又衰，咸阳晚眺泪堪垂。","去路全无千里客，秋田不见五陵儿。","秦家故事随流水，汉代高坟对石碑。","回首青山独不语，羡君谈笑万年枝。"],"theme":"咏史怀古","theme2":["悼亡挽歌","边塞征战"],"style":"旷达","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["园林","秋"],"cats":{"抒情":["伤感","孤独","悼亡","怀古"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.96},{"uid":"e4b624d5-60a5-42e4-8417-298431fb7625","title":"成都府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["翳翳桑榆日，照我征衣裳。","我行山川异，忽在天一方。","但逢新人民，未卜见故乡。","大江东流去，游子去日长。","曾城填华屋，季冬树木苍。","喧然名都会，吹箫间笙簧。","信美无与适，侧身望川梁。","鸟[雀]夜各归，中原杳茫茫。","初月出不高，众星尚争光。","自古有羁旅，我何苦哀伤。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","夜","月"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"山水":["长江"]},"theme_conf":0.617},{"uid":"edeba321-b6dc-4573-b3d9-6e5d1ac95d0c","title":"将之泸郡旅次遂州遇裴晤员外谪居于此话旧凄凉因寄二首 二","author":"郑谷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔年共照松溪影，松折溪荒僧已无。","今日重思锦城事，雪销花谢梦何殊。","乱离未定身俱老，骚雅全休道甚孤。","我拜师门更南去，荔枝春熟向渝泸。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["雪","春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"人物":["老师"],"食物":["荔枝"]},"theme_conf":0.92},{"uid":"1d65129a-ea27-4ec6-b8ed-8c12ee3d0d0a","title":"秋日书怀","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["金貂玉铉奉君恩，夜漏晨钟老掖垣。","参决万机空有媿，静观群动亦无言。","杯中壮志红颜歇，林下秋声绛叶翻。","倦鸟不知归去日，青芜白露满郊园。"],"theme":"咏怀抒感","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"慷慨","mood2":["恬淡"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"],"人生":["励志","梦想"]},"theme_conf":0.9},{"uid":"948fa40a-492e-4fa1-99f4-b002ae87cd24","title":"清平调词三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"theme":"游仙梦幻","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.513},{"uid":"fdf597bd-d45c-407d-9a5b-739be83771de","title":"春日望海","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["披襟眺沧海，凭轼玩春芳。","积流横地纪，疎派引天潢。","仙气凝三岭，和风扇八荒。","拂潮云布色，穿浪日舒光。","照岸花分彩，迷云雁断行。","怀卑运深广，持满守灵长。","有形非易测，无源讵可量。","洪涛经变野，翠岛屡成桑。","之罘思汉帝，碣石想秦皇。","霓裳非本意，端拱且图王。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":0.693},{"uid":"7b60930e-556e-433e-a978-8a175c33ee87","title":"病柏","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有柏生崇冈，童童状车盖。","偃蹙龙虎姿，主当风云会。","神明依正直，故老多再拜。","岂知千年根，中路颜色坏。","出非不得地，蟠据亦高大。","岁寒忽无凭，日夜柯叶改。","丹凤领九雏，哀鸣翔其外。","鸱鸮志意满，养子穿穴内。","客从何乡来，伫立久吁怪。","静求元精理，浩荡难倚赖。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":["恬淡"],"scene":["冬","夜"],"cats":{"抒情":["思乡"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"ae660471-84bc-4a58-a438-005b8a99c3c1","title":"赤壁","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深锁二乔。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.739},{"uid":"22abc39e-e43e-4644-97f0-08053b5fa3ee","title":"相和歌辞 上云乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞香走红满天春，花龙盘盘上紫云。","三千宫女列金屋，五十弦瑟海上闻。","大江碎碎银沙路，嬴女机中断烟素。","断烟素，缝舞衣，八月一日君前舞。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","春","月"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["长江"],"天气":["写云"]},"theme_conf":1.0},{"uid":"f619ba03-5e1d-497e-af90-2367f48e9c01","title":"杂曲歌辞 昔昔盐 一去无还意","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良人征绝域，一去不言还。","百战攻胡虏，三冬阻玉关。","萧萧边马思，猎猎戍旗闲。","独把千重恨，连年未解颜。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"人生":["战争"]},"theme_conf":0.796},{"uid":"253ad6ba-185c-4915-9b9a-95e2d1a4515a","title":"梅花二首 二","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["迎春雪艳飘零极，度夕蟾华掩映多。","欲托清香传远信，一枝无计奈愁何。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["花","冬","雪","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.98},{"uid":"fde30eaa-9b2c-47ce-ba49-c1356353ac9a","title":"陇西行四首 二","author":"陈陶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["誓扫匈奴不顾身，五千貂锦丧胡尘。","可怜无定河边骨，犹是春闺梦里人。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"绮丽","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.448},{"uid":"ad7a0111-98f9-43e5-bad4-9c73c5336389","title":"归雁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闻道今春雁，南归自广州。","见花辞涨海，避雪到罗浮。","是物关兵气，何时免客愁。","年年霜露隔，不过五湖秋。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.559},{"uid":"32083c21-f38b-4576-93f8-7dda5f34ff6b","title":"湖中古愁三首 二","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["昔我覩云梦，穷秋经汨罗。","灵均竟不返，怨气成微波。","奠桂开古祠，朦胧入幽萝。","落日潇湘上，凄凉吟九歌。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","江","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.65},{"uid":"cp3852710fce4ca5","title":"祝英台近","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["采幽香，巡古苑，竹冷翠微路。","斗草溪根，沙印小莲步。","自怜两鬓清霜，一年寒食，又身在、云山深处。","昼闲度。","因甚天也悭春，轻阴便成雨。","绿暗长亭，归梦趁风絮。","有情花影阑干，莺声门径，解留我、霎时凝伫。"],"theme":"羁旅思乡","theme2":["闲适隐逸","节令风俗","送别"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","清明"],"cats":{"抒情":["离别","思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.85},{"uid":"3a07b10d-d744-4217-9ed1-39199b7ec44f","title":"送王六觐巢县叔父二首 二","author":"李涉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长忆山阴旧会时，王家兄弟尽相随。","老来放逐潇湘路，泪滴秋风引献之。"],"theme":"送别","theme2":["亲情"],"style":"沉郁","style2":["旷达","婉约"],"mood":"愁怨","mood2":["相思"],"scene":["秋","山"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.603},{"uid":"3cc093e1-e345-4ffe-9721-f49b48891cfa","title":"洛下送牛相公出镇淮南","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北阙至东京，风光十六程。","坐移丞相阁，春入广陵城。","红斾拥双节，白须无一茎。","万人开路看，百吏立班迎。","阃外君弥重，尊前我亦荣。","何须身自得，将相是门生。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","楼"],"cats":{"四季":["春天"],"人物":["老师"]},"theme_conf":0.689},{"uid":"29ad430b-4f67-43c7-bbd2-0a7020e2a9aa","title":"和段校书冬夕寄题庐山","author":"刘得仁","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["名高身未到，此恨蓄多时。","是夕吟因话，他年必去随。","尝闻庐岳顶，半入楚江湄。","几处悬崖上，千寻瀑布垂。","炉峰松淅沥，湓浦柳参差。","日色连湖白，钟声拂浪迟。","烟梯缘薜荔，岳寺步欹危。","地本饶灵草，林曾出祖师。","石楼霞耀壁，猨树鹤分枝。","细径萦岩末，高窗见海涯。","嵌空寒更极，寂寞夜尤思。","阴谷冰埋术，仙田雪覆芝。","乱泉禅客濑，异迹逸人知。","藓室新开灶，柽潭末了棋。","如何遂闲放，长得在希夷。","空务渔樵事，方无道路悲。","谢公台尚在，陶令柳潜衰。","尘外难相许，人间贵迹遗。","虽怀丹桂影，不忘白云期。","仁者终携手，今朝预赋诗。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山","瀑布"]},"theme_conf":0.381},{"uid":"484621fd-eb0e-4699-a17c-a7b8944752b9","title":"郊庙歌辞 五郊乐章 黑帝羽音","author":"魏征","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["严冬季月，星回风厉。","享祀报功，方祚来岁。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","月"],"cats":{"四季":["冬天"]},"theme_conf":0.94},{"uid":"e3bf5676-319c-460e-b5b2-e53daad7f6d0","title":"秋行官张请督促东渚耗稻向毕清晨遣女奴阿稽竖子阿段往问","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东渚雨今足，伫闻稉稻香。","上天无偏颇，蒲稗各自长。","人情见非类，田家戒其荒。","功夫竞搰搰，除草置岸旁。","谷者命之本，客居安可忘。","青春具所务，勤垦免乱常。","吴牛力容易，竝驱动莫当。","丰苗亦已穊，云水照方塘。","有生固蔓延，静一资隄防。","督领不无人，提携颇在纲。","荆扬风土暖，肃肃候微霜。","尚恐主守疎，用心未甚臧。","清朝遣婢仆，寄语逾崇冈。","西成聚必散，不独陵我仓。","岂要仁里誉，感此乱世忙。","北风吹蒹葭，蟋蟀近中堂。","荏苒百工休，郁纡迟暮伤。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.688},{"uid":"e26934fb-899d-4d12-aeec-81f11c5e903f","title":"送辰州郑使君","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁人不谴谪，君去独堪伤。","长子家无弟，慈亲老在堂。","惊魂随驿吏，冒暑向炎方。","未到猨啼处，参差已断肠。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["伤感","孤独"],"四季":["夏天"],"人物":["母亲"]},"theme_conf":0.758},{"uid":"e4d4c69a-9803-4863-bb93-8b0be8420bbd","title":"郊居对雨寄赵涓给事包佶郎中","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暑雨青山里，随风到野居。","乱沤浮曲砌，悬溜响前除。","尘镜愁多掩，蓬头嬾更梳。","夜窗凄枕席，阴壁润图书。","萧飒宜新竹，龙钟拾野蔬。","石泉空自咽，药圃不堪锄。","浊水淙深辙，荒兰拥败渠。","繁枝留宿鸟，碎浪出寒鱼。","桑屐时登望，荷衣自卷舒。","应怜在泥滓，无路托高车。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["雨","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.577},{"uid":"55b05ee5-c0de-46ce-8265-ec644b42ec4c","title":"清明日自西午桥至瓜岩村有怀","author":"张继","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晚霁龙门雨，春生汝穴风。","鸟啼官路静，花发毁垣空。","鸣玉慙时辈，垂丝学老翁。","旧游人不见，惆怅洛城东。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":["清新"],"mood":"愁怨","mood2":["惆怅","恬淡"],"scene":["清明","春"],"cats":{"四季":["春天"],"生活":["乡村","写桥"],"节日":["清明节"]},"theme_conf":0.76},{"uid":"f85432ef-54f1-4cc0-91c5-91af18ff0d05","title":"春日玄武门宴群臣","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["韶光开令序，淑气动芳年。","驻辇华林侧，高宴柏梁前。","紫庭文珮满，丹墀衮绂连。","九夷簉瑶席，五狄列琼筵。","娱宾歌湛露，广乐奏钧天。","清尊浮绿醑，雅曲韵朱弦。","粤余君万国，还慙抚八埏。","庶几保贞固，虚己厉求贤。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["青春"]},"theme_conf":0.95},{"uid":"4506e47c-d89b-45ca-a9c5-8f9c457409b6","title":"奉酬睢阳李太守","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["公族称王佐，朝经允帝求。","本枝疆我李，盘石冠诸刘。","礼乐光辉盛，山河气象幽。","系高周柱史，名重晋阳秋。","华省膺推择，青云宠宴游。","握兰多具美，前席有嘉谋。","赋得黄金赐，言皆白璧酬。","着鞭驱驷马，操刃解全牛。","出镇兼方伯，承家复列侯。","朝瞻孔北海，时用杜荆州。","广固才登陟，毘陵忽阻修。","三台冀入梦，四岳尚分忧。","郡邑连京口，山川望石头。","海门当建节，江路引鸣驺。","俗见中兴理，人逢至道休。","先移白额横，更息赭衣偷。","梁国歌来晚，徐方怨不留。","岂伊齐政术，将以变浇浮。","讼简知能吏，刑宽察要囚。","坐堂风偃草，行县雨随辀。","地是蒙庄宅，城遗阏伯丘。","孝王余井径，微子故田畴。","冬至招摇转，天寒䗖𬟽收。","猿岩飞雨雪，兔苑落梧楸。","列戟霜侵户，褰帏月在钩。","好贤常解榻，乘兴每登楼。","逸足横千里，高谈注九流。","诗题青玉案，衣赠黑貂裘。","穷巷轩车静，闲斋耳目愁。","未能方管乐，翻欲慕巢由。","讲德良难敌，观风岂易俦。","寸心仍有适，江海一扁舟。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["楼","舟","冬","山","秋"],"cats":{"抒情":["伤感"],"四季":["秋天","冬天"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"21d815f2-631f-4389-935e-f7054b2552e2","title":"谪官辰州冬至日[有]怀","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年长至在长安，策杖曾簪獬豸冠。","此岁长安逢至日，下堦遥想雪霜寒。","梦随行伍朝天去，身寄穷荒报国难。","北望南郊消息断，江头唯有泪阑干。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["相思","愁怨"],"scene":["冬"],"cats":{"抒情":["思乡","伤感","爱国"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"da5d4724-adca-4fa3-a364-6a7e79157a9a","title":"郊庙歌辞 五郊乐章 青帝角音 舒和","author":"魏征","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["笙歌籥舞属年韶，鹭鼓凫钟展时豫。","调露初迎绮春节，承云遽践苍霄驭。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.65},{"uid":"cp5992981c866722","title":"高阳台","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["修竹凝妆，垂杨驻马，凭阑浅画成图。","山色谁题，楼前有雁斜书。","东风紧送斜阳下，弄旧寒、晚酒醒馀。","自销凝，能几花前，顿老相如。","伤春不在高楼上，在灯前攲枕，雨外熏炉。","怕舣游船，临流可奈清臞。","飞红若到西湖底，搅翠澜、总是愁鱼。","莫重来，吹尽香绵，泪满平芜。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["楼","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"6925b93e-60a1-47f4-aad6-121caddd115d","title":"郊庙歌辞 祀九宫贵神乐章 豫和 一","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["于昭上穹，临下有光。","羽翼五佐，周流八荒。","谁其飨之，时文对敭。","虞经夏典，兹礼未遑。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.88},{"uid":"cd7b79ad-21b9-4628-ab5f-ddc8ba1343b6","title":"病橘","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["群橘少生意，虽多亦奚为。","惜哉结实小，酸涩如棠棃。","剖之尽蠹虫，采掇爽其宜。","纷然不适口，岂只存其皮。","萧萧半死叶，未忍别故枝。","玄冬霜雪积，况乃回风吹。","尝闻蓬莱殿，罗列潇湘姿。","此物岁不稔，玉食失光辉。","寇盗尚凭陵，当君减膳时。","汝病是天意，吾谂罪有司。","忆昔南海使，奔腾献荔支。","百马死山谷，到今耆旧悲。"],"theme":"送别","theme2":["游仙梦幻"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":0.541},{"uid":"862104e5-cfeb-4843-9e5f-8bdff6294563","title":"感春","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["看花泪尽知春尽，魂断看花秪恨春。","名位未沾身欲老，诗书宁救眼前贫。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"11b013f9-aa6a-4e55-8e68-195dc62f161f","title":"感遇十二首 七","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江南有丹橘，经冬犹绿林。","岂伊地气暖，自有岁寒心。","可以荐嘉客，奈何阻重深。","运命唯所遇，循环不可寻。","徒言树桃李，此木岂无阴。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["冬","江南"],"cats":{"四季":["冬天"]},"theme_conf":0.509},{"uid":"a31bfdee-c214-4ace-af0e-caeead25ec0c","title":"寒硖","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["行迈日悄悄，山谷势多端。","云门转绝岸，积阻霾天寒。","寒硖不可度，我实衣裳单。","况当仲冬交，溯沿增波澜。","野人寻烟语，行子傍水餐。","此生免荷殳，未敢辞路难。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","山"],"cats":{"四季":["冬天"]},"theme_conf":1.0},{"uid":"cp2d3f94e5589c06","title":"醉垂鞭","author":"张先","dynasty":"宋","section":"宋词","form":"词","paragraphs":["双蝶绣罗裙。","东池宴。","初相见。","朱粉不深匀。","闲花淡淡春。","细看诸处好。","人人道。","柳腰身。","昨日乱山昏。","来时衣上云。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["豪放","冲淡"],"mood":"恬淡","mood2":[],"scene":["酒","春"],"cats":{"四季":["春天"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"1dae0963-7101-4cf3-a045-1c0607adc419","title":"渔父","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白发沧浪上，全忘是与非。","秋潭垂钓去，夜月叩船归。","烟影侵芦岸，潮痕在竹扉。","终年狎鸥鸟，来去且无机。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","夜","月","舟","江"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.737},{"uid":"3e627ebd-0fd3-4669-a32c-5d108d5d4ce6","title":"相和歌辞 决绝[词]三首 一","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乍可为天上牵牛织女星，不愿为庭前红槿枝。","七月七日一相见，故心终不移。","那能朝开暮飞去，一任东西南北吹。","分不两相守，恨不两相思。","对面且如此，背面当何知。","春风撩乱伯劳语，此时抛去时。","握手苦相问，竟不言后期。","君情既决绝，妾意已参差。","借如死生别，安得长苦悲。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"旷达","style2":["沉郁"],"mood":"悲怆","mood2":["相思","愁怨"],"scene":["七夕","春","月"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"四季":["春天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"9c08d89e-9c4a-4cb2-a7f7-8affe0e8fe70","title":"送夏侯校书归华阴别墅","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山前白鹤村，竹雪覆柴门。","候客定为黍，务农因燎原。","乳冰悬暗井，莲石照晴轩。","贳酒邻里睦，曝衣场圃喧。","依然望君去，余性亦何昏。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","冬"],"cats":{"抒情":["离别"],"四季":["夏天"],"生活":["乡村"]},"theme_conf":0.483},{"uid":"e9ff4727-4dec-4fd8-ab61-336c693af7c3","title":"清明日登城春望寄大夫使君","author":"王表","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春城闲望爱睛天，何处风光不眼前。","寒食花开千树雪，清明日出万家烟。","兴来促席唯同舍，醉后狂歌尽少年。","闻说莺啼却惆怅，诗成不见谢临川。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"相思","mood2":["惆怅"],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.86},{"uid":"c2d84f66-1a8b-4780-aa15-84c95ab8c2a9","title":"说洄溪招退者","author":"元结","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长松亭亭满四山，山间乳窦流清泉。","洄溪正在此山里，乳水松膏常灌田。","松膏乳水田肥良，稻苗如蒲米粒长。","糜色如珈玉液酒，酒熟犹闻松节香。","溪边老翁年几许，长男头白孙嫁女。","问言只食松田米，无药无方向人语。","浯溪石下多泉源，盛暑大寒冬大温。","屠苏宜在水中石，洄溪一曲自当门。","吾今欲作洄溪翁，谁能住我舍西东。","勿惮山深与地僻，罗浮尚有葛仙翁。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["酒","冬","山","夏"],"cats":{"四季":["夏天","冬天"],"节日":["春节"]},"theme_conf":0.759},{"uid":"e1404531-b21b-4e48-b715-9a9ead6cf56c","title":"寄卢仝","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉川先生洛城里，破屋数间而已矣。","一奴长须不裹头，一婢赤脚老无齿。","辛勤奉养十余人，上有慈亲下妻子。","先生结发憎俗徒，闭门不出动一纪。","至今邻僧乞米送，仆忝县尹能不耻。","俸钱供给公私余，时致薄少助祭祀。","劝参留守谒大尹，言语才及輙掩耳。","水北山人得名声，去年去作幕下士。","水南山人又继往，鞍马仆从塞闾里。","少室山人索价高，两以谏官徴不起。","彼皆刺口论世事，有力未免遭驱使。","先生事业不可量，惟用法律自绳己。","春秋三传束高阁，独抱遗经究终始。","往年弄笔嘲同异，怪辞惊众谤不已。","近来自说寻坦途，犹上虚空跨绿駬。","去年生儿名添丁，意令与国充耘耔。","国家丁口连四海，岂无农夫亲耒耜。","先生抱才终大用，宰相未许终不仕。","假如不在陈力列，立言垂范亦足恃。","苗裔当蒙十世宥，岂谓贻厥无基阯。","故知忠孝生天性，洁身乱伦安足拟。","昨晚长须来下状，隔墙恶少恶难似。","每骑屋山下窥阚，浑舍惊怕走折趾。","凭依婚媾欺官吏，不信令行能禁止。","先生受屈未曾语，忽此来告良有以。","嗟我身为赤县令，操权不用欲何俟。","立召贼曹呼伍伯，尽取鼠辈尸诸市。","先生又遣长须来，如此处置非所喜。","况又时当长养节，都邑未可猛政理。","先生固是余所畏，度量不敢窥涯涘。","放纵是谁之过欤，效尤戮仆愧前史。","买羊沽酒谢不敏，偶逢明月曜桃李。","先生有意许降临，更遣长须致双鲤。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月","春","塞外","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":0.95},{"uid":"c9ef6401-b33c-4077-89bc-f01fc3279dce","title":"莺莺诗","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["殷红浅碧旧衣裳，取次梳头暗澹妆。","夜合带烟笼晓日，牡丹经雨泣残阳。","低迷隐笑原非笑，散漫清香不似香。","频动横波嗔阿母，等闲教见小儿郎。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":["悲怆","欢愉"],"scene":["春","鸟","花","夜","雨"],"cats":{"四季":["春天"],"人物":["母亲","儿童"],"动物":["写鸟"]},"theme_conf":0.88},{"uid":"08cf0ce8-bd26-4bab-a4d2-5bc43acf8376","title":"相和歌辞 日出行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["日出东方隈，似从地底来。","历天又入海，六龙所舍安在哉？","其始与终古不息，人非元气安能与之久裴回。","草不谢荣于春风，木不怨落于秋天。","谁挥鞭策驱四运，万物兴歇皆自然。","羲和羲和，汝奚汩没于荒淫之波。","鲁阳何德？驻景挥戈。","逆道违天，矫诬实多。","吾将囊括大块，浩然与溟涬同科。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"天气":["太阳"]},"theme_conf":0.65},{"uid":"bc8adf47-d6ff-46f9-99a3-ee2833e075b7","title":"杂曲歌辞 昔昔盐 花飞桃李蹊","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远期难可托，桃李自依依。","花径无容迹，戎裘未下机。","随风开又落，度日扫还飞。","欲折枝枝赠，那知归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"f523cd08-69d6-45c1-bc6a-633f43223f59","title":"春日淇上作","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["淇上春风涨，鸳鸯逐浪飞。","清明桑叶小，度雨杏花稀。","卫女红粧薄，王孙白马肥。","相将踏青去，不解惜罗衣。"],"theme":"节令风俗","theme2":["爱情相思","山水田园"],"style":"绮丽","style2":["婉约"],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"抒情":["爱情"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"e9e6425c-6c14-4f69-8694-87a8b96a43de","title":"春望","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["国破山河在，城春草木深。","感时花溅泪，恨别鸟惊心。","烽火连三月，家书抵万金。","白头搔更短，浑欲不胜簪。"],"theme":"咏怀抒感","theme2":["边塞征战","山水田园"],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"]},"theme_conf":0.7},{"uid":"42bc232f-00c5-4e92-8c55-8f38280a9dbe","title":"杂曲歌辞 爱妾换马 一","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一面妖桃千里蹏，娇姿骏背价应齐。","乍牵玉勒辞金栈，催整花钿出绣闺。","去日岂无沾袂泣，归时还有顿衔嘶。","婵娟躞蹀春风里，挥手摇鞭杨柳堤。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":1.0},{"uid":"153dd336-48dc-4173-a668-e9b90b2304fb","title":"舞曲歌辞 冬白纻歌","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["吴宫夜长宫漏款，帘幕四垂灯焰暖。","西施自舞王自管，雪纻翻翻鹤翎散。","促节牵繁舞腰嬾，舞腰嬾，王罢饮。","盖覆西施凤花锦，身作匡床臂为枕。","朝佩𪭢𪭢王晏寝，酒醒阍报门无事。","子胥死后言为讳，近王之臣谕王意。","共笑越王穷惴惴，夜夜抱冰寒不睡。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["欢愉"],"scene":["冬","夜"],"cats":{"抒情":["怀古"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"b67ddf05-43fb-4859-a1a9-34f95d45aabf","title":"和晋陵陆丞早春游望","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光照绿苹。","忽闻歌苦调，归思欲沾巾。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"清新","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.464},{"uid":"0336e989-ea54-4fdc-80b6-ffd5c6595a35","title":"热三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雷霆空霹雳，云雨竟虚无。","炎赫衣流汗，低垂气不苏。","乞为寒水玉，愿作冷秋菰。","何似儿童岁，风凉出舞雩。"],"theme":"咏怀抒感","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","雨","夏"],"cats":{"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.83},{"uid":"ee3195f6-eb17-4e87-b714-f7cf07ff03f2","title":"鼓吹曲辞 上之回","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三十六离宫，楼台与天通。","阁道步行月，美人愁烟空。","恩疎宠不及，桃李伤春风。","淫乐意何极，金舆向回中。","万乘出黄道，千旗扬彩虹。","前军细柳北，后骑甘泉东。","岂问渭川老，宁邀襄野童。","秋暮瑶池宴，归来乐未穷。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"沉郁","style2":["悲慨"],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.538},{"uid":"889929d5-2846-4b0b-a3ad-1572ec48dfa4","title":"仲夏江阴官舍寄裴明府","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万室边江次，孤城对海安。","朝霞晴作雨，湿气晚生寒。","苔色侵衣桁，潮痕上井栏。","题诗招茂宰，思尔欲辞官。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["江河"]},"theme_conf":0.97},{"uid":"3781db86-9a0f-4243-806a-63bfbd4bc927","title":"送刘禹锡侍御出刺连州","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["遐荒迢遰五羊城，归兴浓消客里情。","家近似忘山路险，土甘殊觉瘴烟轻。","梅花清入罗浮梦，荔子红分广海程。","此去定知偿隐趣，石田春雨读书耕。"],"theme":"送别","theme2":[],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["花","春","雨","山"],"cats":{"四季":["春天"],"人生":["读书"],"食物":["荔枝"]},"theme_conf":0.538},{"uid":"776db07f-66d2-4776-bd49-70f44b8aa67f","title":"奉和太常王卿酬中书李舍人中书寓直春夜对月见寄","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["露如轻雨月如霜，不见星河见鴈行。","虚晕入池波自泛，满轮当苑桂多香。","春台几望黄龙阙，云路宁分白玉郎。","是夜巴歌应金石，岂殊萤影对清光。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"绮丽","style2":["婉约","清新"],"mood":"相思","mood2":[],"scene":["月","春","夜"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮","星星"]},"theme_conf":0.98},{"uid":"ef9b9e25-0e0d-4eca-83c6-43d1b4fa241f","title":"赠渔父","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["芦花深泽静垂纶，月夕烟朝几十春。","自说孤舟寒水畔，不曾逢著独醒人。"],"theme":"闲适隐逸","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春","舟","月"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"8c811630-909b-4aa3-ac92-db90021e132d","title":"崔驸马山亭宴集","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧史幽栖地，林间蹋凤毛。","洑流何处入，乱石闭门高。","客醉挥金椀，诗成得绣袍。","清秋多宴会，终日困香醪。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","山","楼","秋"],"cats":{"四季":["秋天"],"动物":["写马"]},"theme_conf":0.536},{"uid":"cp0f9b3bff925f7f","title":"驻马听・寂寂瑶阶，春日阑珊景物乖。困人天色，不堪梳洗傍妆台。梨花","author":"刘庭信","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["寂寞玉容衰，海常零落胭脂败。","自裁划，今春更比前春煞。"],"theme":"闺情宫怨","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"动物":["写马"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"c501f17a-230a-49b5-833c-5889a4e9bc85","title":"自淇涉黄河途中作十三首 十一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我行倦风湍，辍棹将问津。","空传歌瓠子，感慨独愁人。","孟夏桑叶肥，秾阴夹长津。","蚕农有时节，田野无闲人。","临水狎渔樵，望山怀隐沦。","谁能去京洛，顦顇对风尘。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["江","夏","舟","山"],"cats":{"抒情":["伤感","孤独"],"四季":["夏天"],"山水":["黄河"]},"theme_conf":0.603},{"uid":"99fc9acc-fbe7-4ecf-a3f3-5b9426ed68eb","title":"舞曲歌辞 屈柘词","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["杨柳萦桥绿，玫瑰拂地红。","绣衫金騕褭，花髻玉珑璁。","宿雨香潜润，春流水暗通。","画楼初梦断，晴日照湘风。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["花","春","雨","楼"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"0d876872-31d8-49d7-a9cf-efbf71e5827b","title":"横吹曲辞 紫骝马","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["争场看鬬鸡，白鼻紫䯄嘶。","漳水春归晚，丛台日向低。","歇鞍珠作汗，试劒玉如泥。","为谢红梁燕，年年妾独栖。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"8b41afb4-d737-43e1-9f79-1a8101eaa87e","title":"相和歌辞 从军行","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔从李都尉，双鞬照马蹄。","擒生黑山北，杀敌黄云西。","太白沈虏地，边草复萋萋。","归来邯郸市，百尺青楼梯。","感激然诺重，平生胆力齐。","芳筵暮歌发，艳粉轻鬟低。","半醉秋风起，铁骑门前嘶。","远戍报烽火，孤城严鼓鼙。","挥鞭望尘去，少妇莫含啼。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.858},{"uid":"8073152d-7f39-430b-93d2-24a9f7fc5323","title":"冬到金华山观因得故拾遗陈公学堂遗迹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涪右众山内，金华紫崔嵬。","上有蔚蓝天，垂光抱琼台。","系舟接绝壁，杖策穷萦回。","四顾俯层巅，澹然川谷开。","雪岭日色死，霜鸿有余哀。","焚香玉女跪，雾里仙人来。","陈公读书堂，石柱仄青苔。","悲风为我起，激烈伤雄才。"],"theme":"山水田园","theme2":["悼亡挽歌","游仙梦幻"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["山","冬"],"cats":{"抒情":["伤感","悼亡"],"四季":["冬天"],"人生":["读书"]},"theme_conf":0.424},{"uid":"e46d6dff-6b75-4e72-8637-707d78481256","title":"裴侍郎湘川回以青竹筒相遗因而赠之","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["楚竹青玉润，从来湘水阴。","缄书取直节，君子知虚心。","入用随宪简，积文不受金。","体将丹凤直，色映秋霜深。","宁肯假伶伦，谬为龙凤吟。","唯将翰院客，昔秘瑶华音。","长跪捧嘉贶，岁寒惭所钦。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","冬"],"cats":{"四季":["秋天","冬天"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"41e3f463-1460-4aed-a203-56402ea427ef","title":"戏招诸客","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄醅绿醑迎冬熟，绛帐红炉逐夜开。","谁道洛中多逸客，不将书唤不曾来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"四季":["冬天"],"人物":["老师"]},"theme_conf":1.0},{"uid":"b4636285-4584-486f-8b92-1192ac91983a","title":"谢刘相寄天柱茶","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["两串春团敌夜光，名题天柱印维扬。","偷嫌曼倩桃无味，捣觉嫦娥药不香。","惜恐被分缘利市，尽应难觅为供堂。","麤官寄与真抛却，赖有诗情合得尝。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜"],"cats":{"抒情":["感恩"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.82},{"uid":"f1b0eaa8-b5f7-4fd4-8431-2cb0bb304f54","title":"九日绝句","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禁苑秋来爽气多，昆明风动起沧波。","中流箫鼓诚堪赏，讵假横汾发櫂歌。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"793368a9-a932-42cc-bf9c-e959f80b45eb","title":"京口怀古","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["大江横万里，古渡渺千秋。","浩浩波声险，苍苍天色愁。","三方归汉鼎，一水限吴州。","霸国今何在，清泉长自流。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江","江南"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"]},"theme_conf":0.693},{"uid":"18e0b8cc-e35e-44c2-9756-c08d1bd2a2f6","title":"下第题长安客舍","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不遂青云望，愁看黄鸟飞。","棃花度寒食，客子未春衣。","世事随时变，交情与我违。","空余主人柳，相见却依依。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["恬淡","惆怅"],"scene":["清明","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.507},{"uid":"cp749e871e4d03de","title":"淡黄柳","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["空城晓月。","吹入垂杨陌。","马上单衣寒恻恻。","看尽鹅黄嫩绿，都是江南旧相识。","正岑寂。","明朝又寒食。","强携酒、小桥宅，怕梨花落尽成秋色。","燕燕飞来，问春何在，唯有池塘自碧。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["清明","江南","酒","秋","春","月"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"生活":["写桥"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"cp1eb7d5610773cc","title":"水龙吟","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚天千里清秋，水随天去秋无际。","遥岑远目，献愁供恨，玉簪螺髻。","落日楼头，断鸿声里，江南游子。","把吴钩看了，栏干拍遍，无人会、登临意。","休说鲈鱼堪。","尽西风、季鹰归未。","求田问舍，怕应羞见，刘郎才气。","可惜流年，忧愁风雨，树犹如此。","倩何人，唤取盈盈翠袖，英雄泪。"],"theme":"闺情宫怨","theme2":["亲情"],"style":"婉约","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":["江南","秋","雨"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.588},{"uid":"0d722410-b3ba-4272-a9ae-ccd584cde3df","title":"舞曲歌辞 柘枝词 三","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["意气成功日，春风起絮天。","楼台新邸第，歌舞小婵娟。","急破催摇曳，罗衫半脱肩。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["楼","中秋","春"],"cats":{"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"4a4822fe-71f9-448f-923f-ea4061d09e2f","title":"相和歌辞 采莲曲二首 二","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["采莲朅来水无风，莲潭如镜松如龙。","夏衫短袖交斜红，艳歌笑鬬新芙蓉，戏鱼住听莲花东。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","花"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"5f5d6ee5-b0eb-4fe8-b26f-26f4bd9fe093","title":"杂曲歌辞 渭城少年行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳二月梨花飞，秦地行人春忆归。","扬鞭走马城南陌，朝逢驿使秦川客。","驿使前日发章台，传道长安春早来。","棠梨宫中燕初至，葡萄馆里花正开。","念此使人归更早，三月便达长安道。","长安道上春可怜，摇风荡日曲河边。","万户楼台临渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬鸡下杜尘初合，走马章台日半斜。","章台帝城称贵里，青楼日晚歌钟起。","贵里豪家白马骄，五陵年少不相饶。","双双挟弹来金市，两两鸣鞭上渭桥。","渭城桥头酒新熟，金鞍白马谁家宿。","可怜锦瑟筝琵琶，玉台清酒就君家。","小妇春来不解羞，娇歌一曲杨柳花。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["欢愉"],"scene":["楼","清明","春","酒"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["青春"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.579},{"uid":"1b942cdf-a8ec-4bf9-8c1e-bba47e0c4726","title":"暮秋枉裴道州手札率尔遣兴寄近呈苏涣侍御","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["久客多枉友朋书，素书一月凡一束。","虚名但蒙寒温问，泛爱不救沟壑辱。","齿落未是无心人，舌存耻作穷途哭。","道州手札适复至，纸长要自三过读。","盈把那须沧海珠，入怀本倚昆山玉。","拨弃潭州百斛酒，芜没潇岸千株菊。","使我昼立烦儿孙，令我夜坐费灯烛。","忆子初尉永嘉去，红颜白面花映肉。","军符侯印取岂迟，紫燕𫘧耳行甚速。","圣朝尚飞战鬬尘，济世宜引英俊人。","黎元愁痛会苏息，夷狄跋扈徒逡巡。","授钺筑坛闻意旨，颓纲漏网期弥纶。","郭钦上书见大计，刘毅答诏惊群臣。","他日更仆语不浅，明公论兵气益振。","倾壶箫管黑白发，儛劒霜雪吹青春。","宴筵曾语苏季子，后来杰出云孙比。","茅斋定王城郭门，药物楚老渔商市。","市北肩舆每联袂，郭南抱瓮亦隐几。","无数将军西第成，早作丞相东山起。","鸟雀苦肥秋粟菽，蛟龙欲蛰寒沙水。","天下鼓角何时休，阵前部曲终日死。","附书与裴因示苏，此生已媿须人扶。","致君尧舜付公等，早据要路思捐躯。"],"theme":"边塞征战","theme2":["送别","民生疾苦"],"style":"沉郁","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨","慷慨"],"scene":["秋","夜"],"cats":{"抒情":["伤感","爱国"],"四季":["秋天"],"人生":["青春","战争"]},"theme_conf":0.356},{"uid":"cp6dc364d590f073","title":"猫儿坠・绿荷萧索无可盖眠鸥，碧粼粼露远洲。羁人无力冷飕飕，合愁，","author":"高明","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["早知道宋玉当时顿觉伤秋。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["江","夏","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["夏天","秋天"],"动物":["写鸟","写猫"],"植物":["荷花"]},"theme_conf":0.517},{"uid":"9ea879f4-9781-469a-8b52-fc5777e633c2","title":"茅屋为秋风所破歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["八月秋高风怒号，卷我屋上三重茅。","茅飞度江洒江郊，高者挂罥长林梢。","下者飘转沈塘坳，南邨群童欺我老无力。","忍能对面为盗贼，公然抱茅入竹去。","唇焦口燥呼不得，归来倚仗自叹息。","俄顷风定云墨色，秋天漠漠向昏黑。","布衾多年冷似铁，骄儿恶卧踏里裂。","床床屋漏无干处，雨脚如麻未断绝。","自经丧乱少睡眠，长夜沾湿何由彻。","安得广厦千万间，大庇天下寒士俱欢颜。","风雨不动安如山，呜呼！何时眼前突兀见此屋？","吾庐独破受冻死亦足。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"悲慨","style2":["幽峭"],"mood":"孤寂","mood2":["慷慨","欢愉"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.568},{"uid":"c4912092-34c2-42fe-a9ff-b924b0dddf7f","title":"相和歌辞 春江花月夜","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉树歌阑海云黑，花庭忽作青芜国。","秦淮有水水无情，还向金陵漾春色。","杨家二世安九重，不御华芝嫌六龙。","百幅锦帆风力满，连天展尽金芙蓉。","珠翠丁星复明灭，龙头劈浪哀笳发。","千里涵空照水魂，万枝破鼻团香雪。","漏转霞高沧海西，颇黎枕上闻天鸡。","蛮弦代雁曲如语，一醉昏昏天下迷。","四方倾动烟尘起，犹在浓香梦魂里。","后主荒宫有晓莺，飞来只隔西江水。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"0532d507-dd36-4bb4-868a-fe771d68c11e","title":"华清宫三十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绣岭明珠殿，层峦下缭墙。","仰窥丹槛影，犹想赭袍光。","昔帝登封后，中原自古强。","一千年际会，三万里农桑。","几席延尧舜，轩墀接禹汤。","雷霆驰号令，星斗焕文章。","钓筑乘时用，芝兰在处芳。","北扉闲木索，南面富循良。","至道思玄圃，平居厌未央。","钩陈裹岩谷，文陛压青苍。","歌吹千秋节，楼台八月凉。","神仙高缥缈，环珮碎丁当。","泉暖涵窓镜，云娇惹粉囊。","嫩岚滋翠葆，清渭照红粧。","帖泰生灵寿，懽娱岁序长。","月闻仙曲调，霓作舞衣裳。","雨露偏金穴，乾坤入醉乡。","玩兵师汉武，回手倒干将。","黥鬣掀东海，胡牙揭上阳。","喧呼马嵬血，零落羽林枪。","倾国留无路，还魂怨有香。","蜀峰横惨澹，秦树远微茫。","鼎重山难转，天扶业更昌。","望贤余故老，花萼旧池塘。","往事人谁问，幽襟泪独伤。","碧簷斜送日，殷叶半凋霜。","迸水倾瑶砌，疎风罅玉房。","尘埃羯鼓索，片段荔枝筐。","鸟啄摧寒木，蜗涎蠹画梁。","孤烟知客恨，遥起泰陵傍。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":["沉郁","豪放"],"mood":"愁怨","mood2":["孤寂","恬淡"],"scene":["山","花","园林","楼"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["秋天"],"人生":["战争"],"食物":["荔枝"]},"theme_conf":0.305},{"uid":"ae472a2c-7977-4ed6-a893-7ef7c3136666","title":"柴门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟登瀼西，回首望两崖。","东城干旱天，其气如焚柴。","长影没窈窕，余光散唅呀。","大江蟠嵌根，归海成一家。","下冲割坤轴，竦壁攒镆铘。","萧飒洒秋色，氛昏霾日车。","峡门自此始，最窄容浮查。","禹功翊造化，疎凿就攲斜。","巨渠决太古，众水为长蛇。","风烟渺吴蜀，舟楫通盐麻。","我今远游子，飘转混泥沙。","万物附本性，约身不愿奢。","茅栋盖一床，清池有余花。","浊醪与脱粟，在眼无咨嗟。","山荒人民少，地僻日夕佳。","贫病固其常，富贵任生涯。","老于干戈际，宅幸蓬荜遮。","石乱上云气，杉清延月华。","赏妍又分外，理惬夫何夸。","足了垂白年，敢居高士差。","书此豁平昔，回首犹暮霞。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["长江"],"天气":["月亮"],"生活":["乡村"]},"theme_conf":0.35},{"uid":"1fcf1381-8137-43b2-8863-bc92e00f50c8","title":"相和歌辞 决绝[词]三首 二","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["噫春冰之将泮，何余怀之独结。","有美一人，于焉旷绝。","一日不见，比一日于三年，况三年之旷别。","水得风兮小而已波，笋在苞兮高不见节。","矧桃李之当春，竞众人之攀折。","我自顾悠悠而若云，又安能保君皓皓之如雪。","感破镜之分明，覩泪痕之余血。","幸他人之既不我先，又安能使他人之终不我夺。","已焉哉！织女别黄姑，一年一度暂相见，彼此隔河何事无。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["春","冬","七夕","雪"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"e70522e6-cb7f-4624-94e7-96ce81db4c6c","title":"故吏部郎中赠给事中韦公挽歌二首 二","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["社里东城接，松阡北地开。","闻笳春色惨，执绋故人哀。","终日南山对，何时渭水回。","仁兄与恩旧，相望泣泉台。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","山"],"cats":{"抒情":["友情","悼亡"],"四季":["春天"]},"theme_conf":0.98},{"uid":"cpd2765c5b36f5e9","title":"青玉案","author":"无名氏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["年年社日停针线。","怎忍见、双飞燕。","今日江城春已半。","一身犹在，乱山深处，寂寞溪桥畔。","春衫著破谁针线。","点点行行泪痕满。","落日解鞍芳草岸。","花无人戴，酒无人劝，醉也无人管。"],"theme":"羁旅思乡","theme2":["山水田园","闲适隐逸"],"style":"婉约","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["酒","春","花"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.93},{"uid":"ea9ee6ef-9a41-42c5-8676-e47b412f0db9","title":"奉陪郑驸马韦曲二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["韦曲花无赖，家家恼杀人。","绿尊虽尽日，白发好禁春。","石角钩衣破，藤枝刺眼新。","何时占业竹，头戴小乌巾。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"动物":["写马"]},"theme_conf":0.72},{"uid":"cp910bd0baa4338d","title":"玉蝴蝶","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["望处雨收云断，凭阑悄悄，目送秋光。","晚景萧疏，堪动宋玉悲凉。","水风轻、苹花渐老，月露冷、梧叶飘黄。","遣情伤。","故人何在，烟水茫茫。","难忘。","文期酒会，几孤风月，屡变星霜。","海阔山遥，未知何处是潇湘。","念双燕、难凭远信，指暮天、空识归航。","黯相望。","断鸿声里，立尽斜阳。"],"theme":"送别","theme2":["哲理悟道"],"style":"绮丽","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":["悲怆","相思"],"scene":["秋","月","酒"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["秋天"]},"theme_conf":0.524},{"uid":"b4a96752-93b2-4088-bdb3-4c45a5584e78","title":"龊龊","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龊龊当世士，所忧在饥寒。","但见贱者悲，不闻贵者叹。","大贤事业异，远抱非俗观。","报国心皎洁，念时涕汍澜。","妖姬坐左右，柔指发哀弹。","酒肴虽日陈，感激宁为欢。","秋阴欺白日，泥潦不少干。","河堤决东郡，老弱随惊湍。","天意固有属，谁能诘其端。","愿辱太守荐，得充谏诤官。","排云呌阊阖，披腹呈琅玕。","致君岂无术，自进诚独难。"],"theme":"民生疾苦","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["酒","秋"],"cats":{"抒情":["伤感","孤独","爱国"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"2dad9262-faad-45d2-a3d8-69c51f97ddad","title":"送萧颖士赴东府得散字","author":"殷少野","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["官闲幕府下，聊以任纵诞。","文学鲁仲尼，高标嵇中散。","出门时雨润，对酒春风暖。","感激知己恩，别离魂欲断。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","春","雨"],"cats":{"抒情":["友情","离别"],"四季":["春天"]},"theme_conf":0.827},{"uid":"27423bb8-fa3f-41e6-83a6-9c105c176d3d","title":"御沟新柳","author":"冯宿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夹道天渠远，垂丝御柳新。","千条宜向日，万户共迎春。","轻翠含烟发，微音逐吹频。","静看思渡口，回望忆江滨。","袅袅分游骑，依依驻旅人。","阳和如可及，攀折在兹辰。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"清新","style2":["婉约","冲淡"],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.528},{"uid":"4e409fd6-6f44-40e3-82b0-3c0fb1f146ef","title":"秋暮忆中秋夜与王璠侍御赏月因怆远离聊以奉寄","author":"鲍防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["前月月明夜，美人同远光。","清尘一以间，今夕坐相忘。","风落芙蓉露，疑余绣被香。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"冲淡","style2":["沉郁","清新"],"mood":"相思","mood2":["欢愉"],"scene":["中秋","月","夜","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"天气":["月亮"],"人物":["女子"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"dc5bb894-c908-405b-8280-571cdb08da82","title":"绝句","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["江边踏青罢，回首见旌旗。","风起春城暮，高楼鼓角悲。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["清明","春","楼","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["清明节"]},"theme_conf":1.0},{"uid":"46b17890-4fbe-4d78-9fae-35ad3bad08e2","title":"奉和月夜观星应令","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["早秋炎景暮，初弦月彩新。","清风涤暑气，零露净嚣尘。","薄雾销轻縠，鲜云卷夕鳞。","休光灼前曜，瑞彩接重轮。","缘情摛圣藻，并作命徐陈。","宿草诚渝滥，吹嘘偶搢绅。","天文岂易述，徒知仰北辰。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月","夏","夜"],"cats":{"四季":["夏天"],"天气":["月亮","星星"]},"theme_conf":0.97},{"uid":"b0a1fb5f-9390-4ccb-b4e2-9bde13822508","title":"洛阳早春忆吉中孚校书司空曙主簿因寄清江上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["值迥逢高驻马频，雪晴闲看洛阳春。","莺声报远同芳信，柳色邀欢似故人。","酒貌昔将花共艳，鬓毛今与草争新。","年来百事皆无绪，唯与汤师结净因。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["孤寂","欢愉"],"scene":["春"],"cats":{"抒情":["友情","思念"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.82},{"uid":"a50fdaca-5397-4000-8c2c-bfcb9ab8e681","title":"杂曲歌辞 从军中行路难二首 一","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新","绮丽"],"mood":"相思","mood2":["恬淡"],"scene":["江","夏","塞外","楼","山","春"],"cats":{"抒情":["思念"],"四季":["春天","夏天"],"天气":["星星"],"人生":["战争"],"生活":["边塞"],"节日":["春节"]},"theme_conf":0.599},{"uid":"f2413b7a-cfda-4d88-8c24-6684aa4bcf8a","title":"七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今兹商用事，余热亦已末。","衰年旅炎方，生意从此活。","亭午减汗流，北邻耐人聒。","晚风爽乌匼，筋力苏摧折。","闭目逾十旬，大江不止渴。","退藏恨雨师，健步闻旱魃。","园蔬抱金玉，无以供采掇。","密云虽聚散，徂暑终衰歇。","前圣眘焚巫，武王亲救暍。","阴阳相主客，时序递回斡。","洒落唯清秋，昏霾一空阔。","萧萧紫塞雁，南向欲行列。","歘思红颜日，霜露冻阶闼。","胡马挟雕弓，鸣弦不虚发。","长鈚逐狡兔，突羽当满月。","惆怅白头吟，萧条游侠窟。","临轩望山阁，缥缈安可越。","高人炼丹砂，未念将朽骨。","少壮迹颇疎，欢乐曾倏忽。","杖藜风尘际，老丑难翦拂。","吾子得神仙，本是池中物。","贱夫美一睡，烦促婴词笔。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","月","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","秋天"],"山水":["长江"],"天气":["太阳","月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.448},{"uid":"133359e4-c7c2-4a43-9adc-e5e8ea4e2e41","title":"杂曲歌辞 少年行四首 三","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["弓背霞明劒照霜，秋风走马出咸阳。","未收天子河湟地，不拟回头望故乡。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.517},{"uid":"8aa6132d-c61e-4218-af24-5d9009e6795d","title":"春日书情寄元校书伯和相国元子","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["数岁平津邸，诸生出门时。","羇孤力行早，疎贱托身迟。","芳草看无厌，青山到未期。","贫居悲老大，春日上茅茨。","卫玠琼瑶色，玄成鼎鼐姿。","友朋汉相府，兄弟谢家诗。","律合声虽应，劳歌调自悲。","流年不可住，惆怅镜中丝。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["惆怅","孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.88},{"uid":"d8eb4cff-a052-4634-bb6a-1285a0f124fe","title":"元日恩赐柏叶应制","author":"李乂","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["劲节凌冬劲，芳心待岁芳。","能令人益寿，非止麝含香。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","冬"],"cats":{"四季":["冬天"],"节日":["春节"],"植物":["叶子"]},"theme_conf":0.94},{"uid":"738fc3d5-b2e3-4f00-8a81-496c103cdd58","title":"同吉中孚梦桃源 二","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜静春梦长，梦逐仙山客。","园林满芝术，鸡犬傍篱栅。","几处花下人，看予笑头白。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","欢愉"],"scene":["春","夜","山","园林"],"cats":{"四季":["春天"],"人生":["梦想"],"生活":["乡村"],"植物":["桃花"]},"theme_conf":0.438},{"uid":"eaef090a-c731-44fb-8d03-829ed9237e25","title":"柳州罗池庙诗（题拟）","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["荔子丹兮蕉黄（「蕉」下或有「叶」字，或有「子」字），杂肴蔬兮进侯堂。","侯之船兮两旗，度中流兮风泊之，待侯不来兮不知我悲。","侯乘驹兮入庙，慰我民兮不嚬以笑。","鹅之山兮柳之水，桂树团团兮白石齿齿。","侯朝出游兮暮来归，春与猿吟兮秋鹤与飞。","（《唐文粹》及欧阳修所见《韩集》均作「秋与鹤飞」。","《集古录跋尾》卷八录碑文作「秋鹤与飞」，欧疑碑文有误。","沈括《梦溪笔谈》卷十四以为此用《楚辞》相错成文格，今从其说。","）北方之人兮为侯是非，千秋万岁兮侯无我违。","福我兮寿我，驱厉鬼兮山之左。","下无湿兮高无干，秔稌充羡兮蛇蛟结蟠。","我民报事兮无怠其始，自今兮钦于世世。","（同前书卷三一、《唐文粹》卷五二《柳州罗池庙碑》附）（〖1〗《柳州罗池庙碑》云：「三年孟秋辛卯，侯降于州之后堂，欧阳翼等见而拜之。","其夕，梦翼而告之曰：『馆我于罗池。","』其日景辰，庙成，大祭。","过客李仪醉酒，慢侮堂上，得疾，扶出庙门即死。","明年春，魏忠、欧阳翼使谢宁来京师，请书其事于石。","余谓柳侯生能泽其民，死能惊动祸福之，以食其土，可谓灵也已。","作迎享送神诗遗柳民，俾歌以祀焉而幷刻之。","……其词曰〖词略〗。","」《湖南通志·金石》六著录嘉定刻此碑，题作《唐罗池庙享神词碑》，附魏绍芳跋此为享神诗。","《唐诗别裁集》卷七收入。","朱东润师主编《中国历代文学作品选》中编第一册收此诗，题作《柳州罗池庙诗》，解题云：「此庙建成后，韩愈为撰《柳州罗池庙碑》，诗就附在碑文的后面。","诗效《楚辞·九歌》体，作为祭祀中迎神、送神时歌唱之用。","」）。"],"theme":"佛道禅颂","theme2":["咏物","咏史怀古","山水田园"],"style":"绮丽","style2":["幽峭","豪放"],"mood":"悲怆","mood2":[],"scene":["园林","酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人生":["读书"],"植物":["柳树"],"食物":["荔枝"]},"theme_conf":0.75},{"uid":"b6bf3b29-a210-4644-9ac4-51c39dac7751","title":"南阳道中作","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["东风雨洗顺阳川，蜀锦花开绿草田。","彩雉鬬时频驻马，酒旗翻处亦留钱。","新晴日照山头雪，薄暮人争渡口船。","早晚到家春欲尽，今年寒食月初圆。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨","清明","雪","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"5846db55-7817-45af-bdf7-f4bd4eea5386","title":"元日寄韦氏妹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近闻韦氏妹，迎在汉钟离。","郎伯殊方镇，京华旧国移。","春城回北斗，郢树发南枝。","不见朝正使，啼痕满面垂。"],"theme":"亲情","theme2":["送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.93},{"uid":"b4e7cec1-f391-4b59-a09e-7815b6675fff","title":"题庄上人房","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不语焚香坐，心知道已成。","流年衰此世，定力见他生。","暮雪余春冷，寒灯续昼明。","寻常五侯至，敢望下阶迎。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","春"],"cats":{"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"e70730a9-552c-481c-aadc-364713afd410","title":"横吹曲辞 折杨柳","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂杨拂绿水，摇艳东风年。","花明玉关雪，叶暖金窗烟。","美人结长恨，相对心凄然。","攀条折春色，远寄龙庭前。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"植物":["柳树"]},"theme_conf":0.526},{"uid":"4c9c3d75-272f-4529-bf21-8aafbe5b276e","title":"杂曲歌辞 昔昔盐 那能惜马蹏","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云中路杳杳，江畔草萋萋。","妾久垂珠泪，君何惜马蹏。","边风悲晓角，营月怨春鼙。","未道休征战，愁眉又复低。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["婉约","悲慨"],"mood":"愁怨","mood2":[],"scene":["春","月","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.665},{"uid":"935306d8-d08d-41f7-b8f0-cad379229322","title":"采莲曲","author":"李康成","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采莲去，月没春江曙。","翠钿红袖水中央，青荷莲子杂衣香，云起风生归路长。","归路长，那得久。","各回船，两摇手。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春","月","花","舟","江"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":0.699},{"uid":"6b939a56-7ec3-4f83-a887-48db856ae272","title":"杂曲歌辞 古别离","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["白水东悠悠，中有西行舟。","舟行有返棹，水去无还流。","奈何生别者，戚戚怀远游。","远游谁当惜，所悲会难收。","自君间芳躧，青阳四五遒。","皓月掩兰室，光风虚蕙楼。","相思无明晦，长叹累冬秋。","离居分迟暮，驾高何淹留。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"相思","mood2":["悲怆"],"scene":["舟","冬"],"cats":{"抒情":["离别","思念","伤感"],"四季":["冬天"]},"theme_conf":0.842},{"uid":"12cabe5b-f212-401c-bcd7-fc940a5870b6","title":"立春后休沐","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["心与青春背，新年亦掩扉。","渐穷无相学，惟避不材讥。","积病攻难愈，衔恩报转微。","定知书课日，优诏许辞归。"],"theme":"咏怀抒感","theme2":[],"style":"旷达","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["青春"],"节日":["春节"]},"theme_conf":0.78},{"uid":"ed13392c-ff75-46b4-923b-509cadddbc24","title":"冬宵各为四韵","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雕宫静龙漏，绮阁宴公侯。","珠帘烛燄动，绣柱月光浮。","云起将歌发，风停与管遒。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["冬","夜","月"],"cats":{"抒情":["闺怨"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"cp4f2dbc5ba59cc9","title":"高阳台","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残雪庭阴，轻寒帘影，霏霏玉管春葭。","小帖金泥，不知春在谁家。","相思一夜窗前梦，奈个人、水隔天遮。","但凄然，满树幽香，满地横斜。","江南自是离愁苦，况游骢古道，归雁平沙。","怎得银笺，殷勤与说年华。","如今处处生芳草，纵凭高、不见天涯。","更消他，几度东风，几度飞花。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"婉约","style2":["沉郁","绮丽"],"mood":"相思","mood2":["愁怨"],"scene":["春","花"],"cats":{"抒情":["爱情","思念","思乡","伤感"],"四季":["春天"]},"theme_conf":0.639},{"uid":"5139878e-bd5a-4aa3-9333-00b1ce9f4cc4","title":"海上谣","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["桂水寒于江，玉兔秋冷咽。","海底觅仙人，香桃如瘦骨。","紫鸾不肯舞，满翅蓬山雪。","借得龙堂宽，晓出揲云髪。","刘郎旧香炷，立见茂陵树。","云孙帖帖卧秋烟，上元细字如蚕眠。"],"theme":"游仙梦幻","theme2":["民生疾苦"],"style":"幽峭","style2":["婉约","豪放"],"mood":"欢愉","mood2":[],"scene":["元宵","秋","雪","中秋"],"cats":{"四季":["秋天"],"节日":["元宵节","中秋节"]},"theme_conf":0.78},{"uid":"c56ad06f-0556-40c9-a32b-cdd4cc2536c8","title":"夜泊湘江","author":"于武陵","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风吹楚树，此地独先秋。","何事屈原恨，不随湘水流。","凉天生片月，竟夕伴孤舟。","一作南行客，无成空白头。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","江","端午","秋","舟"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"6d8b0386-c539-45d8-8d63-f7d90c74f21c","title":"哭刘夫子","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近问南州客，云亡已数春。","痛心曾受业，追服恨无亲。","孀妇归乡里，书斋属四邻。","不知经乱后，奠祭有何人。"],"theme":"悼亡挽歌","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","悼亡"],"四季":["春天"],"人物":["老师"]},"theme_conf":0.97},{"uid":"ab8714f5-9716-490c-ba80-04926c6c4849","title":"送柳道士","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["去世能成道，游仙不定家。","归期千岁鹤，行迈五云车。","海上春应尽，壶中日未斜。","不知相忆处，琪树几枝花。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.546},{"uid":"aaf62ace-7464-47ef-a354-f952b9e2d2a9","title":"终南秋雪","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南岭见秋雪，千门生早寒。","闲时驻马望，高处卷帘看。","雾散琼枝出，日斜铅粉残。","偏宜曲江上，倒影入清澜。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","秋"],"cats":{"四季":["秋天"],"天气":["写雪"],"人物":["老师"]},"theme_conf":0.92},{"uid":"c50ef689-8ad8-43b3-8504-54a2a5a54171","title":"奉陪郑驸马韦曲二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野寺垂杨里，春畦乱水间。","美花多映竹，好鸟不归山。","城郭终何事，风尘岂驻颜。","谁能共公子，薄暮欲俱还。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"3379b41f-7a57-4cee-80e9-d4028f214653","title":"东郊迎春","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晓见苍龙驾，东郊春已迎。","彩云天仗合，玄象太阶平。","佳气山川秀，和风政令行。","句陈霜骑肃，御道雨师清。","律向韶阳变，人随草木荣。","遥观上林树，今日遇迁莺。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":1.0},{"uid":"a6819c5a-cece-4e07-a998-9513c2c2851d","title":"叶落","author":"吴融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["红影飘来翠影微，一辞林表不知归。","伴愁无色烟犹在，替恨成啼露未晞。","若逐水流应万里，莫因风起便孤飞。","楚郊千树秋声急，日暮纷纷惹客衣。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"a87be94b-e983-40ff-8350-48a16dbfc585","title":"过严君平古井","author":"郑世翼","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["严平本高尚，远蹈古人风。","卖卜成都市，流名大汉中。","旧井改人世，寒泉久不通。","多年既罢汲，无禽乃遂空。","如何属秋气，唯见落双桐。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"f44b8de6-f634-4dcd-9976-675e2f0e9507","title":"湖州贡焙新茶","author":"张文规","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["凤辇寻春半醉回，僊娥进水御帘开。","牡丹花笑金钿动，传奏吴兴紫笋来。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["江","春","酒","江南"],"cats":{"四季":["春天"],"食物":["写茶"]},"theme_conf":0.75},{"uid":"fcf6c22d-0c07-4dfb-852c-43e7e0a2206b","title":"一叶落","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["烦暑郁未退，凉飙潜已起。","寒温与盛衰，遰相为表里。","萧萧秋林下，一叶忽先委。","勿言微摇落，摇落从此始。"],"theme":"哲理悟道","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","秋"],"cats":{"四季":["夏天","秋天"],"植物":["叶子"]},"theme_conf":0.86},{"uid":"5a8125f7-cc2c-43dc-82e6-3d74dcb898c2","title":"宫词一百首 五十八","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["风帘水阁压芙蓉，四面钩栏在水中。","避热不归金殿宿，秋河织女夜妆红。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","秋","夜","楼"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"ef3c51b2-f0a5-4d9b-8ae3-2a24b342ddee","title":"新乐府 隋堤柳\t悯亡国也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隋堤柳，岁久年深尽衰朽。","风飘飘兮雨萧萧，三株两株汴河口。","老枝病叶愁杀人，曾经大业年中春。","大业年中炀天子，种柳成行夹流水。","西自黄河东至淮，绿阴一千三百里。","大业末年春暮月，柳色如烟絮如雪。","南幸江都恣佚游，应将此柳系龙舟。","紫髯郎将护锦缆，青娥御史直迷楼。","海内财力此时竭，舟中歌笑何日休。","上荒下困势不久，宗社之危如缀旒。","炀天子，自言福祚长无穷，岂知皇子封酅公。","龙舟未过彭城合，义旗已入长安宫。","萧墙祸生人事变，晏驾不得归秦中。","土坟数尺何处葬，吴公台下多悲风。","二百年来汴河路，沙草和烟朝复暮。","后王何以鉴前王，请看隋堤亡国树。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["江","端午","楼","舟","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["黄河"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"6bb164b4-b9d3-4d23-b54b-e71e3535ddc7","title":"左掖梨花","author":"丘为","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["冷艳全欺雪，余香乍入衣。","春风且莫定，吹向玉阶飞。"],"theme":"咏物","theme2":["闺情宫怨"],"style":"悲慨","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["花","雪","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"植物":["梨花"]},"theme_conf":0.556},{"uid":"cp71daa4431df0fe","title":"混江龙・他若是含情一笑，朱唇一颗嵌樱桃。梨花玉体，杨柳纤腰。眉黛","author":"赵彦晖","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["春山娇滴滴，眼波秋水绿淘淘。","可观可看，宜喜宜嗔。","堪怜堪爱，难画难描。","拨银筝音吕韵悠扬，唱阳春白雪依腔调。","你便有千金买笑，怎能够一刻春宵。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["旷达","婉约"],"mood":"欢愉","mood2":[],"scene":["江","春","花","雪","秋"],"cats":{"抒情":["闺怨"],"四季":["春天","秋天"],"植物":["梨花","桃花","柳树"]},"theme_conf":0.694},{"uid":"bdb32446-6efc-402e-93f0-901b8eefe57e","title":"杂曲歌辞 生别离","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["食蘗不易食梅难，蘗能苦兮梅能酸。","未如生别之为难，苦在心兮酸在肝。","晨鸡载鸣残月没，征马重嘶行人出。","回看骨肉哭一声，梅酸蘗苦甘如蜜。","黄河水白黄云秋，行人河边相对愁。","天寒野旷何处宿？棠梨叶战风飕飕。","生离别，生离别，忧从中来无断绝。","忧积心劳血气衰，未年三十生白发。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋","月"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.762},{"uid":"a4027d74-3867-4341-ad57-5248746e36a5","title":"和令狐相公春日寻花有怀白侍郎阁老","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["芳菲满雍州，鸾凤许同游。","花迳须深入，时光不少留。","色鲜由树嫩，枝亚为房稠。","静对仍持酒，高看特上楼。","晴宜连夜赏，雨便一年休。","共忆秋官处，余霞曲水头。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","楼","花"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.95},{"uid":"fad0b1d2-0982-4e21-a0f7-9fbde68bd3e3","title":"秋晓招隐寺东峰茶宴送内弟阎伯均归江州","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["万畦新稻傍山村，数里深松到寺门。","幸有香茶留穉子，不堪秋草送王孙。","烟尘怨别唯愁隔，井邑萧条谁忍论。","莫怪临歧独垂泪，魏舒偏念外家恩。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":["沉郁","婉约"],"mood":"愁怨","mood2":[],"scene":["秋","山"],"cats":{"抒情":["伤感"],"四季":["秋天"],"食物":["写茶"]},"theme_conf":0.362},{"uid":"23ef9a8b-4c38-48e4-a143-a54a9d411abc","title":"送从舅成都县丞广归蜀","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["襃谷通岷岭，青冥此路深。","晚程椒瘴热，野饭荔枝阴。","古郡三刀夜，春桥万里心。","唯应对杨柳，暂醉卓家琴。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜","酒"],"cats":{"四季":["春天"],"生活":["写桥"],"食物":["荔枝"]},"theme_conf":0.466},{"uid":"f7fd325f-acb2-479e-9c0d-e104a1c519df","title":"锄药咏","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["莳药穿林复在𪩘，浓香秀色深能浅。","云气垂来裛露偏，松阴占处知春晚。","拂曙残莺百啭催，萦泉带石几花开。","不随飞鸟缘枝去，如笑幽人出谷来。","对之不觉忘疎嬾，废卷荷锄嫌日短。","岂无萱草树堦墀，惜尔幽芳世所遗。","但使芝兰出萧艾，不辞手足皆胼胝。","宁学陶潜空嗜酒，颓龄舍此事东菑。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春","鸟","酒"],"cats":{"四季":["春天"],"生活":["田野"]},"theme_conf":0.385},{"uid":"d35f583a-c20c-453c-a886-e13f98b2e4b4","title":"春思","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住秦城邻汉苑，心随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时反斾勒燕然。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.596},{"uid":"a36a0840-505a-449f-b3eb-e0060e8ae76d","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["羽毛似雪无瑕点，顾影秋池舞白云。","闲整素仪三岛近，回飘清唳九霄闻。","好风顺举应摩日，逸翮将成莫恋群。","凌励坐看空碧外，更怜凫鹭老江𣸣。"],"theme":"咏物","theme2":["咏史怀古"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","冬","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"42f17f00-bbc1-4b5b-82c1-3e9e012725ba","title":"赠阙下裴舍人","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["二月黄莺飞上林，春城紫禁晓阴阴。","长乐钟声花外尽，龙池柳色雨中深。","阳和不散穷途恨，霄汉长怀捧日新。","献赋十年犹未遇，羞将白发对华簪。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["春"],"cats":{"四季":["春天"]},"theme_conf":0.96},{"uid":"51e0d2da-d7db-4cd4-bdf8-a8f915a4834f","title":"送李八秘书赴杜相公幕","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青帘白舫益州来，巫峡秋涛天地回。","石出倒听枫叶下，橹摇背指菊花开。","贪趋相府今晨发，恐失佳期后命催。","南极一星朝北斗，五云多处是三台。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["星星"]},"theme_conf":0.554},{"uid":"a73d7bc0-d427-4363-9cff-b17eecd95e9d","title":"相和歌辞 朝云引","author":"郎大家宋氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["巴西巫峡指巴东，朝云触石上朝空。","巫山巫峡高何已，行雨行云一时起。","一时起，三春暮。","若言来，且就阳台路。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","雨","山"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":1.0},{"uid":"f3c09e9e-e471-4489-9d3f-a598832ac638","title":"悲陈陶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孟冬十郡良家子，血作陈陶泽中水。","野旷天清无战声，四万义军同日死。","群胡归来血洗箭，仍唱胡歌饮都市。","都人回面北向啼，日夜更望官军至。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cp148022419cf353","title":"念奴娇","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["萧条庭院，有斜风细雨，重门须闭。","宠柳娇花寒食近，种种恼人天气。","险韵诗成，扶头酒醒，别是闲滋味。","征鸿过尽，万千心事难寄。","楼上几日春寒，帘垂四面，玉阑干慵倚。","被冷香消新梦觉，不许愁人不起。","清露晨流，新桐初引，多少游春意。","日高烟敛，更看今日晴未。"],"theme":"送别","theme2":["节令风俗","闲适隐逸"],"style":"婉约","style2":["清新","幽峭"],"mood":"相思","mood2":["慷慨","愁怨"],"scene":["雨","园林","楼","清明","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雨"],"节日":["寒食节","清明节"]},"theme_conf":0.45},{"uid":"ab0c8118-d665-4dc1-be2b-901ae13395ed","title":"夏日杨长宁宅送崔侍御常正字入京","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["醉酒扬雄宅，升堂子贱琴。","不堪垂老鬓，还对欲分襟。","天地西江远，星辰北斗深。","乌台俯麟阁，长夏白头吟。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["星星"]},"theme_conf":0.688},{"uid":"7fc091bf-83dd-498d-87e0-d82fd2575e0f","title":"赴阙次留献荆南成相公三十韵","author":"吴融","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["分阃兼文德，持衡有武功。","荆南知独去，海内更谁同。","拔地孤峰秀，当天一鹗雄。","云生五色笔，月吐六钧弓。","骨格凌秋耸，心源见底空。","神清飡沆瀣，气逸饮洪蒙。","临事成奇策，全身仗至忠。","解鞍欺李广，煮弩笑臧洪。","往昔逢多难，来兹故统戎。","卓旗云梦泽，扑火细腰宫。","铲土楼台搆，连江雉堞笼。","似平铺掌上，疑涌出壶中。","岂是劳人力，宁因役鬼工。","本遗三户在，今匝万家通。","画舸横青雀，危樯列彩虹。","席飞巫峡雨，袖拂宋亭风。","塲广盘毬子，池闲引钓筒。","礼贤金璧贱，煦物雪霜融。","酒满梁尘动，棋残漏滴终。","俭常资澹静，贵绝恃穹崇。","唯要臣诚显，那求帝渥隆。","甘棠名异奭，大树姓非冯。","自念为迁客，方谐谒上公。","痛知遭止棘，频叹委飘蓬。","借宅诛茅绿，分囷指粟红。","只惭燕馆盛，宁觉阮途穷。","涣汗沾明主，沧浪别钓翁。","去曾忧塞马，归欲逐边鸿。","积感深于海，衔恩重极嵩。","行行柳门路，回首下离东。"],"theme":"应制干谒","theme2":["闲适隐逸","应制干谒","送别"],"style":"冲淡","style2":["清新","幽峭"],"mood":"孤寂","mood2":["恬淡"],"scene":["楼","秋","酒","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["彩虹"]},"theme_conf":0.95},{"uid":"c8928378-7719-4940-a9b9-848d78b21d5b","title":"春日江村五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["种竹交加翠，栽桃烂熳红。","经心石镜月，到面雪山风。","赤管随王命，银章付老翁。","岂知牙齿落，名玷荐贤中。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春","江","雪"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"ce493923-7c4b-41a9-94e9-cf95741c018c","title":"酬程延秋夜即事见赠","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长簟迎风早，空城澹月华。","星河秋一雁，砧杵夜千家。","节候看应晚，心期卧亦赊。","向来吟秀句，不觉已鸣鸦。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","夜"],"cats":{"四季":["秋天"],"天气":["月亮","星星"]},"theme_conf":0.97},{"uid":"202641be-8d53-4de4-b477-fcbef11c89bf","title":"种白蘘荷","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["血虫化为疠，夷俗多所神。","衔猜每腊毒，谋富不为仁。","蔬果自远至，杯酒盈肆陈。","言甘中必苦，何用知其真。","华洁事外饰，尤病中州人。","钱刀恐贾害，饥至益逡巡。","窜伏常战栗，怀故逾悲辛。","庶氏有嘉草，攻禬事久泯。","炎帝垂灵编，言此殊足珍。","崎岖乃有得，托以全余身。","纷敷碧树阴，眄睐心所亲。"],"theme":"讽喻刺世","theme2":["民生疾苦","边塞征战","咏物"],"style":"沉郁","style2":["清新"],"mood":"悲怆","mood2":[],"scene":["夏","酒"],"cats":{"抒情":["伤感"],"四季":["夏天"],"人生":["战争"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"215caa5f-74fc-4e81-af61-b8ba6c9a9ff0","title":"落第归乡留别长安主人","author":"豆卢复","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["客里愁多不记春，闻莺始叹柳条新。","年年下第东归去，羞见长安旧主人。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.597},{"uid":"992319d5-c110-4285-9302-cb6d8144bd85","title":"田家春望","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["出门何所见，春色满平芜。","可叹无知己，高阳一酒徒。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.598},{"uid":"ab185b82-5200-4a6d-a327-a21749e60981","title":"越溪村居","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["年来桡客寄禅扉，多话贫居在翠微。","黄雀数声催柳变，清溪一路踏花归。","空林野寺经过少，落日深山伴侣稀。","负米到家春未尽，风萝闲扫钓鱼矶。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江南","春"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":0.495},{"uid":"afb9c85b-d867-4bda-8c84-516d90b554e0","title":"落叶","author":"孔德绍","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["早秋惊叶落，飘零似客心。","翻飞未肯下，犹言惜故林。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.761},{"uid":"ecfeec5e-3205-401e-bc5d-e9b58efb9031","title":"桃源行送友","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["武陵川径入幽遐，中有鸡犬秦人家，家傍流水多桃花。","桃花两边种来久，流水一通何时有。","垂条落蘂暗春风，夹岸芳菲至山口。","岁岁年年能寂寥，林下青苔日为厚。","时有仙鸟来衔花，曾无世人此携手。","可怜不知若为名，君往从之多所更。","古驿荒桥平路尽，崩湍怪石小溪行。","相见维舟登览处，红堤绿岸宛然成。","多君此去从仙隐，令人晚节悔营营。"],"theme":"送别","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["春","花"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.408},{"uid":"fedb06cc-37da-4aaf-8f39-85ebcb08b947","title":"早秋三首 一","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["遥夜泛清瑟，西风生翠萝。","残萤委玉露，早鴈拂银河。","高树晓还密，远山晴更多。","淮南一叶下，自觉老烟波。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"]},"theme_conf":1.0},{"uid":"a5301061-dc9b-4a5b-b5ec-55cb5c2feb65","title":"晋公魏国夫人柳氏挽歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鱼轩海上遥，鸾影月中销。","双剑来时合，孤桐去日凋。","夕阳迷陇隧，秋雨咽笳箫。","画翣无留影，铭旌已度桥。"],"theme":"悼亡挽歌","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","月","雨"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.99},{"uid":"e49af687-a500-425c-a9cb-0e7816bbb04e","title":"赠翰林张四学士","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["翰林逼华盖，鲸力破沧溟。","天上张公子，宫中汉客星赋诗拾翠殿，佐酒望云亭。","紫诰仍兼绾，黄麻似六经。","内分金带赤，恩与荔枝青。","无复随高凤，空余泣聚萤。","此生任春草，垂老独漂萍。","傥忆山阳会，悲歌在一听。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒","春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.78},{"uid":"16aeb267-54a8-4c49-9d94-3306022db14d","title":"东兵长句十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["上党争为天下脊，邯郸四十万秦坑。","狂童何者欲专地，圣主无私岂玩兵。","玄象森罗摇北落，诗人章句咏东征。","雄如马武皆弹劒，少似终军亦请缨。","屈指庙堂无失策，垂衣尧舜待升平。","羽林东下雷霆怒，楚甲南来组练明。","即墨龙文光照曜，常山蛇阵势纵横。","落雕都尉万人敌，黑矟将军一鸟轻。","渐见长围云欲合，可怜穷垒带犹萦。","凯歌应是新年唱，便逐春风浩浩声。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["春"],"cats":{"抒情":["爱国"],"四季":["春天"],"人生":["战争"],"节日":["春节"]},"theme_conf":1.0},{"uid":"5849dc58-0b5b-4181-ad61-285eb6ca25f5","title":"秋思","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋室浩烟雾，风柳怨寒蜩。","机杼夜声切，蕙兰芳意消。","美人湘水曲，桂檝洞庭遥。","常恐时光谢，蹉跎红艳凋。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["女子"],"人生":["时光"]},"theme_conf":1.0},{"uid":"680c2d30-359c-475e-8e95-069f7018fdb0","title":"春日与诸公泛舟","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千里雪山开，沱江春水来。","驻帆云缥缈，吹管鹤裴回。","身外流年驶，尊前落景催。","不应归棹远，明月在高台。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","春"],"cats":{"四季":["春天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":0.65},{"uid":"bc326cee-2472-4d7d-8c4c-97a590a72ade","title":"官渡柳歌送李员外承恩往扬州觐省","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见官渡河两岸，三月杨柳枝。","千条万条色，一一胜绿丝。","花作铅粉絮，叶成翠羽帐。","此时送远人，怅望春水上。","远客折杨柳，依依两含情。","夹郎木兰舟，送郎千里行。","郎把紫泥书，东征觐庭闱。","脱却貂襜褕，新著五彩衣。","双凤幷两翅，将雏东南飞。","五两得便风，几日到扬州。","莫贪扬州好，客行剩淹留。","郎到官渡头，春阑已应久。","殷勤道远别，为谢大堤柳。","攀条傥相忆，五里一回首。","明年柳枝黄，问郎还家否。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["春","舟"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.702},{"uid":"cpfe0eee546aea6b","title":"八声甘州","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["渺空烟四远，是何年、青天坠长星。","幻苍崖云树，名娃金屋，残霸宫城。","箭径酸风射眼，腻水染花腥。","时靸双鸳响，廊叶秋声。","宫里吴王沈醉，倩五湖倦客，独钓醒醒。","问苍波无语，华发奈山青。","水涵空、阑干高处，送乱鸦、斜日落渔汀。","连呼酒，上琴台去，秋与云平。"],"theme":"咏史怀古","theme2":["闲适隐逸","送别","闺情宫怨"],"style":"豪放","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["酒","江","楼","秋"],"cats":{"抒情":["孤独","闺怨","怀古"],"四季":["秋天"]},"theme_conf":0.96},{"uid":"ce71032a-c075-492c-9554-51eb080348a5","title":"奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制","author":"王维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["渭水自萦秦塞曲，黄山旧遶汉宫斜。","銮舆迥出千门柳，阁道廻看上苑花。","云里帝城双凤阙，雨中春树万人家。","为乘阳气行时令，不是宸游玩物华。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨","楼","山"],"cats":{"四季":["春天"],"天气":["写雨"]},"theme_conf":0.99},{"uid":"365cf5e5-97f6-4c86-a2c3-0638591bec07","title":"赋得秋菊有佳色","author":"公乘亿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["陶令篱边菊，秋来色转佳。","翠攒千片叶，金剪一枝花。","蘂逐蜂须乱，英随蝶翅斜。","带香飘绿绮，和酒上乌纱。","散漫摇霜彩，娇妍漏日华。","芳菲彭泽见，更称在谁家。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.721},{"uid":"cp6a47d06d7bc689","title":"醉太平・这些时春寒绣ブ，月暗重门，梨花暮雨近黄昏，把香衾自温。金","author":"吴昌龄","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["杯不洗心头闷，青鸾不寄云边信，玉容不见意中人。","空教人害损。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","花","春","月","雨","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"],"食物":["写酒"]},"theme_conf":0.619},{"uid":"22e90c0d-2b59-4500-8e5d-80d38ec4692c","title":"闻官军收河南河北","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["劒外忽传收蓟北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌须纵酒，青春作伴好还乡。","即从巴峡穿巫峡，便下襄阳向洛阳。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["青春","读书"]},"theme_conf":0.512},{"uid":"36f4450b-ab48-4dad-8d98-a1f7ae6c66e9","title":"和武中丞秋日寄怀简诸僚故","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["退朝还公府，骑吹息繁阴。","吏散秋庭寂，乌啼烟树深。","威生奉白简，道胜外华簪。","风物清远目，功名怀寸阴。","云衢念前侣，彩翰写冲襟。","凉菊照幽径，败荷攒碧浔。","感时江海思，报国松筠心。","空愧寿陵步，芳尘何处寻。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"冲淡","style2":["清新"],"mood":"慷慨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["爱国"],"四季":["秋天"]},"theme_conf":0.96},{"uid":"a58dc2b0-7454-4599-aa4c-a06605f39978","title":"相和歌辞 子夜四时歌六首 冬歌二首 一","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["北极严气升，南至温风谢。","调丝竞短歌，拂枕怜长夜。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","冬"],"cats":{"抒情":["闺怨"],"四季":["冬天"]},"theme_conf":0.82},{"uid":"cd904f43-b9eb-4e30-a3fe-f2bcb215a8db","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红似燕支腻如粉，伤心好物不须臾。","山中风起无时节，明日重来得在无。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["清新","婉约"],"mood":"孤寂","mood2":[],"scene":["月","花","山","冬","夏"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["太阳","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.446},{"uid":"cd3d8e0c-a549-44a9-b55c-4f1c9b9befed","title":"秋霖中奉裴令公见招早出赴会马上先寄六韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨暗三秋日，泥深一尺时。","老人平旦出，自问欲何之。","不是寻医药，非干送别离。","素书传好语，绛帐赴佳期。","续借桃花马，催迎杨柳姬。","只愁张录事，罚我怪来迟。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写雨"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.88},{"uid":"538c200b-49c5-4487-8087-9736b2947053","title":"楚怨","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋入楚江水，独照汨罗魂。","手把绿荷泣，意愁珠泪翻。","九门不可入，一犬吠千门。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["端午","秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"bdd14fd6-3be3-4f4f-acb7-4c8080ee8c83","title":"赠衡岳隐禅师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["拥褐安居南岳头，白云高寺见衡州。","石窗湖水摇寒月，枫树猨声报夜秋。","讲席旧逢山鸟至，梵经初向竺僧求。","垂垂身老将传法，因下人间逐北游。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["老师"],"人生":["哲理"]},"theme_conf":0.82},{"uid":"b42b8d7b-3d04-46ed-ba87-11478e25d391","title":"送刘评事充朔方判官赋得征马嘶","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["征马向边州，萧萧嘶不休。","思深应带别，声断为兼秋。","岐路风将远，关山月共愁。","赠君从此去，何日大刀头。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","月","塞外","山"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"动物":["写马"]},"theme_conf":0.479},{"uid":"9d2bcfb9-1052-40ca-8a14-87ba811aee4e","title":"秋暮言志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朝光浮烧野，霜华净碧空。","结浪冰初镜，在迳菊方丛。","约岭烟深翠，分旗霞散红。","抽思滋泉侧，飞想傅岩中。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["秋","山"],"cats":{"四季":["秋天"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"6872be3d-cd6b-4609-b54a-e481006f6cf6","title":"奉和圣制春中兴庆宫酺宴应制","author":"张说","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["千龄逢启圣，万域共来威。","庆接郊禋后，酺承农事稀。","御楼横广路，天乐下重闱。","鸾凤调歌曲，虹霓动舞衣。","合声云上聚，连步月中归。","物覩恩无外，神和道入微。","镐京陪乐饮，柏殿奉文飞。","徒竭秋云影，何资春日晖。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.99},{"uid":"526d4ecc-e123-4b9d-a213-958bb947593d","title":"凉州词二首 一","author":"王之涣","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春光不度玉门关。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.508},{"uid":"d09d57f9-e7ee-4088-8cf0-06423f1dede0","title":"四皓驿听琴送王师简归湖南使幕","author":"窦庠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朱弦韵正调，清夜似闻韶。","山馆月犹在，松枝雪未消。","城笳三奏晓，别鹤一声遥。","明日思君处，春泉翻寂寥。"],"theme":"送别","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江","雪","春","夜","月","山"],"cats":{"抒情":["爱国"],"四季":["春天"]},"theme_conf":0.95},{"uid":"7ecd869d-dd96-421b-905b-a70a0cb44bad","title":"琴曲歌辞 秋风引","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["何处秋风至？萧萧送鴈群。","朝来入庭树，孤客最先闻。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.402},{"uid":"f55da3dd-e810-4e90-b065-acb1459bf7c5","title":"踏歌行 一","author":"陈去疾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鸳鸯楼下万花新，翡翠宫前百戏陈。","夭矫翔龙衔火树，飞来瑞凤散芳春。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵","花","春","楼"],"cats":{"抒情":["爱情"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"7bc83be6-9f75-4612-af7d-f4fa66548049","title":"去杭州","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["房杜王魏之子孙，虽及百代为清门。","骏骨凤毛真可贵，冈头泽底何足论。","去年江上识君面，爱君风貌情已敦。","与君言语见君性，灵府坦荡消尘烦。","自兹心洽迹亦洽，居常并榻游竝轩。","柳阴覆岸郑监水，李花压树韦公园。","每出新诗共联缀，闲因醉舞相牵援。","时寻沙尾枫林夕，夜摘兰丛衣露繁。","今君别我欲何去，自言远结迢迢婚。","简书五府已再至，波涛万里酬一言。","为君再拜赠君语，愿君静听君勿喧。","君名师范欲何范，君之烈祖遗范存。","永宁昔在抡鉴表，沙汰沈浊澄浚源。","君今取友由取士，得不别白清与浑。","昔公事主尽忠谠，虽及死谏誓不谖。","今君佐藩如佐主，得不陈露詶所恩。","昔公为善日不足，假寐待旦朝至尊。","今君三十朝未与，得不寸晷倍玙璠。","昔公令子尚贵主，公执舅礼妇执笲。","返拜之仪自此绝，关雎之化皎不昏。","君今远娉奉明祀，得不齐励亲苹蘩。","斯言皆为书佩带，然后别袂乃可扪。","别袂可扪不可解，解袂开帆凄别魂。","魂摇江树鸟飞没，帆挂樯竿鸟尾翻。","翻风驾浪拍何处，直指杭州由上元。","上元萧寺基址在，杭州潮水霜雪屯。","潮户迎潮击潮鼓，潮平潮退有潮痕。","得得为题罗刹石，古来非独伍员冤。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":["慷慨"],"scene":["江","元宵","秋"],"cats":{"抒情":["离别"],"四季":["秋天"],"节日":["元宵节"]},"theme_conf":0.603},{"uid":"0dc28dbc-d080-47fc-b44a-229e310c187a","title":"相和歌辞 襄阳乐","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["大堤花月夜，长江春水流。","东风正上信，春夜特来游。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["长江"]},"theme_conf":0.8},{"uid":"94ae3e7e-eb5d-414c-bfd6-124f50687ce5","title":"客夜与故人偶集","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天秋月又满，城阙夜千重。","还作江南会，翻疑梦里逢。","风枝惊暗鹊，露草覆寒蛩。","羁旅长堪醉，相留畏晓钟。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["友情","思乡"],"四季":["秋天"]},"theme_conf":0.649},{"uid":"d8364f1e-c63c-4df1-8772-e856094fef55","title":"台头寺愿上人院古松下有小松裁毫末新生与纤草不辨重其有凌云干霄之志与赵八员外裴十补阙同赋之","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["细草亦全高，秋毫乍堪比。","及至干霄日，何人复居此。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","楼","秋"],"cats":{"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.52},{"uid":"7fa19519-78a9-494b-b6f2-2a22a48ba3f3","title":"三日书怀因示百僚","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["佳节上元巳，芳时属暮春。","流觞想兰亭，捧劒得金人。","风轻水初绿，日晴花更新。","天文信昭回，皇道颇敷陈。","恭己每从俭，清心常保真。","戒兹游衍乐，书以示群臣。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["元宵","花","春","酒"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["元宵节"]},"theme_conf":0.86},{"uid":"6ba9e234-c171-4129-ab2e-b52db1026621","title":"鼓吹曲辞 芳树","author":"罗隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["细蘂慢逐风，暖香闲破鼻。","青帝固有心，时时动人意。","去年高枝犹压地，今年低枝已顦顇。","吾所以见造化之权，变通之理。","春夏作头，秋冬为尾。","循环反复无穷已，今生长短同一轨。","若使威可以制，力可以止，秦皇不肯敛手下沙丘，孟贲不合低头入蒿里。","伊人彊猛犹如此，顾我劳生何足恃？","但愿开素袍，倾绿蚁，陶陶兀兀大醉于青冥白昼间。","任他上是天，下是地。"],"theme":"哲理悟道","theme2":[],"style":"婉约","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["花","夏","冬","春","秋"],"cats":{"四季":["春天","夏天","秋天","冬天"]},"theme_conf":0.88},{"uid":"8f3bd134-ac28-4961-b0c9-141140f72e47","title":"横吹曲辞 折杨柳 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楼上春风过，风前杨柳歌。","枝疎缘别苦，曲怨为年多。","花惊燕地雪，叶映楚池波。","谁堪别离此，征戍在交河。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","春","楼"],"cats":{"抒情":["离别"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.664},{"uid":"3ff56a31-51e0-4926-a44e-73635f47c545","title":"郊庙歌辞 享太庙乐章 景云舞","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["景云霏烂，告我帝符。","噫帝冲德，与天为徒。","笙镛遥远，俎豆虚无。","春秋孝献，回复此都。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春","秋","雨"],"cats":{"四季":["春天","秋天"],"天气":["写云"]},"theme_conf":0.95},{"uid":"5f5d9f3e-a3d3-446a-ba9c-3066f4b6eff9","title":"杂曲歌辞 少年行四首 四","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["霜满中庭月过楼，金尊玉柱对清秋。","当年称意须为乐，不到天明未肯休。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cp2e2a1c2fd58b4f","title":"喜迁莺","author":"刘一止","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓光催角。","听宿鸟未惊，邻鸡先觉。","迤逦烟村，马嘶人起，残月尚穿林薄。","泪痕带霜微凝，酒力冲寒犹弱。","叹倦客、悄不禁，重染风尘京洛。","追念，人别后，心事万重，难觅孤鸿托。","翠幌娇深，曲屏香暖，争念岁寒飘泊。","怨月恨花烦恼，不是不曾经著。","这情味，望一成消减，新来还恶。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["欢愉"],"scene":["鸟","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.5},{"uid":"05d0c667-b634-4962-8141-6a0cd84f56be","title":"一叶落","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["轻叶独悠悠，天高片影流。","随风来此地，何树落先秋。","变色黄应近，辞林绿尚稠。","无双浮水面，孤绝落关头。","乍减诚难觉，将凋势未休。","客心空自比，谁肯问新愁。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["清新","旷达"],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"aae1a96c-39e5-4b58-be2e-232eff1e671f","title":"惜花三首 二","author":"张碧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["老鸦拍翼盘空疾，准拟浮生如瞬息。","阿母蟠桃香未齐，汉皇骨葬秋山碧。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["花","秋"],"cats":{"四季":["秋天"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"6d3b137e-8d62-4d8d-be0f-88c9589f8ae6","title":"野老","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["野老篱前江岸回，柴门不正逐江开。","渔人网集澄潭下，贾客船随返照来。","长路关心悲劒阁，片云何意傍琴台。","王师未报收东郡，城阙秋生画角哀。"],"theme":"咏怀抒感","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["楼","秋","江","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.7},{"uid":"f0d03f1b-abb4-4c3c-84b8-ee1925878a97","title":"琴曲歌辞 幽兰","author":"崔涂","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽植众能知，贞芳只暗持。","自无君子佩，未是国香衰。","白露沾长早，青春每到迟。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人生":["青春"]},"theme_conf":0.96},{"uid":"db9d91d8-9d41-4922-82a7-1c8d23f66238","title":"秋夜梁七兵曹同宿二首 二","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["好欲弃吾道，今宵又遇君。","老夫相劝酒，稚子待题文。","月下谁家笛，城头几片云。","如何此幽兴，明日重离群。"],"theme":"寄赠酬答","theme2":["亲情","边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"cp5be9581b63edc2","title":"锁窗寒・琐寒窗","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["暗柳啼鸦，单衣伫立，小帘朱户。","桐花半亩，静锁一庭愁雨。","洒空阶，夜阑未休，故人剪烛西窗语。","似楚江暝宿，风灯零乱，少年羁旅。","迟暮。","嬉游处。","正店舍无烟，禁城百五。","旗亭唤酒，付与高阳俦侣。","想东园，桃李自春，小唇秀靥今在否。","到归时，定有残英，待客携尊俎。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春","夜","酒","雨"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"a68013c8-4630-41c6-a5ee-a658b57f58fe","title":"淮上喜会梁川故人","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江汉曾为客，相逢每醉还。","浮云一别后，流水十年间。","欢笑情如旧，萧疎鬓已斑。","何因北归去，淮上对秋山。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","江","酒","山"],"cats":{"抒情":["友情"],"四季":["秋天"]},"theme_conf":0.78},{"uid":"6290b8f0-48de-407f-be2c-629140d91f83","title":"春泛若耶溪","author":"綦毋潜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽意无断绝，此去随所偶。","晚风吹行舟，花路入溪口。","际夜转西壑，隔山望南斗。","潭烟飞溶溶，林月低向后。","生事且弥漫，愿为持竿叟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"]},"theme_conf":1.0},{"uid":"49255a86-1217-48f7-b480-0f562a4dcf91","title":"远怀舍弟颖观等","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阳翟空知处，荆南近得书。","积年仍远别，多难不安居。","江汉春风起，冰霜昨夜除。","云天犹错莫，花萼尚萧疎。","对酒都疑梦，吟诗正忆渠。","旧时元日会，乡党羡吾庐。"],"theme":"羁旅思乡","theme2":["节令风俗","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["花","春","酒","夜","江","冬"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.412},{"uid":"b7b344b4-2f7a-48a0-97b1-50073a9263c8","title":"和席八十二韵","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绛阙银河曙，东风右掖春。","官随名共美，花与思俱新。","绮陌朝游间，绫衾夜直频。","横门开日月，高阁切星辰。","庭变寒前草，天销霁后尘。","沟声通苑急，柳色压城匀。","纶綍谋猷盛，丹青步武亲。","芳菲含斧藻，光景畅形神。","傍砌看红药，巡池咏白苹。","多情怀酒伴，余事作诗人。","倚玉难藏拙，吹竽久混真。","坐慙空自老，江海未还身。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"孤寂","mood2":[],"scene":["春","园林","花"],"cats":{"四季":["春天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"09fea87e-c0a8-44bc-a18f-307b9f7ee92b","title":"杂曲歌辞 桃花曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["魏帝宫人舞凤楼，隋家天子泛龙舟。","君王夜醉春眠[晏]，不觉桃花逐水流。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","端午","舟","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"节日":["端午节"],"植物":["桃花"]},"theme_conf":0.9},{"uid":"cp412e673eb67571","title":"贺新郎","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["深院榴花吐。","画帘开、衣纨扇，午风清暑。","儿女纷纷夸结束，新样钗符艾虎。","早已有、游人观渡。","老大逢场慵作戏，任陌头、年少争旗鼓。","溪雨急，浪花舞。","灵均标致高如许。","忆生平、既纫兰佩，更怀椒糈。","谁信骚魂千载后，波底垂涎角黍。","又说是、蛟馋龙怒。","把似而今醒到了，料当年、醉死差无苦。","聊一笑，吊千古。"],"theme":"闺情宫怨","theme2":["山水田园"],"style":"清新","style2":["旷达"],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"抒情":["闺怨"],"四季":["夏天"]},"theme_conf":0.531},{"uid":"ccf1691d-8325-4d04-9eda-9d8608216ba7","title":"周平西墓","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["英威今寂寞，陈迹对崇丘。","壮志清风在，荒坟白日愁。","穷泉那复晓，乔木不知秋。","岁岁寒塘侧，无人水自流。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","冬"],"cats":{"抒情":["孤独","怀古"],"四季":["秋天","冬天"],"人生":["励志","梦想"]},"theme_conf":0.96},{"uid":"b0049020-3b5e-4a46-9b66-71f6de65501d","title":"杂曲歌辞 少年行三首 一","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["十八羽林郎，戎衣事汉王。","臂鹰金殿侧，挟弹玉舆旁。","驰道春风起，陪游出建章。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"8435b46d-bbf1-49e5-af66-6f2d5681f1bf","title":"寄李儋元锡","author":"韦应物","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年花里逢君别，今日花开已一年。","世事茫茫难自料，春愁黯黯独成眠。","身多疾病思田里，邑有流亡愧俸钱。","闻道欲来相问讯，西楼望月几廻圆。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["春","楼","月"],"cats":{"四季":["春天"]},"theme_conf":0.94},{"uid":"fde17d21-b335-43ef-8a18-c476b60f4b57","title":"茅堂检校收稻二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["稻米炊能白，秋葵煮复新。","谁云滑易饱，老藉软俱匀。","种幸房州熟，苗同伊阙春。","无劳映渠盌，自有色如银。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","春"],"cats":{"四季":["春天","秋天"],"生活":["田野"]},"theme_conf":1.0},{"uid":"ee380cd0-fea2-4baa-92b7-c82c834265e6","title":"相和歌辞  豫章行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["胡风吹代马，北拥鲁阳关。","吴兵照海雪，西讨何时还？","半渡上辽津，黄云惨无颜。","老母与子别，呼天野草间。","白马绕旌旗，悲鸣相追攀。","白杨秋月苦，早落豫章山。","本为休明人，斩虏素不闲。","岂惜战鬬死，为君埽凶顽。","精感石没羽，岂忘惮险艰。","楼船若鲸飞，波荡落星湾。","此曲不可奏，三军鬓成斑。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","秋","月","楼","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["母亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.582},{"uid":"d3357800-9021-4647-a0a0-98499a0ee3c5","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"02304a34-5fd7-44fc-a781-9a1ed35a8a03","title":"秋风二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["秋风淅淅吹巫山，上牢下牢修水关。","吴樯楚柁牵百丈，暖向神都寒未还。","要路何日罢长戟，战自青羌连百蛮。","中巴不曾消息好，暝传戍鼓长云间。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"]},"theme_conf":1.0},{"uid":"39c8eb21-2fd1-42bb-9540-3ff56ea983c3","title":"鼓吹曲辞 朱鹭","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["翩翩兮朱鹭，来泛春塘栖绿树。","羽毛如翦色如染，远飞欲下双翅敛。","避人引子入深壍，动处水纹开滟滟。","谁知豪家网尔躯，不如饮啄江海隅。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.65},{"uid":"cpd4852635a024cd","title":"八声甘州","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对潇潇、暮雨洒江天，一番洗清秋。","渐霜风凄惨，关河冷落，残照当楼。","是处红衰翠减，苒苒物华休。","惟有长江水，无语东流。","不忍登高临远，望故乡渺邈，归思难收。","叹年来踪迹，何事苦淹留。","想佳人、妆楼望，误几回、天际识归舟。","争知我、倚阑干处，正恁凝愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"山水":["长江"],"人物":["女子"]},"theme_conf":1.0},{"uid":"40e33874-18b2-4ad8-942e-41240bc9d97c","title":"秋兴八首 七","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昆明池水汉时功，武帝旌旗在眼中。","织女机丝虚月夜，石鲸鳞甲动秋风。","波漂菰米沈云黑，露冷莲房坠粉红。","关塞极天唯鸟道，江湖满地一渔翁。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"生活":["边塞"],"节日":["七夕节"]},"theme_conf":0.7},{"uid":"c8a4faa6-8666-44f9-b4c9-df78d7af844d","title":"送别","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["山中相送罢，日暮掩柴扉。","春草明年绿，王孙归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":1.0},{"uid":"3db0baa7-cb74-422c-b606-17dadb3a97f4","title":"暮秋与裴居晦宴因见采菊花之作","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菊花低色过重阳，似忆王孙白玉觞。","今日王孙好收采，高天已下两回霜。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","秋"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.72},{"uid":"8ac1fb39-17d3-4dae-b046-94dfd282aa77","title":"相和歌辞 善哉行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["大鹏刷翮谢溟渤，青云万层高突出。","下视秋涛空渺弥，旧处鱼龙皆细物。","人生在世何容易，眼浊心昏信生死。","愿除嗜欲待身轻，携手同寻列仙事。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":[],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.65},{"uid":"7f1258da-f56c-4485-aea5-e405a6ce4997","title":"题桃树","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["小径升堂旧不斜，五株桃树亦从遮。","高秋总𫗪贫人实，来岁还舒满眼花。","帘户每宜通乳燕，儿童莫信打慈鵶。","寡妻群盗非今日，天下车书正一家。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"d3e70d45-82d5-44a7-a20e-cbb2c762d857","title":"夜坐吟","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["踏踏马蹄谁见过，眼看北斗直天河。","西风罗幕生翠波，铅华笑妾颦青蛾。","为君起唱长相思，帘外严霜皆倒飞。","明星烂烂东方陲，红霞梢出东南涯，陆郎去矣乘班骓。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念","闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.5},{"uid":"35b59fb5-75cd-4bf0-ac6e-86b0dd9cb22a","title":"焦篱店醉题","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛下渠头百卉新，满筵歌笑独伤春。","何须更弄邵翁伯，即我此身如此人。"],"theme":"咏物","theme2":["山水田园","闲适隐逸"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"生活":["乡村"],"食物":["写酒"]},"theme_conf":0.43},{"uid":"5e190844-b5af-4f96-8560-1fab6dded1cf","title":"巴陵寄李二户部张十四礼部","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江南春草初幂幂，愁杀江南独愁客。","秦中杨柳也应新，转忆秦中相忆人。","万里莺花不相见，登高一望泪沾巾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春","江南","重阳","江"],"cats":{"抒情":["思念","伤感"],"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.85},{"uid":"367c97eb-901c-4688-ab45-2ee634454c0a","title":"赠王随","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青云自致晚应遥，朱邸新婚乐事饶。","饮罢更怜双袖舞，试来偏爱五花骄。","帐里炉香春梦晓，堂前烛影早更朝。","更说毬场新雨歇，王孙今日定相邀。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春","雨"],"cats":{"四季":["春天"],"人生":["梦想"]},"theme_conf":0.87},{"uid":"cp1e3fc70b8b96e6","title":"千秋岁引","author":"王安石","dynasty":"宋","section":"宋词","form":"词","paragraphs":["别馆寒砧，孤城画角。","一派秋声入寥廓。","东归燕从海上去，南来雁向沙头落。","楚台风，庾楼月，宛如昨。","无奈被些名利缚。","无奈被他情担阁。","可惜风流总闲却。","当初漫留华表语，而今误我秦楼约。","梦阑时，酒醒后，思量著。"],"theme":"咏怀抒感","theme2":["送别","羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["秋","楼"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"]},"theme_conf":0.85},{"uid":"5022a1cb-449b-4dcc-8b78-33e9e5914d02","title":"相和歌辞 大堤行","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["大堤行乐处，车马相驰突。","岁岁春草生，踏青二三月。","王孙挟珠弹，游女矜罗韈。","携手今莫同，江花为谁发。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["清明","春","月","江"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"ccbadda6-7e25-4df6-bde4-cff74e45d080","title":"瘦马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["东郊瘦马使我伤，骨骼硉兀如堵墙。","绊之欲动转敧侧，此岂有意仍腾骧。","细看六印带官字，众道三军遗路旁。","皮干剥落杂泥滓，毛暗萧条连雪霜。","去岁奔波逐余寇，骅骝不惯不得将。","士卒多骑内厩马，惆怅恐是病乘黄。","当时历块误一蹶，委弃非汝能周防。","见人惨澹若哀诉，失主错莫无晶光。","天寒远放雁为伴，日暮不收乌啄疮。","谁家且养愿终惠，更试明年春草长。"],"theme":"羁旅思乡","theme2":["边塞征战","悼亡挽歌"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":["恬淡","悲怆"],"scene":["雪","春"],"cats":{"抒情":["思乡","伤感","悼亡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.371},{"uid":"27acb13b-76e1-46ee-a681-148fc96b24b6","title":"早秋京口旅泊章侍御寄书相问因以赠之时七夕","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["移家避寇逐行舟，厌见南徐江水流。","吴越征徭非旧日，秣陵凋弊不宜秋。","千家闭户无砧杵，七夕何人望斗牛。","祗有同时骢马客，偏宜尺牍问穷愁。"],"theme":"羁旅思乡","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.74},{"uid":"cpdfe6d2cd46549c","title":"夏云峰","author":"仲殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["天阔云高，溪横水远。","晚日寒生轻晕。","闲阶静、杨花渐少，朱门掩、莺声犹嫩。","悔匆匆、过却清明，旋占得馀芳，已成幽恨。","都几日阴沈，连宵慵困。","起来韶华都尽。","怨入双眉闲斗损。","乍品得情怀，看承全近。","深深态、无非自许。","厌厌意、终羞人间。","争知道、梦里蓬莱，待忘了馀香，时传音信。","纵留得莺花，东风不住，也则眼前愁闷。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":["沉郁","冲淡"],"mood":"愁怨","mood2":["恬淡"],"scene":["夏","花","清明","春","山"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","夏天"],"天气":["写云"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"54313608-eb28-4f12-9583-7a821d285ec4","title":"天河","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["常时任显晦，秋至辄分明。","纵被微云掩，终能永夜清。","含星动双阙，伴月照边城。","牛女年年渡，何曾风浪生。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕","秋","夜","月"],"cats":{"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"66711c88-d15e-4440-a51c-03447a294dee","title":"秋中雨田园即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["漠漠重云暗，萧萧密雨垂。","为霖淹古道，积日满荒陂。","五稼何时获，孤村几户炊。","乱流发通圃，腐叶著秋枝。","暮爨新樵湿，晨渔旧浦移。","空余去年菊，花发在东篱。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["雨","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"],"生活":["乡村","田野"]},"theme_conf":0.762},{"uid":"cde3ddab-b6aa-4cce-99de-e600b9e82746","title":"红叶","author":"吴融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["露染霜干片片轻，斜阳照处转烘明。","和烟飘落九秋色，随浪泛将千里情。","几夜月中藏鸟影，谁家庭际伴蛩声。","一时衰飒无多恨，看着清风彩剪成。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.96},{"uid":"cfec06fe-678e-45b9-8da3-93ed36cb9f9e","title":"单父逢邓司仓覆仓库因而有赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["邦牧今坐啸，群贤趋纪纲。","四人忽不扰，耕者遥相望。","粲粲府中妙，授词如履霜。","炎炎伏热时，草木无晶光。","匹马度睢水，清风何激扬。","校缗阅帑藏，发廪欣斯箱。","邂逅得相逢，欢言至夕阳。","开襟自公余，载酒登琴堂。","举桮挹山川，寓目穷毫芒。","白鸟向田尽，青蝉归路长。","醉中不惜别，况乃正游梁。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","秋","夏"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.88},{"uid":"cp209532e96ad70c","title":"咏池上梨花诗","author":"王融","dynasty":"魏晋南北朝","section":"魏晋南北朝","form":"五言绝句","paragraphs":["翻阶没细草，集水间疏萍。","芳春照流雪，深夕映繁星。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花","园林","雪","春"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"b47c9575-fe60-44e4-92f7-94386b4d512f","title":"春和杜相公移入长兴宅奉呈诸宰执","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["欲向幽偏适，还从绝地移。","秦官鼎食贵，尧世土阶卑。","戟户槐阴满，书窗竹叶垂。","才分午夜漏，遥隔万年枝。","北阙深恩在，东林远梦知。","日斜门掩暎，山远树参差。","论道齐鸳翼，题诗忆凤池。","从公亦何幸，长与珮声随。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["春","夜"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["庐山"]},"theme_conf":0.95},{"uid":"3c004054-61d3-442e-b15c-07ee460b9cfe","title":"天门谷题孙逸人石壁","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["崖石乱流处，竹深斜照归。","主人卧磻石，心耳涤清晖。","春雷近作解，空谷半芳菲。","云栋彩虹宿，药圃蝴蝶飞。","恶嚣慕嘉遯，几夜瞻少微。","相见竟何说，忘情同息机。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["泰山"],"天气":["彩虹"]},"theme_conf":0.465},{"uid":"d97a60f8-4b5a-4f77-a39a-00c869ff0ff3","title":"小苑春望宫池柳色","author":"张昔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["小苑春初至，皇衢日更清。","遥分万条柳，回出九重城。","隐映龙池润，参差凤阙明。","影宜宫雪曙，色带禁烟晴。","深浅残阳变，高低晓吹轻。","年光正堪折，欲寄一枝荣。"],"theme":"送别","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"节日":["寒食节"],"植物":["柳树"]},"theme_conf":0.508},{"uid":"495d3ae4-4bc2-46f3-a2bd-1fda9353283f","title":"景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["余本燕赵人，秉心愚且直。","群籍备所见，孤贞每自饬。","徇禄期代耕，受任亦量力。","幸逢休明时，朝野两荐推。","一朝趋金门，十载奉瑶墀。","入掌迁固笔，出参枚马词。","吏部既三践，中书亦五期。","进无负鼎说，退慙补衮诗。","常恐婴悔吝，不得少酬私。","嗷嗷路傍子，纳谤纷无已。","上动明主疑，下贻大臣耻。","毫发顾无累，冰壶邈自持。","天道何期平，幽冤终见明。","始佐庐陵郡，寻牧襄阳城。","彤帏荷新宠，朱黻蒙旧荣。","力薄慙任重，恩深知命轻。","饬徒留前路，行子悲且慕。","犹闻长乐钟，尚辨青门树。","慈亲不忍诀，昆弟默相顾。","去去勿重陈，川长日云暮。"],"theme":"咏怀抒感","theme2":["应制干谒","闲适隐逸","送别"],"style":"清新","style2":["旷达","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["春","江"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人物":["母亲"],"人生":["梦想"],"动物":["写马"]},"theme_conf":0.85},{"uid":"d5f4c0a5-e669-4943-85bd-6b9c2f15d98d","title":"晚春永宁墅小园独坐寄上王相公","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东阁一何静，莺声落日愁。","夔龙暂为别，昏旦思兼秋。","蕙草出篱外，花枝寄竹幽。","上方传雅颂，七夕让风流。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["春","七夕","园林"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["七夕节"]},"theme_conf":0.85},{"uid":"601d90fb-3589-44f1-9a25-9e16af2102c3","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["把烛成桥夜，回舟坐客时。","天高云去尽，江迥月来迟。","衰谢多扶病，招邀屡有期。","异方乘此兴，乐罢不无悲。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["幽峭","沉郁"],"mood":"欢愉","mood2":["悲怆"],"scene":["江","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"山水":["江河"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"d6631944-18f1-4767-a2d4-77b1516758cd","title":"保大五年元日大雪同太弟景遂汪王景逷齐王景逵进士李建勋中书徐铉勤政殿学士张义方登楼赋","author":"嗣主璟","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["珠帘高卷莫轻遮，往往相逢隔岁华。","春气昨宵飘律管，东风今日放梅花。","素姿好把芳姿掩，落势还同舞势斜。","坐有宾朋尊有酒，可怜清味属侬家。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["豪放","旷达"],"mood":"欢愉","mood2":[],"scene":["雪","楼","春","冬"],"cats":{"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.82},{"uid":"cb457f4a-a49c-46cc-becf-d4419d617b79","title":"玉华宫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["溪回松风长，苍鼠窜古瓦。","不知何王殿，遗构绝壁下。","阴房鬼火青，坏道哀湍泻。","万籁真笙竽，秋色正萧洒。","美人为黄土，况乃粉黛假。","当时侍金舆，故物独石马。","忧来藉草坐，浩歌泪盈把。","冉冉征途间，谁是长年者。"],"theme":"山水田园","theme2":["悼亡挽歌"],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋"],"cats":{"抒情":["伤感","孤独","悼亡"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.516},{"uid":"46d56217-7555-4a85-99fd-2ef265de9b8d","title":"初秋莲塘归","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋光净无迹，莲消锦云红。","只有溪上山，还识扬舲翁。","如何白苹花，幽渚笑凉风。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"cpaf5595daded2dc","title":"渔家傲","author":"朱服","dynasty":"宋","section":"宋词","form":"词","paragraphs":["小雨廉纤风细细。","万家杨柳轻烟里。","恋树湿花飞不起。","愁无比。","和春付与西流水。","九十光阴能有几。","金龟解尽留无计。","寄语东城沽酒市。","拼一醉。","而今乐事他年泪。"],"theme":"咏怀抒感","theme2":["羁旅思乡","送别","闲适隐逸"],"style":"婉约","style2":["豪放","沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.88},{"uid":"1809b35f-90e9-48f1-9844-c467caabddd7","title":"琴曲歌辞 胡笳十八拍 第十八拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["归来故乡见亲族，田园半芜春草绿。","明烛重然煨烬灰，寒泉更洗沈泥玉。","载持巾栉礼仪好，一弄丝桐生死足。","出入关山十二年，哀情尽在胡笳曲。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","塞外","园林","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.412},{"uid":"15a3131f-aaa2-4557-9233-aeceb9edbb63","title":"舟中夜雪有怀卢十四侍御弟","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朔风吹桂水，朔雪夜纷纷。","暗度南楼月，寒深北渚云。","烛斜初近见，舟重竟无闻。","不识山阴道，听鸡更忆君。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["雪","夜","舟","冬"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["写风","写雪"]},"theme_conf":0.65},{"uid":"f8055804-4c69-4e9d-b63c-d649c86a6b5f","title":"奉汉中王手札报韦侍御萧尊师亡","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日萧韦逝，淮王报峡中。","少年疑柱史，多术怪仙公。","不但时人惜，祗应吾道穷。","一哀侵疾病，相识自儿童。","处处邻家笛，飘飘客子蓬。","强吟怀旧赋，已作白头翁。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["悼亡"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.98},{"uid":"23818817-a8c2-4a52-a995-0f84dd5b548e","title":"送敭法师","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["度岁不相见，严冬始出关。","孤烟寒色树，高雪夕阳山。","瀑布寺应到，牡丹房甚闲。","南朝遗迹在，此去几时还。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["冬","雪"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["瀑布"]},"theme_conf":0.616},{"uid":"cp416a83451dd8fb","title":"扬州慢","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["淮左名都，竹西佳处，解鞍少驻初程。","过春风十里，尽荠麦青青。","自胡马窥江去后，废池乔木，犹厌言兵。","渐黄昏，清角吹寒，都在空城。","杜郎俊赏，算而今，重到须惊。","纵豆蔻词工，青楼梦好，难赋深情。","二十四桥仍在，波心荡、冷月无声。","念桥边红药，年年知为谁生。"],"theme":"边塞征战","theme2":["山水田园"],"style":"幽峭","style2":["清新","悲慨"],"mood":"孤寂","mood2":["相思"],"scene":["春","楼","月"],"cats":{"四季":["春天"],"生活":["写桥"]},"theme_conf":0.618},{"uid":"d9bb3556-f0d9-4989-afdd-0163fb826a01","title":"相和歌辞 从军行","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋来风瑟瑟，群马胡行疾。","严城昼不开，伏兵暗相失。","天子庙堂拜，将军玉门出。","纷纷伊洛间，戎马数千匹。","军门压黄河，兵气冲白日。","平生怀伏劒，忼慨既投笔。","南登汉月孤，北走燕云密。","近取韩彭计，早知孙吴术。","丈夫清万里，谁能埽一室。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["江","秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"cpdef5aab5815c88","title":"木兰花慢","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["老来情味减，对别酒、怯流年。","况屈指中秋，十分好月，不照人圆。","无情水、都不管，共西风、只等送归船。","秋晚莼鲈江上，夜深儿女灯前。","征衫。","便好去朝天。","玉殿正思贤。","想夜半承明，留教视草，却遣筹边。","长安故人问我，道寻常、泥酒只依然。","目断秋霄落雁，醉来时响空弦。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","酒","夜","中秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.568},{"uid":"c166938b-f267-49e1-8a9b-a76852e97540","title":"阌乡姜七少府设脍戏赠长歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姜侯设脍当严冬，昨日今日皆天风。","河冻未渔不易得，凿冰恐侵河伯宫。","饔人受鱼鲛人手，洗鱼磨刀鱼眼红。","无声细下飞碎雪，有骨已剁觜春葱。","偏劝腹腴媿年少，软炊香饭缘老翁。","落碪何曾白纸湿，放箸未觉金盘空。","新欢便饱姜侯德，清觞异味情屡极。","东归贪路自觉难，欲别上马身无力。","可怜为人好心事，于我见子真颜色。","不恨我衰子贵时，怅望且为今相忆。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["冬"],"cats":{"抒情":["思念","思乡"],"四季":["冬天"]},"theme_conf":0.86},{"uid":"1e5d503c-12ee-4e2c-a645-80e5e892316b","title":"赠薛戴","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晓雾忽为霜，寒蝉还罢响。","行人在长道，日暮多归想。","射策本何功，名登绛帐中。","遂矜丘室重，不料阮途穷。","交结慙时辈，龙钟似老翁。","机非鄙夫正，懒是平生性。","欹枕鸿雁高，闭关花药盛。","厨烟当雨绝，阶竹连窗暝。","欲赋苦饥行，无如消渴病。","旧业历胡尘，荒原少四邻。","田园空有处，兄弟未成人。","毛义心长苦，袁安家转贫。","今呈胸臆事，当为泪沾巾。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["老师"],"生活":["田野"]},"theme_conf":0.96},{"uid":"4e92a96d-aa74-4153-8314-b6df22d1e18a","title":"相和歌辞 子夜四时歌四首 春歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"],"theme":"闺情宫怨","theme2":["民生疾苦"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.471},{"uid":"0f9dd333-5f18-478b-8b18-53ed1bf06e91","title":"秋夜听严绅巴童唱竹枝歌","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巴人远从荆山客，回首荆山楚云隔。","思归夜唱竹枝歌，庭槐叶落秋风多。","曲中历历叙乡土，乡思绵绵楚词古。","身骑吴牛不畏虎，手提蓑笠欺风雨。","猨啼日暮江岸边，绿芜连山水连天。","来时十三今十五，一成新衣已再补。","鸿雁南飞报邻伍，在家欢乐辞家苦。","天晴露白钟漏迟，泪痕满面看竹枝。","曲终寒竹风袅袅，西方落日东方晓。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["儿童"],"植物":["竹子"]},"theme_conf":0.586},{"uid":"cpfed98815648c9e","title":"绿头鸭・多丽","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["玉人家，画楼珠箔临津。","托微风、彩箫流怨，断肠马上曾闻。","燕堂开、艳妆丛里，调琴思、认歌颦。","麝蜡烟浓，玉莲漏短，更衣不待酒初醺。","绣屏掩、枕鸳相就，香气渐暾暾。","回廊影，疏钟淡月，几许销魂。","翠钗分、银笺封泪，舞鞋从此生尘。","住兰舟、载将离恨，转南浦、背西曛。","记取明年，蔷薇谢后，佳期应未误行云。","凤城远，楚梅香嫩，先寄一枝春。","青门外，祗凭芳草，寻访郎君。"],"theme":"送别","theme2":["闺情宫怨"],"style":"婉约","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["花","夜","酒","舟","春"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"]},"theme_conf":0.436},{"uid":"0055db4e-e8d3-41a0-b201-0e3b970e27b6","title":"秋夜曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"ef36b0a2-6327-47a2-b777-ccf669af3ebb","title":"大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老向巴人里，今辞楚塞隅。","入舟飜不乐，解缆独长吁。","窄转深啼狖，虚随乱浴凫。","石苔凌几杖，空翠扑肌肤。","叠壁排霜劒，奔泉溅水珠。","杳冥藤上下，浓澹树荣枯。","神女峰娟妙，昭君宅有无。","曲留明怨惜，梦尽失欢娱。","摆阖盘涡沸，欹斜激浪输。","风雷缠地脉，冰雪耀天衢。","鹿角真走险，狼头如跋胡。","恶滩宁变色，高卧负微躯。","书史全倾挠，装囊半压濡。","生涯临臬兀，死地脱斯须。","不有平川决，焉知众壑趋。","乾坤霾涨海，雨露洗春芜。","欧鸟牵丝飏，骊龙濯锦纡。","落霞沈绿绮，残月坏金枢。","泥笋苞初荻，沙茸出小蒲。","雁儿争水马，燕子逐樯乌。","绝岛容烟雾，环洲纳晓晡。","前闻辨陶牧，转眄拂宜都。","县郭南畿好，津亭北望孤。","劳心依憩息，朗咏划昭苏。","意遣乐还笑，衰迷贤与愚。","飘萧将素发，汩没听洪𬬻。","丘壑曾忘返，文章敢自诬。","此生遭圣代，谁分哭穷途。","卧疾淹为客，蒙恩早厕儒。","廷争酬造化，朴直乞江湖。","滟滪险相迫，沧浪深可逾。","浮名寻已已，嬾计却区区。","喜近天皇寺，先披古画图。","应经帝子渚，同泣舜苍梧。","朝士兼戎服，君王按湛卢。","旄头初俶扰，鹑首丽泥涂。","甲卒身虽贵，书生道固殊。","出尘皆野鹤，历块匪辕驹。","伊吕终难降，韩彭不易呼。","五云高太甲，六月旷抟扶。","回首黎元病，争权将帅诛。","山林托疲苶，未必免崎岖。"],"theme":"羁旅思乡","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":["沉郁","清新"],"mood":"欢愉","mood2":["悲怆","孤寂"],"scene":["江","鸟","春","舟","山"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"山水":["江河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.8},{"uid":"22099372-939e-4154-a175-15d5365ac21c","title":"奉酬乐天立秋夕有怀见寄","author":"李绅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["深夜星汉静，秋风初报凉。","阶篁淅沥响，露叶参差光。","冰兔半升魄，铜壶微滴长。","薄帷乍飘卷，襟带轻摇飏。","此际昏梦清，斜月满轩房。","屣履步前楹，劒戟森在行。","重城宵正分，号鼓互相望。","独坐有所思，夫君鸾凤章。","天津落星河，一苇安可航。","龙泉白玉首，鱼服黄金装。","报国未知効，惟鹈徒在梁。","裴回顾戎旃，颢气生东方。","衰叶满栏草，斑毛盈镜霜。","羸牛未脱辕，老马强腾骧。","吟君白雪唱，慙媿巴人肠。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"孤寂","mood2":["慷慨","欢愉"],"scene":["秋"],"cats":{"抒情":["孤独","爱国"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.96},{"uid":"f889634b-508b-4a3a-9557-b64733de3b45","title":"奉和过旧宅应制","author":"上官仪","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["石关清晚夏，璇舆御早秋。","神麾飏珠雨，仙吹响飞流。","沛水祥云泛，宛郊瑞气浮。","大风迎汉筑，藂烟入舜球。","翠梧临凤邸，滋兰带鹤舟。","偃伯歌玄化，扈跸颂王游。","遗簪谬昭奖，珥笔荷恩休。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["夏","秋","舟"],"cats":{"四季":["夏天","秋天"],"山水":["瀑布"]},"theme_conf":0.98},{"uid":"af55f487-b2a8-4e2c-a3ab-406cd7a450fb","title":"春日即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["邻里朝光徧，披衣夜醉醒。","庖厨非旧火，林木发新青。","接果移天性，疎泉逐地形。","清明来几日，戴胜已堪听。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.76},{"uid":"f1177b2a-c00f-4d1a-a8f8-95e33bd6c4f5","title":"秋风二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["秋风淅淅吹我衣，东流之外西日微。","天清小城捣练急，石古细路行人稀。","不知明月为谁好，早晚孤帆他夜归。","会将白发倚庭树，故园池台今是非。"],"theme":"羁旅思乡","theme2":["送别"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","园林","月"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写风","月亮"]},"theme_conf":0.567},{"uid":"cp7d9065abd6353a","title":"玉楼春","author":"严仁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春风只在园西畔。","荠菜花繁胡蝶乱。","冰池晴绿照还空，香径落红吹已断。","意长翻恨游丝短。","尽日相思罗带缓。","宝奁明月不欺人，明日归来君试看。"],"theme":"爱情相思","theme2":["边塞征战"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["爱情","思念"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.577},{"uid":"6ed3a7f5-c68a-40ba-b28f-50ebbfac1091","title":"相和歌辞 春江花月夜二首 二","author":"张子容","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["交甫怜瑶佩，仙妃难重期。","沈沈绿江晚，惆怅碧云姿。","初逢花上月，言是弄珠时。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["月","江","春","花","夜"],"cats":{"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.65},{"uid":"15c6cbc9-753a-4f09-86bf-4fe2d8bb1fee","title":"凉思","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客去波平槛，蝉休露满枝。","永怀当此节，倚立自移时。","北斗兼春远，南陵寓使迟。","天涯占梦数，疑误有新知。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"]},"theme_conf":1.0},{"uid":"fd63be75-f6b3-491d-91d5-04179194f1aa","title":"初春登楼即目观作述怀","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凭轩俯兰阁，眺瞩散灵襟。","绮峰含翠雾，照日蕊红林。","镂丹霞锦岫，残素雪斑岑。","拂浪堤垂柳，娇花鸟续吟。","连甍岂一拱，众干如千寻。","明非独材力，终藉栋梁深。","弥怀矜乐志，更惧戒盈心。","媿制劳居逸，方规十产金。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼","春","花"],"cats":{"抒情":["孤独","怀古"],"四季":["春天"],"天气":["写雪"]},"theme_conf":0.565},{"uid":"2c08a55b-3506-4770-a3fb-66b0d021835e","title":"奉贺阳城郡王太夫人恩命加邓国太夫人","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["卫幕衔恩重，潘舆送喜频。","济时瞻上将，锡号戴慈亲。","富贵当如此，尊荣迈等伦。","郡依封土旧，国与大名新。","紫诰鸾回纸，清朝燕贺人。","远传冬笋味，更觉彩衣春。","奕叶班姑史，芬芳孟母邻。","义方兼有训，词翰两如神。","委曲承颜体，骞飞报主身。","可怜忠与孝，双美画骐麟。"],"theme":"送别","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","春"],"cats":{"四季":["春天","冬天"],"人物":["母亲"]},"theme_conf":0.51},{"uid":"05ca1eef-d549-4f8e-b853-1340fbb486b8","title":"杂曲歌辞 行路难五首 三","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见荒树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟空守闺。","独宿自然堪下泪，况复时闻乌夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","春","秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["春天","秋天"],"人生":["战争"],"节日":["中秋节"]},"theme_conf":0.714},{"uid":"dff1b780-5ef1-4c4f-abff-ef38d41e3c32","title":"醉歌行赠公安颜少府请顾八题壁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["神仙中人不易得，颜氏之子才孤标。","天马长鸣待驾驭，秋鹰整翮当云霄。","君不见东吴顾文学，君不见西汉杜陵老。","诗家笔势君不嫌，词翰升堂为君埽。","是日霜风冻七泽，乌蛮落照衔赤壁。","酒酣耳热忘头白，感君意气无所惜，一为歌行歌主客。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["恬淡","孤寂"],"scene":["酒","秋"],"cats":{"抒情":["孤独","感恩"],"四季":["秋天"],"食物":["写酒"]},"theme_conf":0.86},{"uid":"913c4360-669c-4e85-ba3d-49dec96abce4","title":"东峰亭各赋一物得阴崖竹","author":"袁邕","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["终岁寒苔色，寂寥幽思深。","朝歌犹夕岚，日永流清阴。","龙钟负烟雪，自有凌云心。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["冬","山","楼","雪"],"cats":{"四季":["冬天"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"9cf2d943-e52c-4406-bd53-03f686f4abb7","title":"和都官苗员外秋夜省直对雨简诸知己","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["多雨南宫夜，仙郎寓直时。","漏长丹凤阙，秋冷白云司。","萤影侵堦乱，鸿声出苑迟。","萧条人吏散，小谢有新诗。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋","雨"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"d76f7632-9926-40d4-8ac2-497f7ca08223","title":"安邑里中秋怀寄高员外","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["原宪素非贫，嵇康自寡欲。","守道识通穷，达命齐荣辱。","庭梧变葱蒨，篱菊扬芳馥。","坠叶翻夕霜，高堂瞬华烛。","况兹寒夜永，复叹流年促。","感物思殷勤，怀贤心踯躅。","雄词封禅草，丽句阳春曲。","高德十年兄，异才千里足。","咫尺邈雪霜，相望如琼玉。","欲识岁寒心，松筠更秋绿。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["秋","中秋","雪"],"cats":{"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"417dd972-fc55-4972-b698-e5e595453dbd","title":"相和歌辞 王昭君","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["自矜妖艳色，不顾丹青人。","那知粉缋能相负，却使容华飜误身。","上马辞君嫁骄虏，玉颜对人啼不语。","北风雁急浮清秋，万里独见黄河流。","纤腰不复汉宫宠，双蛾长向胡天愁。","琵琶弦中苦调多，萧萧羌笛声相和。","可怜一曲传乐府，能使千秋伤绮罗。"],"theme":"题画咏艺","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["江","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["黄河"]},"theme_conf":0.435},{"uid":"dd40f188-e63b-48e7-9418-7e8e667b7308","title":"送陆鸿渐栖霞寺采茶","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["采茶非采菉，远远上层崖。","布叶春风暖，盈筐白日斜。","旧知山寺路，时宿野人家。","借问王孙草，何时泛椀花。"],"theme":"送别","theme2":["闲适隐逸","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"动物":["写鸟"],"食物":["写茶"]},"theme_conf":0.376},{"uid":"78975868-daef-40f6-89f2-1aa8b5308c55","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 三","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["已愁花落荒岩底，复恨根生乱石间。","几度欲移移不得，天教抛掷在深山。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","花","月","冬","夏"],"cats":{"抒情":["伤感","孤独","感恩"],"四季":["夏天","冬天"],"天气":["月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.475},{"uid":"c91e2fce-3d9c-42fa-9692-39d502521789","title":"春寻柳先生","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["言是商山老，尘心莫问年。","白髯垂策短，乌帽据梧偏。","酒熟飞巴雨，丹成见海田。","疎云披远水，景动石床前。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"07e12fb9-a0f7-4cba-81a3-65b03dbf4639","title":"冬至后西湖泛舟看断冰偶成长句","author":"李郢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["一阳生后阴飙竭，湖上层冰看折时。","云母扇摇当殿色，珊瑚树碎满盘枝。","斜汀藻动鱼应觉，极浦波生鴈未知。","山影浅中留瓦砾，日光寒外送涟漪。","崖崩苇岸纵横散，篙蹙兰舟片段随。","曾向黄河望冲激，大鹏飞起雪风吹。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["冬","江","舟"],"cats":{"四季":["冬天"],"山水":["黄河","西湖"]},"theme_conf":0.86},{"uid":"e9f0c9ff-9301-4ad3-99f5-7283edd3aa6d","title":"伤春赠远","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去水流年日并驰，年光客思两相随。","咨嗟斑鬓今承弁，慙愧新荷又发池。","杨柳逶迤愁远道，鹧鸪啁哳怨南枝。","忆君何啻同琼树，但向春风送别离。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念","伤感"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.86},{"uid":"f198211f-331a-4f1f-87f2-ca57cc5264cd","title":"春日咏梅花二首 一","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["靓妆才罢粉痕新，递晓风回散玉尘。","若遣有情应怅望，已兼残雪又兼春。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"cpda401b77a73d37","title":"贺新郎","author":"叶梦得","dynasty":"宋","section":"宋词","form":"词","paragraphs":["睡起啼莺语。","掩青苔、房栊向晚，乱红无数。","吹尽残花无人见，惟有垂杨自舞。","渐暖霭、初回轻暑。","宝扇重寻明月影，暗尘侵、尚有乘鸾女。","惊旧恨，遽如许。","江南梦断横江渚。","浪黏天、葡萄涨绿，半空烟雨。","无限楼前沧波意，谁采苹花寄取。","但怅望、兰舟容与。","万里云帆何时到，送孤鸿、目断千山阻。","谁为我，唱金缕。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新","豪放"],"mood":"孤寂","mood2":[],"scene":["月","舟","江","江南","花","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"]},"theme_conf":0.659},{"uid":"571a9d34-1572-42f4-bb50-96c4d88974b4","title":"春日忆李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白也诗无敌，飘然思不群。","清新庾开府，俊逸鲍参军。","渭北春天树，江东日暮云。","何时一尊酒，重与细论文。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"6f9c734b-00ef-4d46-b30a-79ff6770c7aa","title":"长安书怀","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岐路今如此，还堪恸哭频。","关中成久客，海上老诸亲。","谷口田应废，乡山草又春。","年年销壮志，空作献书人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"97e74ab5-16ae-4acf-b0b1-9329ebce61fe","title":"詶浙东李侍郎越州春晚即事长句","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["越中蔼蔼繁华地，秦望峰前禹穴西。","湖草初生边鴈去，山花半谢杜鹃啼。","青油昼卷临高阁，红斾晴翻绕古堤。","明日汉庭征旧德，老人争出若耶溪。"],"theme":"山水田园","theme2":["应制干谒"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["江南"],"cats":{"四季":["春天"],"山水":["西湖"]},"theme_conf":0.545},{"uid":"f0d11fd0-26d2-4608-aeb0-dc841b80470b","title":"瀑布","author":"章孝标","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋河溢长空，天洒万丈布。","深雷隐云壑，孤电挂岩树。","沧溟晓喷寒，碧落晴荡素。","非趋下流急，势使不得住。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["山","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"]},"theme_conf":1.0},{"uid":"afc80a09-19c1-466c-aeda-9a90b0b0ff3f","title":"商山麻涧","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["云光岚彩四面合，柔柔垂柳十余家。","雉飞鹿过芳草远，牛巷鸡埘春日斜。","秀眉老父对罇酒，蒨袖女儿簪野花。","征车自念尘土计，惆怅溪边书细沙。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["恬淡"],"scene":["山","花","春","酒"],"cats":{"四季":["春天"],"人物":["父亲"]},"theme_conf":0.706},{"uid":"2e8ddf82-3bbc-49aa-ac97-2abdd2cd760a","title":"相和歌辞 懊恼曲","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["藕丝作线难胜针，蘂粉染黄那得深。","玉白兰芳不相顾，倡楼一笑轻千金。","莫言自古皆如此，健劒刜钟铅绕指。","三秋庭绿尽迎霜，惟有荷花守红死。","西江小吏朱斑轮，柳缕吐芽香玉春。","两股金钗已相许，不令独作空城尘。","悠悠楚水流如马，恨紫愁红满平野。","野土千年怨不平，至今烧作鸳鸯瓦。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["沉郁","旷达"],"mood":"愁怨","mood2":[],"scene":["花","秋"],"cats":{"抒情":["爱情","伤感"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"4cf19354-4c0a-4e55-980b-69fa7f81ed0f","title":"游子吟","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"人物":["母亲"]},"theme_conf":0.845},{"uid":"0999303b-6686-4053-8fd7-c69c1a37a46f","title":"白菊三首 二","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫惜西风又起来，犹能婀娜傍池台。","不辞暂被霜寒挫，舞袖招香即却回。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.95},{"uid":"b541e528-83cc-4c89-9990-94fda479abdb","title":"留别郑三韦九兼洛下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["忆昨相逢论久要，顾君哂我轻常调。","羁旅虽同白社游，诗书已作青云料。","蹇质蹉跎竟不成，年过四十尚躬耕。","长歌达者桮中物，大笑前人身后名。","幸逢明盛多招隐，高山大泽征求尽。","此时亦得辞渔樵，青袍裹身荷圣朝。","犂牛钓竿不复见，县人邑吏来相邀。","远路鸣蝉秋兴发，华堂美酒离忧销。","不知何日更携手，应念兹晨去折腰。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["秋","酒"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.432},{"uid":"7c79a705-fd5b-48b1-bc25-3d8658cd634c","title":"相和歌辞 从军行三首 三","author":"李约","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["候火起雕城，尘砂拥战声。","游军藏汉帜，降骑说蕃情。","霜降滮池浅，秋深太白明。","嫖姚方虎视，不觉请添兵。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["战争"]},"theme_conf":0.864},{"uid":"cp8d4d1ee0e7ab9c","title":"应天长","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["条风布暖，霏雾弄晴，池塘遍满春色。","正是夜堂无月，沈沈暗寒食。","梁间燕，前社客。","似笑我、闭门愁寂。","乱花过，隔院芸香，满地狼藉。","长记那回时，邂逅相逢，郊外驻油壁。","又见汉宫传烛，飞烟五候宅。","青青草，迷路陌。","强带酒，细寻前迹。","市桥远，柳下人家，犹自相识。"],"theme":"节令风俗","theme2":["羁旅思乡","咏史怀古"],"style":"婉约","style2":["清新","冲淡"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["清明","园林","花","春","酒","夜"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.68},{"uid":"3f218bb2-5f46-423d-869b-fa166ac8ba49","title":"秋灯对雨寄史近崔积","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["坐听宫城传晚漏，起看衰叶下寒枝。","空庭绿草结离念，细雨黄花赠所思。","蟋蟀已惊良节度，茱萸偏忆故人期。","相逢莫厌尊前醉，春去秋来自不知。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["雨","秋"],"cats":{"抒情":["友情","思念"],"四季":["秋天"],"天气":["写雨"],"节日":["元宵节","重阳节"]},"theme_conf":0.95},{"uid":"afa0d6db-b93a-4e96-aae9-59ec920eb6de","title":"杂曲歌辞 游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故巢思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰晖百年内，惟愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何艰哉？北斗不可斟。","夜晴星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蜻蛚催寒砧。","立身计几误，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧因古今。","胡为不归欤，孤负丘中琴。","腰下是何物？牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山杳岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾霄汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分堙沈。","层城发云韶，玉府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋","江","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.291},{"uid":"ff9ba6ba-1892-40f7-b02c-2ce2e0e2c8ed","title":"高荷","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["种藕百余根，高荷才四叶。","飐闪碧云扇，团圆青玉叠。","亭亭自擡举，鼎鼎难藏擪。","不学著水荃，一生长怗怗。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.631},{"uid":"fc228c0d-4d2a-45a3-a137-a3ca03b5d7f0","title":"与从弟瑾同下第后出关言别 四","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谁怜苦志已三冬，却欲躬耕学老农。","流水白云寻不尽，期君何处得相逢。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"抒情":["离别"],"四季":["冬天"],"生活":["田野"]},"theme_conf":0.476},{"uid":"1eb3241e-272e-4183-801d-b37e6beb048f","title":"拟娼楼节怨","author":"刘方平","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上苑离离莺度，昆明幂幂蒲生。","时光春华可惜，何须对镜含情。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.544},{"uid":"ebb316eb-28f4-4a18-9eb2-07ccf943a7eb","title":"送少微上人东南游","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石梁人不到，独往更迢迢。","乞食山家少，寻钟野寺遥。","松门风自扫，瀑布雪难消。","秋夜闻清梵，余音逐海潮。"],"theme":"送别","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","雪","秋","山","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.511},{"uid":"064b1fa2-3649-4b01-a0c0-4bc73c9d8a89","title":"郊庙歌辞 享太庙乐章 崇德舞","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["五运改卜，千龄启圣。","彤云晓聚，黄星夜映。","叶阐珠囊，基开玉镜。","下临万宇，上齐七政。","雾开三象，尘清九服。","海溓星晖，远安迩肃。","天地交泰，华夷辑睦。","翔泳归仁，中外禔福。","绩逾黜夏，勋高翦商。","武陈七德，刑设三章。","祥禽巢阁，仁兽游梁。","卜年惟永，景福无疆。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["雄浑","清新"],"mood":"欢愉","mood2":[],"scene":["夏","夜"],"cats":{"四季":["夏天"]},"theme_conf":0.9},{"uid":"ad765a79-3c31-49ca-9e63-6bebc466ecd3","title":"送李殷游边","author":"刘驾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["十年梦相识，一觏俄远别。","征驾在我傍，草草意难说。","君居洞庭日，诗句满魏阙。","如何万里来，青桂看人折。","行装不及备，西去偶然诀。","孟夏出都门，红尘客衣热。","荒城见羊马，野馆具薇蕨。","边境渐无虞，旅宿常待月。","西园置酒地，日夕簪裾列。","壮志安可留，槐花樽前发。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["酒","园林","月","江","夏"],"cats":{"四季":["夏天"],"人生":["励志","梦想"]},"theme_conf":0.683},{"uid":"cp1061a9efb70635","title":"踏莎行","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["燕燕轻盈，莺莺娇软。","分明又向华胥见。","夜长争得薄情知，春初早被相思染。","别后书辞，别时针线。","离魂暗逐郎行远。","淮南皓月冷千山，冥冥归去无人管。"],"theme":"送别","theme2":["爱情相思"],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["春","鸟"],"cats":{"抒情":["爱情","离别","思念"],"四季":["春天"]},"theme_conf":0.631},{"uid":"cpead5ea21c5d00e","title":"六州歌头","author":"韩元吉","dynasty":"宋","section":"宋词","form":"词","paragraphs":["东风著意。","先上小桃枝。","红粉腻。","娇如醉。","倚朱扉。","记年时。","隐映新妆，面临水岸。","春将半。","云日暖。","斜桥转。","夹城西。","草软莎平跋马，垂杨渡、玉勒争嘶。","认蛾眉凝笑，脸薄拂燕支。","绣户曾窥。","恨依依。","共携手处。","香如雾。","红随步。","怨春迟。","消瘦损。","凭谁问。","只花知。","泪空垂。","旧日堂前燕，和烟雨，又双飞。","人自老。","春长好。","梦佳期。","前度刘郎，几许风流地，花也应悲。","但茫茫暮霭，目断武陵溪。","往事难追。"],"theme":"咏物","theme2":["爱情相思","山水田园","咏史怀古"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.75},{"uid":"620190f9-ce46-4ac0-979a-2926f377fb5a","title":"和杜录事题红叶","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒山十月旦，霜叶一时新。","似烧非因火，如花不待春。","连行排绛帐，乱落剪红巾。","解驻篮轝看，风前唯两人。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"e0b629da-76cc-4223-98b8-25fad7f63656","title":"忆寿春废虎坑余以春二月至郡主吏举所职称霍山多虎每岁采茶为患择肉于人至春常修陷穽数十所勒猎者采其皮睛余悉除罢之是岁虎不复为害至余去郡三载","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["匪将履尾求兢惕，那效探雏所患争。","当路绝群尝诫暴，为猫驱狝亦先迎。","每推至化宣余力，岂用潜机害尔生。","休逐豺狼止贪戾，好为仁兽答皇明。"],"theme":"咏物","theme2":["边塞征战","送别","山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"食物":["写茶"]},"theme_conf":0.65},{"uid":"ed79f9bc-d5d1-4251-b22d-d091e0758a3f","title":"无题","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["相见时难别亦难，东风无力百花残。","春蚕到死丝方尽，蜡炬成灰泪始干。","晓镜但愁云鬓改，夜吟应觉月光寒。","蓬山此去无多路，青鸟殷勤为探看。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["月","春"],"cats":{"抒情":["伤感"],"四季":["春天"]},"theme_conf":0.691},{"uid":"912f6639-a774-4d02-8c17-07f6bc3b1d63","title":"送大理张卿","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春色依依惜解携，月卿今夜泊隋堤。","白沙洲上江篱长，绿树村边谢豹啼。","迁客比来无倚仗，故人相去隔云泥。","越禽唯有南枝分，目送孤鸿飞向西。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","春","月","夜"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"生活":["乡村"]},"theme_conf":0.783},{"uid":"4dc66101-9b61-41a9-9e26-965eef8d818d","title":"盛山十二诗 梅谿","author":"韦处厚","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["夹岸凝清素，交枝漾浅沦。","味调方荐实，腊近又先春。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","冬"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"49194c4b-b775-4d21-a506-fc0a2ff308f1","title":"相和歌辞 子夜四时歌四首 秋歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏？良人罢远征。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","月"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"]},"theme_conf":0.576},{"uid":"30a09ffc-27bf-4fec-b22b-6e91f4dd8a0a","title":"杂曲歌辞 春游曲三首 二","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["骋望登香阁，争高下砌台。","林间踏青去，席上意钱来。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","楼","清明"],"cats":{"四季":["春天"],"节日":["清明节"]},"theme_conf":1.0},{"uid":"cpcbaaff5279b82b","title":"西地梨诗","author":"沈约","dynasty":"魏晋南北朝","section":"魏晋南北朝","form":"五言绝句","paragraphs":["列茂河阳苑，蓄紫滥觞隈。","翻黄秋沃若，落素春徘徊。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","秋","春"],"cats":{"四季":["春天","秋天"],"植物":["梨花"]},"theme_conf":0.2},{"uid":"4ac3f099-73da-43e8-a4e5-1dbbd9427491","title":"闺怨","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["闺中少妇不曾愁，春日凝妆上翠楼。","忽见陌头杨柳色，悔教夫壻觅封侯。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"e5949236-b878-4ef5-aa53-445651fb04ac","title":"情人玉清歌","author":"毕耀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["洛阳有人名玉清，可怜玉清如其名。","善踏斜柯能独立，婵娟花艳无人及。","珠为帬，玉为缨，临春风，吹玉笙。","悠悠满天星，黄金阁上晚妆成。","云和曲中为曼声，玉梯不得蹈。","摇袂两盈盈，城头之日复何情。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"0878208a-077c-4a26-9aa1-3b7d6a3cf1fd","title":"早秋宿叶堕所居","author":"罗隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["池荷叶正圆，长历报时殚。","旷野云蒸热，空庭雨始寒。","蝇蚊犹得志，簟席若为安。","浮世知谁是，劳歌共一懽。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","园林"],"cats":{"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.65},{"uid":"c5b74274-de21-482b-ae7a-b0d8200bbb18","title":"琴曲歌辞 湘妃","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["帝子不可见，秋风来暮思。","婵娟湘江月，千载空蛾眉。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["中秋","秋","月","江"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"2ac203a8-6e70-4b78-ad75-9acacae9b04a","title":"相和歌辞  北上行","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北上何所苦，北上缘太行。","磴道盘且峻，巉岩凌穹苍。","马足蹶侧石，车轮摧高冈。","沙尘接幽州，烽火连朔方。","杀气毒劒戟，严风裂衣裳。","奔鲸夹黄河，凿齿屯洛阳。","前行无归日，返顾思旧乡。","惨戚冰雪里，悲号绝中肠。","尺布不掩体，皮肤剧枯桑。","汲水涧谷阻，采薪陇坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，饥饮零露浆。","叹此北上苦，停骖为之伤。","何日王道平？开颜覩天光。"],"theme":"边塞征战","theme2":["民生疾苦","山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["秋","冬","江","雪"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"山水":["黄河"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.296},{"uid":"c824482e-922d-4bcd-9a6c-63b21b20b56d","title":"瀑布寺贞上人院","author":"郑巢","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["林疎多暮蝉，师去宿山烟。","古壁灯熏画，秋琴雨润弦。","竹间窥远鹤，岩上取寒泉。","西岳沙房在，归期更几年。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","园林","秋","夜","雨"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.548},{"uid":"cac5a624-4332-4200-9b3d-735cb790e16d","title":"中和节赐百官燕集因示所怀","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["至化恒在宥，保和兹息人。","推诚抚诸夏，与物长为春。","仲月风景暖，禁城花柳新。","芳时协金奏，赐宴同群臣。","丝竹岂云乐，忠贤惟所亲。","庶洽朝野意，旷然天地均。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["鸟","夏","花","春","月"],"cats":{"四季":["春天","夏天"],"动物":["写鸟"]},"theme_conf":0.86},{"uid":"2769113d-0cac-4e67-83cb-0c10685f8381","title":"春宿左省","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["花隐掖垣暮，啾啾栖鸟过。","星临万户动，月傍九霄多。","不寝听金钥，因风想玉珂。","明朝有封事，数问夜如何。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":[],"scene":["春"],"cats":{"四季":["春天"]},"theme_conf":0.65},{"uid":"bcd31207-66ec-44c9-9890-1c70b6e8ea69","title":"相和歌辞 挽歌二首 一","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["阴风吹黄蒿，挽歌渡秋水。","车马却归城，孤坟月明里。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","月"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"]},"theme_conf":0.98},{"uid":"43c9f1f6-3a24-489d-a8c9-552711348736","title":"奉和虢州刘给事使君三堂新题二十一咏 荷池","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["风雨秋池上，高荷盖水繁。","未谙鸣摵摵，那似卷翻翻。"],"theme":"应制干谒","theme2":["咏物"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["园林","夏","雨"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"ab4e15ff-7244-4bd0-860e-4622b1feca27","title":"中秋夜登楼望月寄人","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西楼见月似江城，脉脉悠悠倚槛情。","万里此情同皎洁，一年今日最分明。","初惊桂子从天落，稍误芦花带雪平。","知称玉人临水见，可怜光彩有余清。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["月","中秋","楼","秋"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"cf68f337-d8fc-48a3-b89e-a828d08189a6","title":"喜观即到复题短篇二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["巫峡千山暗，终南万里春。","病中吾见弟，书到汝为人。","意荅儿童问，来经战伐新。","泊船悲喜后，款款话归秦。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放","沉郁"],"mood":"欢愉","mood2":[],"scene":["春","舟","山"],"cats":{"四季":["春天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.65},{"uid":"1f66d2ec-8418-485e-a434-e21a0d439dda","title":"杂曲歌辞 秋夜曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"5aac5703-ad15-4da8-84fb-ff0e68557569","title":"立春日宴高陵任明府宅","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春灰今变候，密雪又霏霏。","坐客同心满，流年此会稀。","风成空处乱，素积夜来飞。","且共衔杯酒，陶潜不得归。"],"theme":"节令风俗","theme2":[],"style":"冲淡","style2":["旷达"],"mood":"欢愉","mood2":[],"scene":["春","酒","雪"],"cats":{"四季":["春天"],"人生":["时光"]},"theme_conf":0.8},{"uid":"96455db1-a0c6-402c-8892-05c6b9a3d029","title":"秋夜寄丘二十二员外","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["怀君属秋夜，散步咏凉天。","山空松子落，幽人应未眠。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"]},"theme_conf":0.97},{"uid":"3850fcde-577f-4a8a-8fae-3efe63b00439","title":"赋得夏首启节","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北阙三春晚，南荣九夏初。","黄莺弄渐变，翠林花落余。","瀑流还响谷，猿啼自应虚。","早荷向心卷，长杨就影舒。","此时欢不极，调轸坐相于。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.638},{"uid":"6b2be4af-0264-4adc-80c4-0691ad752f41","title":"相和歌辞 采莲曲二首 二","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["涔阳女儿花满头，毵毵同泛木兰舟。","春风日暮南湖里，争唱菱歌不肯休。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["舟","春"],"cats":{"四季":["春天"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"6c492d0a-ef0a-4938-8c65-fa50a5de7d5e","title":"宿赞公房","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["杖锡何来此，秋风已飒然。","雨荒深院菊，霜倒半池莲。","放逐宁违性，虚空不离禅。","相逢成夜宿，陇月向人圆。"],"theme":"佛道禅颂","theme2":["山水田园","送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.8},{"uid":"6dbed00f-b5d4-4276-8de1-d65054b3d4a7","title":"和程员外春日东郊即事","author":"包何","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["郎官休浣怜迟日，野老欢娱为有年。","几处折花惊蝶梦，数家留叶待蚕眠。","藤垂宛地萦珠履，泉迸侵堦浸绿钱。","直到闭关朝谒去，莺声不散柳含烟。"],"theme":"民生疾苦","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"1fd7fb7a-8fd1-45bc-9dcb-803c52590d34","title":"横吹曲辞 折杨柳","author":"余延寿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大道连国门，东西种杨柳。","葳蕤君不见，褭娜垂来久。","缘枝栖暝禽，雄去雌独吟。","余花怨春尽，微月起秋阴。","坐望窗中蝶，起攀枝上叶。","好风吹长条，妸娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁杀陇头人。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","塞外","秋","月","楼"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","秋天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.644},{"uid":"2fa17eef-441f-4e0f-bb10-37d2d71f601c","title":"军事院霜菊盛开因书一绝寄上谏议","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金华千点晓霜凝，独对壶觞又不能。","已过重阳三十日，至今犹自待王弘。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","秋","酒","园林"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.403},{"uid":"c34fab35-9a2e-4bc3-82e7-e6d79c091b0b","title":"冬日临昆明池","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石鲸分玉溜，劫烬隐平沙。","柳影冰无叶，梅心冻有花。","寒野凝朝雾，霜天散夕霞。","欢情犹未极，落景遽西斜。"],"theme":"民生疾苦","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"]},"theme_conf":1.0},{"uid":"d4baf2d1-ea61-4fb3-a284-e889275bdca2","title":"杂曲歌辞 长相思三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长相思，在长安，络纬秋啼金井栏。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有绿水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.775},{"uid":"f0d0412b-b79c-4643-a730-f980bf7e088a","title":"秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德敍怀斐然之作三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南征为客久，西候别君初。","岁满归凫舄，秋来把雁书。","荆门留美化，姜被就离居。","闻道和亲人，垂名报国余。","连枝不日竝，八座几时除。","往者胡星孛，恭惟汉网疎。","风尘相澒洞，天地一丘墟。","殿瓦鸳鸯坼，宫帘翡翠虚。","钩陈摧徼道，枪櫐失储胥。","文物陪巡守，亲贤病拮据。","公时呵䝟貐，首唱却鲸鱼。","势惬宗萧相，材非一范雎。","尸填太行道，血走浚仪渠。","滏口师仍会，函关愤已摅。","紫微临大角，皇极正乘舆。","赏从频峨冕，殊私再直庐。","岂惟高卫霍，曾是接应徐。","降集飜翔凤，追攀绝众狙。","侍臣双宋玉，战策两穰苴。","鉴澈劳悬镜，荒芜已荷锄。","向来披述作，重此忆吹嘘。","白发甘凋丧，青云亦卷舒。","经纶功不朽，跋涉体何如。","应讶耽湖橘，常餐占野蔬。","十年婴药饵，万里狎樵渔。","扬子淹投阁，邹生惜曳裾。","但惊飞熠耀，不记改蟾蜍。","烟雨封巫峡，江淮略孟诸。","汤池虽险固，辽海尚填淤。","努力输肝胆，休烦独起予。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","幽峭"],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["离别","爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.532},{"uid":"82319857-3f0e-4f8f-8e9b-d636d68cae97","title":"琴曲歌辞 飞龙引二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["鼎湖流水清且闲，轩辕去时有弓劒。","古人传道留其间，后宫婵娟多花颜。","乘鸾飞烟亦不还，骑龙攀天造天关。","造天关，闻天语，长云河车载玉女。","载玉女，过紫皇，紫皇乃赐白兔所捣之药，后天而老凋三光。","下视瑶池见王母，蛾眉萧飒如秋霜。"],"theme":"游仙梦幻","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","中秋"],"cats":{"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.437},{"uid":"06798167-53e9-4e1b-b84f-b150edd78eac","title":"夏日梅溪馆寄庞舍人","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["东阳宾礼重，高馆望行期。","埽簟因松叶，𥮾瓜使竹枝。","卷帘闻鸟近，翻枕梦人迟。","坐听津桥说，今营太守碑。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.567},{"uid":"c7e721a1-9169-46c6-bbf3-970fef076539","title":"相和歌辞 铜雀妓","author":"刘商","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["魏主矜蛾眉，美人美于玉。","高台无昼夜，歌舞竟未足。","盛色如转圜，夕阳落深谷。","仍令身殁后，尚足平生欲。","红粉横泪痕，调弦空向屋。","举头君不在，唯见西陵木。","玉辇岂再来，娇鬟为谁绿。","那堪秋风里，更舞阳春曲。","曲终情不胜，阑干向西哭。","台边生野草，来去罥罗縠。","况复陵寝间，双双见麋鹿。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["绮丽","沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","夜","秋","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天","秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"6f33754e-1fb7-4140-8654-d729e9254a10","title":"走笔谢孟谏议寄新茶","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["日高丈五睡正浓，军将打门惊周公。","口云谏议送书信，白绢斜封三道印。","开缄宛见谏议面，手阅月团三百片。","闻道新年入山里，蛰虫惊动春风起。","天子须尝阳羡茶，百草不敢先开花。","仁风暗结珠琲瓃，先春抽出黄金芽。","摘鲜焙芳旋封裹，至精至好且不奢。","至尊之余合王公，何事便到山人家。","柴门反关无俗客，纱帽笼头自煎吃。","碧云引风吹不断，白花浮光凝椀面。","一椀喉吻润，两椀破孤闷。","三椀搜枯肠，唯有文字五千卷。","四椀发轻汗，平生不平事。","尽向毛孔散，五椀肌骨清。","六椀通仙灵，七椀吃不得也。","唯觉两腋习习清风生，蓬莱山，在何处？","玉川子，乘此清风欲归去。","山上群仙司下土，地位清高隔风雨。","安得知百万亿苍生命，堕在巅崖受辛苦。","便为谏议问苍生，到头还得苏息否。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["雨","花","春","山"],"cats":{"抒情":["感恩"],"四季":["春天"],"节日":["春节"],"食物":["写茶"]},"theme_conf":0.9},{"uid":"caa023cf-9f55-450c-9638-1cf5c0223cc1","title":"杂曲歌辞 长相思三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["日色已尽花含烟，月明欲素愁不眠。","赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。","此曲有意无人传，愿随春风寄燕然，忆君迢迢隔青天。","昔日横波目，今成流泪泉。","不信妾肠断，归来看取明镜前。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["春","月"],"cats":{"抒情":["爱情","思念","伤感"],"四季":["春天"]},"theme_conf":0.5},{"uid":"bdd79ce6-205b-4c91-bf73-532087f5acfe","title":"杂曲歌辞 空城雀","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["空城雀，何不飞来人家住？","空城无人种禾黍。","土间生子草间长，满地蓬蒿幸无主。","近村虽有高树枝，雨中无食长苦饥。","八月小儿夹弓箭，家家畏我田头飞。","但能不出空城里，秋时百草皆有子。","黄口黄口莫啾啾，长尔得成无横死。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","雨","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.522},{"uid":"6f0897e1-ef12-4042-8e56-8cb1134cf9c3","title":"初秋夜坐","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["斜廊连绮阁，初月照宵帏。","塞冷鸿飞疾，园秋蝉噪迟。","露结林疎叶，寒轻菊吐滋。","愁心逢此节，长叹独含悲。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["幽峭","悲慨"],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"8674fa82-1c80-400d-b329-2c6ef1c5fee2","title":"冬日汉江南行将赴夏口途次江陵界寄裴尚书","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五部拥双旌，南依墨客卿。","关山迥梁甸，波浪接湓城。","烟景迷时候，云帆渺去程。","蛤珠冯月吐，芦雁触罗惊。","浦树凝寒晦，江天湛镜清。","赏心随处惬，壮志逐年轻。","舟檝不可驻，提封如任情。","向方曾指路，射策许言兵。","兰渚歇芳意，菱歌非应声。","元戎武昌守，羊祜幸连营。"],"theme":"寄赠酬答","theme2":["送别","山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["江","江南","冬","夏","舟"],"cats":{"四季":["夏天","冬天"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.87},{"uid":"8944162e-0986-4d0b-b9f9-ce0b899c0298","title":"相和歌辞 饮马长城窟行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["驰马渡河干，流深马渡难。","前逢锦车使，都护在楼兰。","轻骑犹衔勒，疑兵尚解鞍。","温池下绝涧，栈道接危峦。","拓地勋未赏，亡城律讵宽。","有月关犹暗，经春陇尚寒。","云昏无复影，冰合不闻湍。","怀君不可遇，聊持报一餐。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["春","楼","月"],"cats":{"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.821},{"uid":"b5f1094b-b9be-43cf-8e04-9b984642a630","title":"杂曲歌辞 清平调 一","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"theme":"游仙梦幻","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.513},{"uid":"1168c377-42c2-4c1f-a283-1ba089165dab","title":"秋日荆南述怀三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔承推奖分，媿匪挺生材。","迟暮宫臣忝，艰危衮职陪。","扬镳随日驭，折槛出云台。","罪戾宽犹活，干戈塞未开。","星霜玄鸟变，身世白驹催。","伏枕因超忽，扁舟任往来。","九钻巴噀火，三蛰楚祠雷。","望帝传应实，昭王问不回。","蛟螭深作横，豺虎乱雄猜。","素业行已矣，浮名安在哉？","琴乌曲怨愤，庭鹤舞摧颓。","秋雨漫湘水，阴风过岭梅。","苦摇求食尾，常曝报恩顋。","结舌防谗柄，探肠有祸胎。","苍茫步兵哭，展转仲宣哀。","饥籍家家米，愁征处处杯。","休为贫士叹，任受众人咍。","得丧初难识，荣枯划易该。","差池分组冕，合沓起蒿莱。","不必伊周地，皆知屈宋才。","汉庭和异域，晋史坼中台。","霸业寻常体，忠臣忌讳灾。","群公纷戮力，圣虑窅裴回。","数见铭钟鼎，真宜法斗魁。","愿闻锋镝铸，莫使栋梁摧。","盘石圭多翦，凶门毂少推。","垂旒资穆穆，祝网但恢恢。","赤雀飜然至，黄龙讵假媒。","贤非梦傅野，隐类凿颜坯。","自古江湖客，冥心苦死灰。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏史怀古","讽喻刺世"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","园林","舟"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"人生":["时光","战争"]},"theme_conf":0.95},{"uid":"fbf22c24-6020-4423-b6ce-2980ad7128d6","title":"过天门街","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雪尽终南又欲春，遥怜翠色对红尘。","千车万马九衢上，回首看山无一人。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春","山"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"cp8bb678591e441b","title":"伴云来・天香","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["烟络横林，山沈远照，逦迤黄昏钟鼓。","烛映帘栊，蛩催机杼，共苦清秋风露。","不眠思妇，齐应和、几声砧杵。","惊动天涯倦宦，岁华行暮。","当年酒狂自负。","谓东君、已春相付。","流浪征骖北道，客墙南浦。","幽恨无人晤语。","赖明月曾知旧游处。","好伴云来，还将梦去。"],"theme":"羁旅思乡","theme2":["民生疾苦","送别"],"style":"豪放","style2":["婉约","沉郁"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["月","秋"],"cats":{"抒情":["离别","思乡","孤独"],"四季":["秋天"],"天气":["写云","月亮"]},"theme_conf":0.286},{"uid":"6fc239af-e267-4a89-a804-330cf037dcb5","title":"秋夜有怀高三十五兼呈空和尚","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晚节闻君趋道深，结茅栽树近东林。","大师几度曾摩顶，高士何年遂发心。","北渚三更闻过雁，西城万里动寒砧。","不见支公与玄度，相思拥膝坐长吟。"],"theme":"哲理悟道","theme2":["爱情相思"],"style":"豪放","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.603},{"uid":"85a83aa1-746f-4baa-bc0f-deaf8de5fdcd","title":"相和歌辞 白头吟","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["洛阳城东桃李花，飞来飞去落谁家。","洛阳女儿惜颜色，行逢落花长叹息。","今年花落颜色改，明年花开复谁在。","已见松柏摧为薪，更闻桑田变成海。","古人无复洛城东，今人还对落花风。","年年岁岁花相似，岁岁年年人不同。","寄言全盛红颜子，须怜半死白头翁。","此翁白头真可怜，伊昔红颜美少年。","公子王孙芳树下，清歌妙舞落花前。","光禄池台文锦绣，将军楼阁画神仙。","一朝卧病无人识，三春行乐在谁边。","宛转蛾眉能几时，须臾白发乱如丝。","但看旧来歌舞地，惟有黄昏鸟雀悲。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","花","春","夜"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"]},"theme_conf":0.477},{"uid":"26f3fc34-fc1c-41ef-8c59-9b6d1806020e","title":"杂曲歌辞 少年行","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千点斓斒喷玉骢，青丝结尾绣缠騣。","鸣鞭晚出章台路，叶叶春依杨柳风。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"acef2d2d-cbcc-441c-8163-e1669a19b202","title":"题梨花睡鸭图","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔年家住太湖西，常过吴兴罨画溪。","水阁筠帘春似海，梨花影里睡凫鹥。","（见《吴兴艺文志补》卷四四）。"],"theme":"题画咏艺","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春","江南"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":0.762},{"uid":"163e6b84-544c-426c-820f-0b6bac718a2d","title":"相和歌辞 江南曲","author":"罗隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江烟湿雨鲛绡輭，漠漠远山眉黛浅。","水国多愁又有情，夜槽压酒银船满。","绷丝采怨凝晓空，吴王台榭春梦中。","鸳鸯㶉𫛶唤不起，平铺渌水眠东风。","西陵路边月悄悄，油壁轻车嫁苏小。"],"theme":"咏史怀古","theme2":["山水田园","爱情相思"],"style":"婉约","style2":["冲淡"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["爱情","伤感","怀古"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.55},{"uid":"a782bd15-160a-4ffd-803e-35334740fbff","title":"相和歌辞 张静婉采莲曲","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兰膏坠发红玉春，燕钗拖颈抛盘云。","城西杨柳向娇晚，门前沟水波潾潾。","麒麟公子朝天客，珮马珰珰铛度春陌。","掌中无力舞衣轻，翦断鲛绡破春碧。","抱月飘烟一尺腰，麝脐龙髓怜娇饶。","秋罗拂衣碎光动，露重花多香不销。","㶉𫛶胶胶塘水满，绿萍如粟莲茎短。","一夜西风送雨来，粉痕零落愁红浅。","船头折藕丝暗牵，藕根莲子相留连。","郎心似月月易缺，十五十六清光圆。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":["愁怨"],"scene":["秋","花","春","月"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["荷花"]},"theme_conf":0.503},{"uid":"99b28edd-1f27-415b-993f-f7ca05f18279","title":"深上人见访忆李端","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雁稀秋色尽，落日对寒山。","避事多称疾，留僧独闭关。","心归尘俗外，道胜有无间。","仍忆东林友，相期久不还。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋","鸟","山"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.56},{"uid":"d71a5667-a683-40ec-bb82-94373c508595","title":"春日咏梅花二首 二","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青帝来时值远芳，残花残雪尚交光。","隔年拟待春消息，得见春风已断肠。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"157a14f5-9ce9-41a4-ad4d-05e4b7ba595e","title":"杂曲歌辞 长干行","author":"张潮","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["壻贫如珠玉，壻富如埃尘。","贫时不忘旧，富贵多宠新。","妾本富家女，与君为偶匹。","惠好一何深，中门不曾出。","妾有绣衣裳，葳蕤金缕光。","念君贫且贱，易此从远方。","远方三千里，发去悔不已。","日暮情更来，空望去时水。","孟夏麦始秀，江上多南风。","商贾归欲尽，君今尚巴东。","巴东有巫山，窈窕神女颜。","常恐游此山，果然不知还。"],"theme":"闺情宫怨","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","山"],"cats":{"抒情":["思乡","闺怨"],"四季":["夏天"]},"theme_conf":0.41},{"uid":"dfb8c500-4eb8-4816-9b13-91d292ad9c6f","title":"襄阳寒食寄宇文籍","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["烟水初销见万家，东风吹柳万条斜。","大堤欲上谁相伴，马踏春泥半是花。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["清明","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"cae8a893-7ae6-4824-b4c5-eada730b075f","title":"苏武庙","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苏武魂销汉使前，古祠高树两茫然。","云边雁断胡天月，陇上羊归塞草烟。","廻日楼台非甲帐，去时冠劒是丁年。","茂陵不见封侯印，空向秋波哭逝川。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["惆怅","欢愉"],"scene":["楼","塞外","江南","秋","月"],"cats":{"抒情":["怀古"],"四季":["秋天"],"生活":["边塞"]},"theme_conf":0.461},{"uid":"cp0ebe2ac2d276d9","title":"绣鸾凤花犯・花犯","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚江湄，湘娥乍见，无言洒清泪。","淡然春意。","空独倚东风，芳思谁寄。","凌波路冷秋无际。","香云随步起。","谩记得，汉宫仙掌，亭亭明月底。","冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。","春思远，谁叹赏、国香风味。","相将共、岁寒伴侣。","小窗净、沈烟熏翠袂。","幽梦觉，涓涓清露，一枝灯影里。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":["绮丽","冲淡"],"mood":"愁怨","mood2":["孤寂"],"scene":["花","春","月","冬"],"cats":{"抒情":["伤感","孤独","闺怨"],"四季":["春天","冬天"],"天气":["月亮"]},"theme_conf":0.588},{"uid":"4b3cec93-fc44-44d2-91fa-a4feed67aaf9","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蛰龙三冬卧，老鹤万里心。","昔时贤俊人，未遇犹视今。","嵇康不得死，孔明有知音。","又如垅底松，用舍在所寻。","大哉霜雪干，岁久为枯林。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["冬","雪"],"cats":{"抒情":["友情"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"21781aca-5d96-4c9e-9bc1-ed8140e1107b","title":"杂曲歌辞 悲哉行","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["悲哉为儒者，力学不能疲。","读书眼欲暗，秉笔手生胝。","十上方一第，成名常苦迟。","纵有宦达者，两鬓已成丝。","可怜少壮日，适在穷贱时。","丈夫老且病，焉用富贵为。","沈沈朱门宅，中有乳臭儿。","状貌如妇人，光明膏粱肌。","手不把书卷，身不擐戎衣。","二十袭封爵，门承勋戚资。","春来日日出，服御何轻肥。","朝从博徒饮，暮有倡楼期。","评封还酒债，堆金选蛾眉。","声色狗马外，其余一无知。","山苗与涧松，地势随高卑。","古来无奈何，非君独伤悲。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春","读书"]},"theme_conf":0.641},{"uid":"84c3e8ec-51c4-408a-b93f-a56ad1360586","title":"敬宗睿武昭愍孝皇帝挽歌三首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["任贤劳梦寐，登位富春秋。","欲遂东人幸，宁虞杞国忧。","长杨收羽骑，太液泊龙舟。","惟有衣冠在，年年怆月游。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","春","秋","舟","月"],"cats":{"抒情":["悼亡"],"四季":["春天","秋天"],"节日":["端午节"]},"theme_conf":0.99},{"uid":"c5154a66-2e69-41ff-bc12-718763201e90","title":"梅花二首 一","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["应为阳春信未传，固将青艳属残年。","东君欲待寻佳约，剩寄衣香与粉绵。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春","冬"],"cats":{"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"0b4a2ac4-56be-43c9-83e4-753081c0caf0","title":"过卢明府有赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["良吏不易得，古人今可传。","静然本诸已，以此知其贤。","我行挹高风，羡尔兼少年。","胸怀豁清夜，史汉如流泉。","明日复行春，逶迤出郊坛。","登高见百里，桑野郁芊芊。","时平俯鹊巢，岁熟多人烟。","奸猾唯闭户，逃亡归种田。","廻轩自郭南，老幼满马前。","皆贺蚕农至，而无徭役牵。","君观黎庶心，抚之诚万全。","何幸逢大道，愿言烹小鲜。","能奏明廷主，一试武城弦。"],"theme":"寄赠酬答","theme2":["民生疾苦","山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","重阳"],"cats":{"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"f51694bd-8955-4c4d-9ed6-673c2fbb5321","title":"太子李舍人城东别业与二三文友逃暑","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下马失炎暑，重门深绿篁。","宫臣礼嘉客，林表开兰堂。","兹夕兴难尽，澄罍照墨塲。","鲜风吹印绶，密坐皆馨香。","美景惜文会，清吟迟羽觞。","东林晚来好，目极趣何长。","鸟道挂疎雨，人家残夕阳。","城隅拥归骑，留醉恋琼芳。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"抒情":["友情","离别","思乡"],"四季":["夏天"],"山水":["庐山"]},"theme_conf":0.585},{"uid":"aaa3d713-8c7f-4f46-a0d5-39ed552d9511","title":"杂曲歌辞 鸣雁行","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["嗷嗷鸣雁鸣且飞，穷秋南去春北归。","去寒就暖识所处，天长地阔栖息稀。","风霜酸苦稻粱微，羽毛摧落身不肥。","徘徊反顾群侣违，哀鸣欲下洲渚非。","江南水阔朝云多，草长沙輭无网罗。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟","江","秋","江南"],"cats":{"抒情":["思乡"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.487},{"uid":"c1ebbb06-55b7-40d1-8f23-63491faa6fa7","title":"送崔侍御入朝","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十年犹执宪，万里独归春。","旧国逢芳草，青云见故人。","潘郎今发白，陶令本家贫。","相送临京口，停桡泪满巾。"],"theme":"送别","theme2":[],"style":"豪放","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["春天"]},"theme_conf":1.0},{"uid":"dbde2fca-6bfe-4f14-bf89-5df0f900b277","title":"鼓吹曲辞 鼓吹铙歌 吐谷浑","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吐谷浑盛彊，背西海以夸。","岁侵扰我疆，退匿险且遐。","帝谓神武师，往征靖皇家。","烈烈斾其旗，熊虎杂龙蛇。","王旅千万人，衔枚默无哗。","束刃逾山徼，张翼纵漠沙。","一举刈膻腥，尸骸积如麻。","除恶务本根，况敢遗萌芽。","洋洋西海水，威命穷天涯。","系虏来王都，犒乐穷休嘉。","登高望还师，竟野如春华。","行者靡不归，亲戚讙要遮。","凯旋献清庙，万国思无邪。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["塞外","春","重阳"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.522},{"uid":"0cc77a07-c1db-4875-9e12-9574e51aab15","title":"荆南兵马使太常卿赵公大食刀歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["太常楼船声嗷嘈，问兵刮寇趋下牢。","牧出令奔飞百艘，猛蛟突兽纷腾逃。","白帝寒城驻锦袍，玄冬示我胡国刀。","壮士短衣头虎毛，凭轩拔鞘天为高。","翻风转日木怒号，冰翼雪澹伤哀猱。","镌错碧甖䴙鹈膏，铓锷已莹虚秋涛。","鬼物撇捩辞坑壕，苍水使者扪赤条。","龙伯国人罢钓鼇，芮公回首颜色劳。","分阃救世用贤豪，赵公玉立高歌起。","揽环结佩相终始，万岁持之护天子。","得君乱丝与君理，蜀江如线如针水。","荆岑弹丸心未已，贼臣恶子休干纪。","魑魅魍魉徒为耳，妖腰乱领敢欣喜。","用之不高亦不庳，不似长劒须天倚。","吁嗟光禄英雄弭，大食宝刀聊可比。","丹青宛转麒麟里，光芒六合无泥滓。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨","幽峭"],"mood":"慷慨","mood2":[],"scene":["冬","楼"],"cats":{"四季":["冬天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.805},{"uid":"26a0266d-313c-4911-b629-2418556d1b03","title":"洗兵马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["中兴诸将收山东，捷书日报清昼同。","河广传闻一苇过，胡危命在破竹中。","祗残邺城不日得，独任朔方无限功。","京师皆骑汗血马，回纥喂肉葡萄宫。","已喜皇威清海岱，常思仙仗过崆峒。","三年笛里关山月，万国兵前草木风。","成王功大心转小，郭相谋深古来少。","司徒清鉴悬明镜，尚书气与秋天杳。","二三豪俊为时出，整顿乾坤济时了。","东走无复忆鲈鱼，南飞觉有安巢鸟。","青春复随冠冕入，紫禁正耐烟花绕。","鹤禁通霄凤辇备，鸡鸣问寝龙楼晓。","攀龙附凤势莫当，天下尽化为侯王。","汝等岂知蒙帝力，时来不得夸身强。","关中既留萧丞相，幕下复用张子房。","张公一生江海客，身长九尺须眉苍。","征起适遇风云会，扶颠始知筹策良。","青袍白马更何有，后汉今周喜再昌。","寸地尺天皆入贡，奇祥异瑞争来送。","不知何国致白环，复道诸山得银瓮。","隐士休歌紫芝曲，词人解撰河清颂。","田家望望惜雨干，布谷处处催春种。","淇上健儿归莫嬾，城南思妇愁多梦。","安得壮士挽天河，净洗甲兵长不用。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["旷达","清新"],"mood":"欢愉","mood2":["相思"],"scene":["鸟","春"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["青春","战争"],"动物":["写马"]},"theme_conf":0.43},{"uid":"a2b4fe60-9809-422d-afa7-143a2088f045","title":"阙题","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["道由白云尽，春与青溪长。","时有落花至，远随流水香。","闲门向山路，深柳读书堂。","幽映每白日，清辉照衣裳。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":0.406},{"uid":"edc07822-6fcc-44f0-836f-956c0ad2d4e8","title":"进秋隼","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岂悟因罗者，迎霜献紫微。","夕阳分素臆，秋色上花衣。","举翅云天近，回眸燕雀稀。","应随明主意，百中有光辉。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["哲理"]},"theme_conf":1.0},{"uid":"cp7169fdcc1834b8","title":"望湘人","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["厌莺声到枕，花气动帘，醉魂愁梦相半。","被惜馀薰，带惊剩眼。","几许伤春春晚。","泪竹痕鲜，佩兰香老，湘天浓暖。","记小江、风月佳时，屡约非烟游伴。","须信鸾弦易断。","奈云和再鼓，曲终人远。","认罗袜无踪，旧处弄波清浅。","青翰棹舣，白苹洲畔。","尽木临皋飞观。","不解寄、一字相思，幸有归来双燕。"],"theme":"爱情相思","theme2":["送别"],"style":"沉郁","style2":["婉约","冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["春","江","鸟","花"],"cats":{"抒情":["爱情","思念","伤感"],"四季":["春天"]},"theme_conf":0.556},{"uid":"d9aa05ba-6c7d-4ebd-9401-5edd412f9b93","title":"轻薄行","author":"齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["玉鞭金镫骅骝蹄，横眉吐气如虹霓。","五陵春暖芳草齐，笙歌到处花成泥。","日沉月上且鬬鸡，醉来莫问天高低。","伯阳道德何唾咦，仲尼礼乐徒卑栖。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","月","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.65},{"uid":"71999aa1-55dd-4449-81b0-41f04686bf2e","title":"听蜀僧濬弹琴","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蜀僧抱绿绮，西下峨眉峰。","为我一挥手，如听万壑松。","客心洗流水，余响入霜钟。","不觉碧山暮，秋云暗几重。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","秋"],"cats":{"四季":["秋天"]},"theme_conf":0.538},{"uid":"11626f58-4066-4818-b22d-d23bd4b25a9b","title":"相和歌辞 采菱曲","author":"储光羲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浊水菱叶肥，清水菱叶鲜。","义不游浊水，志士多苦言。","潮没具区薮，潦深云梦田。","朝随北风去，暮逐南风还。","浦口多渔家，相与邀我船。","饭稻以终日，羹莼将永年。","方冬水物穷，又欲休山樊。","尽室相随从，所贵无忧患。"],"theme":"山水田园","theme2":[],"style":"旷达","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","舟"],"cats":{"四季":["冬天"]},"theme_conf":0.796},{"uid":"99c57fb0-4d0e-47f6-95a6-ef1769ddb878","title":"宫词三十首 二十一","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["迥出芙蓉阁上头，九天悬处正当秋。","年年七夕晴光里，宫女穿针尽上楼。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","七夕","秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.771},{"uid":"6340ef19-35e2-4194-96a9-3ee0a667905b","title":"送魏万之京","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["朝闻游子唱离歌，昨夜微霜初渡河。","鸿鴈不堪愁里听，云山况是客中过。","关城树色催寒近，御苑砧声向晚多。","莫见长安行乐处，空令岁月易蹉跎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["秋","夜","月","山"],"cats":{"抒情":["伤感"],"四季":["秋天"]},"theme_conf":0.714},{"uid":"7c93c162-d424-4d91-b71b-7c9b81713b8c","title":"赤壁","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深鏁二乔。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.739},{"uid":"b458468f-a5c3-44a5-aa38-29e8ab8f3533","title":"酬别薛三蔡大留简韩十四主簿","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迢递辞京华，辛勤异乡县。","登高俯沧海，廻首泪如霰。","同人久离别，失路还相见。","薛侯怀直道，德业应时选。","蔡子负清才，当年擢宾荐。","韩公有奇节，词赋凌群彦。","读书嵩岑间，作吏沧海甸。","伊余寡栖托，感激多愠见。","纵诞非尔情，飘沦任疵贱。","忽枉琼瑶作，乃深平生眷。","始谓吾道存，终嗟客游倦。","归心无昼夜，别事除言宴。","复值凉风时，苍茫夏云变。"],"theme":"送别","theme2":["羁旅思乡"],"style":"雄浑","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["雪","夏","江","重阳"],"cats":{"抒情":["离别","思乡"],"四季":["夏天"],"人生":["读书"],"节日":["重阳节"]},"theme_conf":0.63},{"uid":"b9521e2b-963e-4d90-acf3-d87c2a135071","title":"古意呈补阙乔知之","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["卢家少妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催木叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁谓含愁独不见，更教明月照流黄。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","秋","夜"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.594},{"uid":"cp6ed8f2981cfc67","title":"霜叶飞","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["断烟离绪。","关心事，斜阳红隐霜树。","半壶秋水荐黄花，香西风雨。","纵玉勒、轻飞迅羽。","凄凉谁吊荒台古。","记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。","聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。","小蟾斜影转东篱，夜冷残蛩语。","早白发、缘愁万缕。","惊飙从卷乌纱去。","漫细将、茱萸看，但约明年，翠微高处。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"],"植物":["叶子"]},"theme_conf":0.78},{"uid":"cp1018b391d4cfee","title":"六丑","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["正单衣试酒，恨客里、光阴虚掷。","愿春暂留，春归如过翼。","一去无迹。","为问花何在，夜来风雨，葬楚宫倾国。","钗钿堕处遗香泽。","乱点桃蹊，轻翻柳陌。","多情为谁追惜。","但蜂媒蝶使，时叩窗隔。","东园岑寂。","渐蒙笼暗碧。","静绕珍丛底，成叹息。","长条故惹行客。","似牵衣待话，别情无极。","残英小、强簪巾帻。","终不似一朵，钗头颤袅，向人侧。","漂流处、莫趁潮汐。","恐断红、尚有相思字，何由见得。"],"theme":"咏物","theme2":["爱情相思","羁旅思乡","送别"],"style":"沉郁","style2":["冲淡","婉约"],"mood":"相思","mood2":["孤寂"],"scene":["雨","花","春","酒"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.93},{"uid":"051a325b-0ad3-42b1-89dc-8c9d09cf45d5","title":"相和歌辞 苦寒行","author":"刘驾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["严寒动八荒，莿莿无休时。","阳乌不自暖，雪压扶桑枝。","岁暮寒益壮，青春安得归。","朔雁到南海，越禽何处飞？","谁言贫士叹，不为身无衣。"],"theme":"民生疾苦","theme2":["羁旅思乡"],"style":"豪放","style2":["幽峭"],"mood":"愁怨","mood2":["孤寂","慷慨"],"scene":["雪","春","鸟","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.51},{"uid":"1b9d00c7-3128-4bee-b338-2d354d51c002","title":"和武相公中秋锦楼玩月得苍字","author":"张正一","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高秋今夜月，皓色正苍苍。","远水澄如练，孤鸿逈带霜。","旅人方积思，繁宿稍沈光。","朱槛叨陪赏，尤宜清漏长。"],"theme":"应制干谒","theme2":[],"style":"雄浑","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["秋","中秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"6b4fc113-fbd5-44ef-9815-8a084b6f7a0b","title":"陈使君山庄","author":"牟融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["新卜幽居地自偏，士林争羡使君贤。","数椽潇洒临溪屋，十亩膏腴附郭田。","流水断桥芳草路，淡烟疎雨落花天。","秋成准拟重来此，沈醉何妨一榻眠。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":["山","花","秋","雨"],"cats":{"四季":["秋天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.444},{"uid":"ac3757d4-033b-4c69-baf8-8558055d42d4","title":"陈后宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玄武开新苑，龙舟䜩幸频。","渚莲参法驾，沙鸟犯句陈。","寿献金茎露，歌翻玉树尘。","夜来江令醉，别诏宿临春。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["江","端午","舟","春","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["端午节"]},"theme_conf":0.637},{"uid":"2076be94-1be6-4df6-b8a4-4bd7a755d247","title":"杂曲歌辞 鸣雁行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["胡雁鸣，辞燕山，昨发委羽朝度关。","一一衔芦枝，南飞散落天地间。","连行接翼往复还，客居烟波寄湘吴。","凌霜触雪毛体枯，畏逢矰缴惊相呼。"],"theme":"咏物","theme2":["咏物"],"style":"旷达","style2":[],"mood":"相思","mood2":[],"scene":["鸟"],"cats":{"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.85},{"uid":"cp3132bc43c19b92","title":"摸鱼儿","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怎知他、春归何处，相逢且尽尊酒。","少年袅袅天涯恨，长结西湖烟柳。","休回首。","但细雨断桥，憔悴人归后。","东风似旧。","问前度桃花，刘郎能记，花复认郎否。","君且住，草草留君翦韭。","前宵更恁时候。","深杯欲共歌声滑，翻湿春衫半袖。","空眉皱。","看白发尊前，已似人人有。","临分把手。","叹一笑论文，清狂顾曲，此会几时又。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["旷达","豪放"],"mood":"愁怨","mood2":[],"scene":["春","雨","酒","夜","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["西湖"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"1558a170-9f05-4a1a-b907-b9f6061f4772","title":"饯济阴梁明府各探一物得荷叶","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["荷叶生幽渚，芳华信在兹。","朝朝空此地，采采欲因谁。","但恐星霜改，还将蒲稗衰。","怀君美人别，聊以赠心期。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人物":["女子"],"人生":["青春"],"植物":["荷花","叶子"]},"theme_conf":0.799},{"uid":"9391ef33-933e-452d-8fc3-5c6ccfe8eb12","title":"和崔中丞中秋月","author":"张南史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋夜月偏明，西楼独有情。","千家看露湿，万里觉天清。","映水金波动，衔山桂树生。","不知飞鹊意，何用此时惊。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["月","中秋","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"24eec460-2dda-41a7-8104-e590096f3e03","title":"相和歌辞 长歌行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["桃李得日开，荣华照当年。","东风动百物，草木尽欲言。","枯枝无丑叶，涸水吐清泉。","大力运天地，羲和无停鞭。","功名不早著，竹帛将何宣？","桃李务青春，谁能贯白日。","富贵与神仙，蹉跎成两失。","金石犹销铄，风霜无久质。","畏落日月后，强欢歌与酒。","秋霜不惜人，倏忽侵蒲柳。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"天气":["太阳"],"人生":["青春"]},"theme_conf":1.0},{"uid":"37cd5393-d24a-426a-9c53-a774251bd650","title":"蒙山作","author":"萧颖士","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东蒙镇海沂，合沓余百里。","清秋净氛霭，崖崿隐天起。","于役劳往还，息徒暂攀跻。","将穷绝迹处，偶得冥心理。","云气杂虹霓，松声乱风水。","微明绿林际，杳窱丹洞里。","仙鸟时可闻，羽人邈难视。","此焉多深邃，贤达昔所止。","子尚捐俗纷，季随蹑遐轨。","蕴真道弥旷，怀古情未已。","白鹿凡几游，黄精复奚似。","顾予尚牵缠，家业重书史。","少学务从师，壮年贵趋仕。","方驰桂林誉，未暇桃源美。","岁暮期再寻，幽哉羡门子。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"清新","style2":["旷达"],"mood":"慷慨","mood2":[],"scene":["山","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["彩虹"]},"theme_conf":0.435},{"uid":"db2a09c3-7311-42be-84ba-afe3b8063943","title":"解秋十首 五","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新月才到地，轻河如泛云。","萤飞高下火，树影参差文。","露簟有微润，清香时暗焚。","夜闲心寂默，洞庭无垢氛。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","江","元宵"],"cats":{"四季":["秋天"],"节日":["元宵节"]},"theme_conf":0.76},{"uid":"8d2bd14f-e18f-4296-a4f0-972b09a7928a","title":"初夏","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一朝春夏改，隔夜鸟花迁。","阴阳深浅叶，晓夕重轻烟。","哢鸎犹响殿，横丝正网天。","珮高兰影接，绶细草纹连。","碧鳞惊櫂侧，玄燕舞檐前。","何必汾阳处，始复有山泉。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":1.0},{"uid":"30cd14b3-98fd-4a64-b57f-6d2cc05f52d9","title":"暮春喜雨诗","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["风云喜际会，雷雨遂流滋。","荐币虚陈礼，动天实精思。","渐侵九夏节，复在三春时。","霡霂垂朱阙，飘飖入绿墀。","郊坰既沾足，黍稷有丰期。","百辟同康乐，万方伫雍熙。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨"],"cats":{"四季":["春天"],"天气":["写雨"]},"theme_conf":0.66},{"uid":"d1647555-1944-4bdb-9515-7ab825db789b","title":"奉和武相公中秋锦楼玩月得来字","author":"徐放","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉露中秋夜，金波碧落开。","鹊惊初泛滥，鸿思共裴回。","远月清光徧，高空爽气来。","此时陪永望，更得上燕台。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["中秋","秋","月"],"cats":{"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"c3c25268-b08b-4126-8e77-141cf5bbeaad","title":"茂陵村行赠何兆","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春天黄鸟啭，野迳白云闲。","解带依芳草，支颐想故山。","人行九州路，树老五陵间。","谁道临邛远，相如自忆还。"],"theme":"寄赠酬答","theme2":["山水田园","咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","山"],"cats":{"抒情":["思念","怀古"],"四季":["春天"],"生活":["乡村"]},"theme_conf":0.64},{"uid":"57239e87-5c37-4c28-b253-a7bc96649ea4","title":"横吹曲辞 出塞","author":"张易之","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["侠客重恩光，骢马饰金装。","瞥闻传羽檄，驰突救边荒。","转战磨筓地，横行戴斗乡。","将军占太白，小妇怨流黄。","騕褭青丝骑，娉婷红粉妆。","一春莺度曲，八月雁成行。","谁堪坐秋思，罗袖拂空床。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","春","鸟"],"cats":{"四季":["春天"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.728},{"uid":"cp29e160902dce30","title":"六丑","author":"彭元逊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["似东风老大，那复有、当时风气。","有情不收，江山身是寄。","浩荡何世。","但忆临官道，暂来不住，便出门千里。","痴心指望回风坠。","扇底相逢，钗头微缀。","他家万条千缕，解遮亭障驿，不隔江水。","瓜洲曾舣，等行人岁岁。","日下长秋，城乌夜起。","帐庐好在春睡。","共飞归湖上，草青无地。","雨、春心如腻。","欲待化、丰乐楼前，青门都废。","何人念、流落无几。","点点抟作，雪绵松润，为君泪。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"婉约","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["江","春","楼"],"cats":{"抒情":["思念","思乡"],"四季":["春天"]},"theme_conf":0.415},{"uid":"1575c835-1241-4d7b-99dc-6d700549ac65","title":"渭城曲","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["渭城朝雨浥轻尘，客舍青青杨柳春。","劝君更尽一杯酒，西出阳关无故人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","春"],"cats":{"抒情":["友情"],"四季":["春天"]},"theme_conf":0.589},{"uid":"1bcd81fb-6fb5-4994-b9ec-6baf5bbd4142","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朔风飘胡雁，惨澹带砂砾。","长林何萧萧，秋草萋更碧。","北里富熏天，高楼夜吹笛。","焉知南邻客，九月犹𫄨绤。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["夜","秋","楼","月","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.551},{"uid":"af29ed64-419d-4eeb-803a-8466d45a7a2b","title":"昼梦","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["二月饶睡昏昏然，不独夜短昼分眠。","桃花气暖眼自醉，春渚日落梦相牵。","故乡门巷荆棘底，中原君臣豺虎边。","安得务农息战鬬，普天无吏横索钱。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["春","月","夜","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.658},{"uid":"b7dd27c6-0626-42da-a842-380334fadf9a","title":"寄上礼部李侍郎","author":"崔峒","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吴楚相逢处，江湖共泛时。","任风舟去远，待月酒行迟。","白发常同欢，青云本要期。","贵来君却少，秋至老偏悲。","玉佩明朝盛，苍苔陋巷滋。","追寻恨无路，唯有梦相思。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["江","舟","酒","秋","月"],"cats":{"抒情":["思念"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"56bec3c2-9c0c-4d40-9750-2e28bdc9a20e","title":"送綦毋潜落第还乡","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣代无隐者，英灵尽来归。","遂令东山客，不得顾采薇。","既至君门远，孰云吾道非。","江淮度寒食，京洛缝春衣。","置酒临长道，同心与我违。","行当浮桂櫂，未几拂荆扉。","远树带行客，孤村当落晖。","吾谋适不用，勿谓知音稀。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","春","酒"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.443},{"uid":"d2d9fa8e-5872-480a-ad45-b1b62af3619a","title":"题洛苑梧叶上","author":"天宝宫人","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["旧宠悲秋扇，新恩寄早春。","聊题一片叶，将寄接流人。"],"theme":"咏物","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["秋","春"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["叶子"]},"theme_conf":0.47},{"uid":"0d8d840d-1f94-44da-9b52-18a01cf8ed82","title":"下第日书情寄上叔父","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["微才空觉滞京师，末学曾为叔父知。","雪里题诗偏见赏，林间饮酒独令随。","游客尽伤春色老，贫居还惜暮阴移。","欲归江海寻山去，愿报何人得桂枝。"],"theme":"寄赠酬答","theme2":["亲情"],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["雪","酒","春","江","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.8},{"uid":"9b8940d5-7966-47ab-bbf9-55efadf169b3","title":"观云篇","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兴云感阴气，疾足如见机。","晴来意态行，有若功成归。","葱茏含晚景，洁白凝秋晖。","夜深度银汉，漠漠仙人衣。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","秋","七夕","夜"],"cats":{"四季":["秋天"],"天气":["写云"],"节日":["七夕节"]},"theme_conf":0.65},{"uid":"92dd65da-8301-4c83-b8f3-986b6095c481","title":"征怨","author":"柳中庸","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["岁岁金河复玉关，朝朝马策与刀环。","三春白雪归青冢，万里黄河遶黑山。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["江","雪","春","山"],"cats":{"四季":["春天"],"山水":["黄河"]},"theme_conf":0.71},{"uid":"e2595ed8-1345-4194-86f6-ec71bd785110","title":"同诸公登慈恩寺塔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高标跨苍天，烈风无时休。","自非旷士怀，登兹翻百忧。","方知象教力，足可追冥搜。","仰穿龙蛇窟，始出枝撑幽。","七星在北户，河汉声西流。","羲和鞭白日，少昊行清秋。","秦山忽破碎，泾渭不可求。","俯视但一气，焉能辨皇州。","回首叫虞舜，苍梧云正愁。","惜哉瑶池饮，日宴昆仑丘。","黄鹄去不息，哀鸣何所投。","君看随阳雁，各有稻粱谋。"],"theme":"咏史怀古","theme2":["哲理悟道","咏史怀古","游仙梦幻"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.6},{"uid":"0a988f56-b22d-48cb-94f1-fc75e2532eab","title":"长相思","author":"刘复","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长相思，在桂林，苍梧山远潇湘深。","秋堂零泪倚金瑟，朱颜摇落随光阴。","长宵嘹唳鸿命侣，河汉苍苍隔牛女。","宁知一水不可渡，况复万山修且阻。","彩丝织绮文双鸳，昔时赠君君可怜。","何言一去瓶落井，流尘歇灭金炉前。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约","雄浑"],"mood":"相思","mood2":[],"scene":["七夕","秋","山"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人生":["时光"],"节日":["七夕节"]},"theme_conf":0.705},{"uid":"cb168b3b-d104-4df7-9868-1e1225ddb941","title":"春晓","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["春眠不觉晓，处处闻啼鸟。","夜来风雨声，花落知多少。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"]},"theme_conf":1.0},{"uid":"cp3e738af0f919e6","title":"甘州・八声甘州","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["记玉关、踏雪事清游。","寒气脆貂裘。","傍枯林古道，长河饮马，此意悠悠。","短梦依然江表，老泪洒西州。","一字无题处，落叶都愁。","载取白云归去，问谁留楚佩，弄影中洲。","折芦花赠远，零落一身秋。","向寻常野桥流水，待招来、不是旧沙鸥。","空怀感，有斜阳处，却怕登楼。"],"theme":"山水田园","theme2":["羁旅思乡","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"生活":["写桥"]},"theme_conf":0.358},{"uid":"cp2a56a9bb8978f0","title":"三台","author":"万俟咏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["见梨花初带夜月，海棠半含朝雨。","内苑春、不禁过青门，御沟涨、潜通南浦。","东风静、细柳垂金缕。","望凤阙、非烟非雾。","好时代、朝野多欢，遍九陌、太平箫鼓。","乍莺儿百啭断续，燕子飞来飞去。","近绿水、台榭映秋千，斗草聚、双双游女。","饧香更、酒冷踏青路。","会暗识、夭桃朱户。","向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。","正轻寒轻暖漏永，半阴半晴云暮。","禁火天、已是试新妆，岁华到、三分佳处。","清明看、汉宫传蜡炬。","散翠烟、飞入槐府。","敛兵卫、阊阖门开，住传宣、又还休务。"],"theme":"节令风俗","theme2":["节令风俗","送别"],"style":"清新","style2":["婉约","绮丽"],"mood":"欢愉","mood2":[],"scene":["清明","春","夜","酒","楼"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.86},{"uid":"12d952ff-d24d-4920-86ac-54e2f1404375","title":"贞元末东院尝接事今西川武相公于兹三周谬领中宪徘徊厅宇多获文篇夏日即事因寄四韵","author":"窦群","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["重轩深似谷，列柏镇含烟。","境绝苍蝇到，风生白雪前。","弹冠惊迹近，专席感恩偏。","霄汉朝来下，油幢路几千。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","园林"],"cats":{"抒情":["感恩"],"四季":["夏天"]},"theme_conf":0.9},{"uid":"57444b76-3bd5-4667-8998-b0888da88a61","title":"送叶秀才","author":"王初","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["快骑璁珑刻玉羁，河梁返照上征衣。","层冰春近蟠龙起，九泽云闲独鹤飞。","行想北山清梦断，重游西洛故人稀。","汉庭狗监深知己，有日前驱负弩归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["春","冬","山","园林"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.649},{"uid":"56f2dfa5-3d19-4b8f-a6da-8323290985ba","title":"杂诗","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["百花结成子，春物舍我去。","流年惜不得，独坐空闺暮。","心自有所待，甘为物华悮。","未必千黄金，买得一人顾。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"dfb61907-f39f-4797-8ee8-4086c79317a9","title":"伤进士谢庭皓","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["献书犹未达明君，何事先游岱岳云。","惟有春风护冤魄，与生青草盖孤坟。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春"],"cats":{"抒情":["伤感","孤独","悼亡","感恩"],"四季":["春天"],"山水":["泰山"]},"theme_conf":0.98},{"uid":"fabc073e-fb05-46e9-92c1-398d7c47c759","title":"阳城驿","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["商有阳城驿，名同阳道州。","阳公没已久，感我泪交流。","昔公孝父母，行与曾闵俦。","既孤善兄弟，兄弟和且柔。","一夕不相见，若怀三岁忧。","遂誓不婚娶，没齿同衾裯。","妹夫死他县，遗骨无人收。","公令季弟往，公与仲弟留。","相别竟不得，三人同远游。","共负他乡骨，归来藏故丘。","栖迟居夏邑，邑人无苟媮。","里中竞长短，来问劣与优。","官刑一朝耻，公短终身羞。","公亦不遗布，人自不盗牛。","问公何能尔，忠信先自修。","发言当道理，不顾党与讐。","声香渐翕习，冠盖若云浮。","少者从公学，老者从公游。","往来相告报，县尹与公侯。","名落公卿口，涌如波荐舟。","天子得闻之，书下再三求。","书中愿一见，不异旱地虬。","何以持为聘，束帛藉琳球。","何以持为御，驷马驾安辀。","公方伯夷操，事殷不事周。","我实唐士庶，食唐之田畴。","我闻天子忆，安敢专自由。","来为谏大夫，朝夕侍冕旒。","希夷惇薄俗，密勿献良筹。","神医不言术，人瘼曾暗瘳。","月请谏官俸，诸弟相对谋。","皆曰亲戚外，酒散目前愁。","公云不有尔，安得此嘉猷。","施余尽酤酒，客来相献酬。","日旰不谋食，春深仍弊裘。","人心良戚戚，我乐独由由。","贞元岁云暮，朝有曲如钩。","风波势奔蹙，日月光绸缪。","齿牙属为猾，禾黍暗生蟊。","岂无司言者，肉食吞其喉。","岂无司搏者，利柄扼其鞲。","鼻复势气塞，不得辩薰莸。","公虽未显谏，惴惴如患瘤。","飞章八九上，皆若珠暗投。","炎炎日将炽，积燎无人抽。","公乃帅其属，决谏同报仇。","延英殿门外，叩合仍叩头。","且曰事不止，臣谏誓不休。","上知不可遏，命以美语酬。","降官司成署，俾之为赘疣。","奸心不快活，击刺砺戈矛。","终为道州去，天道竟悠悠。","遂令不言者，反以言为訧。","喉舌坐成木，鹰鹯化为鸠。","避权如避虎，冠豸如冠猴。","平生附我者，诗人称好逑。","私来一执手，恐若坠诸沟。","送我不出户，决我不回眸。","唯有太学生，各具粮与糇。","咸言公去矣，我亦去荒陬。","公与诸生别，步步驻行驺。","有生不可诀，行行过闽瓯。","为师得如此，得为贤者不。","道州闻公来，鼓舞歌且讴。","昔公居夏邑，狎人如狎鸥。","况自为刺史，岂复援鼓桴。","滋章一时罢，教化天下遒。","炎瘴不得老，英华忽已秋。","有鸟哭杨震，无儿悲邓攸。","唯余门弟子，列树松与楸。","今来过此驿，若吊汨罗洲。","祠曹讳羊祜，此驿何不侔。","我愿避公讳，名为避贤邮。","此名有深意，蔽贤天所尤。","吾闻玄元教，日月冥九幽。","幽阴蔽翳者，永为幽翳囚。"],"theme":"咏史怀古","theme2":["送别","边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["夏","月"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["夏天"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"a7318ace-183f-44e8-9704-3fceabe908be","title":"人日寄杜二拾遗","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["人日题诗寄草堂，遥怜故人思故乡。","柳条弄色不忍见，梅花满枝空断肠。","身在远藩无所预，心怀百忧复千虑。","今年人日空相忆，明年人日知何处。","一卧东山三十春，岂知书劒老风尘。","龙钟还忝二千石，愧尔东西南北人。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["友情","思念","思乡","伤感"],"四季":["春天"],"天气":["太阳"]},"theme_conf":0.94},{"uid":"cpc4da66c71f7c81","title":"三姝媚","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湖山经醉惯。","溃春衫、啼痕酒痕无限。","又客长安，叹断襟零袂，尘谁浣。","紫曲门荒，沿败井、风摇青蔓。","对语东邻，犹是曾巢，谢堂双燕。","春梦人间须断。","但怪得、当年梦缘能短。","绣屋秦筝，傍海棠偏爱，夜深开宴。","舞歇歌沈，花未减、红颜先变。","伫久河桥欲去，斜阳泪满。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":[],"scene":["酒","春","花"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"07bec374-ff61-4d05-842c-c57c25f1d888","title":"陪杜侍御游湘西两寺独宿有题一首因献杨常侍","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长沙千里平，胜地犹在险。","况当江阔处，斗起势匪渐。","深林高玲珑，青山上琬琰。","路穷台殿辟，佛事焕且俨。","剖竹走泉源，开廊架崖广。","是时秋之残，暑气尚未歛。","群行忘后先，朋息弃拘检。","客堂喜空凉，华榻有清簟。","涧蔬煮蒿芹，水果剥菱芡。","伊余夙所慕，陪赏亦云忝。","幸逢车马归，独宿门不掩。","山楼黑无月，渔火灿星点。","夜风一何喧，杉桧屡磨飐。","犹疑在波涛，怵惕梦成魇。","静思屈原沈，远忆贾谊贬。","椒兰争妬忌，绛灌共谗谄。","谁令悲生肠，坐使泪盈脸。","翻飞乏羽翼，指摘困瑕玷。","珥貂藩维重，政化类分陕。","礼贤道何优，奉己事苦俭。","大厦栋方隆，巨川檝行剡。","经营诚少暇，游宴固已歉。","旅程愧淹留，徂岁嗟荏苒。","平生每多感，柔翰遇频染。","展转岭猿鸣，曙灯青睒睒。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["欢愉"],"scene":["山","楼","夜","端午","夏"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天"],"节日":["端午节"]},"theme_conf":0.433},{"uid":"306c2503-eff5-418b-873e-c72596a676bd","title":"杂曲歌辞 春江曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["春江无云潮水平，蒲心出水凫雏鸣。","长干夫壻爱远行，自染春衣缝已成。","妾身生长金陵侧，去年随夫住江北。","春来未到父母家，舟小风多渡不得。","欲辞舅姑先问人，私向江头祭水神。"],"theme":"闺情宫怨","theme2":["亲情","山水田园"],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["江","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.85},{"uid":"d3ab98da-082d-4117-98e1-79bc8c2635ed","title":"赋得樱桃","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["华林满芳景，洛阳徧阳春。","朱颜含远日，翠色影长津。","乔柯啭娇鸟，低枝映美人。","昔作园中实，今来席上珍。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"1fc07309-faba-489d-924d-9c46e950a35c","title":"裴端公使院赋得隔帘见春雨","author":"包何","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["细雨未成霖，垂帘但觉阴。","唯看上砌湿，不遣入簷深。","度隟沾霜简，因风润绮琴。","须移户外屦，簷溜夜相侵。"],"theme":"咏物","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.621},{"uid":"b0d04448-935e-4e7a-ad7e-9a69c31b0ad7","title":"阆水歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["嘉陵江色何所似，石黛碧玉相因依。","正怜日破浪花出，更复春从沙际归。","巴童荡桨攲侧过，水鸡衔鱼来去飞。","阆中胜事可肠断，阆州城南天下稀。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["春","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["励志"]},"theme_conf":1.0},{"uid":"c0b9984d-eb82-4994-9aeb-dd578cf8b3c1","title":"和钱员外早冬玩禁中新菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禁署寒气迟，孟冬菊初坼。","新黄间繁绿，烂若金照碧。","仙郎小隐日，心似陶彭泽。","秋怜潭上看，日惯篱边摘。","今来此地赏，野意潜自适。","金马门内花，玉山峰下客。","寒芳引清句，吟玩烟景夕。","赐酒色偏宜，握兰香不敌。","凄凄百卉死，岁晚冰霜积。","唯有此花开，殷勤助君惜。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["冬"],"cats":{"四季":["秋天","冬天"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"974914ee-1fc0-4952-a863-820bad2e4065","title":"为有","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["为有云屏无限娇，凤城寒尽怕春宵。","无端嫁得金龟壻，辜负香衾事早朝。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["春","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.7},{"uid":"b795db08-a132-4d2c-9925-654193077602","title":"喜弟淑再至为长歌","author":"李渤","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["前年别时秋九月，白露吹霜金吹烈。","离鸿一别影初分，泪袖双挥心哽咽。","别来几度得音书，南岳知□□□□。","庐山峨峨倚天碧，捧排空崖千万尺。","社牓长题高士名，食堂每记云山迹。","我本开云此山住，偶为名利相萦误。","自负心机四十年，羞闻社客山中篇。","忧时魂梦忆归路，觉来疑在林中眠。","昨日亭前乌鹊喜，果得今朝尔来此。","吾吟行路五十篇，尽说江南数千里。","自怜兄弟今五人，共萦儒素家尚贫。","虽然廪饩各不一，就中总免拘常伦。","长兄年少曾落托，拔劒沙场随卫霍。","口里虽谭周孔文，怀中不舍孙吴略。","次兄一生能苦节，夏聚流萤冬映雪。","非论疾恶志如霜，更觉临泉心似铁。","第三之兄更奇异，昂昂独负青云志。","下看金玉不如泥，肯道王侯身可贵。","却愁清逸不干时，高踪大器无人知。","倘逢感激许然诺，必能万古留清规。","念尔年来方二十，夙夜孜孜能独立。","卷中笔落星汉摇，洞里丹灵鬼神泣。","嗟余流浪心最狂，十年学劒逢时康。","心中不解事拘束，世间谈笑多相妨。","广海青山殊未足，逢著高楼还醉宿。","朝走安公枥上驹，暮伦陶令篱边菊。","近来诗思殊无况，苦被时流不相放。","云腾浪走势未衰，鹤膝蜂腰岂能障。","送尔为文殊不识，贵从一一传胷臆。","若到湖南见紫霄，会须待我同攀陟。"],"theme":"亲情","theme2":["山水田园","边塞征战"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["山","江南","秋","冬","雪","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["秋天","冬天"],"山水":["庐山"],"人生":["励志","梦想","战争"],"生活":["边塞"]},"theme_conf":0.95},{"uid":"5aee2c13-785a-4735-8a13-069d126a37f6","title":"相和歌辞 采莲曲二首 一","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["弄舟朅来南塘水，荷叶映身摘莲子。","暑衣清净鸳鸯喜，作浪舞花惊不起。","殷勤护惜纤纤指，水菱初熟多新刺。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","舟"],"cats":{"抒情":["爱情"],"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.527},{"uid":"e502aa21-de65-4abd-99ab-ba4773dfbf7e","title":"荅李滁州题庭前石竹花见寄","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["殷疑曙霞染，巧类匣刀裁。","不怕南风热，能迎小暑开。","游蜂怜色好，思妇感年催。","览赠添离恨，愁肠日几廻。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["园林","花","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"植物":["竹子"]},"theme_conf":0.76},{"uid":"db2e0bcc-0147-45e2-ad79-3e571534a6b9","title":"春来曲","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["春欲来，每日望春门早开。","黄衫白马带尘土，逢著探春人却回。","御堤内园晓过急，九衢大宅家家入。","青帝少女染桃花，露妆初出红犹湿。","光风暾暾蝶宛宛，遶树气匝枝柯软。","可怜寒食街中郎，早起著得单衣裳。","少年即见春好处，似我白头无好树。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.78},{"uid":"037a76e5-2949-43de-850c-5bf8f5010ffd","title":"郊庙歌辞 享龙池乐章 第五章","author":"姜皎","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["龙池初出此龙山，常经此地谒龙颜。","日日芙蓉生夏水，年年杨柳变春湾。","尧坛宝匣余烟雾，舜海渔舟尚往还。","愿似飘飖五云影，从来从去九天间。"],"theme":"山水田园","theme2":["应制干谒"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["园林","夏"],"cats":{"四季":["夏天"]},"theme_conf":0.527},{"uid":"d5543626-4658-4fca-bba0-b768fdcba4d9","title":"秋夜安国观闻笙","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["织女分明银汉秋，桂枝梧叶共飕飗。","月露满庭人寂寂，霓裳一曲在高楼。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","七夕","夜"],"cats":{"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"e2f6d3a1-da3e-4651-a066-b9cb1c339757","title":"赋得亚父碎玉斗","author":"裴次元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雄谋竟不决，宝玉将何爱。","倏尔霜刃挥，飒然春冰碎。","飞光动旗帜，散响惊环珮。","霜浓绣帐前，星流锦筵内。","图王业已失，为虏言空悔。","独有青史中，英风冠千载。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春","秋","冬"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人物":["父亲"]},"theme_conf":0.524},{"uid":"cfb724d3-b6ef-4c81-a5c7-ef90595445ad","title":"相和歌辞 陇西行","author":"耿[𣲗]","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雪下阳关路，人稀陇戍头。","封狐犹未翦，边将岂无羞。","白草三冬色，黄云万里愁。","因思李都尉，毕竟不封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"],"生活":["边塞"]},"theme_conf":0.737},{"uid":"01cc3e31-e2e4-4598-915f-36e8dbbe7c95","title":"琴曲歌辞 湘夫人","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["娥眉对湘水，遥哭苍梧间。","万乘既已殁，孤舟谁忍还。","至今楚山上，犹有泪痕斑。","南有涔阳路，渺渺多新愁。","昔神降回时，风波江上秋。","彩云忽无处，碧水空安流。"],"theme":"闺情宫怨","theme2":["闲适隐逸","羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["舟","秋","山","江"],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.392},{"uid":"1365c1c9-e864-4920-ba10-d3815a59f6b7","title":"春日思归","author":"李频","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春情不断若连环，一夕思归鬓欲斑。","壮志未酬三尺劒，故乡空隔万重山。","音书断绝干戈后，亲友相逢梦寐间。","却羡浮云与飞鸟，因风吹去又吹还。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":0.718},{"uid":"015761cf-2c04-44fa-8974-aafe4fa19be3","title":"詶陈翃郎中冬至携柳郎窦郎归河中旧居见寄","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三旬一休沐，清景满林庐。","南郭群儒从，东床两客居。","烧烟浮雪野，麦陇润冰渠。","班白皆持酒，蓬茅尽有书。","终期买寒渚，同此利蒲鱼。"],"theme":"寄赠酬答","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"四季":["冬天"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"a9c061a4-c957-4d74-a0f3-86001d8b2a7f","title":"杂曲歌辞 少年行四首 二","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["家本清河住五城，须凭弓箭得功名。","等闲飞鞚秋原上，独向寒云试射声。"],"theme":"羁旅思乡","theme2":["边塞征战","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡","慷慨"],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.387},{"uid":"cp535eb913df2263","title":"洞仙歌","author":"晁补之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["青烟幂处，碧海飞金镜。","永夜闲阶卧桂影。","露凉时、零乱多少寒，神京远，惟有蓝桥路近。","水晶帘不下，云母屏开，冷浸佳人淡脂粉。","待都将许多明，付与金尊，投晓共、流霞倾尽。","更携取、胡床上南楼，看玉做人间，素秋千倾。"],"theme":"游仙梦幻","theme2":["边塞征战"],"style":"冲淡","style2":["绮丽","清新"],"mood":"恬淡","mood2":[],"scene":["夜","秋","楼"],"cats":{"四季":["秋天"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.547},{"uid":"0613f575-4f07-4326-8591-603fb3d1da45","title":"秦中感秋寄远上人","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丘常欲卧，三径苦无资。","北土非吾愿，东林怀我师。","黄金然桂尽，壮志逐年衰。","日夕凉风至，闻蝉但益悲。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["庐山"],"人生":["励志","梦想"]},"theme_conf":0.82},{"uid":"e27839b5-a0d2-41ff-aa5b-a2a0355afc68","title":"岁日作","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["更劳今日春风至，枯树无枝可寄花。","览镜唯看飘乱发，临风谁为驻浮槎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"990fcce5-9eed-4401-b5b4-e72eb0b05d5f","title":"武陵春日","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["寻春何事却悲凉，春到他乡忆故乡。","秦女洞桃欹涧碧，楚王堤柳舞烟黄。","波涛入梦家山远，名利关身客路长。","不似冥心叩尘寂，玉编金轴有仙方。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["冲淡","悲慨"],"mood":"相思","mood2":["悲怆","孤寂"],"scene":["春"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.557},{"uid":"a353dcb1-12cc-4ca8-af1e-55d1d62445f8","title":"蜀相","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["丞相祠堂何处寻，锦官城外柏森森。","映堦碧草自春色，隔叶黄鹂空好音。","三顾频烦天下计，两朝开济老臣心。","出师未捷身先死，长使英雄泪满襟。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["悲慨","豪放"],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"]},"theme_conf":0.736},{"uid":"cp71965685b8581b","title":"柳梢青","author":"蔡伸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["数声𫛸鴂。","可怜又是，春归时节。","满院东风，海棠铺绣，梨花飘雪。","丁香露泣残枝，算未比、愁肠寸结。","自是休文，多情多感，不干风月。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["春","花","雪"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"a360ba0f-5145-481a-9398-2b0e6955501d","title":"春意二首 一","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["去日丁宁别，情知寒食归。","缘逢好天气，教熨看花衣。"],"theme":"爱情相思","theme2":["送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"35b3a0df-11b4-46ae-bc44-f58f19a51447","title":"题精舍寺","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["石林精舍武溪东，夜扣禅关谒远公。","月在上方诸品静，僧持半偈万缘空。","秋山竟日闻猨啸，落木寒泉听不穷。","惟有双峰最高顶，此心期与故人同。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"冲淡","style2":["幽峭"],"mood":"孤寂","mood2":["恬淡"],"scene":["山","秋","夜","月"],"cats":{"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.66},{"uid":"b10851b9-e6cb-41eb-979a-c897ccaac1df","title":"梅里旅夕","author":"杨凌","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沧洲东望路，旅櫂怆羁游。","枫浦蝉随岸，沙汀鸥转流。","露天星上月，水国夜生秋。","谁忍持相忆，南归一叶舟。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋","江"],"cats":{"抒情":["思念","思乡"],"四季":["秋天"],"植物":["梅花"]},"theme_conf":0.723},{"uid":"b3b95e77-5985-49ef-b603-cce95a5c6ae2","title":"杂曲歌辞 春江曲","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["江水春沈沈，上有双竹林。","竹叶坏水色，郎亦坏人心。"],"theme":"山水田园","theme2":["爱情相思"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"山水":["江河"]},"theme_conf":0.511},{"uid":"a8ffe7a3-5f14-43c9-b22e-28eea904da02","title":"天门街西观荣王聘妃","author":"张光朝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙媛来朱邸，名山出紫微。","三周初展义，百两遂言归。","郑国通梁苑，天津接帝畿。","桥成乌鹊助，盖转凤皇飞。","霜仗迎秋色，星缸满夜辉。","从兹磐石固，应为得贤妃。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"3cda5a92-ffa2-4af0-9217-97ce36113705","title":"枫桥夜泊","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月落乌啼霜满天，江枫渔父对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"生活":["写桥"]},"theme_conf":0.468},{"uid":"48568d08-d789-4eca-b9a8-5dcf09d6a516","title":"李鄠县丈人胡马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["丈人骏马名胡骝，前年避胡过金牛。","回鞭却走见天子，朝饮汉水暮灵州。","自矜胡骝奇绝代，乘出千人万人爱。","一闻说尽急难材，转益愁向驽骀辈。","头上锐耳批秋竹，脚下高蹄削寒玉。","始知神龙别有种，不比俗马空多肉。","洛阳大道时再清，累日喜得俱东行。","凤臆龙鬐未易识，侧身注目长风生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"动物":["写马"]},"theme_conf":0.775},{"uid":"27db32d1-c747-4c6d-a937-4091287b6622","title":"灵门寺赠灵一上人","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["所思劳旦夕，惆怅去湘东。","禅客知何在，春山几处同。","独行残雪里，相见暮云中。","请住东林寺，弥年事远公。"],"theme":"寄赠酬答","theme2":["送别"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["庐山"]},"theme_conf":0.88},{"uid":"029ff16c-6562-4d06-95d9-765045b30c69","title":"新桃行","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["桃生叶婆娑，枝叶四向多。","高未出墙颠，蒿苋相凌摩。","植之三年余，今年初试花。","秋来已成实，其阴良已嘉。","青蝉不来鸣，安得迅羽过。","常恶牵丝虫，蒙幂成网罗。","顾托戏儿童，勿折吾柔柯。","明年结其实，磊磊充汝家。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"c9747409-7db3-4600-8a85-90465a503b29","title":"寄续尊师","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["得道任发白，亦逢城市游。","新经天上取，稀药洞中收。","春木带枯叶，新蒲生漫流。","年年望灵鹤，常在此山头。"],"theme":"佛道禅颂","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"人生":["时光"]},"theme_conf":0.9},{"uid":"dd4c60cf-6385-48a0-86b2-2020cdf70f36","title":"青云干吕 二","author":"彭伉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣布中区化，祥符异域云。","含春初应吕，晕碧已成文。","东起随风暖，西流共日曛。","升时嘉异月，为庆等凝汾。","轻与晴烟比，高将晓雾分。","飘飘如可致，愿此翊明君。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春","月"],"cats":{"四季":["春天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.92},{"uid":"91833140-4a32-4508-b50e-2d5e57c4940d","title":"感春四首 二","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["皇天平分成四时，春气漫诞最可悲。","杂花妆林草盖地，白日坐上倾天维。","蜂喧鸟咽留不得，红萼万片从风吹。","岂如秋霜虽惨冽，摧落老物谁惜之。","为此径须沽酒饮，自外天地弃不疑。","近怜李杜无检束，烂漫长醉多文辞。","屈原离骚二十五，不肯𫗦啜糟与醨。","惜哉此子巧言语，不到圣处宁非痴。","幸逢尧舜明四目，条理品汇皆得宜。","平明出门暮归舍，酩酊马上知为谁。"],"theme":"咏怀抒感","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"节日":["端午节"]},"theme_conf":0.88},{"uid":"83057247-91ce-43d8-8aee-2eccfdcc8773","title":"横吹曲辞 折杨柳","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纤纤折杨柳，持此寄情人。","一枝何足贵，怜是故园春。","迟景那能久，流芳不及新。","更愁征戍客，鬓老边城尘。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","园林"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.468},{"uid":"8b2a898c-bb52-463e-8a8a-989eacb2ce54","title":"华下对菊","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["清香裛露对高斋，泛酒偏能浣旅怀。","不似春风逞红艳，镜前空坠玉人钗。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["重阳","酒","春","花"],"cats":{"四季":["春天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.724},{"uid":"c27559b0-f98d-4b5f-a239-f5ec7cb33f71","title":"漫成二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江臯已仲春，花下复清晨。","仰面贪看鸟，回头错应人。","读书难字过，对酒满壶频。","近识峨眉老，知予嬾是真。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","春"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":0.92},{"uid":"35638e63-ef59-411d-a832-af24221fd0fd","title":"题落叶","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["霜景催危叶，今朝半树空。","萧条故国异，零落旅人同。","飒岸浮寒水，依堦拥夜虫。","随风偏可羡，得到洛阳宫。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.463},{"uid":"cp68f66c294d5089","title":"琵琶仙・自度曲","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["双桨来时，有人似、旧曲桃根桃叶。","歌扇轻约飞花，蛾眉正奇绝。","春渐远、汀洲自绿，更添了、几声啼。","十里扬州，三生杜牧，前事休说。","又还是、宫烛分烟，奈愁里、匆匆换时节。","都把一襟芳思，与空阶榆荚。","千万缕、藏鸦细柳，为玉尊、起舞回雪。","想见西出阳关，故人初别。"],"theme":"送别","theme2":["题画咏艺"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","花","雪"],"cats":{"抒情":["友情","伤感"],"四季":["春天"]},"theme_conf":0.378},{"uid":"b6c590ce-9357-4a67-85bb-29a2402d9c33","title":"和王给事禁省梨花咏","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["巧解逢人笑，还能乱蝶飞。","春时风入户，几片落朝衣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"f613e665-0ed5-449e-9f4f-e094a102f993","title":"九曲词三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万骑争歌杨柳春，千塲对舞绣骐𬴊。","到处尽逢欢洽事，相看总是太平人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["黄河"]},"theme_conf":0.65},{"uid":"d719fd0e-bbf4-49b5-83f7-e04ad1d1b9d3","title":"春日送沈赞府归浔阳觐叔父","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浔阳阮咸宅，九派竹林前。","花屿高如浪，云峰远似天。","江声在南巷，海气入东田。","才子今朝去，风涛思渺然。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["父亲"]},"theme_conf":0.536},{"uid":"06bb6ddd-5f47-42f0-a020-b7671ad56bdf","title":"相和歌辞 短歌行六首 四","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["何处春风吹晓幕？江南绿水通朱阁。","美人二八面如花，泣向东风畏花落。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["春","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.65},{"uid":"cp73f107efe4e3f6","title":"谢池春","author":"李之仪","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒销尽，疏雨过、清明后。","花径敛馀红，风沼萦新皱。","乳燕穿庭户，飞絮沾襟袖。","正佳时，仍晚昼。","著人滋味，真个浓如酒。","频移带眼，空只恁、厌厌瘦。","不见又思量，见了还依旧。","为问频相见，何似长相守。","天不老，人未偶。","且将此恨，分付庭前柳。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":["清新","幽峭"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["园林","春","清明"],"cats":{"抒情":["思念","感恩"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.92},{"uid":"6efdeafd-8fbd-40a2-83f3-7a570f43a2e8","title":"郊庙歌辞 后唐宗庙乐舞辞 武成舞","author":"崔居俭、卢文纪","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["艰难王业，返正皇唐。","先天再造，却日重光。","汉绍世祖，夏资少康。","功成德茂，率祀无疆。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.87},{"uid":"7e29d72b-7386-48c6-af3c-9dafd02f0665","title":"木兰歌","author":"韦元甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["木兰抱杼嗟，借问复为谁。","欲闻所戚戚，感激彊其颜。","老父隶兵籍，气力日衰耗。","岂足万里行，有子复尚少。","胡沙没马足，朔风裂人肤。","老父旧羸病，何以彊自扶。","木兰代父去，秣马备戎行。","易却纨绮裳，洗却铅粉妆。","驰马赴军幕，慷慨携干将。","朝屯雪山下，暮宿青海傍。","夜袭燕支虏，更携于阗羌。","将军得胜归，士卒还故乡。","父母见木兰，喜极成悲伤。","木兰能承父母颜，却卸巾鞲理丝簧。","昔为烈士雄，今为娇子容。","亲戚持酒贺父母，始知生女与男同。","门前旧军都，十年共崎岖。","本结弟兄交，死战誓不渝。","今者见木兰，言声虽是颜貌殊。","惊愕不敢前，叹息徒嘻吁。","世有臣子心，能如木兰节。","忠孝两不渝，千古之名焉可灭。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放","悲慨"],"mood":"悲怆","mood2":["慷慨"],"scene":["冬","夜","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"天气":["写风"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.668},{"uid":"c92216ac-114d-4bda-9c55-89688840f5b0","title":"薄命篇","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔住邯郸年尚少，只是娇羞弄花鸟。","青楼碧纱大道边，绿杨日暮风褭褭。","婵娟玉貌二八余，自怜颜色花不如。","丽质全胜秦氏女，藁砧宁用专城居。","岁去年来年渐长，青春红粉全堪赏。","玉楼珠箔但闲居，南陌东城讵来往。","韶光日日看渐迟，[摽]梅既落行有时。","宁知燕赵娉婷子，翻嫁幽幷游侠儿。","年年结束青丝骑，出门一去何时至。","秋月空悬翡翠帘，春帏嬾卧鸳鸯被。","沙塞经时不寄书，深闺愁独意何如。","花前拭泪情无限，月下调琴恨有余。","离别苦多相见少，洞房愁梦何由晓。","闲看双燕泪霏霏，静对空床魂悄悄。","镜里红颜不自禁，陌头香骑动春心。","为问佳期早晚是，人人总解有黄金。"],"theme":"闺情宫怨","theme2":["送别","闺情宫怨","爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","秋","鸟","春","塞外","中秋"],"cats":{"抒情":["爱情","离别","伤感","闺怨"],"四季":["春天","秋天"],"天气":["月亮"],"人生":["青春"],"节日":["中秋节"]},"theme_conf":0.96},{"uid":"5aee80a3-db54-4787-9e2a-491e108b8f1d","title":"发秦州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我衰更嬾拙，生事不自谋。","无食问乐土，无衣思南州。","汉源十月交，天气凉如秋。","草木未黄落，况闻山水幽。","栗亭名更佳，下有良田畴。","充肠多薯蓣，崖蜜亦易求。","密竹复冬笋，清池可方舟。","虽伤旅寓远，庶遂平生游。","此邦俯要冲，实恐人事稠。","应接非本性，登临未销忧。","谿谷无异石，塞田始微收。","岂复慰老夫，惘然难久留。","日色隐孤戍，乌啼满城头。","中宵驱车去，饮马寒塘流。","磊落星月高，苍茫云雾浮。","大哉乾坤内，吾道长悠悠。"],"theme":"山水田园","theme2":["边塞征战"],"style":"雄浑","style2":["沉郁"],"mood":"孤寂","mood2":["惆怅"],"scene":["夜","冬","塞外","月","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天","冬天"],"生活":["边塞"]},"theme_conf":0.407},{"uid":"c11ca31f-2354-4bf8-8be4-101c5e81c601","title":"登润州城","author":"江为","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天末江城晚，登临客望迷。","春潮平岛屿，残雨隔虹霓。","鸟与孤帆远，烟和独树低。","乡山何处是，目断广陵西。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江","春","雨","舟"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.399},{"uid":"2d99b5dd-863a-4b50-ad3d-fe5c9ea8a8d9","title":"送元处士游天台","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青冥路口绝人行，独与僧期上赤城。","树列烟岚春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野馆风来竹气清。","若过石桥看瀑布，不妨高处便题名。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","楼","雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["瀑布"],"天气":["写雪"],"生活":["写桥"]},"theme_conf":0.458},{"uid":"511b0ab5-253f-4f98-b82e-6029d875abcf","title":"重题","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["涕泗不能收，哭君余白头。","儿童相识尽，宇宙此生浮。","江雨铭旌湿，湖风井径秋。","还瞻魏太子，宾客减应刘。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江","秋","雨"],"cats":{"四季":["秋天"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"2c6094fa-74b2-4226-b42d-d06cc51fb646","title":"怀鲁","author":"程弥纶","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曲阜国，尼丘山。","周公邈难问，夫子犹启关。","履风雩兮若见，游夏兴兮鲁颜。","天孙天孙，何为今兮学且难，负星明而东游闲闲。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏","山"],"cats":{"抒情":["怀古"],"四季":["夏天"]},"theme_conf":0.9},{"uid":"46c03530-4479-4300-a884-aa4c01ea91a2","title":"招孟武昌","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["风霜枯万物，退谷如春时。","穷冬涸江海，桮湖澄清漪。","湖尽到谷口，单船近堦墀。","湖中更何好，坐见大江水。","欹石为水涯，半山在湖里。","谷口更何好，绝壑流寒泉。","松桂荫茅舍，白云生坐边。","武昌不干进，武昌人不厌。","退谷正可游，桮湖任来泛。","湖上有水鸟，见人不飞鸣。","谷口有山兽，往往随人行。","莫将车马来，令我鸟兽惊。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["江","山","冬"],"cats":{"四季":["冬天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"4e9ac5c4-8f12-40f3-acce-39567d0bdfc5","title":"县斋有怀","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少小尚奇伟，平生足悲咤。","犹嫌子夏儒，肯学樊迟稼。","事业窥臯稷，文章蔑曹谢。","濯缨起江湖，缀佩杂兰麝。","悠悠指长道，去去策高驾。","谁为倾国媒，自许连城价。","初随计吏贡，屡入泽宫射。","虽免十上劳，何能一战霸。","人情忌殊异，世路多权诈。","蹉跎颜遂低，摧折气愈下。","冶长信非罪，侯生或遭骂。","怀书出皇都，衔泪渡清灞。","身将老寂寞，志欲死闲暇。","朝食不盈肠，冬衣才掩髂。","军书既频召，戎马乃连跨。","大梁从相公，彭城赴仆射。","弓箭围狐兔，丝竹罗酒{炙火=肉}。","两府变荒凉，三年就休假。","求官去东洛，犯雪过西华。","尘埃紫陌春，风雨灵台夜。","名声荷朋友，援引乏姻娅。","虽陪彤庭臣，讵纵青冥靶。","寒空耸危阙，晓色曜修架。","捐躯辰在丁，铩翮时方蜡。","投荒诚职分，领邑幸宽赦。","湖波翻日车，岭石坼天罅。","毒雾恒熏昼，炎风每烧夏。","雷威固已加，飓势仍相借。","气象杳难测，声音吁可怕。","夷言听未惯，越俗循犹乍。","指摘两憎嫌，睢盱互猜讶。","祗缘恩未报，岂谓生足藉。","嗣皇新继明，率土日流化。","惟思涤瑕垢，长去事桑柘。","𣃁嵩开云扃，压颍抗风榭。","禾麦种满地，梨枣栽绕舍。","儿童稍长成，雀鼠得驱吓。","官租日输纳，村酒时邀迓。","闲爱老农愚，归弄小女姹。","如今便可尔，何用毕婚嫁。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["夏","冬","江"],"cats":{"抒情":["伤感","孤独","爱国"],"四季":["夏天","冬天"],"人物":["儿童"]},"theme_conf":0.494},{"uid":"970e1233-9d3b-4ee6-92c1-1491ffc37bfa","title":"相和歌辞 凤凰曲","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["嬴女吹玉箫，吟弄天上春。","青鸾不独去，更有携手人。","影灭彩云断，遗声落西秦。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.88},{"uid":"cp96c41b444b7052","title":"幺・故人一去无音信，望篷莱隔几重云。燕未归，春将尽，梨花庭院，和","author":"张可久","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["月掩朱门。","秋思酸斋索赋鸳鸯飞起藕花洲，碧水明秋。","玉人天际认归舟，秋来后，憔悴见花羞。"],"theme":"爱情相思","theme2":["送别","讽喻刺世","山水田园"],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["园林","春","花"],"cats":{"抒情":["爱情","友情"],"四季":["春天"],"动物":["写鸟"],"植物":["梨花"]},"theme_conf":0.284},{"uid":"362e9ec3-e452-4f59-b5f4-10757da34b28","title":"杂曲歌辞 妾薄命","author":"刘元淑","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自从离别守空闺，遥闻征战起云梯。","夜夜愁君辽海外，年年弃妾渭桥西。","阳春白日照空暖，紫燕衔花向庭满。","彩鸾琴里怨声多，飞鹊镜前妆梳断。","谁家夫壻不从征，应是渔阳别有情。","莫道红颜燕地少，家家还似洛阳城。","且逐新人殊未归，还令秋至夜霜飞。","北斗星前横度鴈，南楼月下捣寒衣。","夜深闻鴈肠欲绝，独坐缝衣灯又灭。","暗啼罗帐空自怜，梦度阳关向谁说。","每怜容貌宛如神，如何薄命不胜人。","愿君朝夕燕山至，好作明年杨柳春。"],"theme":"闺情宫怨","theme2":["送别","边塞征战"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","秋","鸟","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天","秋天"],"天气":["星星"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.354},{"uid":"c3a14148-94d9-47f2-afff-9f9ef345b018","title":"寄袁州李嘉祐员外","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谁谓江山阻，心亲梦想偏。","容辉常在目，离别任经年。","郡国通流水，云霞共远天。","行春莺几啭，迟客月频圆。","雁有归乡羽，人无访戴船。","愿徴黄霸入，相见玉堦前。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["春","鸟"],"cats":{"抒情":["离别","思乡"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.96},{"uid":"832147f1-7dcc-4626-b3fc-0d197f29ad77","title":"杂曲歌辞 行路难","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["行路艰难不复歌，故人荣达我蹉跎。","双轮晚上铜梁雪，一叶春浮瘴海波。","自古要津皆若此，方今失路欲如何？","君看西汉翟丞相，凤沼朝辞暮雀罗。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春"],"cats":{"抒情":["友情"],"四季":["春天"]},"theme_conf":1.0},{"uid":"22362105-f266-4297-b3e9-d54b40adf8f0","title":"上阳红叶","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛下三分红叶秋，二分翻作上阳愁。","千声万片御沟上，一片出宫何处流。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"cpa4d238ecabd1f0","title":"高阳台","author":"韩","dynasty":"宋","section":"宋词","form":"词","paragraphs":["频听银签，重燃绛蜡，年华衮衮惊心。","饯旧迎新，能消几刻光阴。","老来可惯通宵饮，待不眠、还怕寒侵。","掩清尊。","多谢梅花，伴我微吟。","邻娃已试春妆了，更蜂腰簇翠，燕股横金。","勾引东风，也知芳思难禁。","朱颜那有年年好，逞艳游、赢取如今。","恣登临。","残雪楼台，迟日园林。"],"theme":"送别","theme2":[],"style":"清新","style2":["绮丽","沉郁"],"mood":"惆怅","mood2":[],"scene":["楼","春"],"cats":{"四季":["春天"],"人生":["青春","时光"]},"theme_conf":1.0},{"uid":"91f95b30-c42f-470a-9df8-dd6284fca474","title":"隋宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["乘兴南游不戒严，九重谁省谏书函。","春风举国裁宫锦，半作障泥半作帆。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","舟"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.722},{"uid":"110ea489-e0f3-40c3-8bd1-39936729a6cf","title":"冬夜题旅馆","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["退飞忆林薮，乐业羡黎庶。","四海尽穷途，一枝无宿处。","严冬北风急，中夜哀鸿去。","孤烛思何深，寒窗坐难曙。","劳歌待明发，惆怅盈百虑。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"豪放","style2":["悲慨"],"mood":"相思","mood2":["孤寂","惆怅"],"scene":["冬","夜"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["冬天"],"人生":["读书"]},"theme_conf":0.624},{"uid":"ea82076e-44f8-4d9c-8844-a2325b642224","title":"题鹤林寺","author":"薛据","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["道门隐形胜，向背临法桥。","松覆山殿冷，花藏溪路遥。","珊珊宝幡挂，燄燄明灯烧。","迟日半空谷，春风连上潮。","少凭水木兴，暂忝身心调。","愿谢携手客，兹山禅侣饶。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","春","山","江"],"cats":{"四季":["春天"],"人生":["哲理"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.533},{"uid":"5679526b-d077-4f1f-a67e-fc430e4643a9","title":"柳州二月榕叶落尽偶题","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宦情羁思共凄凄，春半如秋意转迷。","山城过雨百花尽，榕叶满庭莺乱啼。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["月亮"],"植物":["柳树","叶子"]},"theme_conf":0.421},{"uid":"6eae5ecc-fda0-4ced-ac00-b93e573e381c","title":"观村人牧山田","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["六府且未盈，三农争务作。","贫民乏井税，塉土皆垦凿。","禾黍入寒云，茫茫半山郭。","秋来积霖雨，霜降方铚获。","中田聚黎甿，反景空村落。","顾惭不耕者，微禄同卫鹤。","庶追周任言，敢负谢生诺。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","山","秋"],"cats":{"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.635},{"uid":"cp9b56c892fca6f8","title":"夜游宫","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["人去西楼雁杳。","叙别梦、扬州一觉。","云澹星疏楚山晓。","听啼乌，立河桥，话未了。","雨外蛩声早。","细织就、霜丝多少。","说与萧娘未知道。","向长安，对秋灯，几人老。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","秋"],"cats":{"四季":["秋天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"4bd5be2b-5788-42c0-a300-9d106a73d46e","title":"相和歌辞 子夜四时歌四首 夏歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["镜湖三百里，菡萏发荷花。","五月西施采，人看隘若邪。","回舟不待月，归去越王家。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.504},{"uid":"ad25550b-b0b6-49cd-981a-88d90471b624","title":"寄彭州高三十五使君适虢州岑二十七长史参三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故人何寂寞，今我独凄凉。","老去才难尽，秋来兴甚长。","物情尤可见，辞客未能忘。","海内知名士，云端各异方。","高岑殊缓步，沈鲍得同行。","意惬关飞动，篇终接混茫。","举天悲富骆，近代惜卢王。","似尔官仍贵，前贤命可伤。","诸侯非弃掷，半刺已翱翔。","诗好几时见，书成无信将。","男儿行处是，客子鬬身强。","羁旅推贤圣，沈绵抵咎殃。","三年犹疟疾，一鬼不销亡。","隔日搜脂髓，增寒抱雪霜。","徒然潜隙地，有腼屡鲜妆。","何太龙钟极，于今出处妨。","无钱居帝里，尽室在边疆。","刘表虽遗恨，庞公至死藏。","心微傍鱼鸟，肉瘦怯豺狼。","陇草萧萧白，洮云片片黄。","彭门劒阁外，虢略鼎湖旁。","荆玉簪头冷，巴笺染翰光。","乌麻蒸续晒，丹橘露应尝。","岂异神仙宅，俱兼山水乡。","竹斋烧药灶，花屿读书床。","更得清新否，遥知对属忙。","旧宫宁改汉，淳俗本归唐。","济世宜公等，安贫亦士常。","蚩尤终戮辱，胡羯漫猖狂。","会待祅氛静，论文暂裹粮。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":["孤寂","悲怆"],"scene":["秋","雪"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.373},{"uid":"661bab14-62cd-4385-a173-f47e53e6e649","title":"茅堂检校收稻二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["香稻三秋末，平田百顷间。","喜无多屋宇，幸不碍云山。","御裌侵寒气，尝新破旅颜。","红鲜终日有，玉粒未吾悭。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","花","山"],"cats":{"四季":["秋天"],"生活":["田野"]},"theme_conf":0.718},{"uid":"77ae50af-e0a1-44f5-9d40-b319a0549ea5","title":"咏虹","author":"董思恭","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春暮萍生早，日落雨飞余。","横彩分长汉，倒色媚清渠。","梁前朝影出，桥上晚光舒。","愿逐旌旗转，飘飘侍直庐。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","雨"],"cats":{"四季":["春天"],"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.701},{"uid":"54954a45-c90c-4fa5-858e-90a189f637b4","title":"端午日赐衣","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宫衣亦有名，端午被恩荣。","细葛含风輭，香罗叠雪轻。","自天题处湿，当暑著来清。","意内称长短，终身荷圣情。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"四季":["夏天"],"节日":["端午节"]},"theme_conf":0.66},{"uid":"57203d7f-380c-4052-b21b-d1ea79fbe231","title":"子夜吴歌 春歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"],"theme":"闺情宫怨","theme2":["民生疾苦"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.471},{"uid":"7c5abe03-8a94-43d1-b340-e25aa1f83fc6","title":"春日茶山病不饮酒因呈宾客","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["笙歌登画船，十日清明前。","山秀白云腻，溪光红粉鲜。","欲开未开花，半阴半晴天。","谁知病太守，犹得作茶仙。"],"theme":"寄赠酬答","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","酒","清明"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"],"节日":["清明节"],"食物":["写酒","写茶"]},"theme_conf":0.7},{"uid":"e39702ba-5835-461f-ae4f-4fc597c65478","title":"同李三月夜作","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["霜风惊度雁，月露皓疎林。","处处砧声发，星河秋夜深。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["月","夜","秋"],"cats":{"四季":["秋天"],"天气":["月亮","星星"]},"theme_conf":0.58},{"uid":"8331c76b-a250-4d07-9c28-b8a456e0974c","title":"春雨","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["怅卧新春白袷衣，白门寥落意多违。","红楼隔雨相望冷，珠箔飘灯独自归。","远路应悲春晼晚，残宵犹得梦依稀。","玉珰缄札何由达，万里云罗一雁飞。"],"theme":"山水田园","theme2":["爱情相思","羁旅思乡"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂","相思"],"scene":["雨","春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.38},{"uid":"cpa35401f760960a","title":"桂枝香","author":"王安石","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登临送目。","正故国晚秋，天气初肃。","千里澄江似练，翠峰如簇。","归帆去棹残阳里，背西风、酒旗斜矗。","彩舟云淡，星河鹭起，画图难足。","念往昔、繁华竞逐。","叹门外楼头，悲恨相续。","千古凭高，对此漫嗟荣辱。","六朝旧事随流水，但寒烟、芳草凝绿。","至今商女，时时犹唱，后庭遗曲。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["悲慨","绮丽"],"mood":"悲怆","mood2":["愁怨","恬淡"],"scene":["舟","秋","花"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.578},{"uid":"160c5168-d55c-4a4c-ba73-ae1596f4b900","title":"杂曲歌辞 行路难三首 三","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见少年头上如云发，少壮如云老如雪。","岂知灌顶有醍醐，能使清凉头不热。","吕梁之水挂飞流，鼋鼍蛟蜃不敢游。","少年恃险若平地，独倚长劒凌清秋。","行路难，行路难，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊古城草。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cpe8a61267f2054a","title":"定风波","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["自春来、惨绿愁红，芳心是事可可。","日上花梢，莺穿柳带，犹压香衾卧。","暖酥消，腻云。","终日厌厌倦梳裹。","无那。","恨薄情一去，音书无个。","早知恁么。","悔当初、不把雕鞍锁。","向鸡窗、只与蛮笺象管，拘束教吟课。","镇相随，莫抛躲。","针线闲拈伴伊坐。","和我。","免使年少，光阴虚过。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["花","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"503b3e6f-a832-43df-bf4b-20bbfcef0769","title":"送孔党赴举","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["入贡列诸生，诗书业早成。","家承孔圣后，身有鲁儒名。","楚水通荥浦，春山拥汉京。","爱君方弱冠，为赋少年行。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"2ead7ead-cc7f-410c-8767-d2b8083079fe","title":"郊庙歌辞 祀九宫贵神乐章 太和","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["帝在灵坛，大明登光。","天回云粹，穆穆皇皇。","金奏九夏，圭陈八芗。","旷哉动植，如熙春阳。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","春"],"cats":{"四季":["春天","夏天"]},"theme_conf":0.85},{"uid":"bcf6124b-d0ca-48b1-9b9a-c62824a7d759","title":"严氏溪放歌行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天下甲马未尽销，岂免沟壑常漂漂。","劒南岁月不可度，边头公卿仍独骄。","费心姑息是一役，肥肉大酒徒相要。","呜呼古人已粪土，独觉志士甘渔樵。","况我飘转无定所，终日慽慽忍羁旅。","秋宿霜溪素月高，喜得与子长夜语。","东游西还力实倦，从此将身更何许。","知子松根长茯苓，迟暮有有意来同煮。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["秋","夜","月","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.529},{"uid":"d441a467-c7a4-4a9b-8f4a-bcba626c16d8","title":"奉和春日游龙门应制","author":"武三思","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤架临香地，龙舆上翠微。","星宫含雨气，月殿抱春辉。","碧涧长虹下，雕梁早燕归。","云疑浮宝盖，石似拂天衣。","露草侵阶长，风花遶席飞。","日斜宸赏洽，清吹入重闱。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["绮丽","婉约"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["彩虹","太阳"]},"theme_conf":0.99},{"uid":"e9a7af99-eb7c-4977-bb08-833c8f32f7f9","title":"早春西湖闲游怅然兴怀忆与微之同赏因思在越官重事殷镜湖之游或恐未暇偶成十八韵寄微之","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上马复呼宾，湖边景气新。","管弦三数事，骑从十余人。","立换登山屐，行携漉酒巾。","逢花看当妓，遇草坐为茵。","西日笼黄柳，东风荡白苹。","小桥装鴈齿，轻浪甃鱼鳞。","画舫牵徐转，银船酌慢巡。","野情遗世累，醉态任天真。","彼此年将老，平生分最亲。","高天从所愿，远地得为邻。","云树分三驿，烟波限一津。","飜嗟寸步隔，却厌尺书频。","浙右称雄镇，山阴委重臣。","贵垂长紫绶，荣驾大朱轮。","出动刀枪队，归生道路尘。","鴈惊弓易散，鸥怕鼓难驯。","百吏瞻相面，千夫捧拥身。","自然闲兴少，应负镜湖春。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":["相思","恬淡"],"scene":["江南","春","江","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"ea6c5a06-ed63-49f3-82aa-bb7bbded3ee5","title":"鼓吹曲辞 有所思","author":"刘氏云","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朝亦有所思，暮亦有所思。","登楼望君处，蔼蔼浮云飞。","浮云遮却阳关道，向晚谁知妾怀抱。","玉井苍苔春院深，桐花落地无人扫。"],"theme":"边塞征战","theme2":["送别","闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","楼","园林"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写云"],"生活":["边塞"]},"theme_conf":0.38},{"uid":"cp30a4d20b32a6da","title":"祝英台令","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["宝钗分，桃叶渡。","烟柳暗南浦。","怕上层楼，十日九风雨。","断肠片片飞红，都无人管，倩谁唤、流莺声住。","鬓边觑。","试把花卜心期，才簪又重数。","罗帐灯昏，呜咽梦中语。","是他春带愁来，春归何处。","却不解、将愁归去。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["楼","春","雨"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"]},"theme_conf":0.533},{"uid":"dfcaab39-5c64-4eba-911e-2dec1cedc259","title":"送陵州路使君赴任","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["王室比多难，高官皆武臣。","幽燕通使者，岳牧用词人。","国待贤良急，君当拔擢新。","佩刀成气象，行盖出风尘。","战伐乾坤破，疮痍府库贫。","众僚宜洁白，万役但平均。","霄汉瞻佳士，泥途任此身。","秋天正摇落，回首大江滨。"],"theme":"送别","theme2":[],"style":"旷达","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["长江"]},"theme_conf":0.616},{"uid":"05a734dd-b434-428e-ab3f-695ac637d516","title":"伤桃源薛道士","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["坛边松在鹤巢空，白鹿闲行旧径中。","手植红桃千树发，满山无主任春风。"],"theme":"山水田园","theme2":["悼亡挽歌"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.491},{"uid":"95016fcd-87f8-4828-9d26-b9a2b43c5a89","title":"过鸣臯隐者","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["磻石老红鲜，徴君卧几年。","飞泉出林下，一径过崖巅。","鸡犬逐人静，云霞宜地偏。","终朝数峰胜，不远一壶前。","仲月霁春雨，香风生药田。","丹溪不可别，琼草色芊芊。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","月","雨","山"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":0.515},{"uid":"151b748b-c973-46df-9c3a-6ce7a9ab53e0","title":"杂曲歌辞 汉宫少年行","author":"李益","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见上宫警夜营八屯，冬冬街鼓朝朱轩。","玉阶霜仗拥未合，少年排入铜龙门。","暗闻弦管九天上，宫漏沈沈清吹繁。","才明走马绝驰道，呼鹰挟弹通缭垣。","玉笼金琐养黄口，探雏取卵伴王孙。","分曹六博快一掷，迎欢先意笑语喧。","巧为柔媚学优孟，儒衣嬉戏冠沐猨。","晚来香街经柳市，行过倡市宿桃根。","相逢杯酒一言失，回朱点白闻至尊。","金张许史伺颜色，王侯将相莫敢论。","岂知人事无定势，朝欢暮戚如掌翻。","椒房宠移子爱夺，一夕秋风生戾园。","徒用黄金将买赋，宁知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老张丞相，南山如天不可上。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"欢愉","mood2":[],"scene":["夜","酒","秋","冬"],"cats":{"抒情":["闺怨","怀古"],"四季":["秋天","冬天"],"人生":["青春"]},"theme_conf":0.513},{"uid":"34bac317-4e11-40fa-abae-731bfb0e8d9c","title":"横吹曲辞 折杨柳","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉窗朝日映，罗帐春风吹。","拭泪攀杨柳，长条宛地垂。","白花飞历乱，黄鸟思参差。","妾自肝肠断，旁人那得知。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"19b577a6-dca0-4c95-9365-7e4a8356e71d","title":"郑驸马池台喜遇郑广文同饮","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["不谓生戎马，何知共酒杯。","然脐郿坞败，握节汉臣回。","白发千茎雪，丹心一寸灰。","别离经死地，披写忽登台。","重对秦箫发，俱过阮宅来。","留连春夜舞，泪落强裴回。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["酒","楼","园林","雪","春"],"cats":{"抒情":["离别"],"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"94c281fc-90b7-47c8-8e6e-a18445b158fb","title":"相和歌辞 子夜四时歌四首 冬歌","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["南光走冷圭，北籁号空木。","年年任霜霰，不减筼筜绿。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["冬","夜"],"cats":{"四季":["冬天"]},"theme_conf":0.66},{"uid":"a3ff9642-7681-4ab7-8cfc-347a97ca7609","title":"山迳柳","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["宛转若游丝，浅深栽绿崦。","年年立春后，即被啼莺占。"],"theme":"咏物","theme2":["咏物","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":0.95},{"uid":"0f1e20b5-a8e4-45cd-a1e2-45710eec46fb","title":"横吹曲辞 骢马曲","author":"纪唐天","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["连钱出塞蹋沙蓬，岂比当时御史骢。","逐北自谙深碛路，连嘶谁念静边功。","登山每与青云合，弄影应知碧草同。","今日虏平将换妾，不如罗袖舞春风。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","春","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.63},{"uid":"90d24d06-910e-476e-8819-47f127e03360","title":"含风夕","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["炎昏勌烦久，逮此含风夕。","夏服稍轻清，秋堂已岑寂。","载欣凉宇旷，复念佳辰掷。","络纬惊岁功，顾我何成绩。","青荧微月钩，幽晖洞阴魄。","水镜涵玉轮，若见渊泉璧。","参差帘牖重，次第笼虚白。","树影满空床，萤光缀深壁。","怅望牵牛星，复为经年隔。","露网褭风珠，轻河泛遥碧。","讵无深秋夜，感此乍流易。","亦有迟暮年，壮年良自惜。","循环切中肠，感念追往昔。","接瞬无停阴，何言问陈积。","馨香推蕙兰，坚贞谕松柏。","生物固有涯，安能比金石。","况兹百龄内，扰扰纷众役。","日月东西驰，飞车无留迹。","来者良未穷，去矣定奚适。","委顺在物为，营营复何益。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"婉约","style2":["绮丽","沉郁"],"mood":"孤寂","mood2":["恬淡","慷慨"],"scene":["夏","秋"],"cats":{"四季":["夏天","秋天"],"天气":["写风","星星"]},"theme_conf":0.567},{"uid":"df01972d-f851-4b0f-bbd5-9e57be874eb6","title":"古意","author":"蒋冽","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冉冉红罗帐，开君玉楼上。","画作同心鸟，衔花两相向。","春风正可怜，吹暎绿窗前。","妾意空相感，君心何处边。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","楼"],"cats":{"抒情":["爱情","闺怨","感恩"],"四季":["春天"]},"theme_conf":0.524},{"uid":"09f26016-922c-4bb4-a70f-a846c5b03661","title":"落日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日在帘钩，溪边春事幽。","芳菲缘岸圃，樵爨倚滩舟。","啅雀争枝坠，飞虫满院游。","浊醪谁造汝，一酌散千忧。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"cp234b5064f09847","title":"浪淘沙","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["五岭麦秋残。","荔子初丹。","绛纱囊里水晶丸。","可惜天教生处远，不近长安。","往事忆开元。","妃子偏怜。","一从魂散马嵬关。","只有红尘无驿使，满眼骊山。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["山","秋"],"cats":{"抒情":["思念","怀古"],"四季":["秋天"],"食物":["荔枝"]},"theme_conf":0.511},{"uid":"0ba3b183-531e-48da-aa22-cacc3936e6aa","title":"杂曲歌辞 伤歌行","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["众毒蔓贞松，一枝难久荣。","岂知黄庭客，仙骨生不成。","春色舍芳蕙，秋风遶枯茎。","弹琴不成曲，始觉知音倾。","馆月改旧照，吊宾写余情。","还舟空江上，波浪送铭旌。"],"theme":"悼亡挽歌","theme2":["羁旅思乡","送别"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春","秋","舟","月","园林","江"],"cats":{"抒情":["友情","思乡","伤感","悼亡"],"四季":["春天","秋天"]},"theme_conf":0.95},{"uid":"cp4411ce7078f356","title":"定风波","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["莫听穿林打叶声。","何妨吟啸且徐行。","竹杖芒鞋轻胜马。","谁怕。","一蓑烟雨任平生。","料峭春风吹酒醒。","微冷。","山头斜照却相迎。","回首向来萧瑟处。","归去。","也无风雨也无晴。"],"theme":"山水田园","theme2":[],"style":"旷达","style2":["幽峭","婉约"],"mood":"恬淡","mood2":[],"scene":["雨","春","酒"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"86500cf0-f0a0-4a79-893e-6bedd71460ee","title":"怀钟陵旧游四首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["滕阁中春绮席开，柘枝蛮鼓殷晴雷。","垂楼万幕青云合，破浪千帆阵马来。","未掘双龙牛斗气，高悬一榻栋梁材。","连巴控越知何事，珠翠沈檀处处堆。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人生":["励志"]},"theme_conf":1.0},{"uid":"609cfa44-628d-4344-91bd-ca03998bf52e","title":"冬至宿杨梅馆","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十一月中长至夜，三千里外远行人。","若为独宿杨梅馆，冷枕单床一病身。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"ce27f085-cc00-44d2-8bdd-2732050b6f44","title":"郊庙歌辞 朝日乐章 肃和","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["惟圣格天，惟明飨日。","帝郊肆类，王宫戒吉。","珪奠春舒，钟歌晓溢。","礼云克备，斯文有秩。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["太阳"]},"theme_conf":0.9},{"uid":"87beeed5-93f8-4ac6-a8e0-6bc7e42957c2","title":"九成宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["十二层城阆苑西，平时避暑拂虹霓。","云随夏后双龙尾，风逐周王八骏蹄。","吴岳晓光连翠𪩘，甘泉晚景上丹梯。","荔枝卢橘沾恩幸，鸾鹊天书湿紫泥。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["彩虹"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"b8ae44b3-ba8d-42d3-85a7-a70aa8608379","title":"长安遇冯著","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客从东方来，衣上灞陵雨。","问客何为来，采山因买斧。","冥冥花正开，飏飏燕新乳。","昨别今已春，鬓丝生几缕。"],"theme":"民生疾苦","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春","雨","山"],"cats":{"抒情":["思乡"],"四季":["春天"]},"theme_conf":0.358},{"uid":"4d6973c8-af8f-4d6f-a5a1-b118bfe79d1e","title":"相和歌辞 相逢行","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二十登汉朝，英声迈今古。","适从东方来，又欲谒明主。","犹酣新丰酒，尚带霸陵雨。","邂逅两相逢，别来间寒暑。","宁知白日晚，暂向花间语。","忽闻长乐钟，走马东西去。"],"theme":"咏史怀古","theme2":["送别"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","酒","雨"],"cats":{"抒情":["怀古"],"四季":["夏天"]},"theme_conf":0.552},{"uid":"4e519eda-bd1c-4705-982e-b96f19b1a67f","title":"汉阴吊崔员外坟","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["远别望有归，叶落望春晖。","所痛泉路人，一去无还期。","荒坟遗汉阴，坟树啼子规。","存没抱冤滞，孤魂意何依。","岂无骨肉亲，岂无深相知。","曝露不复问，高名亦何为。","相携恸君罢，春日空迟迟。"],"theme":"悼亡挽歌","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["孤独","悼亡","感恩"],"四季":["春天"]},"theme_conf":0.99},{"uid":"eaf1094e-b116-4d91-819b-df1a80e1c991","title":"月蚀诗","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["新天子即位五年，岁次庚寅。","斗柄插子，律调黄钟。","森森万木夜僵立，寒气赑屭顽无风。","烂银盘从海底出，出来照我草屋东。","天色绀滑凝不流，冰光交贯寒朣胧。","初疑白莲花，浮出龙王宫。","八月十五夜，比并不可双。","此时怪事发，有物吞食来。","轮如壮士斧斫坏，桂似雪山风拉摧。","百炼镜，照见胆。","平地埋寒灰，火龙珠。","飞出脑，却入蚌蛤胎。","摧环破璧眼看尽，当天一搭如煤炲。","磨踪灭迹须臾间，便似万古不可开。","不料至神物，有此大狼狈。","星如撒沙出，争头事光大。","奴婢炷暗灯，揜菼如玳瑁。","今夜吐燄长如虹，孔隙千道射户外。","玉川子，涕泗下。","中庭独自行，念此日月者。","太阴太阳精，皇天要识物。","日月乃化生，走天汲汲劳四体。","与天作眼行光明，此眼不自保。","天公行道何由行，吾见阴阳家有说。","望日蚀月月光灭，朔月掩日日光缺。","两眼不相攻，此说吾不容。","又孔子师老子云，五色令人目盲。","吾恐天似人，好色即丧明。","幸且非春时，万物不娇荣。","青山破瓦色，绿水冰峥嵘。","花枯无女艳，鸟死沈歌声。","顽冬何所好，偏使一目盲。","传闻古老说，蚀月虾蟇精。","径圆千里入汝腹，汝此痴骸阿谁生。","可从海窟来，便解缘青冥。","恐是眶睫间，揜塞所化成。","黄帝有二目，帝舜重瞳明。","二帝悬四目，四海生光辉。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受虫豸欺。","长嗟白兔捣灵药，恰似有意防奸非。","药成满臼不中度，委任白兔夫何为。","忆昔尧为天，十日烧九州。","金烁水银流，玉煼丹砂焦。","六合烘为窑，尧心增百忧。","帝见尧心忧，勃然发怒决洪流。","立拟沃杀九日妖，天高日走沃不及。","但见万国赤子𧥄𧥄生鱼头，此时九御导九日。","争持节幡麾幢旒，驾车六九五十四头蛟螭虬。","掣电九火辀，汝若蚀开齱齵轮。","御辔执索相爬钩，推荡轰訇入汝喉。","红鳞燄鸟烧口快，翎鬣倒侧声醆邹。","撑肠拄肚礧傀如山丘，自可饱死更不偷。","不独填饥坑，亦解尧心忧。","恨汝时当食，藏头𢬍脑不肯食。","不当食，张唇哆觜食不休。","食天之眼养逆命，安得上帝请汝刘。","呜呼！人养虎，被虎啮。","天媚蟇，被蟇瞎。","乃知恩非类，一一自作孽。","吾见患眼人，必索良工诀。","想天不异人，爱眼固应一。","安得常娥氏，来习扁鹊术。","手操舂喉戈，去此睛上物。","其初犹朦胧，既久如抹漆。","但恐功业成，便此不吐出。","玉川子又涕泗下，心祷再拜额榻砂土中。","地上虮虱臣仝告愬帝天皇，臣心有铁一寸。","可刳妖蟇痴肠，上天不为臣立梯磴。","臣血肉身，无由飞上天。","扬天光，封词付与小心风。","𩙥排阊阖入紫宫，密迩玉几前擘坼。","奏上臣仝顽愚胸，敢死横干天。","代天谋其长，东方苍龙角。","插戟尾捭风，当心开明堂。","统领三百六十鳞虫，坐理东方宫。","月蚀不救援，安用东方龙。","南方火鸟赤泼血，项长尾短飞跋躠。","头戴井冠高逵枿，月蚀鸟宫十三度。","鸟为居停主人不觉察，贪向何人家。","行赤口毒舌，毒虫头上吃却月。","不啄杀，虚眨鬼眼明䆕䆷。","鸟罪不可雪，西方攫虎立踦踦。","斧为牙，凿为齿。","偷牺牲，食封豕。","大蟇一脔，固当软美。","见似不见，是何道理。","爪牙根天不念天，天若准拟错准拟。","北方寒龟被虵缚，藏头入壳如入狱。","虵筋束紧束破壳，寒龟夏鼈一种味。","且当以其肉充臛，死壳没信处。","唯堪支床脚不堪钻灼与天卜，岁星主福德。","官爵奉董秦，忍使黔娄生。","覆尸无衣巾，天失眼不吊。","岁星胡其仁，荧惑矍铄翁。","执法大不中，月明无罪过。","不纠蚀月虫，年年十月朝太微。","支卢谪罚何灾凶，土星与土性相背。","反养福德生祸害，到人头上死破败。","今夜月蚀安可会，太白真将军。","怒激锋铓生，恒州阵斩郦定进。","项骨脃甚春蔓菁，天唯两眼失一眼。","将军何处行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固应乐见天盲时，天若不肯信。","试唤臯陶鬼一问，一如今日。","三台文昌宫，作上天纪纲。","环天二十八宿，磊磊尚书郎。","整顿排班行，劒握他人将。","一四太阳侧，一四天市傍。","操斧代大匠，两手不怕伤。","弧矢引满反射人，天狼呀啄明煌煌。","痴牛与𫘤女，不肯勤农桑。","徒劳含淫思，旦夕遥相望。","蚩尤簸旗弄旬朔，始搥天鼓鸣珰琅。","枉矢能蛇行，眊目森森张。","天狗下舐地，血流何滂滂。","谲险万万党，架搆何可当。","眯目衅成就，害我光明王。","请留北斗一星相北极，指麾万国悬中央。","此外尽扫除，堆积如山冈。","赎我父母光，当时常星没。","殒雨如迸浆，似天会事发。","叱喝诛奸强，何故中道废。","自遗今日殃，善善又恶恶。","郭公所以亡，愿天神圣心。","无信他人忠，玉川子词讫。","风色紧格格，近月黑暗边。","有似动劒戟，须臾痴蟇精。","两吻自决坼，初露半个璧。","渐吐满轮魄，众星尽原赦。","一蟇独诛磔，腹肚忽脱落。","依旧挂穹碧，光彩未苏来。","惨澹一片白，奈何万里光。","受此吞吐厄，再得见天眼。","感荷天地力，或问玉川子。","孔子修春秋，二百四十年。","月蚀尽不收，今子咄咄词。","颇合孔意不，玉川子笑荅。","或请听逗留，孔子父母鲁。","讳鲁不讳周，书外书大恶。","故月蚀不见收，予命唐天。","口食唐土，唐礼过三。","唐乐过五，小犹不说。","大不可数，灾沴无有小大瘉。","安得引衰周，研核其可否。","日分昼，月分夜。","辨寒暑，一主刑。","二主德，政乃举。","孰为人面上，一目偏可去。","愿天完两目，照下万方土。","万古更不瞽，万万古。","更不瞽，照万古。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["幽峭","豪放"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["月","夏","冬"],"cats":{"抒情":["思念","伤感"],"四季":["夏天","冬天"],"天气":["月亮","星星"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.423},{"uid":"cpee91838ef68a70","title":"玉楼春","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["年年跃马长安市。","客舍似家家似寄。","青钱换酒日无何，红烛呼庐宵不寐。","易挑锦妇机中字。","难得玉人心下事。","男儿西北有神州，莫滴水西桥畔泪。"],"theme":"羁旅思乡","theme2":["送别"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","春","楼"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.535},{"uid":"f69bfe05-49ed-4c28-9f39-6aaae0e2aa74","title":"除草","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["草有害于人，曾何生阻修。","其毒甚蜂虿，其多弥道周。","清晨步前林，江色未散忧。","芒刺在我眼，焉能待高秋。","霜露一沾凝，蕙叶亦难留。","荷锄先童穉，日入仍讨求。","转致水中央，岂无双钓舟。","顽根易滋蔓，敢使依旧丘。","自兹藩篱旷，更觉松竹幽。","芟夷不可阙，疾恶信如雠。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","舟"],"cats":{"四季":["秋天"],"生活":["田野"]},"theme_conf":0.762},{"uid":"76d53cae-3896-4d5a-a8ee-5594289c037a","title":"玉华仙子歌","author":"李康成","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["紫阳仙子名玉华，珠盘承露饵丹砂。","转态凝情五云里，娇颜千岁芙蓉花。","紫阳彩女矜无数，遥见玉华皆掩嫭。","高堂初日不成妍，洛渚流风徒自怜。","璇阶霓绮阁，碧题霜罗幕。","仙娥桂树长自春，王母桃花未尝落。","上元夫人宾上清，深宫寂历厌层城。","解佩空怜郑交甫，吹箫不逐许飞琼。","溶溶紫庭步，渺渺瀛台路。","兰陵贵士谢相逢，济北风生尚回顾。","沧洲傲吏爱金丹，清心回望云之端。","羽盖霓裳一相识，传情写念长无极。","长无极，永相随。","攀霄历金阙，弄影下瑶池。","夕宿紫府云母帐，朝餐玄圃昆仑芝。","不学兰香中道绝，却教青鸟报相思。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["元宵","园林","江","楼","花","春"],"cats":{"抒情":["思念"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":0.734},{"uid":"cpf19c04dfb7e362","title":"祝英台近","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["翦红情，裁绿意，花信上钗股。","残日东风，不放岁华去。","有人添烛西窗，不眠侵晓，笑声转、新年莺语。","旧尊俎。","玉纤曾擘黄柑，柔香系幽素。","归梦湖边，还迷镜中路。","可怜千点吴霜，寒销不尽，又相对、落梅如雨。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","楼","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.65},{"uid":"c698e805-b9af-4674-9526-4cfe5df6217c","title":"资圣寺贲法师晚春茶会","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虚室昼常掩，心源知悟空。","禅庭一雨后，莲界万花中。","时节流芳暮，人天此会同。","不知方便理，何路出樊笼。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花"],"cats":{"四季":["春天"],"人生":["哲理"],"食物":["写茶"]},"theme_conf":0.96},{"uid":"d9b26a58-c9cb-4a98-8980-32df48b58348","title":"代九九","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年桃李月，颜色共花宜。","廻脸莲初破，低蛾柳竝垂。","望山多倚树，弄水爱临池。","远被登楼识，潜因倒影窥。","隔林徒想像，上砌转逶迤。","谩掷庭中果，虚攀墙外枝。","强持文玉佩，求结麝香缡。","阿母怜金重，亲兄要马骑。","把将娇小女，嫁与冶游儿。","自隐勤勤索，相要事事随。","每常同坐卧，不省暂参差。","才学羞兼妒，何言宠便移。","青春来易皎，白日誓先亏。","僻性嗔来见，邪行醉后知。","别床铺枕席，当面指瑕疵。","妾貌应犹在，君情遽若斯。","的成终世恨，焉用此宵为。","鸾镜灯前扑，鸳衾手下隳。","参商半夜起，琴瑟一声离。","努力新丛艳，狂风次第吹。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["豪放","婉约"],"mood":"慷慨","mood2":["愁怨"],"scene":["园林","夜","春"],"cats":{"抒情":["离别","闺怨"],"四季":["春天"],"天气":["写风"],"人物":["母亲"],"人生":["青春"]},"theme_conf":0.431},{"uid":"8bfe2432-2fa9-4733-a72a-45030c30a391","title":"竹溪","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["访竹越云崖，即林若溪绝。","宁知修干下，漠漠秋苔洁。","清光溢空曲，茂色临幽澈。","采摘愧芳鲜，奉君岁暮节。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","秋","江南"],"cats":{"四季":["秋天"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"db149aaa-c52b-4893-8b6b-7047bd84b92f","title":"石龛","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["熊罴哮我东，虎豹号我西。","我后鬼长啸，我前狨又啼。","天寒昏无日，山远道路迷。","驱车石龛下，仲冬见虹蜺。","伐竹者谁子，悲歌上云梯。","为官采美箭，五岁供梁齐。","苦云直簳尽，无以充提携。","奈何渔阳骑，飒飒惊烝黎。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":["冬"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"6c3450f9-3313-4b37-a250-3a2a65ffc6ea","title":"杂曲歌辞 春江曲二首 一","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["家寄征江岸，征人几岁游。","不知潮水信，每日到沙头。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["江河"]},"theme_conf":0.5},{"uid":"e7abc715-139b-4987-b57d-c7dacdd8fe6b","title":"相和歌辞 陌上桑","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["美女渭桥东，春还事蚕作。","五马如飞龙，青丝结金络。","不知谁家子，调笑来相谑。","妾本秦罗敷，玉颜艳名都。","绿条映素手，采桑向城隅。","使君且不顾，况复论秋胡。","寒螀爱碧草，鸣凤栖青梧。","托心自有处，但怪傍人愚。","徒令白日暮，高驾空踟蹰。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"欢愉","mood2":["孤寂"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"生活":["写桥"]},"theme_conf":0.41},{"uid":"f5584095-bed0-43b3-a45b-a437877d266c","title":"蒹葭","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["摧折不自守，秋风吹若何。","暂时花戴雪，几处叶沈波。","体弱春风早，丛长夜露多。","江湖后摇落，亦恐岁蹉跎。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江","雪","秋","春","夜"],"cats":{"四季":["春天","秋天"],"天气":["写风"]},"theme_conf":0.96},{"uid":"3dc49c20-317b-4ef3-9b79-8229b5925fd9","title":"大雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西蜀冬不雪，春农尚嗷嗷。","上天回哀眷，朱夏云郁陶。","执热乃沸鼎，纤𫄨成缊袍。","风雷飒万里，霈泽施蓬蒿。","敢辞茅苇漏，已喜黍豆高。","三日无行人，二江声怒号。","流恶邑里清，矧兹远江臯。","荒庭步鹳鹤，隐几望波涛。","沈疴聚药饵，顿忘所进劳。","则知润物功，可以贷不毛。","阴色静陇亩，劝耕自官曹。","四邻耒耜出，何必吾家操。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":["冲淡"],"mood":"悲怆","mood2":["欢愉"],"scene":["冬","雨","夏","雪","春"],"cats":{"四季":["春天","夏天","冬天"]},"theme_conf":1.0},{"uid":"40c2882a-7e79-4915-a77a-95acb7cc4715","title":"在郡秋怀二首 一","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋风入前林，萧瑟鸣高枝。","寂寞游子思，寤叹何人知。","宦成名不立，志存岁已驰。","五十而无闻，古人深所疵。","平生去外饰，直道如不羁。","未得操割效，忽复寒暑移。","物情自古然，身退毁亦随。","悠悠沧江渚，望望白云涯。","露下霜且降，泽中草离披。","兰艾若不分，安用馨香为。"],"theme":"亲情","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["励志"]},"theme_conf":0.519},{"uid":"6804729b-e657-4b19-b04a-300fcc6307ed","title":"唐明堂乐章 徵音","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["赫赫离精御炎陆，滔滔炽景开隆暑。","冀延神鉴俯兰尊，式表虔襟陈桂俎。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.59},{"uid":"7595547c-5365-491b-912f-ab12784afc15","title":"郊庙歌辞 享太庙乐章 大定舞","author":"李回","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["受天明命，敷佑下土。","化时以俭，卫文以武。","氛消夷夏，俗臻往古。","亿万斯年，形于律吕。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.97},{"uid":"cp8c89ce7125f188","title":"薄幸","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["艳真多态。","更的的，频回眄睐。","便认得、琴心相许，与写宜男双带。","记画堂、斜月朦胧，轻颦微笑娇无奈。","便翡翠屏开，芙蓉帐掩，与把香罗偷解。","自过了收灯后，都不见、踏青挑菜。","几回凭双燕，丁宁深意，往来翻恨重帘碍。","约何时再。","正春浓酒暖，人闲昼永无聊赖。","厌厌睡起，犹有花梢日在。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["清明","夜","花","春","酒","月"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.96},{"uid":"aaae5882-9b74-4b45-9bb5-9f773a721119","title":"杂曲歌辞 丽人行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有？翠微㔩叶垂鬓唇。","背后何所见？珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫𫘞之峰出翠釜，水晶之盘行素鳞。","犀筯厌饫久未下，鸾刀缕切空纷纶。","黄门飞鞚不动尘，御厨丝络送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"],"theme":"讽喻刺世","theme2":["讽喻刺世"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":["悲怆"],"scene":["雪","春","花"],"cats":{"四季":["春天"],"人物":["女子"]},"theme_conf":0.95},{"uid":"f0e9fe34-bbb9-4763-be64-4d7ea74b65ec","title":"省中春暮酬嵩阳焦道士见招","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朝花飞暝林，对酒伤春心。","流年催素发，不觉映华簪。","垂老遇知己，酬恩看寸阴。","如何紫芝客，相忆白云深。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["友情","思念"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.92},{"uid":"63397c51-1271-4a83-b1c3-a9daef8f406a","title":"元日","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高轩暧春色，邃阁媚朝光。","彤庭飞彩斾，翠幌曜明珰。","恭己临四极，垂衣驭八荒。","霜戟列丹陛，丝竹韵长廊。","穆矣熏风茂，康哉帝道昌。","继文遵后轨，循古鉴前王。","草秀故春色，梅艳昔年粧。","巨川思欲济，终以寄舟航。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["除夕","园林","楼","春"],"cats":{"四季":["春天"],"节日":["春节"]},"theme_conf":0.93},{"uid":"83a52b39-32c7-4394-b619-3ede125ed7fd","title":"春晚宴两相及礼官丽正殿学士探得风字","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["乾道运无穷，恒将人代工。","阴阳调历象，礼乐报玄穹。","介胄清荒外，衣冠佐域中。","言谈延国辅，词赋引文雄。","野霁伊川绿，郊明巩树红。","冕旒多暇景，诗酒会春风。"],"theme":"应制干谒","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":0.92},{"uid":"8558df16-4368-4416-9be3-fcc3350284f6","title":"南溪春耕","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["荷蓑趣南迳，戴胜鸣条枚。","溪雨有余润，土膏宁厌开。","沟塍落花尽，耒耜度云回。","谁道耦耕倦，仍兼胜赏催。","日长农有暇，悔不带经来。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"生活":["田野"]},"theme_conf":1.0},{"uid":"225f48d3-f1c0-4917-bbee-32aa163d5077","title":"赠张云容舞","author":"杨贵妃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["罗袖动香香不已，红蕖褭褭秋烟里。","轻云岭上乍摇风，嫩柳池边初拂水。"],"theme":"题画咏艺","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["花","秋"],"cats":{"四季":["秋天"],"天气":["写云"]},"theme_conf":0.93},{"uid":"b4f19aab-ff6a-40e2-b499-e43a45f7515c","title":"相和歌辞 子夜四时歌六首 春歌二首 一","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["青楼含日光，绿池起风色。","赠子同心花，殷勤此何极。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜"],"cats":{"抒情":["爱情"],"四季":["春天"]},"theme_conf":0.95},{"uid":"ee06ff18-c97c-41bf-8839-3e628f84df56","title":"春夜峡州田侍御长史津亭留宴","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北斗三更席，西江万里船。","杖藜登水榭，挥翰宿春天。","白发烦多酒，明星惜此筵。","始知云雨峡，忽尽下牢边。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夜","春"],"cats":{"四季":["春天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"480d7d0b-277f-4ad9-9829-e32b45bca9a7","title":"上李常侍","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["旌旗晓过大江西，七校前驱万队齐。","千里政声人共喜，三军令肃马前嘶。","恩沾境内风初变，春入城阴柳渐低。","桃李不须令更种，早知门下旧成蹊。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"cf854c36-62d7-4c54-ad3f-258cfedbb14a","title":"题郑十八著作虔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["台州地阔海冥冥，云水长和岛屿青。","乱后故人双别泪，春深逐客一浮萍。","酒酣嬾舞谁相拽，诗罢能吟不复听。","第五桥东流恨水，皇陂岸北结愁亭。","贾生对𫛳伤王傅，苏武看羊陷贼庭。","可念此翁怀直道，也沾新国用轻刑。","祢衡实恐遭江夏，方朔虚传是岁星。","穷巷悄然车马绝，案头干死读书萤。"],"theme":"送别","theme2":["咏物"],"style":"沉郁","style2":["豪放","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","夏","春","酒"],"cats":{"抒情":["友情","伤感"],"四季":["春天","夏天"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.53},{"uid":"cp99f30691ef4ed8","title":"汉宫春","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春已归来，看美人头上，袅袅春幡。","无端风雨，未肯收尽馀寒。","年时燕子，料今宵、梦到西园。","浑未办、黄柑荐酒，更传青韭堆盘。","却笑东风从此，便薰梅染柳，更没些闲。","闲时又来镜里，转变朱颜。","清愁不断，问何人、会解连环。","生怕见、花开花落，朝来塞雁先还。"],"theme":"节令风俗","theme2":["闲适隐逸","边塞征战"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"],"生活":["边塞"]},"theme_conf":0.85},{"uid":"c9dd1e11-5396-498a-a228-9afeb720dc41","title":"春日江村五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢递来三蜀，蹉跎有六年。","客身逢故旧，发兴自林泉。","过懒从衣结，频游任履穿。","藩篱无限景，恣意买江天。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"c1280e87-ac81-4f9b-9de5-377d6af38ae8","title":"月夜忆舍弟","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["戍鼓断人行，秋边一雁声。","露从今夜白，月是故乡明。","有弟皆分散，无家问死生。","寄书长不避，况乃未休兵。"],"theme":"亲情","theme2":["边塞征战","送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["夜","月","秋"],"cats":{"抒情":["思念","思乡"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.9},{"uid":"c2232345-1eea-47ab-b252-bc20d75b246f","title":"自江州司马授忠州刺史仰荷圣泽聊书鄙诚","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["炎瘴抛身远，泥涂索脚难。","网初鳞拨剌，笼久翅摧残。","雷电颁时令，阳和变岁寒。","遗簪承旧念，剖竹授新官。","乡觉前程近，心随外事宽。","生还应有分，西笑问长安。"],"theme":"应制干谒","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"动物":["写马"],"植物":["荷花"]},"theme_conf":0.78},{"uid":"9b4f2d56-6df4-4999-a82c-11283529dd51","title":"感遇十二首 一","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兰叶春葳蕤，桂华秋皎洁。","欣欣此生意，自尔为佳节。","谁知林栖者，闻风坐相悦。","草木有本心，何求美人折。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"人物":["女子"]},"theme_conf":0.509},{"uid":"b0a1ab7c-8206-4c5c-b333-d5410c429a19","title":"徐卿二子歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见徐卿二子生绝奇，感应吉梦相追随。","孔子释氏亲抱送，竝是天上麒麟儿。","大儿九龄色清澈，秋水为神玉为骨。","小儿五岁气食牛，满堂宾客皆回头。","吾知徐公百不忧，积善衮衮生公侯。","丈夫生儿有如此二雏者，名位岂肯悲微休。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"慷慨","mood2":["相思","悲怆"],"scene":["秋"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.617},{"uid":"018cab44-8167-40eb-8934-09667eb405da","title":"挽辞 一","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["珠碎眼前珍，花凋世外春。","未销心里恨，又失掌中身。","玉笥犹残药，香匳已染尘。","前哀将后感，无泪可沾巾。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":[],"scene":["花","春"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"]},"theme_conf":0.99},{"uid":"930a9bfb-ee77-4806-b03c-7bf63a9b070e","title":"宋州东登望题武陵驿","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["梁宋人稀鸟自啼，登舻一望倍含凄。","白骨半随河水去，黄云犹傍郡城低。","平陂战地花空落，旧苑春田草未齐。","明主频移虎符守，几时行县向黔黎。"],"theme":"咏史怀古","theme2":["羁旅思乡","咏物"],"style":"悲慨","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"人生":["战争"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"0710a746-8660-4bc1-b073-8ce51ac9f4d9","title":"梦李白二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浮云终日行，游子久不至。","三夜频梦君，情亲见君意。","告归常局促，苦道来不易。","江湖多风波，舟楫恐失坠。","出门搔白首，若负平生志。","冠盖满京华，斯人独顦顇。","孰云网恢恢，将老身反累。","千秋万岁名，寂莫身后事。"],"theme":"寄赠酬答","theme2":["民生疾苦","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["江","舟","秋","夜"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.75},{"uid":"3e971330-6463-4711-83aa-1d0da96589e1","title":"王夫子","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["王夫子，送君为一尉，东南三千五百里。","道途虽远位虽卑，月俸犹堪活妻子。","男儿口读古人书，束带敛手来从事。","近将徇禄给一家，远则行道佐时理。","行道佐时须待命，委身下位无为耻。","命苟未来且求食，官无卑高及远迩。","男儿上既未能济天下，下又不至饥寒死。","吾观九品至一品，其间气味都相似。","紫绶朱绂青布衫，颜色不同而已矣。","王夫子，别有一事欲劝君，遇酒逢春且欢喜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["惆怅"],"scene":["酒","春"],"cats":{"抒情":["离别"],"四季":["春天"],"人物":["老师"]},"theme_conf":0.749},{"uid":"731721e5-508d-452f-aaab-5b61f196de4c","title":"秋日二首 二","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["爽气澄兰沼，秋风动桂林。","露凝千片玉，菊散一丛金。","日岫高低影，云空点缀阴。","蓬瀛不可望，泉石且娱心。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"108dcb9b-73b4-4157-9269-32514cd5dc3e","title":"途中酬李少府赠别之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西上逢节换，东征私自怜。","故人今卧疾，欲别还留连。","举酒临南轩，夕阳满中筵。","宁知江上兴，乃在河梁偏。","行李多光辉，札翰忽相鲜。","谁谓岁月晚，交情尚贞坚。","终嗟州县劳，官谤复迍邅。","虽负忠信美，其如方寸悬。","连帅扇清风，千里犹眼前。","曾是趋藻镜，不应翻弃捐。","日来知自强，风气殊未痊。","可以加药物，胡为輙忧煎。","驱马出大梁，原野一悠然。","柳色感行客，云阴愁远天。","皇明烛幽遐，德泽普照宣。","鹓鸿列霄汉，燕雀何翩翩。","余亦惬所从，渔樵十二年。","种瓜漆园里，凿井卢门边。","去去勿重陈，生涯难勉旃。","或期遇春事，与尔复周旋。","投报空回首，狂歌谢比肩。"],"theme":"送别","theme2":[],"style":"豪放","style2":["冲淡","清新"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["友情","离别","伤感"],"四季":["春天"]},"theme_conf":0.679},{"uid":"138a236c-ce00-433b-8931-5460b685d243","title":"庭柳","author":"姚系","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["褭褭柳杨枝，当轩杂珮垂。","交阴总共密，分条各自宜。","因依似永久，揽结更伤离。","爱此阳春色，秋风莫遽吹。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春","秋"],"cats":{"四季":["春天","秋天"],"植物":["柳树"]},"theme_conf":0.556},{"uid":"b130568d-ec30-48db-ae64-7883c77f10b7","title":"郭处士击瓯歌","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["佶栗金虬石潭古，勺陂潋滟幽修语。","湘君宝马上神云，碎佩丛铃满烟雨。","吾闻三十六宫花离离，软风吹春星斗稀。","玉晨冷磬破昏梦，天露未干香著衣。","兰钗委坠垂云发，小响丁当逐回雪。","晴碧烟滋重叠山，罗屏半掩桃花月。","太平天子驻云车，龙𬬻勃郁双蟠拏。","宫中近臣抱扇立，侍女低鬟落翠花。","乱珠触续正跳荡，倾头不觉金乌斜。","我亦为君长叹息，缄情远寄愁无色。","莫沾香梦绿杨丝，千里春风正无力。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","雪"],"cats":{"抒情":["伤感"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.512},{"uid":"5c81fa14-3388-49bf-af9d-f425ec3b522d","title":"星名诗","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["虚怀何所欲，岁晏聊懒逸。","云翼谢翩翻，松心保贞实。","风秋景气爽，叶落井迳出。","陶然美酒酣，所谓幽人吉。","自当轻尺璧，岂复埽一室。","安用簪进贤，少微斯可必。"],"theme":"闲适隐逸","theme2":[],"style":"豪放","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["秋","酒"],"cats":{"四季":["秋天"],"天气":["星星"]},"theme_conf":0.9},{"uid":"dc01e269-75e6-4f68-8ce1-ea2615ba9719","title":"题思禅寺上方","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["溪口闻法鼓，停桡登翠屏。","攀云到金界，合掌开禅扃。","郁律众山抱，空蒙花雨零。","老僧指香楼，云是不死庭。","眇眇于越路，茫茫春草青。","远山喷百谷，缭绕驰东溟。","目极道何在，境照心亦冥。","𬴃然诸根空，破结如破瓶。","下视三界狭，但闻五浊腥。","山中有良药，吾欲隳天形。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"相思","mood2":["悲怆"],"scene":["花","山","春","雨","楼"],"cats":{"四季":["春天"],"人生":["哲理"]},"theme_conf":0.97},{"uid":"59e2fe4b-c925-4b3e-851d-e1c355c43b98","title":"关山月","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高高秋月明，北照辽阳城。","塞迥光初满，风多晕更生。","征人望乡思，战马闻鼙惊。","朔风悲边草，胡沙暗虏营。","霜凝匣中劒，风惫原上旌。","早晚谒金阙，不闻刁斗声。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["塞外","月","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写风","月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.595},{"uid":"051a3fc4-b7c9-4345-a255-2e7887b448e5","title":"相和歌辞 子夜四时歌四首 春歌","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["山连翠羽屏，草接烟华席。","望尽南飞燕，佳人断信息。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜"],"cats":{"四季":["春天"],"人物":["女子"]},"theme_conf":0.92},{"uid":"cp17149d5a941159","title":"瑞鹤仙","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["悄郊原带郭。","行路永，客去车尘漠漠。","斜阳映山落。","敛馀红、犹恋孤城栏角。","凌波步弱。","过短亭、何用素约。","有流莺劝我，重解绣鞍，缓引春酌。","不记归时早暮，上马谁扶，醒眠朱阁。","惊飙动幕。","扶残醉，绕红药。","叹西园、已是花深无地，东风何事又恶。","任流光过却。","犹喜洞天自乐。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春","鸟","酒","楼","塞外"],"cats":{"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.669},{"uid":"2204bcb6-175b-46ba-a5f1-60e7e86f526d","title":"冬月长安雨中见终南雪","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋节新已尽，雨疎露山雪。","西峰稍觉明，残滴犹未绝。","气侵瀑布水，冻著白云穴。","今朝灞浐鴈，何夕潇湘月。","想彼石房人，对雪扉不闭。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","雪","雨","月"],"cats":{"四季":["冬天"],"山水":["瀑布"],"天气":["写雨","写雪","月亮"]},"theme_conf":0.611},{"uid":"a032115c-e129-487b-b0cb-c8d15f01d2a7","title":"行路难","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["出门行路难，富贵安可期。","淮阴不免恶少辱，阮生亦作穷途悲。","颠倒英雄古来有，封侯却属屠沽儿。","长安车马随轻肥，青云宾从纷交驰。","白眼向人多意气，宰牛烹羊如折葵。","䜩乐宁知白日短，时时醉拥双蛾眉。","扬雄闭门空读书，门前碧草春离离。","不如拂衣且归去，世上浮名徒尔为。"],"theme":"羁旅思乡","theme2":["送别"],"style":"豪放","style2":["婉约"],"mood":"慷慨","mood2":["悲怆","欢愉"],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["读书"]},"theme_conf":0.5},{"uid":"3c1693fc-f4e6-43b7-a66f-6379c3a26eef","title":"长相思","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长相思，在长安，络纬秋啼金井阑。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有渌水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.775},{"uid":"70b41da6-9b4d-4392-b0fb-23ef70a1cd78","title":"横吹曲辞 折杨柳","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["倡楼启曙扉，园柳正依依。","鸟鸣知岁隔，条变识春归。","露叶疑啼脸，风花乱舞衣。","攀折聊将寄，军中书信稀。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","楼","园林"],"cats":{"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"d8ff176a-ba69-4277-a54e-9e515bc19304","title":"相和歌辞 雁门太守行","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["黑云压城城欲摧，甲光向月金鳞开。","角声满天秋色里，塞上燕支凝夜紫。","半卷红旗临易水，霜重鼓寒声不起。","报君黄金台上意，提携玉龙为君死。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟","秋"],"cats":{"四季":["秋天"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.658},{"uid":"884a25ac-d492-45dc-aeb8-d1e7c987ff0a","title":"燕居","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋斋膏沐暇，旭日照轩墀。","露重芭蕉叶，香凝橘柚枝。","简书随吏散，宝骑与僧期。","报国得何力，流年已觉衰。"],"theme":"咏怀抒感","theme2":[],"style":"清新","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"a23b4c7c-255d-4a62-b221-4b62b42fcbcb","title":"将之京国赠薛员外","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["黄叶下空馆，寂寥寒雨愁。","平居岁华晏，络纬啼林幽。","节物凋壮志，咄嗟不能休。","空怀赵鞅叹，变化良无由。","所思杳何如，侧身仰皇州。","苍烟晦楚野，寒浪埋昭丘。","赵壹赋命薄，陈思多世忧。","翻然羡鱼鸟，畅矣山川游。","薛公龙泉姿，其气在斗牛。","南冠束秀发，白石劳悲讴。","圭衮照崇阅，文儒嗣箕裘。","旷然方寸地，霁海浮云舟。","澧浦一遗佩，郢南再悲秋。","叫阍路既阻，浩荡怀灵修。","莫奏武溪笛，且登仲宣楼。","亨通与否闭，物理相沈浮。","天子坐宣室，夔龙奉谟猷。","行当赐环去，岂作遗贤羞。"],"theme":"应制干谒","theme2":["山水田园"],"style":"冲淡","style2":["雄浑","旷达"],"mood":"孤寂","mood2":["愁怨","慷慨"],"scene":["舟","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.91},{"uid":"f99f99d1-0379-4ce5-a570-90e6b5db19b4","title":"太子纳妃太平公主出降","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙楼光曙景，鲁馆启朝扉。","艳日浓妆影，低星降婺辉。","玉庭浮瑞色，银牓藻祥徽。","云转花萦盖，霞飘叶缀旗。","雕轩回翠陌，宝驾归丹殿。","鸣珠佩晓衣，镂璧轮开扇。","华冠列绮筵，兰醑申芳宴。","环阶凤乐陈，玳席珍羞荐。","蝶舞袖香新，歌分落素尘。","欢凝欢懿戚，庆叶庆初姻。","暑阑炎气息，凉早吹疎频。","方期六合泰，共赏万年春。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","花","楼"],"cats":{"抒情":["闺怨"],"四季":["夏天"]},"theme_conf":0.65},{"uid":"cp839304eb1db0bb","title":"玉楼春","author":"晏殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿杨芳草长亭路。","年少抛人容易去。","楼头残梦五更钟，花底离情三月雨。","无情不似多情苦。","一寸还成千万缕。","天涯地角有穷时，只有相思无尽处。"],"theme":"送别","theme2":["爱情相思","羁旅思乡"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["楼","春"],"cats":{"抒情":["爱情","离别","思念","思乡"],"四季":["春天"]},"theme_conf":0.378},{"uid":"ea947281-09d2-4141-a645-d41ab8e32f8e","title":"天竺寺七叶堂避暑","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["郁郁复郁郁，伏热何时毕？","行入七叶堂，烦暑随步失。","簷雨稍霏微，窗风正萧瑟。","清宵一觉睡，可以销百疾。"],"theme":"哲理悟道","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"87589e47-69eb-4b30-8204-5678cb0c8636","title":"游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故窠思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰归百年内，唯愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何难哉，北斗不可斟。","夜静星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蟋蟋催寒碪。","立身计几悮，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧罔古今。","胡为不归欤，辜负匣中琴。","腰下是何物，牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山窅岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾宵汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分湮沈。","层城登云韶，王府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"恬淡","mood2":["愁怨","悲怆"],"scene":["秋","江","月","夜","鸟"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.292},{"uid":"6c71ef5d-2b99-4ece-b3db-deefc25bc346","title":"途中立春寄杨郇伯","author":"窦常","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浪迹终年客，惊心此地春。","风前独去马，泽畔耦耕人。","老大交情重，悲凉外物亲。","子云今在宅，应见柳条新。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.88},{"uid":"cp6c209a20f4de27","title":"醉蓬莱","author":"赵长卿","dynasty":"宋","section":"宋词","form":"词","paragraphs":["正火山槐夏，黛叶湘枝，荔子新摘。","千里驰驱，荐仙源佳席。","浪比龙晴，未输崖蜜，灿烂然红摘。","满贮雕盘，纤纤素手，丹苞新擘。","梨栗粗疏，带酸橘柚，凡品多般，总羞标格。","何以浓香，洗烦襟仙液。","为爱真妃，再三珍重，价倾城倾国。","玉骨冰肌，风流酝藉，直宜消得。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"欢愉","mood2":[],"scene":["酒","夏","花"],"cats":{"四季":["夏天"],"食物":["写酒","荔枝"]},"theme_conf":0.755},{"uid":"f61de6f0-8b47-4b5f-8344-b95849bd556d","title":"鼓吹曲辞 有所思","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["君子事行役，再空芳岁期。","美人旷延伫，万里浮云思。","园槿绽红艳，郊桑柔绿滋。","坐看长夏晚，秋月生罗帏。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约","豪放"],"mood":"相思","mood2":[],"scene":["夏","花","秋","月","园林"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"],"人物":["女子"]},"theme_conf":0.524},{"uid":"bcad32a8-54b7-4b67-b811-bb0f46d1428b","title":"驾幸新丰温泉宫献诗三首 一","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["三冬季月景[龙]年，万乘观风出灞川。","遥看电跃龙为马，回瞩霜原玉作田。"],"theme":"应制干谒","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","月"],"cats":{"四季":["冬天"]},"theme_conf":0.99},{"uid":"31bc78e4-ece6-4a4f-b5bb-a8c00df6c620","title":"杂曲歌辞 鸣雁行","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动地来，吹起沙上声。","闺中有边思，玉筯此时横。","莫怕儿女恨，主人烹不鸣。"],"theme":"羁旅思乡","theme2":["闺情宫怨","亲情"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"],"天气":["写风"],"动物":["写鸟"]},"theme_conf":0.41},{"uid":"5f444f7d-1c9a-42c5-a2dd-1dda1aac432a","title":"望送魏征葬","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阊阖总金鞍，上林移玉辇。","野郊怆新别，河桥非旧饯。","惨日映峰沈，愁云随盖转。","哀笳时断续，悲旌乍舒卷。","望望情何极，浪浪泪空泫。","无复昔时人，芳春共谁遣。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁","绮丽"],"mood":"悲怆","mood2":["愁怨","相思"],"scene":["春","山"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"41d292d2-b752-4c30-8b6b-7b7380f2f9bd","title":"赋得","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住层城临汉苑，[心]随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时返斾勒燕然。"],"theme":"咏物","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","月","鸟"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.39},{"uid":"49016fc5-51cc-4d01-896d-a6e14768ce6e","title":"横吹曲辞 紫骝马","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["紫骝行且嘶，双飜碧玉蹄。","临流不肎渡，似惜锦障泥。","白雪关山远，黄云海树迷。","挥鞭万里去，安得念春闺。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["雪","春","塞外","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.358},{"uid":"2ca1001f-fdbb-40f3-8338-ded648912642","title":"晚春闲居杨工部寄诗杨常州寄茶同到因以长句荅之","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宿酲寂寞眠初起，春意阑珊日又斜。","劝我加餐因早笋，恨人休醉是残花。","闷吟工部新来句，渴饮毗陵远到茶。","兄弟东西官职冷，门前车马向谁家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["冲淡","清新"],"mood":"恬淡","mood2":["孤寂","愁怨"],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.9},{"uid":"1aaa5f58-ec89-4cdc-b96a-2717e03edf95","title":"挽辞 二","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["艳质同芳树，浮危道略同。","正悲春落实，又苦雨伤丛。","秾丽今何在？飘零事已空。","沈沈无问处，千载谢东风。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"]},"theme_conf":0.99},{"uid":"c8e50d0a-dd19-4fa2-b07e-95882090e9d7","title":"横吹曲辞 折杨柳 一","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杨柳多短枝，短枝多别离。","赠远累攀折，柔条安得垂。","青春有定节，离别无定时。","但恐人别促，不怨来迟迟。","莫言短枝条，中有长相思。","朱颜与绿杨，幷在别离期。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人生":["青春"],"植物":["柳树"]},"theme_conf":0.753},{"uid":"2f37297b-77d5-412b-bc73-105bfa4d011d","title":"蜀先主庙","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天地英雄气，千秋尚凛然。","势分三足鼎，业复五铢钱。","得相能开国，生儿不象贤。","凄凉蜀故妓，来舞魏宫前。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"82ed411b-a2e4-4e0b-94fb-b73c350e7f6f","title":"相和歌辞 相逢行二首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["朝骑五花马，谒帝出银台。","秀色谁家子，云车珠箔开。","金鞭遥指点，玉勒近迟回。","夹毂相借问，疑从天上来。","怜肠愁欲断，斜日复相催。","下车何轻盈，飘然似落梅。","邀入青绮门，当歌共衔杯。","衔杯映歌扇，似月云中见。","相见不相亲，不如不相见。","相见情已深，未语可知心。","胡为守空闺，孤眠愁锦衾。","锦衾与罗帏，缠緜会有时。","春风正澹荡，暮雨来何迟？","愿因三青鸟，更报长相思。","光景不待人，须臾发成丝。","当年失行乐，老去徒伤悲。","持此道密意，无令旷佳期。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["春","酒"],"cats":{"抒情":["爱情","思念","伤感","孤独","闺怨"],"四季":["春天"]},"theme_conf":0.404},{"uid":"22063a2e-01e8-4550-ade4-56e43fe96672","title":"春日江村五首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["扶病垂朱绂，归休步紫苔。","郊扉存晚计，幕府媿群材。","燕外晴丝卷，鸥边水叶开。","隣家送鱼鼈，问我数能来。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":0.709},{"uid":"a0588679-461e-449d-9758-01d6bc1f6e9d","title":"句","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寒食少天气，东风多柳花。","小桃知客意，春尽始开花。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.67},{"uid":"6f50b001-74c4-4c85-a2a3-626560010c86","title":"长安客舍赠李行父明府","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["藏器待时少，知人自古难。","遂令丹穴凤，晚食金琅玕。","谁谓兵戈际，鸣琴方一弹。","理烦善用简，济猛能兼宽。","夙夜念黎庶，寝兴非宴安。","洪波未静壑，何树不惊鸾。","凫舄傍京辇，甿心悬灌坛。","高槐暗苦雨，长剑生秋寒。","旅食还为客，饥年亦尽欢。","亲劳携斗水，往往救泥蟠。","但恐酬明义，蹉跎芳岁阑。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["秋","夜","山","雨"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.78},{"uid":"0fd231d3-c040-4a2c-9b0b-5b96297cb884","title":"别李明府","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["宠光五世要青组，出入珠宫引箫鼓。","醉舞雄王玳瑁床，娇嘶骏马珊瑚柱。","胡儿夹鼓越婢随，行捧玉盘尝荔枝。","罗山道士请人送，林邑使臣调象骑。","爱君一身游上国，阙下名公如旧识。","万里初怀印绶归，湘江过尽岭花飞。","五侯焦石烹江笋，千户沈香染客衣。","别后想君难可见，苍梧云里空山县。","汗苑芳菲入夏阑，待君障日蒲葵扇。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["花","山","夏","江"],"cats":{"抒情":["离别"],"四季":["夏天"],"食物":["荔枝"]},"theme_conf":0.55},{"uid":"cpc4cd8e0d3c721d","title":"摸鱼儿","author":"朱嗣发","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对西风、鬓摇烟碧，参差前事流水。","紫丝罗带鸳鸯结，的的镜盟钗誓。","浑不记、漫手织回文，几度欲心碎。","安花著蒂。","奈雨覆云翻，情宽分窄，石上玉簪脆。","朱楼外。","愁压空云欲坠。","月痕犹照无寐。","阴晴也只随天意。","枉了玉消香碎。","君且醉。","君不见、长门青草春风泪。","一时左计。","悔不早荆钗，暮天修竹，头白倚寒翠。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"天气":["写风"]},"theme_conf":0.733},{"uid":"6531a82b-78e5-4182-b59d-01cb0031652f","title":"茶中杂咏 茶坞","author":"皮日休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闲寻尧氏山，遂入深深坞。","种荈已成园，栽葭宁记亩。","石洼泉似掬，岩罅云如缕。","好是夏初时，白花满烟雨。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","夏","雨"],"cats":{"四季":["夏天"],"食物":["写茶"]},"theme_conf":0.86},{"uid":"cp1dbe46a9ca1ac2","title":"绮罗香","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["做冷欺花，将烟困柳，千里偷催春暮。","尽日冥迷，愁里欲飞还住。","惊粉重、蝶宿西园，喜泥润、燕归南浦。","最妨它、佳约风流，钿车不到杜陵路。","沈沈江上望极，还被春潮晚急，难寻官渡。","隐约遥峰，和泪谢娘眉妩。","临断岸、新绿生时，是落红、带愁流处。","记当日、门掩梨花，翦灯深夜语。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["花","春","江","夜"],"cats":{"抒情":["离别","伤感"],"四季":["春天"]},"theme_conf":1.0},{"uid":"cpbf1334f01df25f","title":"少年游","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["长安古道马迟迟。","高柳乱蝉栖。","夕阳岛外，秋风原上，目断四天垂。","归云一去无踪迹，何处是前期。","狎兴生疏，酒徒萧索，不似去年时。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","酒"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.72},{"uid":"0ef99715-15ba-4586-98d0-bb90aece4b71","title":"杂曲歌辞 鸣雁行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["七月朔方雁心苦，联影翻空落南土。","八月江南阴复晴，浮云绕天难夜行。","羽翼劳痛心虚惊，一声相呼百处鸣。","楚童夜宿烟波侧，沙上布罗连草色。","月暗风悲欲下天，不知何处容栖息？","楚童胡为伤我神，尔不曾作远行人。","江南羽族本不少，宁得网罗此客鸟。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["鸟","江","江南"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.745},{"uid":"f87f89bd-21a1-4861-9590-eb27a2888aa2","title":"郊庙歌辞 梁太庙乐舞辞 大合舞","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["於穆皇祖，濬哲雍熙。","美溢中夏，化被南陲。","后稷累德，公刘创基。","肇兴九庙，乐合来仪。"],"theme":"应制干谒","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.93},{"uid":"0a96850c-2e49-4c26-879d-a84eae5d8b9e","title":"乐天池馆夏景方妍白莲初开彩舟空泊唯邀缁侣因以戏之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["池馆今正好，主人何寂然。","白莲方出水，碧树未鸣蝉。","静室宵闻磬，斋厨晚绝烟。","蕃僧如共载，应不是神仙。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["夏","园林","舟"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.82},{"uid":"4925c861-b0f8-4b2f-923e-9cba2df1323e","title":"洛阳女儿行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["洛阳女儿对门居，才可容颜十五余。","良人玉勒乘骢马，侍女金盘鲙鲤鱼。","画阁朱楼尽相望，红桃绿柳垂簷向。","罗帏送上七香车，宝扇迎归九华帐。","狂夫富贵在青春，意气骄奢剧季伦。","自怜碧玉亲教舞，不惜珊瑚持与人。","春窗曙灭九微火，九微片片飞花璅。","戏罢曾无理曲时，妆成秪是薰香坐。","城中相识尽繁华，日夜经过赵李家。","谁怜越女颜如玉，贫贱江头自浣纱。"],"theme":"闺情宫怨","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["春","楼","花"],"cats":{"抒情":["思乡","闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.396},{"uid":"35d74803-47e5-41c2-9631-a9ef240491e0","title":"赠普门上人","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["支公身欲老，长在沃州多。","慧力堪传教，禅功久伏魔。","山云随坐夏，江草伴头陀。","借问回心后，贤愚去几何。"],"theme":"佛道禅颂","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","山","江"],"cats":{"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.88},{"uid":"cpab03d04d6ede46","title":"谢金莲诗酒红梨花・仙吕/点绛唇","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["恰才个满目繁华，可又早落红飞下，春潇洒。","苔径轻踏，香衬凌波袜。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","酒","春"],"cats":{"抒情":["感恩"],"四季":["春天"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"811a5f9e-0df5-46f1-a587-0d4df7bca5a0","title":"无题四首 二","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["飒飒东风细雨来，芙蓉塘外有轻雷。","金蟾啮鏁烧香入，玉虎牵丝汲井回。","贾氏窥帘韩掾少，宓妃留枕魏王才。","春心莫共花争发，一寸相思一寸灰。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雨","春","花"],"cats":{"抒情":["爱情","思念"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.713},{"uid":"50321411-cd02-476d-bb62-f1e3f753481d","title":"早春夜宴","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九春开上节，千门敞夜扉。","兰灯吐新燄，桂魄朗圆辉。","送酒惟须满，流杯不用稀。","务使霞浆兴，方乘泛洛归。"],"theme":"节令风俗","theme2":["送别","山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["夜","春","酒"],"cats":{"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.82},{"uid":"f2df70bb-0958-4bc6-bef3-593eae26d678","title":"田家秋日送友","author":"于良史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["苍茫日初宴，遥野云初收。","残雨北山里，夕阳东渡头。","舟依渔溓合，水入田家流。","何意君迷驾，山林应有秋。"],"theme":"山水田园","theme2":["送别"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["太阳"],"生活":["田野"]},"theme_conf":0.412},{"uid":"7cebb127-e2e6-423d-a597-340dc11ecfdf","title":"红叶","author":"唐彦谦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["无处不飘扬，高楼临道旁。","素娥前夕月，青女夜来霜。","宿雨随时润，秋晴著物光。","幽怀长若此，病眼更相妨。","蜀纸裁深色，燕脂落靓粧。","低丛侵小阁，倒影入回塘。","谢朓留霞绮，甘宁弃锦张。","何人休远道，是处有斜阳。","薜荔垂书幌，梧桐坠井床。","晚风生旅馆，寒籁近僧房。","桂绿明淮甸，枫丹照楚乡。","鴈疎临鄠杜，蝉急傍潇湘。","树异桓宣武，园非顾辟疆。","茂陵愁卧客，不自保危肠。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新","沉郁"],"mood":"愁怨","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.7},{"uid":"3d4e85e1-0bed-4e7b-8bb6-81677d9f448d","title":"杂曲歌辞 轻薄行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["玉鞭金镫骅骝蹏，横眉吐气如虹霓。","五陵春暖芳草齐，笙歌到处花成泥。","日沈月上且鬬鸡，醉来莫问天高低。","伯阳道德何涕唾，仲尼礼乐徒卑栖。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","月","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.65},{"uid":"16b8caaa-e64d-4ad8-839f-8627c0a40f62","title":"送魏八","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["更沽淇上酒，还泛驿前舟。","为惜故人去，复怜嘶马愁。","云山行处合，风雨兴中秋。","此路无知己，明珠莫暗投。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","中秋","酒","舟","秋"],"cats":{"抒情":["友情","伤感"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.731},{"uid":"3fff5496-d24c-48c6-9c61-0d8925b663fe","title":"登蒲州逍遥楼","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长榆息烽火，高柳静风尘。","卜征巡九洛，展豫出三秦。","昔是潜龙地，今为上理辰。","时平乘道泰，聊赏遇年春。","黄河分地络，飞观接天津。","一览遗芳翰，千载肃如神。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.565},{"uid":"cpace79dfe6e198c","title":"踏莎行","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["候馆梅残，溪桥柳细。","草熏风暖摇征辔。","离愁渐远渐无穷，迢迢不断如春水。","寸寸柔肠，盈盈粉泪。","楼高莫近危阑倚。","平芜尽处是春山，行人更在春山外。"],"theme":"山水田园","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","山","楼"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.6},{"uid":"d5da9d7d-1e52-4992-8be5-73e556b07e0b","title":"清平调 一","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"theme":"游仙梦幻","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.513},{"uid":"4a9c46cb-b60d-439c-885e-c4dc8522940f","title":"送顾况泗上觐叔父","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴乡岁贡足嘉宾，后进之中见此人。","别业更临洙泗上，拟将书卷对残春。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江南"],"cats":{"四季":["春天"],"人物":["父亲"],"人生":["读书"]},"theme_conf":0.671},{"uid":"8098529a-3316-4f89-a17f-6e6a2ce52d59","title":"咏桃","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["禁苑春晖丽，花蹊绮树妆。","缀条深浅色，点露参差光。","向日分千笑，迎风共一香。","如何仙岭侧，独秀隐遥芳。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["花","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"e2740c24-d6db-4562-81ff-be9f0bfe16e0","title":"闲园即事寄暕公","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["欲就东林寄一身，尚怜儿女未成人。","柴门客去残阳在，药圃虫喧秋雨频。","近水方同梅市隐，曝衣多笑阮家贫。","深山兰若何时到，羡与闲云作四邻。"],"theme":"闲适隐逸","theme2":["闲适隐逸","山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","秋","雨"],"cats":{"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.78},{"uid":"fbb109b7-3b66-4f82-a111-97892b26fa7a","title":"喜闻官军已临贼境二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡虏潜京县，官军拥贼壕。","鼎鱼犹假息，穴蚁欲何逃。","帐殿罗玄冕，辕门照白袍。","秦山当警跸，汉苑入旌旄。","路失羊肠险，云横雉尾高。","五原空壁垒，八水散风涛。","今日看天意，游魂贷尔曹。","乞降那更得，尚诈莫徒劳。","元帅归龙种，司空握豹韬。","前军苏武节，左将吕虔刀。","兵气回飞鸟，威声没巨鼇。","戈鋋开雪色，弓矢尚秋毫。","天步艰方尽，时和运更遭。","谁云遗毒螫，已是沃腥臊。","睿想丹墀近，神行羽卫牢。","花门腾绝漠，拓羯渡临洮。","此辈感恩至，羸俘何足操。","锋先衣染血，骑突劒吹毛。","喜觉都城动，悲怜子女号。","家家卖钗钏，只待献春醪。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","塞外","秋","春","酒"],"cats":{"抒情":["感恩"],"四季":["春天","秋天"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cp66426d06db2e64","title":"夜合花","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳暝河桥，莺晴台苑，短策频惹春香。","当时夜泊，温柔便入深乡。","词韵窄，酒杯长。","翦蜡花、壶箭催忙。","共追游处，凌波翠陌，连棹横塘。","十年一梦凄凉。","似西湖燕去，吴馆巢荒。","重来万感，依前唤酒银罂。","溪雨急，岸花狂。","趁残鸦、飞过苍茫。","故人楼上，凭谁指与，芳草斜阳。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":["雄浑","豪放"],"mood":"愁怨","mood2":[],"scene":["花","酒","夜","鸟","江南","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.558},{"uid":"8baa7c35-9afb-40bf-b5e4-41d9895e2710","title":"相思","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["红豆生南国，秋来发故枝。","愿君多采撷，此物最相思。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"]},"theme_conf":0.714},{"uid":"e110c62b-f130-4558-b4af-8282d6a2a5de","title":"酬杨司业十二兄早秋述情见寄","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白发故人少，相逢意弥远。","往事共销沈，前期各衰晚。","昨来遇弥苦，已复云离𪩘。","秋草古胶庠，寒沙废宫苑。","知心岂忘鲍，咏怀难和阮。","壮志日萧条，那能竞朝幰。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.94},{"uid":"19a657e3-0b2b-4c6b-b69b-14057f346891","title":"从军行","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["丈夫四方志，结发事远游。","远游历燕蓟，独戍边城陬。","西风垅水寒，明月关山悠。","酬恩仗孤剑，十年弊貂裘。","封侯属何人，磋跎雪盈头。","老马思故枥，穷鳞忆深流。","弹铗动深慨，浩歌气横秋。","报国期努力，功名良见收。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"慷慨","mood2":["孤寂"],"scene":["月","秋","雪"],"cats":{"抒情":["孤独","爱国"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.641},{"uid":"17097de0-b154-43fd-9213-91d38353eb8c","title":"杂曲歌辞 桃花行 五","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红蕚竞妍春苑曙，粉茸新向御筵开。","长年愿奉西王宴，近侍慙无东朔才。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春"],"cats":{"抒情":["思乡"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"533e2212-7d88-4b6d-9f5f-a8d42f4d3627","title":"耳聋","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["生年鹖冠子，叹世鹿皮翁。","眼复几时暗，耳从前月聋。","猨鸣秋泪缺，雀噪晚愁空。","黄落惊山树，呼儿问朔风。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","月","冬","山"],"cats":{"抒情":["伤感"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.88},{"uid":"7242db95-41ec-4932-af0b-3d5d9b362775","title":"春日书情赠别司空曙","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["壮志随年尽，谋身意未安。","风尘交契阔，老大别离难。","腊近晴多暖，春迟夜却寒。","谁堪少兄弟，三十又无官。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["离别"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":0.875},{"uid":"cp870b6030df582d","title":"高阳台","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["接叶巢莺，平波卷絮，断桥斜日归船。","能几番游，看花又是明年。","东风且伴蔷薇住，到蔷薇、春已堪怜。","更凄然。","万绿西泠，一抹荒烟。","当年燕子知何处，但苔深韦曲，草暗斜川。","见说新愁，如今也到鸥边。","无心再续笙歌梦，掩重门、浅醉闲眠。","莫开帘。","怕见飞花，怕听啼鹃。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["春","鸟"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.82},{"uid":"d8d4a2e2-28ae-42d1-84ce-306a9b4df039","title":"听唱赤白桃李花","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["赤白桃李花，先皇在时曲。","欲向西宫唱，西宫[宫]树绿。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.7},{"uid":"e82ca232-9a56-4a68-acaa-b6e622fe2777","title":"登叶县故城谒沈诸梁庙","author":"李百药","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["总辔临秋原，登城望寒日。","烟霞共掩映，林野俱萧瑟。","楚塞郁不穷，吴山高渐出。","客行殊未已，沐澡期终吉。","椒桂奠芳樽，风云下虚室。","馆宇肃而静，神心康且逸。","伊我非真龙，勿惊疲朽质。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","秋","酒"],"cats":{"抒情":["怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.548},{"uid":"50cd4ba1-47b5-476b-9b7c-1b3bba01cad6","title":"夏日原西避暑寄吟友","author":"齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["热烟疎竹古原西，日日乘凉此杖藜。","闲处雨声随霹雳，旱田人望隔虹霓。","蝉依独树干吟苦，鸟忆平川渴过齐。","别有相招好泉石，瑞花瑶草尽堪携。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂","恬淡"],"scene":["夏"],"cats":{"抒情":["友情","思念","孤独"],"四季":["夏天"],"天气":["彩虹","太阳"]},"theme_conf":0.88},{"uid":"3d2b033b-eceb-4425-a345-7116bcdb2f5a","title":"春日江村五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["农务村村急，春流岸岸深。","乾坤万里眼，时序百年心。","茅屋还堪赋，桃源自可寻。","艰难贱生理，飘泊到如今。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"47dbfc92-dd51-458f-859a-1953cde28460","title":"秋日作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居值秋节，此日更愁辛。","寂寞无一事，蒿莱通四邻。","闭门生白发，回首忆青春。","岁月不相待，交游随众人。","云霄何处托，愚直有谁亲。","举酒聊自劝，穷通信尔身。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["秋"],"cats":{"抒情":["思念","伤感","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"人生":["青春"]},"theme_conf":0.9},{"uid":"baccf46a-41c4-4a0f-b90f-37cc35b04a64","title":"子夜吴歌 秋歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏，良人罢远征。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","月"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"]},"theme_conf":0.576},{"uid":"96b213f7-21b6-47a8-936c-39dde6ca7969","title":"相和歌辞 櫂歌行","author":"徐坚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["櫂女饰银钩，新妆下翠楼。","霜丝青桂檝，兰栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣船过曲浦，飞帆越回流。","影入桃花浪，香飘杜若洲。","洲长殊未返，萧散云霞晚。","日下大江平，烟生归岸远。","岸远闻潮波，争途游戏多。","因声赵津女，来听采菱歌。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["写云"]},"theme_conf":0.579},{"uid":"a3aec75e-d67c-4a40-920a-c3ccbac03993","title":"秋日夔府咏怀奉寄郑监李宾客一百韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，群书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井为盐速，烧畬度地偏。","有时惊叠嶂，何处觅平川。","㶉𫛶双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎膻。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鹯。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出于畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比昆仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒为百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾著鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鳣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从众，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简为谁编。","行路难何有，招寻兴已专。","由来具飞檝，𫏐拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","𬬻峰生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","众香深黯黯，几地肃芊芊。","勇猛为心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"欢愉","mood2":["恬淡","孤寂"],"scene":["秋","山","鸟","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["女子"],"人生":["励志","战争"],"生活":["乡村","边塞"]},"theme_conf":0.95},{"uid":"49e8d65c-a254-42eb-9bb6-152ba3d3986e","title":"别韦五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["徒然酌桮酒，不觉散人愁。","相识仍远别，欲归翻旅游。","夏云满郊甸，明月照河洲。","莫恨征途远，东看漳水流。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","月","夏"],"cats":{"抒情":["离别","伤感"],"四季":["夏天"],"天气":["月亮"]},"theme_conf":0.721},{"uid":"df4de5cf-ac53-4137-b2be-34b163ec4d73","title":"相和歌辞 子夜冬歌","author":"薛耀","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["朔风扣群木，岩霜凋百草。","借问月中人，安得长不老。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"四季":["冬天"],"天气":["写风"]},"theme_conf":0.84},{"uid":"cpfefb3d1fd306d5","title":"惜黄花慢","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["送客吴皋。","正试霜夜冷，枫落长桥。","望天不尽，背城渐杳，离亭黯黯，恨水迢迢。","翠香零落红衣老，暮愁锁、残柳眉梢。","念瘦腰。","沈郎旧日，曾系兰桡。","仙人凤咽琼箫。","怅断魂送远，九辨难招。","醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。","素秋不解随船去，败红趁、一叶寒涛。","梦翠翘。","怨鸿料过南谯。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","花"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["写桥"],"植物":["菊花"]},"theme_conf":0.497},{"uid":"60de5a95-c758-49be-ad0a-380712d15cb3","title":"杂曲歌辞 少年行","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["射飞夸侍猎，行乐爱联镳。","荐枕青娥艳，鸣鞭白马骄。","曲房珠翠合，深巷管弦调。","日晚春风里，衣香满路飘。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"24f9e8b4-e32d-49e7-af89-50e05880b662","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["行云递崇高，飞雨霭而至。","潺潺石间溜，汩汩松上驶。","亢阳乘秋热，百谷皆已弃。","皇天德泽降，焦卷有生意。","前雨伤卒暴，今雨喜容易。","不可无雷霆，间作鼓增气。","佳声达中宵，所望时一致。","清霜九月天，髣髴见滞穗。","郊扉及我私，我圃日苍翠。","恨无抱瓮力，庶减临江费。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["雨","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"2ece861e-f4da-4663-9ca7-22ed69e049dd","title":"献刘济","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["草绿古燕州，莺声引独游。","雁归天北畔，春尽海西头。","向日花偏落，驰年水自流。","感恩知有地，不上望京楼。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"]},"theme_conf":0.92},{"uid":"cp266b10b82b6e56","title":"木兰花・玉楼春","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["秋千院落重帘暮。","彩笔闲来题绣户。","墙头丹杏雨馀花，门外绿杨风后絮。","朝云信断知何处。","应作襄王春梦去。","紫骝认得旧游踪，嘶过画桥东畔路。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","楼"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.565},{"uid":"5c676620-1448-4ee7-815d-35512077d8ad","title":"郑典设自施州归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾怜荥阳秀，冒暑初有适。","名贤慎所出，不肯妄行役。","旅兹殊俗远，竟以屡空迫。","南谒裴施州，气合无险僻。","攀援悬根木，登顿入天石。","青山自一川，城郭洗忧戚。","听子话此邦，令我心悦怿。","其俗则纯朴，不知有主客。","温温诸侯门，礼亦如古昔。","敕厨倍常羞，杯盘颇狼藉。","时虽属丧乱，事贵赏匹敌。","中宵惬良会，裴郑非远戚。","群书一万卷，博涉供务隙。","他日辱银钩，森疎见矛戟。","倒屣喜旋归，画地求所历。","乃闻风土质，又重田畴辟。","刺史似寇恂，列郡宜竞惜。","北风吹瘴疠，羸老思散策。","渚拂蒹葭塞，峤穿萝茑幂。","此身仗儿仆，高兴潜有激。","孟冬方首路，强饭取崖壁。","叹尔疲驽骀，汗沟血不赤。","终然备外饰，驾驭何所益。","我有平肩舆，前途犹准的。","翩翩入鸟道，庶脱蹉跌厄。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["幽峭","冲淡"],"mood":"欢愉","mood2":[],"scene":["塞外","冬","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","冬天"],"人生":["读书"],"生活":["边塞"]},"theme_conf":0.593},{"uid":"250fab5b-4a5c-47bd-8ef0-d9d82e14b16b","title":"亚父碎玉斗","author":"何儒亮","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["嬴女昔解网，楚王有遗躅。","破关既定秦，碎首闻献玉。","贞姿应刃散，清响因风续。","匪狥切泥功，将明怀璧辱。","莫量汉祖德，空受项君勗。","事去见前心，千秋渭水绿。"],"theme":"亲情","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"e4dc9fac-1160-45b6-8182-51829ac15f72","title":"河南白尹有喜崔宾客归洛兼见怀长句因而继和","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["几年侍从作名臣，却向青云索得身。","朝士忽为方外士，主人仍是眼中人。","双鸾游处天京好，五马行时海峤春。","遥羡光阴不虚掷，肯令丝竹暂生尘。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"1c084d0f-76cc-4294-bd80-4e8672338d39","title":"和梦游春诗一百韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔君梦游春，梦游仙山曲。","怳若有所遇，似惬平生欲。","因寻菖蒲水，渐入桃花谷。","到一红楼家，爱之看不足。","池流渡清泚，草嫩蹋绿蓐。","门柳暗全低，檐樱红半熟。","转行深深院，过尽重重屋。","乌龙卧不惊，青鸟飞相逐。","渐闻玉珮响，始辨珠履躅。","遥见窗下人，娉婷十五六。","霞光抱明月，莲艳开初旭。","缥缈云雨仙，氛氲兰麝馥。","风流薄梳洗，时世宽妆束。","袖輭异文绫，裾轻单丝縠。","裙腰银线压，梳掌金筐蹙。","带襭紫蒲萄，袴花红石竹。","凝情都未语，付意微相瞩。","眉敛远山青，鬟低片云绿。","帐牵翡翠带，被解鸳鸯襆。","秀色似堪餐，秾华如可掬。","半卷锦头席，斜铺绣腰褥。","朱唇素指匀，粉汗红緜扑。","心惊睡易觉，梦断魂难续。","笼委独栖禽，劒分连理木。","存诚期有感，誓志贞无黩。","京洛八九春，未曾花里宿。","壮年徒自弃，佳会应无复。","鸾歌不重闻，凤兆从兹卜。","韦门女清贵，裴氏甥贤淑。","罗扇夹花灯，金鞍攒绣毂。","既倾南国貌，遂坦东床腹。","刘阮心渐忘，潘杨意方睦。","新修履信第，初食尚书禄。","九酝备圣贤，八珍穷水陆。","秦家重萧史，彦辅怜卫叔。","朝馔馈独盘，夜醪倾百斛。","亲宾盛辉赫，妓乐纷晔煜。","宿醉才解酲，朝欢俄枕曲。","饮过君子争，令甚将军酷。","酩酊歌鹧鸪，颠狂舞鸲鹆。","月流春夜短，日下秋天速。","谢傅隙过驹，萧娘风过烛。","全凋蕣花折，半死梧桐秃。","暗镜对孤鸾，哀弦留寡鹄。","凄凄隔幽显，冉冉移寒燠。","万事此时休，百身何处赎。","提携小儿女，将领旧姻族。","再入朱门行，一傍青楼哭。","枥空无廐马，水涸失池[鹜]。","摇落废井梧，荒凉故篱菊。","莓苔上几阁，尘土生琴筑。","舞榭缀蟏蛸，歌梁聚蝙蝠。","嫁分红粉妾，卖散苍头仆。","门客思徬徨，家人泣吚噢。","心期正萧索，宦序仍拘跼。","怀策入崤函，驱车辞郏鄏。","逢时念既济，聚学思大畜。","端详筮仕蓍，磨拭穿杨镞。","始从讐校职，首中贤良目。","一拔侍瑶墀，再升纡绣服。","誓酬君王宠，愿使朝廷肃。","密勿奏封章，清明操宪牍。","鹰鞲中病下，豸角当邪触。","纠谬静东周，申冤动南蜀。","危言诋阍寺，直气忤钧轴。","不忍曲作钩，乍能折为玉。","扪心无媿畏，腾口有谤讟。","只要明是非，何曾虞祸福。","车摧太行路，劒落酆城狱。","襄汉问修途，荆蛮指殊俗。","谪为江府掾，遣事荆州牧。","趋走谒麾幢，喧烦视鞭朴。","簿书常自领，缧囚每亲鞫。","竟日坐官曹，经旬旷休沐。","宅荒渚宫草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天际辞骨肉。","鹤病翅羽垂，兽穷爪牙缩。","行看须间白，谁劝杯中绿。","时伤大野麟，命问长沙𫛳。","夏梅山雨渍，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韵，是我心所蓄。","既去诚莫追，将来幸前勗。","欲除忧恼病，当取禅经读。","须悟事皆空，无令念将属。","请思游春梦，此梦何闪倏。","艳色即空花，浮生乃焦谷。","良姻在嘉偶，顷克为单独。","入仕欲荣身，须臾成黜辱。","合者离之始，乐兮忧所伏。","愁恨僧祇长，欢荣刹那促。","觉悟因傍喻，迷执由当局。","膏明诱暗蛾，阳焱奔痴鹿。","贪为苦聚落，爱是悲林麓。","水荡无明波，轮回死生辐。","尘应甘露洒，垢待醍醐浴。","障要智灯烧，魔须慧刀戮。","外熏性易染，内战心难衂。","法句与心王，期君日三复。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["春","酒","元宵","月","楼"],"cats":{"抒情":["爱情","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人物":["儿童"],"人生":["哲理","梦想"],"节日":["元宵节","清明节"]},"theme_conf":0.9},{"uid":"1ab8a232-27bf-4de3-b67c-28e4735fea7f","title":"横吹曲辞 长安道","author":"韦应物","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家宫殿含云烟，两宫十里相连延。","晨霞出没弄丹阙，春雨依微自甘泉。","春雨依微春尚早，长安贵游爱芳草。","宝马横来下建章，香车却转避驰道。","贵游谁最贵，卫霍世难比。","何能蒙主恩？幸遇边尘起。","归来甲第拱皇居，朱门峨峨临九衢。","中有流苏合欢之宝帐，一百二十凤皇罗列含明珠。","下有锦铺翠被之粲烂，博山吐香五云散。","丽人绮阁情飘飖，头上鸳钗双翠翘。","低鬟曳袖回春雪，聚黛一声愁碧霄。","山珍海错弃藩篱，烹犊炰羔如折葵。","既请列侯封部曲，还将金印授庐儿。","欢荣若此何所苦，但苦白日西南驰。"],"theme":"山水田园","theme2":["闺情宫怨","讽喻刺世"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春","花","雪","雨"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人物":["女子"]},"theme_conf":0.429},{"uid":"3fc8c4c3-b3a0-459b-a497-3b0f2ecfed57","title":"窦朗州见示与澧州元郎中早秋赠荅命同作","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["邻境诸侯同舍郎，芷江兰浦恨无梁。","秋风门外旌旗动，晓露庭中橘柚香。","玉簟微凉宜白昼，金笳入暮应清商。","骚人昨夜闻𫛸鴂，不叹流年惜众芳。"],"theme":"寄赠酬答","theme2":["送别"],"style":"清新","style2":["沉郁","绮丽"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["时光"]},"theme_conf":0.94},{"uid":"cp44b029899def35","title":"疏影","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["苔枝缀玉。","有翠禽小小，枝上同宿。","客里相逢，篱角黄昏，无言自倚修竹。","昭君不惯胡沙远，但暗忆、江南江北。","想佩环、月夜归来，化作此花幽独。","犹记深宫旧事，那人正睡里，飞近蛾绿。","莫似春风，不管盈盈，早与安排金屋。","还教一片随波去，又却怨、玉龙哀曲。","等恁时、重觅幽香，已入小窗横幅。"],"theme":"闺情宫怨","theme2":["山水田园","羁旅思乡"],"style":"绮丽","style2":["婉约","冲淡"],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["夜","江南","花","春","江"],"cats":{"抒情":["思乡","孤独","闺怨"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.373},{"uid":"4a3c83d8-a6f2-46f7-852b-4d2162d1c6c4","title":"经破薛举战地","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年怀壮气，提戈初仗节。","心随朗日高，志与秋霜洁。","移锋惊电起，转战长河决。","营碎落星沈，阵卷横云裂。","一挥氛沴静，再举鲸鲵灭。","于兹俯旧原，属目驻华轩。","沈沙无故迹，减灶有残痕。","浪霞穿水净，峰雾抱莲昏。","世途亟流易，人事殊今昔。","长想眺前踪，抚躬聊自适。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":["慷慨"],"scene":["秋"],"cats":{"四季":["秋天"],"人生":["战争"]},"theme_conf":0.811},{"uid":"cp0ddc73d1a3910a","title":"竹马子・竹马儿","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登孤垒荒凉，危亭旷望，静临烟渚。","对雌霓挂雨，雄风拂槛，微收烦暑。","渐觉一叶惊秋，残蝉噪晚，素商时序。","览景想前欢，指神京，非雾非烟深处。","向此成追感，新愁易积，故人难聚。","凭高尽日凝伫。","赢得消魂无语。","极目霁霭霏微，暝鸦零乱，萧索江城暮。","南楼画角，又送残阳去。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["雨","楼","江","秋","夏"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["夏天","秋天"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.639},{"uid":"1fb10ea4-f46c-4c08-bd06-f039f1907be6","title":"杂诗三首 三","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闻道黄龙戍，频年不解兵。","可怜闺里月，长在汉家营。","少妇今春意，良人昨夜情。","谁能将旗鼓，一为取龙城。"],"theme":"边塞征战","theme2":["爱情相思","闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","月","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.418},{"uid":"19f067ad-0289-4474-a94a-fe5117350987","title":"求自试","author":"窦常","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙禁祥云合，高梧彩凤游。","沈冥求自试，通鉴果蒙收。","文墨悲无位，诗书误白头。","陈王抗表日，毛遂请行秋。","双剑曾埋狱，司空问斗牛。","希垂拂拭惠，感激愿相投。"],"theme":"游仙梦幻","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"7d89d155-45a6-432d-a873-d00d2917c366","title":"送蔡希曾都尉还陇右因寄高三十五书记","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蔡子勇成癖，弯弓西射胡。","健儿宁鬬死，壮士耻为儒。","官是先锋得，材缘挑战须。","身轻一鸟过，枪急万人呼。","云幕随开府，春城赴上都。","马头金狎帢，驼背锦糢糊。","咫尺云山路，归飞青海隅。","上公犹宠锡，突将且前驱。","汉使黄河远，凉州白麦枯。","因君问消息，好在阮元瑜。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":["悲怆"],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.528},{"uid":"8df8e94b-ffe4-4930-af4c-491d7cb04651","title":"奉和中书舍人贾至早朝大明宫","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["鸡鸣紫陌曙光寒，莺啭皇州春色阑。","金阙晓钟开万户，玉阶仙仗拥千官。","花迎劒珮星初落，柳拂旌旗露未干。","独有凤皇池上客，阳春一曲和皆难。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"]},"theme_conf":0.95},{"uid":"4bcfad28-8899-4e64-a87c-5d45a7dddd37","title":"题荐福寺衡岳暕师房","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春城乞食还，高论此中闲。","僧腊堦前树，禅心江上山。","疎帘看雪卷，深户映花关。","晚送门人出，钟声杳霭间。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","春","江","山"],"cats":{"四季":["春天"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"76ea75c2-9fce-4c89-9452-c7f53343d43f","title":"郊庙歌辞 祀风师乐章 亚献终献","author":"包佶","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["膋芗备，玉帛陈。","风动物，乐感神。","三献终，百神臻。","草木荣，天下春。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":0.84},{"uid":"4d16ccaa-a7a3-45e6-b0d9-6e94e3e1d99d","title":"缆船苦风戏题四韵奉简郑十三判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚岸朔风疾，天寒鸧鸹呼。","涨沙霾草树，舞雪渡江湖。","吹帽时时落，维舟日日孤。","因声置驿外，为觅酒家垆。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["舟","冬","江"],"cats":{"抒情":["孤独"],"四季":["冬天"],"天气":["写风"]},"theme_conf":0.86},{"uid":"60f3c484-4e4f-4612-9f93-e753c7c67c02","title":"送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳郑氏伯父京书至女子已前许他族亲事遂停","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禁脔去东床，趋庭赴北堂。","风波空远涉，琴瑟几虚张。","渥水出骐骥，昆山生凤皇。","两家诚款款，中道许苍苍。","颇谓秦晋匹，从来王谢郎。","青春动才调，白首缺辉光。","玉润终孤立，珠明得暗藏。","余寒折花卉，恨别满江乡。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["女子","父亲"],"人生":["青春"]},"theme_conf":0.524},{"uid":"dc52501e-3598-4ebf-bba8-7bf0c3a9a172","title":"归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["化佛示持帚，仲尼称执鞭。","列生御风归，饲豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，长绶趋遥泉。","开士行何苦，双瓶胝两肩。","萧寺百余僧，东厨正扬烟。","露足沙石裂，外形巾褐穿。","若其有此身，岂得安稳眠。","独出违顺境，不为寒暑还。","大圣于其中，领我心之虔。","万法常空灭，无生因忍全。","一国一释迦，一灯分百千。","永愿遗世知，现身弥勒前。","潜容偏虚空，灵响不可传。","智慧舍利佛，神通自干连。","阿若楚系简帛陈如，迦叶迦旜延。","左右二菩萨，文殊幷普贤。","身披六铢衣，亿刦为大僊。","宝塔宝楼阁，重簷交梵天。","譬如一明珠，共赞光白圆。","天魔波[旬]等，降伏金刚坚。","野叉罗刹鬼，亦赦尘垢缠。","乃致金翅鸟，吞龙护洪渊。","一十一众中，身意皆快然。","八河注大海，中有楞伽船。","佛法付国王，平等无颇偏。","天子事端拱，大臣行其权。","玉堂无蝇飞，五月冰凛筵。","尽力答明主，犹自招罪愆。","九族无白身，百花动婵娟。","神圣恶如此，物华不能妍。","禄山一微胡，驱马来自燕。","宛彼宫阙丽，如何犬羊膻。","苦哉千万人，流血成丹川。","此辈之死后，镬汤所熬煎。","业风吹其魂，猛火烧其烟。","独有丁行者，无忧树枝边。","市头盲老人，长者乞一钱。","韬照多密用，为君吟此篇。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","鸟","中秋","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["哲理"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"a7b8e17f-ee93-4bdc-a144-b1ba5ab32bb5","title":"行路难三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机雄才岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道。","君不见吴中张翰称达生，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"theme":"民生疾苦","theme2":["哲理悟道"],"style":"旷达","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["酒","端午","秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.601},{"uid":"d755f74b-18fd-44d1-a6e1-43e77490bb09","title":"喜见外弟又言别","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十年离乱后，长大一相逢。","问姓惊初见，称名忆旧容。","别来沧海事，语罢暮天钟。","明日巴陵道，秋山又几重。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","江","山"],"cats":{"抒情":["离别"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"44b128d9-264f-48b0-83e9-751db7dbb08e","title":"题高云客舍","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤兴日自深，浮云非所仰。","窗中西城峻，树外东川广。","晏起簪葛巾，闲吟倚藜杖。","阮公道在醉，庄子生常养。","五柳转扶疎，千峰恣来往。","清秋香秔获，白露寒菜长。","吴国滞风烟，平陵延梦想。","时人趋缨弁，高鸟违罗网。","世事徒乱纷，吾心方浩荡。","唯将山与水，处处谐真赏。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["山","秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.368},{"uid":"8fc09639-9e38-402f-9827-589c1cc161ff","title":"夏日对雨寄朱放拾遗","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["才非谷永传，无意谒王侯。","小暑金将伏，微凉麦正秋。","远山欹枕见，暮雨闭门愁。","更忆东林寺，诗家第一流。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["相思"],"scene":["夏","雨"],"cats":{"抒情":["思念","伤感"],"四季":["夏天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"c7166837-c70d-4cfd-bf45-baf6930473bf","title":"酬卫八雪中见寄","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["季冬忆淇上，落日归山樊。","旧宅带流水，平田临古村。","雪中望来信，醉里开衡门。","果得希代宝，缄之那可论。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"83648d7d-4cd5-4a8d-9df7-b3c8eb7bb1cc","title":"绝句漫兴九首 六","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["嬾慢无堪不出村，呼儿日在掩柴门。","苍苔浊酒林中静，碧水春风野外昏。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["酒","春"],"cats":{"四季":["春天"],"生活":["乡村"]},"theme_conf":0.593},{"uid":"6c49fcc2-e014-4a5f-8b7b-bc592de83062","title":"遭田父泥饮美严中丞","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["步屧随春风，邨邨自花柳。","田翁逼社日，邀我尝春酒。","酒酣夸新尹，畜眼未见有。","回头指大男，渠是弓弩手。","名在飞骑籍，长番岁时久。","前日放营农，辛苦救衰朽。","差料死则已，誓不举家走。","今年大作社，拾遗能住否。","叫妇开大缾，盆中为吾取。","感此气扬扬，须知风化首。","语多虽杂乱，说尹终在口。","朝来偶然出，自卯将及酉。","久客惜人情，如何拒邻叟。","高声索果栗，欲起时被肘。","指挥过无礼，未觉邨野丑。","月出遮我留，仍嗔问升斗。"],"theme":"应制干谒","theme2":["山水田园","节令风俗","羁旅思乡"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["春","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.62},{"uid":"b320cb73-b204-4653-b12a-5480f3e0436d","title":"南池荷花","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蝉噪城沟水，芙蓉忽已繁。","红花迷越艳，芳意过湘沅。","湛露宜清暑，披香正满轩。","朝朝秖自赏，秾李亦何言。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["花","夏"],"cats":{"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.517},{"uid":"cp6df3966a4d64dc","title":"卜算子","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["驿外断桥边，寂寞开无主。","已是黄昏独自愁，更著风和雨。","无意苦争春，一任群芳妒。","零落成泥碾作尘，只有香如故。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":["婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","花","春","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"a0fdbeaf-ac46-407c-a611-24775a378981","title":"唐明堂乐章 羽音","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["葭律肇启隆冬，苹藻攸陈飨祭。","黄钟既陈玉烛，红粒方殷稔岁。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["冬"],"cats":{"抒情":["怀古"],"四季":["冬天"]},"theme_conf":0.65},{"uid":"80f35550-53c7-4dd4-a386-0710a32fd153","title":"题温处士山居","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁知白云外，别有绿萝春。","苔绕溪边径，花深洞里人。","逸妻看种药，稚子伴垂纶。","颍上逃尧者，何如此养真。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春"],"cats":{"四季":["春天"],"人物":["儿童"]},"theme_conf":0.382},{"uid":"8d7e8e90-79e8-49c1-81f5-e16ed2b07c89","title":"乞新茶","author":"姚合","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["嫩绿微黄碧涧春，采时闻道断荤辛。","不将钱买将诗乞，借问山翁有几人。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"食物":["写茶"]},"theme_conf":0.62},{"uid":"cp7c35167f827ea7","title":"风入松","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["听风听雨过清明。","愁草瘗花铭。","楼前绿暗分携路，一丝柳、一寸柔情。","料峭春寒中酒，交加晓梦啼莺。","西园日日扫林亭。","依旧赏新晴。","黄蜂频扑秋千索，有当时、纤手香凝。","惆怅双鸳不到，幽阶一夜苔生。"],"theme":"山水田园","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["春","清明","楼","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"天气":["写风"],"节日":["清明节"]},"theme_conf":0.446},{"uid":"10ef9dd5-f761-4463-9d90-fa9a426ac89c","title":"横吹曲辞 关山月","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["秋月朗朗关山上，山中行人马蹄响。","关山秋来雨雪多，行人见月唱边歌。","海边漠漠天气白，胡儿夜度黄龙碛。","军中探骑暮出城，伏兵暗处低旌戟。","溪水连地霜草平，野𫘞寻水碛中鸣。","陇头风急雁不下，沙场苦战多流星。","可怜万国关山道，年年战骨多秋草。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","山"],"cats":{"四季":["秋天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.559},{"uid":"fdefa73b-111d-4b67-ae50-343eb1acce7a","title":"宿黄花馆","author":"杨发","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤馆萧条槐叶稀，暮蝉声隔水声微。","年年为客路无尽，日日送人身未归。","何处迷鸿离浦月，谁家愁妇捣霜衣。","夜深不卧帘犹卷，数点残萤入户飞。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["花","秋","月","夜"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.506},{"uid":"0ae0e3bd-a32e-481f-9719-b283da2da964","title":"滁州西涧","author":"韦应物","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["独怜幽草涧边生，上有黄鹂深树鸣。","春潮带雨晚来急，野渡无人舟自横。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"]},"theme_conf":0.78},{"uid":"15079155-e95e-4abc-b36e-f6b605848f37","title":"杂曲歌辞 独不见","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["卢家小妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催下叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁知含愁独不见，使妾明月照流黄。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月","秋"],"cats":{"抒情":["思念","孤独","闺怨"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.698},{"uid":"7cae1dc9-23b8-4611-938d-27d143c3781b","title":"草堂前新开一池养鱼种荷日有幽趣","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["淙淙三峡水，浩浩万顷陂。","未如新塘上，微风动涟漪。","小萍加泛泛，初蒲正离离。","红鲤二三寸，白莲八九枝。","绕水欲成径，护堤方插篱。","已被山中客，呼作白家池。"],"theme":"山水田园","theme2":["闲适隐逸","羁旅思乡"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","夏"],"cats":{"抒情":["思乡"],"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.364},{"uid":"cpa683c993407ae0","title":"烛影摇红","author":"廖世美","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霭霭春空，画楼森耸凌云渚。","紫薇登览最关情，绝妙夸能赋。","惆怅相思迟暮。","记当日、朱阑共语。","塞鸿难问，岸柳何穷，别愁纷絮。","催促年光，旧来流水知何处。","断肠何必更残阳，极目伤平楚。","晚霁波声带雨。","悄无人、舟横野渡。","数峰江上，芳草天涯，参差烟树。"],"theme":"爱情相思","theme2":["爱情相思","山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["江","花","塞外","春","舟","楼"],"cats":{"抒情":["爱情","思念","伤感","孤独"],"四季":["春天"]},"theme_conf":0.75},{"uid":"c64926d8-1757-4e1f-8096-dd24190f1ba1","title":"送萧十八与房侍御廻还","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常苦古人远，今见斯人古。","澹泊遗声华，周旋必邹鲁。","故交在梁宋，游方出庭户。","匹马鸣朔风，一身济河浒。","辛勤采兰咏，款曲翰林主。","岁月催别离，庭围远风土。","寥寥寒烟静，莽莽夕阴吐。","明发不在兹，青天眇难覩。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["园林","月","冬"],"cats":{"抒情":["离别"],"四季":["冬天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"7bb37684-e982-4765-bce8-fbfe3b87dc15","title":"赠别王十七管记","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["故交吾未测，薄宦空年岁。","晚节踪曩贤，雄词冠当世。","堂中皆食客，门外多酒债。","产业曾未言，衣裘与人敝。","飘飖戎幕下，出入关山际。","转战轻壮心，立谈有边计。","云沙自廻合，天海空迢递。","星高汉将骄，月盛胡兵锐。","沙深冷陉断，雪暗辽阳闭。","亦谓扫欃枪，旋惊陷蜂虿。","归旌告东捷，鬬骑传西败。","遥飞绝汉书，已筑长安第。","画龙俱在叶，宠鹤先居卫。","勿辞部曲勋，不藉将军势。","相逢季冬月，伥望穷海裔。","折劒留赠人，严装遂云迈。","我行将悠𥾝，及此还羁滞。","曾非济代谋，且有临深诫。","随波混清浊，与物同丑丽。","眇忆青岩栖，宁忘褐衣拜。","自言爱水石，本欲亲兰蕙。","何意薄松筠，翻然重菅蒯。","恒深取与分，孰慢平生契。","欵曲鸡黍期，酸辛别离袂。","逢时愧名节，遇坎悲沦替。","适赵非解纷，游燕往无说。","浩歌方振荡，逸翮思凌励。","倏若异鹏抟，吾当学蝉蜕。"],"theme":"送别","theme2":[],"style":"豪放","style2":["幽峭","清新"],"mood":"相思","mood2":["恬淡","悲怆"],"scene":["冬","山","鸟","雪","月"],"cats":{"抒情":["离别","思念","伤感"],"四季":["冬天"],"人生":["战争"]},"theme_conf":0.519},{"uid":"c27daaf8-489e-4fdb-8d82-85a074f8fd2e","title":"闻友人入越幕因以诗赠","author":"罗邺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["稽岭春生酒冻销，烟鬟红袖恃娇饶。","岸边丛雪晴香老，波上长虹晚影遥。","正哭阮途归未得，更闻江笔赴嘉招。","人间荣瘁真堪恨，坐想征轩鬓欲凋。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南","雪","春","酒","花"],"cats":{"抒情":["友情"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.9},{"uid":"cp79ac7bfce7f15c","title":"满庭芳","author":"秦观","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓色云开，春随人意，骤雨才过还晴。","古台芳榭，飞燕蹴红英。","舞困榆钱自落，秋千外、绿水桥平。","东风里，朱门映柳，低底按小秦筝。","多情。","行乐处，珠钿翠盖，玉辔红缨。","渐酒空金，花困蓬瀛。","豆蔻梢头旧恨，十年梦，屈指堪惊。","凭阑久，疏烟淡日，寂寞下芜城。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"8f4ff5d9-6454-4e9a-94e9-9baca2276713","title":"相和歌辞 安乐宫","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["深井桐乌起，尚复牵清水。","未盥邵陵王，瓶中弄长翠。","新城安乐宫，宫如凤皇翅。","歌回蜡版鸣，大绾提壶使。","绿繁悲水曲，茱萸别秋子。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["悲慨"],"mood":"欢愉","mood2":["恬淡"],"scene":["重阳","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"ca98fed4-d62e-480c-bcb7-b2b95749441a","title":"琴曲歌辞 胡笳十八拍 第十一拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["日来月往相推迁，迢迢星岁欲周天。","无冬无夏卧霜霰，水冻草枯为一年。","汉家甲子有正朔，绝域三光空自悬。","几回鸿雁来又去，肠断蟾蜍亏复圆。"],"theme":"边塞征战","theme2":["闲适隐逸","民生疾苦"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["月","冬","夏","雪"],"cats":{"抒情":["伤感"],"四季":["夏天","冬天"]},"theme_conf":0.452},{"uid":"078cc610-552e-4224-8413-3dda0ac3c0f5","title":"夏日联句","author":"文宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["人皆苦炎热，我爱夏日长。","熏风自南来，殿阁生微凉。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"天气":["太阳"]},"theme_conf":0.72},{"uid":"db548528-fbd1-4356-bc2d-403760c1267c","title":"登三台言志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["未央初壮汉，阿房昔侈秦。","在危犹骋丽，居奢遂役人。","岂如家四海，日宇罄朝伦。","扇天裁户旧，砌地翦基新。","引月擎宵桂，飘云逼曙鳞。","露除光炫玉，霜阙映雕银。","舞接花梁燕，歌迎鸟路尘。","镜池波太液，庄苑丽宜春。","作异甘泉日，停非路寝辰。","念劳慙逸己，居旷返劳神。","所欣成大厦，宏材伫渭滨。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["豪放","绮丽"],"mood":"慷慨","mood2":[],"scene":["园林","月","鸟","楼","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"b47a1058-7706-4f5b-b110-c5078de3abd6","title":"题惟干上人房","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绳床茅屋下，独坐味闲安。","苦行无童子，忘机避宰官。","是非齐已久，夏腊比应难。","更悟真如性，尘心稍自宽。"],"theme":"佛道禅颂","theme2":["哲理悟道","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"822d55ea-2b24-4067-a997-106adf6d6f55","title":"出猎","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["楚王云梦泽，汉帝长杨宫。","岂若因农暇，阅武出轘嵩。","三驱陈锐卒，七萃列材雄。","寒野霜氛白，平原烧火红。","雕戈夏服箭，羽骑绿沈弓。","怖兽潜幽壑，惊禽散翠空。","长烟晦落景，灌木振严风。","所为除民瘼，非是悦林丛。"],"theme":"边塞征战","theme2":["山水田园","闲适隐逸"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","山"],"cats":{"四季":["夏天"]},"theme_conf":0.412},{"uid":"3e0e1d96-c249-47c4-b16d-4d91dd6e7cce","title":"东郊","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吏舍跼终年，出郊旷清曙。","杨柳散和风，青山澹吾虑。","依丛适自憩，缘涧还复去。","微雨霭芳原，春鸠鸣何处？乐幽心屡止，遵事迹犹遽。","终罢斯结庐，慕陶真可庶。"],"theme":"山水田园","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"]},"theme_conf":0.87},{"uid":"b6d20c68-6a13-491d-b88c-6f25bcd154b8","title":"冬夜集赋得寒漏","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["清冬洛阳客，寒漏建章台。","出禁因风彻，萦窗共月来。","偏将残濑杂，乍与远鸿哀。","遥夜重城警，流年滴水催。","闲斋堪坐听，况有故人杯。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆","恬淡"],"scene":["夜","冬"],"cats":{"四季":["冬天"],"人生":["时光"]},"theme_conf":0.588},{"uid":"2ecf783d-8e3f-4d06-8560-11ba520f5e37","title":"苦竹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青冥亦自守，輭弱强扶持。","味苦夏虫避，丛卑春鸟疑。","轩墀曾不重，剪伐欲无辞。","幸近幽人屋，霜根结在兹。"],"theme":"民生疾苦","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","春"],"cats":{"四季":["春天","夏天"],"植物":["竹子"]},"theme_conf":0.537},{"uid":"f2f04c30-149d-4b2b-bce1-1334adf84739","title":"灞上秋居","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["灞原风雨定，晚见鴈行频。","落叶他乡树，寒灯独夜人。","空园白露滴，孤壁野僧隣。","寄卧郊扉久，何门致此身。"],"theme":"羁旅思乡","theme2":["讽喻刺世","节令风俗","送别"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"]},"theme_conf":0.289},{"uid":"25d13241-414a-4a80-a9aa-7d4c41e8dd64","title":"醉中对红叶","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["临风杪秋树，对酒长年人。","醉貌如霜叶，虽红不是春。"],"theme":"咏物","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"四季":["秋天"],"植物":["叶子"],"食物":["写酒"]},"theme_conf":0.82},{"uid":"a46125e8-7617-40ac-90f6-35d2f9af010c","title":"杂曲歌辞 爱妾换马 二","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绮阁香销华厩空，忍将行雨换追风。","休怜柳叶双眉翠，却爱桃花两耳红。","侍宴永辞春色里，趁朝休立漏声中。","恩劳未尽情先尽，暗泣嘶风两意同。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"悲怆","mood2":["欢愉"],"scene":["花","春","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.729},{"uid":"8c067a87-d475-491d-8786-b811118cfce2","title":"相和歌辞 雁门太守行","author":"庄南杰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["旌旗闪闪摇天末，长笛横吹虏尘阔。","跨下嘶风白练狞，腰间切玉青蛇活。","击革𪭢金燧牛尾，犬羊兵败如山死。","九泉寂寞葬秋虫，湿云荒草啼秋思。"],"theme":"边塞征战","theme2":["羁旅思乡","悼亡挽歌","山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","秋"],"cats":{"抒情":["思乡","孤独","悼亡"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.301},{"uid":"4b13e5da-48ea-4213-9ede-dd8cec48c7c3","title":"春雪间早梅","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梅将雪共春，彩艳不相因。","逐吹能争密，排枝巧妬新。","谁令香满座，独使净无尘。","芳意饶呈瑞，寒光助照人。","㻏珑开已徧，点缀坐来频。","那是俱疑似，须知两逼真。","荧煌初乱眼，浩荡忽迷神。","未许琼华比，从将玉树亲。","先期迎献岁，更伴占兹晨。","愿得长辉暎，轻微敢自珍。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"7822c305-f1b3-4ed3-8011-f69dca0e965a","title":"于太原召侍臣赐宴守岁","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["四时运灰琯，一夕变冬春。","送寒余雪尽，迎岁早梅新。"],"theme":"节令风俗","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["除夕","冬"],"cats":{"四季":["冬天"],"节日":["春节"]},"theme_conf":0.9},{"uid":"028b5cb7-2c3b-4023-ae17-90d2128c5b75","title":"杂曲歌辞 行路难","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉家名臣杨德祖，四代五公享茅土。","父兄子弟绾银黄，跃马鸣珂朝建章。","火浣单衣绣方领，茱萸锦带玉盘囊。","宾客填街复满坐，片言出口生辉光。","世人逐势争奔走，沥胆隳肝惟恐后。","当时一顾生青云，自谓生死长随君。","一朝谢病还乡里，穷巷苍茫绝知己。","秋风落叶闭重门，昨日论交竟谁是。","薄俗嗟嗟难重陈，深山麋鹿下为邻。","鲁连所以蹈沧海，古往今来称达人。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["秋","重阳"],"cats":{"抒情":["友情","思乡"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":1.0},{"uid":"cpf018dd823a543a","title":"安公子","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["弱柳丝千缕。","嫩黄匀遍鸦啼处。","寒入罗衣春尚浅，过一番风雨。","问燕子来时，绿水桥边路。","曾画楼、见个人人否。","料静掩云窗，尘满哀弦危柱。","庾信愁如许。","为谁都著眉端聚。","独立东风弹泪眼，寄烟波东去。","念永昼春闲，人倦如何度。","闲傍枕、百啭黄鹂语。","唤觉来厌厌，残照依然花坞。"],"theme":"爱情相思","theme2":["闺情宫怨","送别"],"style":"婉约","style2":["沉郁"],"mood":"恬淡","mood2":["愁怨"],"scene":["春","雨","鸟"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.86},{"uid":"396cd474-fdac-49f4-9594-f28d013760ac","title":"杂歌谣辞 郑樱桃歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石季龙，僭天禄。","擅雄豪，美人姓郑名樱桃。","樱桃美颜香且泽，娥娥侍寝专宫掖。","后庭卷衣三万人，翠眉清镜不得亲。","官军女骑一千匹，繁花照耀漳河春。","织成花映红纶巾，红旗掣曳卤簿新。","鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。","凤阳重门如意馆，百尺金梯倚银汉。","自言富贵不可量，女为公主男为王。","赤花双簟珊瑚床，盘龙斗帐琥珀光。","淫昏伪位神所恶，灭石者陵终不误。","邺城苍苍白露微，世事飜覆黄云飞。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","春","七夕"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"节日":["七夕节"],"植物":["桃花"]},"theme_conf":0.581},{"uid":"3b70daa4-ed82-4ba5-8dc0-6345d6542862","title":"忆平泉杂咏 忆茗芽","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谷中春日暖，渐忆掇茶英。","欲及清明火，能销醉客酲。","松花飘鼎泛，兰气入瓯轻。","饮罢闲无事，扪萝溪上行。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"节日":["清明节"],"食物":["写茶"]},"theme_conf":0.394},{"uid":"cp23ced89521c2e8","title":"帝台春","author":"李甲","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芳草碧色，萋萋遍南陌。","暖絮乱红，也知人、春愁无力。","忆得盈盈拾翠侣，共携赏、凤城寒食。","到今来，海角逢春，天涯为客。","愁旋释。","还似织。","泪暗拭。","又偷滴。","谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。","拼则而已今拼了，忘则怎生便忘得。","又还问鳞鸿，试重寻消息。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.556},{"uid":"d9a9bf4b-fba8-424b-b81c-309bcdade7aa","title":"奉和裴令公新成午桥庄绿野堂即事","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旧径开桃李，新池凿凤皇。","只添丞相阁，不改午桥庄。","远处尘埃少，闲中日月长。","青山为外屏，绿野是前堂。","引水多随势，栽松不趂行。","年华玩风景，春事看农桑。","花妬谢家妓，兰偷荀令香。","游丝飘酒席，瀑布溅琴床。","巢许终身稳，萧曹到老忙。","千年落公便，进退处中央。"],"theme":"应制干谒","theme2":["闲适隐逸","山水田园"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","酒","月"],"cats":{"四季":["春天"],"山水":["瀑布"],"生活":["写桥"]},"theme_conf":0.97},{"uid":"7bfe6521-bb53-46ae-af7c-2339309f0605","title":"昭德皇后挽歌词","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西汜驰晖过，东园别路长。","岁华唯陇柏，春事罢公桑。","龟兆开泉户，禽巢闭画梁。","更闻哀礼过，明诏制心丧。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","园林"],"cats":{"抒情":["悼亡"],"四季":["春天"]},"theme_conf":0.98},{"uid":"b51c9f56-c13f-487f-846f-90ec85b1b7ac","title":"秋朝木芙蓉","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["水面芙蓉秋已衰，繁条到是著花时。","平明露滴垂红脸，似有朝愁暮落悲。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"cf913d33-9ec7-4d06-a644-07dc1adafde1","title":"题张氏隐居二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春山无伴独相求，伐木丁丁山更幽。","涧道余寒历冰雪，石门斜日到林丘。","不贪夜识金银气，远害朝看糜鹿游。","乘兴杳然迷出处，对君疑是泛虚舟。"],"theme":"闲适隐逸","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","雪","春","舟","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"]},"theme_conf":0.88},{"uid":"786e30bf-b8a8-4067-a51c-1a5b522ed71d","title":"执契静三边","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["执契静三边，持衡临万姓。","玉彩辉关烛，金华流日镜。","无为宇宙清，有美璇玑正。","皎佩星连景，飘衣云结庆。","戢武耀七德，升文辉九功。","烟波澄旧碧，尘火息前红。","霜野韬莲劒，关城罢月弓。","钱缀榆天合，新城柳塞空。","花销葱岭雪，縠尽流沙雾。","秋驾转兢怀，春冰弥轸虑。","书绝龙庭羽，烽休凤穴戍。","衣宵寝二难，食旰餐三惧。","翦暴兴先废，除凶存昔亡。","圆盖归天壤，方舆入地荒。","孔海池京邑，双河沼帝乡。","循躬思励己，抚俗媿时康。","元首伫盐梅，股肱惟辅弼。","羽贤崆岭四，翼圣襄城七。","浇俗庶反淳，替文聊就质。","已知隆至道，共欢区宇一。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":["清新","绮丽"],"mood":"恬淡","mood2":["欢愉"],"scene":["冬","秋","园林","塞外","雪"],"cats":{"四季":["秋天"],"生活":["边塞"]},"theme_conf":0.767},{"uid":"a15343da-3f7e-4d97-8df0-6d9a5b567a40","title":"秋思二首 一","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万木秋霖后，孤山夕照余。","田园无岁计，寒近忆樵渔。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["西湖"],"生活":["田野"]},"theme_conf":1.0},{"uid":"ed927451-c3fd-4566-97a2-c86f8c2fa756","title":"行官张望补稻畦水归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东屯大江北，百顷平若案。","六月青稻多，千畦碧泉乱。","插秧适云已，引溜加溉灌。","更仆往方塘，决渠当断岸。","公私各地著，浸润无天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生银汉。","欧鸟镜里来，关山云边看。","秋菰成黑米，精凿传白粲。","玉粒足晨炊，红鲜任霞散。","终然添旅食，作苦期壮观。","遗穗及众多，我仓戒滋蔓。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","七夕"],"cats":{"抒情":["思乡"],"四季":["秋天"],"山水":["长江"],"生活":["田野"],"节日":["七夕节"]},"theme_conf":0.531},{"uid":"71cd9908-9167-4099-8fef-fe6d27fca4b5","title":"荅友人寄新茗","author":"李群玉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["满火芳香碾曲尘，吴瓯湘水绿花新。","媿君千里分滋味，寄与春风酒渴人。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春","酒"],"cats":{"抒情":["友情"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.95},{"uid":"cp2f1b9514a94dec","title":"鹧鸪天","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["肥水东流无尽期。","当初不合种相思。","梦中未比丹青见，暗里忽惊山鸟啼。","春未绿，鬓先丝。","人间别久不成悲。","谁教岁岁红莲夜，两处沈吟各自知。"],"theme":"爱情相思","theme2":["题画咏艺","送别"],"style":"清新","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["春","夜","山"],"cats":{"抒情":["爱情","思念"],"四季":["春天"]},"theme_conf":0.349},{"uid":"a6250fd5-bdd4-4c24-9074-a3023c832ae4","title":"宿云溪观赋得秋灯引送客","author":"杨衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["云房寄宿秋夜客，一灯荧荧照虚壁。","虫声呼客客未眠，几人语话清景侧。","不可离别愁纷多，秋灯秋灯奈别何。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜","元宵"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写云"],"节日":["元宵节"]},"theme_conf":0.466},{"uid":"cpc07deb8829e3ce","title":"临江仙","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["忆醉三山芳树下，几层风韵忘怀。","黄金颜色五花开。","味如庐橘熟。","贵似荔枝来。","闻道商山馀四老，橘中自酿秋醅。","试呼名品细推排。","重重香腑脏，偏𣨼圣贤杯。"],"theme":"游仙梦幻","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花","酒","江","秋","山"],"cats":{"抒情":["思念"],"四季":["秋天"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"9d22d9e5-04ad-42f1-b88c-7c4b07f012c1","title":"送薛秀才","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虽是寻山客，还同慢世人。","读书惟务静，无褐不忧贫。","野色春冬树，鸡声远近邻。","郄公即吾友，合与尔相亲。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["冬","春","山"],"cats":{"四季":["春天","冬天"],"人生":["读书"]},"theme_conf":0.778},{"uid":"b281e5ae-9731-4a72-b474-7ac786246f35","title":"琴曲歌辞  秋思二首 一","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡风吹雁翼，远别无人乡。","君近鴈来处，几回断君肠。","昔奉千日书，抚心怨星霜。","无书又千日，世路重茫茫。","燕国有佳丽，蛾眉富春光。","自然君归晚，花落君空堂。","君其若不然，岁晚双鸳鸯。","顾兔蚀残月，幽光不如星。","女儿晚事夫，颜色同秋萤。","秋日边马思，武夫不遑宁。","燕歌易水怨，劒舞蛟龙腥。","风折连枝树，水翻无蒂萍。","立身多户门，何必燕山铭。","生世不如鸟，双双比翼翎。"],"theme":"闺情宫怨","theme2":["羁旅思乡","闲适隐逸","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["秋","鸟"],"cats":{"抒情":["爱情","思乡","孤独","闺怨"],"四季":["秋天"]},"theme_conf":0.72},{"uid":"cpf2a280a2cda3d4","title":"月照梨花・河传","author":"黄升","dynasty":"宋","section":"宋词","form":"词","paragraphs":["昼景。","方永。","重帘花影。","好梦犹酣，莺声唤醒。","门外风絮交飞。","送春归。","修蛾画了无人问。","几多别恨。","泪洗残妆粉。","不知郎马何处嘶。","烟草萋迷。","鹧鸪啼。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","月","春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.737},{"uid":"4ceed844-05e4-493f-a345-b26e9230b080","title":"春日题苗发竹亭","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春亭及策上，郎吏谢玄晖。","闲咏疎篁近，高眠远岫微。","偏宜留野客，暂得解朝衣。","犹忆东溪里，雷云掩故扉。"],"theme":"闲适隐逸","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","楼"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"5c373cc0-d72c-4bc8-b39e-c48d0564c86e","title":"酬王维春夜竹亭赠别","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["山月随客来，主人兴不浅。","今宵竹林下，谁觉花源远。","惆怅曙莺啼，孤云还绝𪩘。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["春","夜"],"cats":{"抒情":["离别","孤独"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.715},{"uid":"9c2e9bc9-e7a3-459b-8c90-e3aefae8d962","title":"奉和礼部尚书酬杨著作竹亭歌","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["直城朱户相逦连，九逵丹毂声阗阗。","春官自有花源赏，终日南山当目前。","晨摇玉佩趋温室，莫入竹溪疑洞天。","烟销雨过看不足，晴翠鲜飙逗深谷。","独谣一曲泛流霞，闲对千竿连净绿。","萦回疏凿随胜地，石磴岩扉光景异。","虚斋寂寂清籁唫，幽涧纷纷杂英坠。","家承麟趾贵，劒有龙泉赐。","上奉明时事无事，人间方外兴偏多。","能以簪缨狎薜萝，常通内学青莲偈。","更奏新声白雪歌，风入松，云归栋。","鸿飞灭处犹目送，蝶舞闲时梦忽成。","兰台有客叙交情，返照中林曳履声。","直为君恩催造膝，东方辨色谒承明。"],"theme":"寄赠酬答","theme2":["送别","应制干谒"],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":[],"scene":["楼","山","雪","春"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.8},{"uid":"54008cd0-f9bf-424f-bc55-f15c1e9025f3","title":"赠别二首 一","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["娉娉褭褭十三余，豆蔻梢头二月初。","春风十里扬州路，卷上珠帘总不如。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","月"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":1.0},{"uid":"9532d5be-e0a2-4623-aaf5-322a8b90d1ea","title":"暮秋扬子江寄孟浩然","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["木叶纷纷下，东南日烟霜。","林山相晚暮，天海空青苍。","暝色况复久，秋声亦何长。","孤舟兼微月，独夜仍越乡。","寒笛对京口，故人在襄阳。","咏思劳今夕，江汉遥相望。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["秋","江"],"cats":{"抒情":["友情","孤独"],"四季":["秋天"],"山水":["江河","长江"]},"theme_conf":0.86},{"uid":"5afe3c27-812c-4eed-bb30-74e657009e41","title":"北风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风破南极，朱凤日威垂。","洞庭秋欲雪，鸿雁将安归。","十年杀气盛，六合人烟稀。","吾慕汉初老，时清犹茹芝。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["江","雪","秋","园林","鸟"],"cats":{"抒情":["思乡"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.65},{"uid":"487805d3-fe67-46d9-912d-29587a2cb1c5","title":"赋得弱柳鸣秋蝉","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["散影玉阶柳，含翠隐鸣蝉。","微形藏叶里，乱响出风前。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.75},{"uid":"4f743153-575a-413e-b217-b10d18c723e9","title":"瀑布","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["豁开青冥颠，写出万丈泉。","如裁一条素，白日悬秋天。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.65},{"uid":"4ece9f6a-9b24-427a-9ef7-dce93f2f388e","title":"横吹曲辞 出塞曲","author":"刘济","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["将军在重围，音信绝不通。","羽书如流星，飞人甘泉宫。","倚是幷州儿，少年心胆雄。","一朝随召募，百战争王公。","去年桑干北，今年桑干东。","死是征人死，功是将军功。","汗马牧秋月，疲兵卧霜风。","仍闻左贤王，更欲图云中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外","秋"],"cats":{"四季":["秋天"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.827},{"uid":"dfc0cb68-548a-41aa-a47f-492d7e264183","title":"琴曲歌辞 琴歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["琴调秋些，胡风遶雪。","峡泉生咽，佳人愁些。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.628},{"uid":"efad3f8b-87d3-406e-a916-fc8fb2bdf381","title":"秋日登岳阳楼晴望","author":"张碧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三秋倚练飞金盏，洞庭波定平如刬。","天高云卷绿罗低，一点君山碍人眼。","漫漫万顷铺琉璃，烟波阔远无鸟飞。","西南东北竞无际，直疑侵断青天涯。","屈原回日牵愁吟，龙宫感激致应沈。","贾生憔悴说不得，茫茫烟霭堆湖心。"],"theme":"咏史怀古","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["清新","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","江","秋"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.414},{"uid":"c2e105eb-bf47-46ea-b2d3-fc6e0613e869","title":"冬日有怀李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞书斋里，终朝独尔思。","更寻嘉树传，不忘角弓诗。","短褐风霜入，还丹日月迟。","未因乘兴去，空有鹿门期。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"1d6885a4-d11e-4428-80a8-fcf75d7a41aa","title":"春宫怨","author":"周朴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"050572f1-02f6-40f3-8318-dbe7f8353a84","title":"游长宁公主流杯池二十五首 十","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["霁晓气清和，披襟赏薜萝。","玳瑁凝春色，琉璃漾水波。","跂石聊长啸，攀松乍短歌。","除非物外者，谁就此经过。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["豪放","绮丽"],"mood":"恬淡","mood2":[],"scene":["酒","园林","春"],"cats":{"四季":["春天"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"cpa13dd8628ea1d7","title":"虞美人","author":"舒亶","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芙蓉落尽天涵水。","日暮沧波起。","背飞双燕帖云寒。","独向小楼东畔、倚阑看。","浮生只合尊前老。","雪满长安道。","故人早晚上高台。","赠我江南春色、一枝梅。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","江南","冬","雪","春"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"da88e355-99df-4d78-9680-2f61b0bf8336","title":"秦州杂诗二十首 十","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云气接昆仑，涔涔塞雨繁。","羌童看渭水，使客向河源。","烟火军中幕，牛羊岭上村。","所居秋草净，正闭小蓬门。"],"theme":"边塞征战","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","秋","雨"],"cats":{"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.481},{"uid":"287bc2ee-eb64-4d40-9f02-07052ccea9ca","title":"奉送刘相公江淮催转运","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["国用资戎事，臣劳为主忧。","将徴任土贡，更发济川舟。","拥传星还去，过池凤不留。","唯高饮水节，稍浅别家愁。","落叶淮边雨，孤山海上秋。","遥知谢公兴，微月上江楼。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["江河","西湖"]},"theme_conf":0.54},{"uid":"56c66dee-7bd0-403b-81a4-6b5d552e776d","title":"相和歌辞 燕歌行","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["国之重镇惟幽都，东威九夷制北胡。","五军精卒三十万，百战百胜擒单于。","前临滹沲后沮水，崇山沃野亘千里。","昔时燕王重贤士，黄金筑台从隗始。","倏忽兴王定蓟丘，汉家又以封王侯。","萧条魏晋为横流，鲜卑窃据朝五州。","我唐区夏余十纪，军容武备赫万祀。","彤弓黄钺授元帅，垦耕大漠为内地。","季秋胶折边草腓，治兵羽猎因出师。","千营万队连旌旗，望之如火忽雷驰。","匈奴慑窜穷发北，大荒万里无尘飞。","隋家昔为天下宰，穷兵黩武征辽海。","南风不竞多死声，鼓卧旗折黄云横。","六军将士皆死尽，战马空鞍归故营。","时迁道革天下平，白环入贡沧海清。","自有农夫已高枕，无劳校尉重横行。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","夏"],"cats":{"四季":["夏天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.626},{"uid":"9cac30d1-12da-43d9-8773-ec5a4648c782","title":"相和歌辞 从军有苦乐行","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["劳者且勿歌，我欲送君觞。","从军有苦乐，此曲乐未央。","仆本居陇上，陇水断人肠。","东过秦宫路，宫路入咸阳。","时逢汉帝出，谏猎至长杨。","讵驰游侠窟，非结少年场。","一旦承嘉惠，轻命重恩光。","秉笔参帷帟，从军至朔方。","边地多阴风，草木自凄凉。","断绝海云去，出没胡沙长。","参差引雁翼，隐辚腾军装。","劒文夜如水，马汗冻成霜。","侠气五都少，矜功六郡良。","山河起目前，睚眦死路傍。","北逐驱獯虏，西临复旧疆。","昔还赋余资，今出乃赢粮。","一矢弢夏服，我弓不再张。","寄言丈夫雄，苦乐身自当。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["夏","酒"],"cats":{"抒情":["伤感"],"四季":["夏天"]},"theme_conf":0.56},{"uid":"50d96cb2-de4f-4cbe-bf62-3159b077d2f6","title":"鲁郡途中遇徐十八录事","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谁谓嵩颍客，遂经邹鲁乡。","前临少昊墟，始觉东蒙长。","独行岂吾心，怀古激中肠。","圣人久已矣，游夏遥相望。","裴回野泽间，左右多悲伤。","日出见阙里，川平知汶阳。","弱冠负高节，十年思自强。","终然不得意，去去任行藏。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["惆怅","孤寂"],"scene":["夏"],"cats":{"抒情":["思乡","伤感","孤独","怀古"],"四季":["夏天"]},"theme_conf":0.568},{"uid":"248b95f0-07f4-49d9-a8e5-307ce68fcecf","title":"郊庙歌辞 享太庙乐章 延和","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["巍巍累圣，穆穆重光。","奄有区夏，祚启隆唐。","百蛮饮泽，万国来王。","本枝亿载，鼎祚逾长。"],"theme":"应制干谒","theme2":[],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"]},"theme_conf":0.9},{"uid":"ab07dac2-299a-485a-bc5f-41450e4a41e0","title":"杂曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾本蚕家女，不识贵门仪。","藁砧持玉斧，交结五陵儿。","十日或一见，九日在路岐。","人生此夫壻，富贵欲何为。","杨柳徒可折，南山不可移。","妇人贵结发，宁有再嫁资。","嫁女莫望高，女心愿所宜。","宁从贱相守，不愿贵相离。","蓝叶郁重重，蓝花若榴色。","少妇归少年，华光自相得。","谁言配君子，以奉百年身。","有义即夫壻，无义还他人。","爱如寒炉火，弃若秋风扇。","山岳起面前，相看不相见。","丈夫非小儿，何用强相知。","不见朝生菌，易成还易衰。","征客欲临路，居人还出门。","北风河梁上，四野愁云繁。","岂不恋我家，夫壻多感恩。","前程有日月，勋绩在河源。","少妇马前立，请君听一言。","春至草亦生，谁能无别情。","殷勤展心素，见新莫忘故。","遥望孟门山，殷勤报君子。","既为随阳雁，勿学西流水。","尝闻生别离，悲莫悲于此。","同器不同荣，堂下即千里。","与君贫贱交，何异萍上水。","托身天使然，同生复同死。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["秋","山"],"cats":{"抒情":["离别","思乡","伤感","感恩"],"四季":["秋天"],"山水":["黄河"],"天气":["写风"],"人物":["儿童"],"人生":["青春"]},"theme_conf":0.616},{"uid":"c5c4e4d0-682a-4c8f-9756-c181dc9a52dc","title":"杂曲歌辞 羽林行","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朔雪寒断指，朔风劲裂冰。","胡中射雕者，此日犹不能。","翩翩羽林儿，锦臂飞苍鹰。","挥鞭决白马，走出黄河凌。"],"theme":"山水田园","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","江"],"cats":{"四季":["冬天"],"山水":["黄河"],"天气":["写风"]},"theme_conf":0.509},{"uid":"fbc64d79-0672-454c-9255-e48d063e44f6","title":"奉酬皮先辈霜菊见赠","author":"崔璞","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菊花开晚过秋风，闻道芳香正满丛。","争奈病夫难强饮，应须速自召车公。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","重阳","花"],"cats":{"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"2f6e3b2d-dc26-4be1-bf64-0710c7eaa7cd","title":"相和歌辞 铜雀妓","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳人一壶酒，秋容满千里。","石马卧新烟，忧来何所似？","歌声且潜弄，陵树风自起。","长裾压高台，泪眼看花机。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"cpff779c5996e524","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霁景风软，烟江春涨。","小阁无人，绣帘半上。","花外姊妹相呼。","约樗蒲。","修蛾忘了章台样。","细思一饷。","感事添惆怅。","胸酥臂玉消减，拟觅双鱼。","倩传书。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"惆怅","mood2":["孤寂"],"scene":["花","月","楼","春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"山水":["江河"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"45c8fb06-8bc7-4f39-8874-9d6748c12fb9","title":"杂曲歌辞 凉州 歌第二","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朔风吹叶鴈门秋，万里烟尘昏戍楼。","征马长思青海北，胡笳夜听陇山头。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","楼","夜","冬","山"],"cats":{"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"cp03094b5525f32e","title":"宝鼎现","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["红妆春骑。","踏月影、竿旗穿市。","望不尽、楼台歌舞，习习香尘莲步底。","箫声断、约彩鸾归去，未怕金吾呵醉。","甚辇路、喧阗且止。","听得念奴歌起。","父老犹记宣和事。","抱铜仙、清泪如水。","还转盼、沙河多丽。","漾明光连邸第。","帘影冻、散红光成绮。","月浸葡萄十里。","看往来、神仙才子。","肯把菱花扑碎。","肠断竹马儿童，空见说、三千乐指。","等多时春不归来，到春时欲睡。","又说向、灯前拥髻。","暗滴鲛珠坠。","便当日、亲见霓裳，天上人间梦里。"],"theme":"闺情宫怨","theme2":["山水田园","民生疾苦"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["相思"],"scene":["花","楼","春","月"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人物":["儿童"]},"theme_conf":0.405},{"uid":"27400495-0bfe-4223-a30b-a6c4a1ef4816","title":"寄赠虢州张参军","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三十事诸侯，贤豪冠北州。","桃花迎骏马，苏合染轻裘。","观妓将军第，题诗关尹楼。","青林朝送客，绿屿晚回舟。","好栗分通子，名香赠莫愁。","洗杯新酒熟，把烛故人留。","百雉归云过，千峰宿雨收。","蒹葭露下晚，菡萏水中秋。","忆昨陪行乐，常时接献酬。","佳期虽雾散，惠问亦川流。","开卷酲堪解，含毫思苦抽。","无因达情意，西望日悠悠。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","旷达"],"mood":"愁怨","mood2":["相思"],"scene":["酒","中秋","花","舟","秋"],"cats":{"抒情":["友情","思念","伤感"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.91},{"uid":"caddd8da-5834-41d5-a136-9e1a56c7cef2","title":"杂曲歌辞 行路难五首 四","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见云间月，暂盈还复缺。","君不见林下风，声远意难穷。","亲故平生欲聚散，欢娱未尽尊酒空。","自叹青青陵上柏，岁寒能与几人同。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","相思"],"scene":["酒","冬","月"],"cats":{"抒情":["思念","思乡"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"b881b056-6d92-45e8-9620-4710a375776f","title":"和晋陵陆丞早春游望","author":"杜审言","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光转绿苹。","忽闻歌古调，归思欲沾巾。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.464},{"uid":"fb376b71-91c6-44ee-b2e4-40f5b3f71b8f","title":"寄令狐郎中","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["嵩云秦树久离居，双鲤迢迢一纸书。","休问梁园旧宾客，茂陵秋雨病相如。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋","雨","园林"],"cats":{"四季":["秋天"]},"theme_conf":0.95},{"uid":"cp72c5d65e1c6c79","title":"玉胡蝶・玉蝴蝶","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚雨未摧宫树，可怜闲叶，犹抱凉蝉。","短景归秋，吟思又接愁边。","漏初长、梦魂难禁，人渐老、风月俱寒。","想幽欢。","土花庭，虫网阑干。","无端。","啼蛄搅夜，恨随团扇，苦近秋莲。","一笛当楼，谢娘悬泪立风前。","故园晚、强留诗酒，新雁远、不致寒暄。","隔苍烟。","楚香罗袖，谁伴婵娟。"],"theme":"爱情相思","theme2":["闲适隐逸","边塞征战","哲理悟道"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":[],"scene":["秋","园林","楼","夜","中秋","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.8},{"uid":"97c98650-151d-4c52-8504-1e6c66820058","title":"赠裴九侍御昌江草堂弹琴","author":"贾至","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朔风吹疎林，积雪在崖𪩘。","鸣琴草堂响，小涧清且浅。","沈吟东山意，欲去芳岁晚。","怅望黄绮心，白云若在眼。"],"theme":"题画咏艺","theme2":["送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江","冬","雪"],"cats":{"四季":["冬天"],"天气":["写风","写雪"]},"theme_conf":0.41},{"uid":"c06c6f1d-b88f-4169-8df1-6aea35110ec1","title":"柳边","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["只道梅花发，那知柳亦新。","枝枝总到地，叶叶自开春。","紫燕时飜翼，黄鹂不露身。","汉南应老尽，霸上远愁人。"],"theme":"咏物","theme2":[],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.78},{"uid":"7109feaf-91db-4b77-a50e-3e71c6a4c66c","title":"送韦讽上阆州录事参军","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["国步犹艰难，兵革未衰息。","万方哀嗷嗷，十载供军食。","庶官务割剥，不暇忧反侧。","诛求何多门，贤者贵为德。","韦生富春秋，洞彻有清识。","操持纪纲地，喜见朱丝直。","当令豪夺吏，自此无颜色。","必若救疮痍，先应去蟊贼。","挥泪临大江，高天意凄恻。","行行树佳政，慰我深相忆。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"山水":["长江"]},"theme_conf":0.464},{"uid":"dc20aed7-693e-44db-99c4-ab3d8f5ba7d1","title":"南阳公请东樱桃亭子春䜩","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万木皆未秀，一林先含春。","此地独何力，我公布深仁。","霜叶日舒卷，风枝远埃尘。","初英濯紫霞，飞雨流清津。","赏异出嚣杂，折芳积懽忻。","文心兹焉重，俗尚安能珍。","碧玉粧粉比，飞琼秾艳均。","鸳鸯七十二，花态并相新。","常恐遗秀志，迨兹广䜩陈。","芳菲争胜引，歌咏竟良辰。","方知戏马会，永谢登龙宾。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["爱情","孤独"],"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"9d551104-88c1-4011-b24a-2ef8f5e60731","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["如折芙蓉栽旱地，似抛芍药挂高枝。","云埋水隔无人识，唯有南宾太守知。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["月","冬","夏","花","山"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["写云","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.488},{"uid":"f2d99429-122c-47c4-a117-06779c58a4f5","title":"相和歌辞 子夜四时歌六首 秋歌二首 二","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["辟恶茱萸囊，延年菊花酒。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","秋","夜"],"cats":{"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.95},{"uid":"8cd434d7-67ab-4501-8aac-e4a5e8b12dd2","title":"郊庙歌辞 五郊乐章 送神","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["春末冬暮，徂夏杪秋。","土王四月，时季一周。","黍稷已享，笾豆宜收。","送神有乐，神其赐休。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","夏","春","秋","月"],"cats":{"四季":["春天","夏天","秋天","冬天"]},"theme_conf":1.0},{"uid":"8d968574-77fb-46e2-9594-d31f60408227","title":"同群公宿开善寺赠陈十六所居","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["驾车出人境，避暑投僧家。","裴回龙象侧，始见香林花。","读书不及经，饮酒不胜茶。","知君悟此道，所未搜袈裟。","谈空忘外物，持诫破诸邪。","则是无心地，相看唯月华。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏","花","酒","月"],"cats":{"四季":["夏天"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.72},{"uid":"08dc6c3a-07bc-479a-9bbe-4225ff0352e6","title":"忆幼子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骥子春犹隔，莺歌暖正繁。","别离惊节换，聪慧与谁论。","涧水空山道，柴门老树村。","忆渠愁只睡，炙背俯晴轩。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.638},{"uid":"932de3da-b56d-4987-b9cc-3b2d5956a4ff","title":"悼诗","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["永念难消释，孤怀痛自嗟。","雨深秋寂莫，愁引病增加。","咽绝风前思，昏蒙眼上花。","空王应念我，穷子正迷家。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"]},"theme_conf":0.98},{"uid":"f91f3117-2bf2-4d12-999a-aca174124715","title":"清平调 三","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["名花倾国两相欢，常得君王带笑看。","解得春风无限恨，沈香亭北倚阑干。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["楼","花","春"],"cats":{"四季":["春天"]},"theme_conf":1.0},{"uid":"23b288e3-01d9-4688-8f00-8572431a2819","title":"同乐天和微之深春二十首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何处深春好，春深阿母家。","瑶池长不夜，珠树正开花。","桥峻通星渚，楼暄近日车。","层城十二阙，相对日西斜。"],"theme":"亲情","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"b6210ab6-af10-41ce-b847-ad41e94aaf8a","title":"送钱拾遗归兼寄刘校书","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["墟落岁阴暮，桑榆烟景昏。","蝉声静空馆，雨色隔秋原。","归客不可望，悠然林外村。","终当报芸阁，携手醉柴门。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","雨","楼","酒"],"cats":{"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.496},{"uid":"3979821a-6f07-41ad-9625-f9a4b76d9108","title":"过柳溪道院","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["溪上谁家掩竹扉，鸟啼浑似惜春晖。","日斜深巷无人迹，时见棃花片片飞。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.705},{"uid":"5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","春","重阳","雨"],"cats":{"抒情":["离别","伤感"],"四季":["春天"],"人物":["女子"],"人生":["青春"],"节日":["重阳节"],"植物":["柳树"]},"theme_conf":0.653},{"uid":"556a1fa5-a3d2-48cb-bfb7-354c057e042f","title":"季冬自嵩山赴洛道中作","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皇运偶中变，长蛇食中土。","天盖西北倾，众星陨如雨。","胡尘动地起，千里闻战鼓。","死人成为阜，流血涂草莽。","策马何纷纷，捐躯抗豺虎。","甘心赴国难，谁谓荼叶苦。","天子初受命，省方造区宇。","斩鲸安溟波，截鼇作天柱。","三微复正统，五玉归文祖。","不图汉官仪，今日忽再覩。","升高望京邑，佳气连海浦。","宝鼎歊景云，明堂舞干羽。","虎臣囗激昂，囗囗囗御侮。","腐儒著缝掖，何处议邹鲁。","西上轘辕山，丘陵横今古。","和气蒸万物，腊月春霭吐。","得为太平人，穷达不足数。","他日遇封禅，著书继三五。"],"theme":"边塞征战","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山","冬"],"cats":{"抒情":["爱国"],"四季":["冬天"],"人生":["哲理","战争"]},"theme_conf":0.433},{"uid":"2516cd79-8ae0-47b0-9bad-0a807c57dbb1","title":"紫参歌","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["远公林下满青苔，春药偏宜间石开。","往往幽人寻水见，时时仙蝶隔云来。","阴阳雕刻花如鸟，对凤连鸡一何小。","春风宛转虎溪傍，紫翼红翘翻霁光。","贝叶经前无住色，莲花会里暂留香。","蓬山才子怜幽性，白云阳春动新咏。","应知仙卉老云霞，莫赏夭桃满蹊迳。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"天气":["写云"]},"theme_conf":1.0},{"uid":"e6fd205b-a5b4-415a-87f4-ad87b918ebbb","title":"赴无锡别灵一上人","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高僧本姓竺，开士旧名林。","一入春山里，千峰不可寻。","新年芳草徧，度日白云深。","欲问微官去，悬知讶此心。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["山","春"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.549},{"uid":"cp9665af6a84dad4","title":"宴清都","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绣幄鸳鸯柱。","红情密，腻云低护秦树。","芳根兼倚，花梢钿合，锦屏人妒。","东风睡足交枝，正梦花、瑶钗燕股。","障滟蜡、满照欢丛，嫠蟾冷落羞度。","人间万感幽单，华清惯浴，春盎风露。","连鬟并暖，同心共结，向承恩处。","凭谁为歌长恨，暗殿锁、秋灯夜语。","叙旧期、不负春盟，红朝翠暮。"],"theme":"闺情宫怨","theme2":["爱情相思","咏史怀古"],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["春","花","夜"],"cats":{"抒情":["爱情","闺怨","怀古"],"四季":["春天"]},"theme_conf":0.4},{"uid":"cf912dac-30ed-4f16-a951-ddecd90387ed","title":"郡斋左偏栽竹百余竿炎凉已周青翠不改而为墙垣所蔽有乖爱赏假日命去斋居之东墙由是俯临轩阶低映帷户日夕相对颇有翛然之趣","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["斋居栽竹北窗边，素壁新开映碧鲜。","青蔼近当行药处，绿阴深到卧帷前。","风惊晓叶如闻雨，月过春枝似带烟。","老子忆山心暂缓，退公闲坐对婵娟。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":["恬淡","相思"],"scene":["夏","中秋","楼","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.464},{"uid":"bd7949f8-c961-4bfd-a307-1fe9e621028c","title":"哀王孙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长安城头头白乌，夜飞延秋门上呼。","又向人家啄大屋，屋底达官走避胡。","金鞭断折九马死，骨肉不待同驰驱。","腰下实玦青珊瑚，可怜王孙泣路隅。","问之不肯道姓名，但道困苦乞为奴。","已经百日窜荆棘，身上无有完肌肤。","高帝子孙尽隆准，龙种自与常人殊。","豺狼在邑龙在野，王孙善保千金躯。","不敢长语临交衢，且为王孙立斯须。","昨夜东风吹血腥，东来橐驼满旧都。","朔方健儿好身手，昔何勇锐今何愚。","窃闻天子已传位，贤德北服南单于。","花门剺面请雪耻，慎勿出口他人狙。","哀哉王孙慎勿疎，五陵佳气无时无。"],"theme":"讽喻刺世","theme2":["边塞征战"],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":[],"scene":["雪","夜","秋"],"cats":{"四季":["秋天"]},"theme_conf":0.6},{"uid":"995a9440-f8e3-4a9b-843d-27a34ea8b671","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伐竹为桥结构同，褰裳不涉往来通。","天寒白鹤归华表，日落青龙见水中。","顾我老非题柱客，知君才是济川功。","合欢却笑千年事，驱石何时到海东。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["冬","江"],"cats":{"四季":["冬天"],"天气":["太阳"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.52},{"uid":"6038ff33-cb0f-4ab7-82bd-c603b030c1bb","title":"伤歙州陈二使君","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["怜君辞满卧沧洲，一旦云亡万事休。","慈母断肠妻独泣，寒云惨色水空流。","江村故老长怀惠，山路孤猨亦共愁。","寂寞荒坟近渔浦，野松孤月即千秋。"],"theme":"悼亡挽歌","theme2":["山水田园","亲情"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["江","秋","月"],"cats":{"抒情":["伤感","孤独","悼亡","感恩"],"四季":["秋天"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"0db5450e-f1e0-4d53-8106-529def535537","title":"杂曲歌辞 清平调 三","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["名花倾国两相欢，长得君王带笑看。","解释春风无限恨，沈香亭北倚阑干。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["楼","花","春"],"cats":{"四季":["春天"]},"theme_conf":1.0},{"uid":"101844bd-db52-4b7b-a097-c45162545c77","title":"同李九士曹观壁画云作","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["始知帝乡客，能画苍梧云。","秋天万里一片色，只疑飞尽犹氛氲。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写云"]},"theme_conf":0.733},{"uid":"5f8937e3-49b1-4ee9-93fe-4ea590143f89","title":"孟氏","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孟氏好兄弟，养亲唯小园。","承颜胝手足，坐客强盘[飧]。","负米力葵外，读书秋树根。","卜邻惭近舍，训子学谁门。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋","园林"],"cats":{"四季":["秋天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"8e1e7b7e-1824-402a-8ef1-ada1b0490f58","title":"秋野五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋野日疏芜，寒江动碧虚。","系舟蛮井络，卜宅楚村墟。","枣熟从人打，葵荒欲自锄。","盘餐老夫食，分减及溪鱼。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"生活":["田野"]},"theme_conf":0.508},{"uid":"46c4b862-f6f9-43de-9eb7-6465af52b1f5","title":"寒食戏赠","author":"柳中庸","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春暮越江边，春阴寒食天。","杏花香麦粥，柳絮伴秋千。","酒是芳菲节，人当桃李年。","不知何处恨，已解入筝弦。"],"theme":"节令风俗","theme2":["送别"],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["清明","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"785ddb64-8fd9-402b-b4fc-8cb50e1469ed","title":"琴茶","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["兀兀寄形群动内，陶陶任性一生间。","自抛官后春多醉，不读书来老更闲。","琴里知闻唯渌水，茶中故旧是蒙山。","穷通行止长相伴，谁道吾今无往还。"],"theme":"闲适隐逸","theme2":[],"style":"悲慨","style2":[],"mood":"恬淡","mood2":[],"scene":["春","酒","山"],"cats":{"四季":["春天"],"人生":["读书"],"食物":["写茶"]},"theme_conf":0.94},{"uid":"cp00f32cca7838bf","title":"永遇乐","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["落日熔金，暮云合璧，人在何处。","染柳烟浓，吹梅笛怨，春意知几许。","元宵佳节，融和天气，次第岂无风雨。","来相召、香车宝马，谢他酒朋诗侣。","中州盛日，闺门多暇，记得偏重三五。","铺翠冠儿，拈金雪柳，簇带争济楚。","如今憔悴，风鬟霜鬓，怕见夜间出去。","不如向、帘儿底下，听人笑语。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["夜","雨","元宵","冬","雪","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":0.515},{"uid":"b3e78cdb-4a2b-439c-99da-34b466fe138e","title":"暮春题瀼西新赁草屋五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彩云阴复白，锦树晓来青。","身世双蓬鬓，乾坤一草亭。","哀歌时自短，醉舞为谁醒。","细雨荷锄立，江猨吟翠屏。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽"],"mood":"悲怆","mood2":[],"scene":["雨","春"],"cats":{"四季":["春天"],"天气":["写云","写雨"]},"theme_conf":1.0},{"uid":"4ed14233-782c-4837-9c21-d6b8de27518b","title":"水帘吟","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["万滴相随万响兼，路尘天产尽旁沾。","源从颢气何因绝，派助前溪岂觉添。","豪客每来清夏葛，愁人才见认愁簷。","嘉名已极终难称，别是风流不是帘。"],"theme":"山水田园","theme2":["送别","闺情宫怨"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"抒情":["伤感","闺怨"],"四季":["夏天"],"山水":["瀑布"]},"theme_conf":0.451},{"uid":"bd3a0a24-fd2c-4aa9-86d9-ff08f158bb61","title":"宿诚禅师山房题赠二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宴坐白云端，清江直下看。","来人望金刹，讲席绕香坛。","虎啸夜林动，鼍鸣秋涧寒。","众音徒起灭，心在净中观。"],"theme":"哲理悟道","theme2":["送别"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山","秋","夜"],"cats":{"四季":["秋天"],"人物":["老师"],"人生":["哲理"]},"theme_conf":0.442},{"uid":"d9d4c055-1dc0-4555-b180-979008c8d0f0","title":"南充谢郡客游澧州留赠宇文中丞","author":"畅当","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仆本濩落人，辱当州郡使。","量力颇及早，谢归今即已。","萧萧若凌虚，襟带顿销靡。","车服率然来，涔阳作游子。","郁郁寡开颜，默默独行李。","忽逢平生友，一笑方在此。","秋情宁风日，楚思浩云水。","为语弋林者，冥冥鸿远矣。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["秋"],"cats":{"抒情":["思乡","孤独","感恩"],"四季":["秋天"]},"theme_conf":0.88},{"uid":"768287b6-de28-4e1a-90b7-b1446f1dca99","title":"病中辱崔宣城长句见寄兼有觥绮之赠因以四韵总而酬之","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["刘[桢]病发经春卧，谢朓诗来尽日吟。","三道旧夸收片玉，一章新喜获双金。","信题霞绮缄情重，酒试银觥表分深。","科第门生满霄汉，岁寒少得似君心。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春","酒","冬"],"cats":{"四季":["春天","冬天"],"人物":["老师"]},"theme_conf":0.98},{"uid":"370b53ae-949e-45cf-92b0-3aca072c1b86","title":"丽人行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有，翠微㔩叶垂鬓唇。","背后何所见，珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫驼之峰出翠釜，水精之盘行素鳞。","犀箸厌饫久未下，銮刀缕切空纷纶。","黄门飞鞚不动尘，御厨络绎送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"],"theme":"讽喻刺世","theme2":["讽喻刺世"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":["悲怆"],"scene":["雪","春","花"],"cats":{"四季":["春天"],"人物":["女子"]},"theme_conf":0.95},{"uid":"7e26f9c9-ef6f-4b26-bf34-c683d1e41786","title":"杂曲歌辞 长相思","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月西风兴，月冷霜华凝。","思君秋夜长，一夜魂九升。","二月东风来，草坼花心开。","思君春日迟，一日肠九回。","妾住洛桥北，君住洛桥南。","十五即相识，今年二十三。","有如女萝草，生在松之侧。","蔓短枝苦高，萦回上不得。","人言人有愿，愿至天必成。","愿作远方兽，步步比肩行。","愿作深山木，枝枝连理生。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","春"],"cats":{"抒情":["爱情","思念"],"四季":["春天","秋天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"f3900a71-2d1e-4099-81d9-2f4e099b0940","title":"秋夜闻鴈寄南十五兼呈空和尚","author":"张南史","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晚节闻君道趣深，结茅栽树近东林。","禅师几度曾摩顶，高士何年更发心。","北渚三更闻过鴈，西城万木动寒砧。","不见支公与玄度，相思拥膝坐长吟。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["夜","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.9},{"uid":"8138a2d0-cd03-4430-95cf-487daa5d6902","title":"将赴成都草堂途中有作先寄严郑公五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["处处青江带白苹，故园犹得见残春。","雪山斥候无兵马，锦里逢迎有主人。","休怪儿童延俗客，不教鹅鸭恼比邻。","习池未觉风流尽，况复旌州赏更新。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["园林","雪","春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["儿童"]},"theme_conf":0.95},{"uid":"cb5b6b57-47da-4cde-aa13-9a28bebc7fc4","title":"琴曲歌辞 湘妃列女操","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有虞夫人哭虞后，淑女何事又伤离。","竹上泪迹生不尽，寄哀云和五十丝。","云和经奏钧天曲，乍听宝琴遥嗣续。","三湘测测流急绿，秋夜露寒蜀帝飞。","枫林月斜楚臣宿，更疑川宫日黄昏。","暗携女手殷勤言，环佩玲珑有无间。","终疑既远双悄悄，苍梧旧云岂难召。","老猨心寒不可啸，目眄眄兮意蹉跎。"],"theme":"咏史怀古","theme2":["闲适隐逸","悼亡挽歌","山水田园"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["伤感","悼亡","怀古"],"四季":["秋天"]},"theme_conf":0.85},{"uid":"9c56b83a-34f3-4a30-a7fe-c0f7bb2fcac1","title":"送夏侯审参军游江东","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["袖中多丽句，未遣世人闻。","醉夜眠江月，闲时逐海云。","荻花寒漫漫，鸥鸟暮群群。","若到长沙苑，渔家更待君。"],"theme":"送别","theme2":["边塞征战","山水田园"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","夏","夜"],"cats":{"四季":["夏天"],"山水":["江河"]},"theme_conf":0.375},{"uid":"b11c8320-d662-41e0-a9f2-8f4d4c4ceccd","title":"冬狩","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["烈烈寒风起，惨惨飞云浮。","霜浓凝广隰，冰厚结清流。","金鞍移上苑，玉勒骋平畴。","旌旗四望合，罝罗一面求。","楚踣争兕殪，秦亡角鹿愁。","兽忙投密树，鸿惊起砾洲。","骑敛原尘静，戈回岭日收。","心非洛汭逸，意在渭滨游。","禽荒非所乐，抚辔更招忧。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"81d2c0f7-48ad-4b35-b142-9ed40165e8e2","title":"孟生诗","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孟生江海士，古貌又古心。","尝读古人书，谓言古犹今。","作诗三百首，窅默咸池音。","骑驴到京国，欲和熏风琴。","岂识天子居，九重郁沈沈。","一门百夫守，无籍不可寻。","晶光荡相射，旗戟翩以森。","迁延乍却走，惊怪靡自任。","举头看白日，泣涕下沾襟。","朅来游公卿，莫肯低华簪。","谅非轩冕族，应对多差参。","萍蓬风波急，桑榆日月侵。","奈何从进士，此路转岖嵚。","异质忌处群，孤芳难寄林。","谁怜松桂性，竞爱桃李阴。","朝悲辞树叶，夕感归巢禽。","顾我多慷慨，穷檐时见临。","清宵静相对，发白聆苦吟。","采兰起幽念，眇然望东南。","秦吴修且阻，两地无数金。","我论徐方牧，好古天下钦。","竹实凤所食，德馨神所歆。","求观众丘小，必上泰山岑。","求观众流细，必泛沧溟深。","子其听我言，可以当所箴。","既获则思返，无为久滞淫。","卞和试三献，期子在秋砧。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["旷达"],"mood":"悲怆","mood2":["相思"],"scene":["山","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["泰山"]},"theme_conf":0.647},{"uid":"17483666-0c00-4a97-9824-4ee04d4ca776","title":"蕉叶","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["绿绮新裁织女机，摆风摇日影离披。","只应青帝行春罢，闲倚东墙卓翠旗。"],"theme":"送别","theme2":["闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["七夕","春"],"cats":{"四季":["春天"],"节日":["七夕节"],"植物":["叶子"]},"theme_conf":0.5},{"uid":"b5d52c7f-9cd4-4805-8b40-47771a17af7b","title":"赠别晋三处士","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有人家住清河源，渡河问我游梁园。","手持道经注已毕，心知内篇口不言。","卢门十年见秋草，此心惆怅谁能道。","知己从来不易知，慕君为人与君好。","别时九月桑叶疎，出门千里无行车。","爱君且欲君先达，今上求贤早上书。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","月"],"cats":{"抒情":["友情","离别"],"四季":["秋天"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"bee2cbb1-71a9-4702-91dc-cce9446269ff","title":"徐十八晦落第","author":"欧阳詹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["嘉谷不夏熟，大器当晚成。","徐生异凡鸟，安得非时鸣。","汲汲有所为，驱驱无本情。","懿哉苍梧凤，终见排云征。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人生":["励志"]},"theme_conf":0.65},{"uid":"c0f319bd-70b8-4e2b-ad82-9ed3d84ed7b0","title":"相和歌辞 怨歌行","author":"吴少微","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["城南有怨妇，含怨倚兰丛。","自谓二八时，歌舞入汉宫。","皇恩弄幸玉堂中，绿陌黄花催夜酒。","锦衣罗袂逐春风，建章西宫焕若神。","燕赵美女二千人，君王厌德不忘新。","况群艳冶纷来陈，是时别君不再见。","三十三春长信殿，长信重门昼掩关。","清房晓帐幽且闲，绮窗虫网氛尘色。","文轩莺对桃李颜，天王贵宫不贮老。","浩然泪陨今来还，自怜转晚暮。","试逐佳游芳草路，小腰丽女夺人奇。","金鞍少年曾不顾，归来谁为夫。","请谢西家妇，莫辞先醉解罗襦。"],"theme":"闺情宫怨","theme2":["送别","羁旅思乡"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["春","酒","鸟"],"cats":{"抒情":["思乡","伤感","闺怨","感恩"],"四季":["春天"]},"theme_conf":0.97},{"uid":"18174707-b8de-4a21-8b90-08b2a03a5ce8","title":"舞曲歌辞 白纻歌","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["皎皎白纻白且鲜，将作春衫称少年。","裁缝长短不能定，自持刀尺向姑前。","复恐兰膏污纤指，常遣傍人收堕珥。","衣裳著时寒食下，还把玉鞭鞭白马。"],"theme":"咏物","theme2":["边塞征战"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["清明","春"],"cats":{"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.72},{"uid":"103a8266-2d76-413d-9cde-e32f15f47d4c","title":"九月九日幸临渭亭登高得秋字","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月正乘秋，三杯兴已周。","泛桂迎尊满，吹花向酒浮。","长房萸早熟，彭泽菊初收。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","月","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.92},{"uid":"cp40369a60024392","title":"浣溪沙","author":"晏殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一向年光有限身。","等闲离别易消魂。","酒筵歌席莫辞频。","满目山河空念远，落花风雨更伤春。","不如怜取眼前人。"],"theme":"送别","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","酒","春"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":0.38},{"uid":"7715e2f7-4e7e-4794-942e-bfbad57f953d","title":"燕歌行","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见渔阳八月塞草腓，征人相对并思归。","云和朔气连天黑，蓬杂惊沙散野飞。","是时天地阴埃遍，瀚海龙城皆习战。","两军鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄无厌不复和。","汉兵候月秋防塞，胡骑乘冰夜渡河。","河塞东西万余里，地与京华不相似。","燕支山下少春晖，黄沙碛里无流水。","金戈玉剑十年征，红粉青楼多怨情。","厌向殊乡久离别，秋来愁听捣衣声。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["鸟","塞外","秋"],"cats":{"抒情":["离别","思念","伤感","感恩"],"四季":["秋天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.592},{"uid":"fb5a52a2-c14b-4302-b5b1-ab18d92348ab","title":"自淇涉黄河途中作十三首 九","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝从北岸来，泊船南河浒。","试共野人言，深觉农夫苦。","去秋虽薄熟，今夏犹未雨。","耕耘日勤劳，租税兼舃卤。","园蔬空寥落，产业不足数。","尚有献芹心，无因见明主。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江","夏","秋","舟","雨","园林"],"cats":{"四季":["夏天","秋天"],"山水":["江河","黄河"]},"theme_conf":0.636},{"uid":"2c24cec1-4105-4511-bf8b-bc6d5d8d48c7","title":"送李少府贬峡中王少府贬长沙","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["嗟君此别意何如，驻马衔桮问谪居。","巫峡啼猿数行泪，衡阳归雁几封书。","青枫江上秋天远，白帝城边古木疎。","圣代即今多雨露，暂时分手莫踌躇。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"]},"theme_conf":0.556},{"uid":"2186935c-d029-4ee0-b0b1-4f6341b0323b","title":"野菊","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦竹园南椒坞边，微香冉冉泪涓涓。","已悲节物同寒雁，忍委芳心与暮蝉。","细路独来当此夕，清尊相伴省他年。","紫云新苑移花处，不取霜栽近御筵。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["花","重阳","秋"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.757},{"uid":"6335b64e-eb8c-4bfb-af43-04079f2bdd4c","title":"相和歌辞 子夜四时歌四首 夏歌","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["兰眼擡露斜，莺唇映花老。","金龙倾漏尽，玉井敲冰早。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","夏"],"cats":{"四季":["夏天"]},"theme_conf":0.63},{"uid":"09c772f5-e6c7-4b3c-9902-1a0af8e8255c","title":"绝句九首 九","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["设道春来好，狂风大放颠。","吹花随水去，飜却钓鱼船。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":["春","舟"],"cats":{"四季":["春天"],"天气":["写风"]},"theme_conf":1.0}];
